window.kbParts["entries-a8b5deb0d0928be9"] = {"nodes":{"k-5a52c06a53e893e2":{"review":{"definition":"2025年中央城市工作会议指出，我国城市发展正从大规模增量扩张阶段转向存量提质增效为主的阶段，发展重心转向提升既有城市空间和资源的质量与利用效率。","explanation":"会议同时指出，我国城镇化正从快速增长期转向稳定发展期。B项把城市发展原先所处的大规模增量扩张阶段写成转型的去向，颠倒了会议判断中的发展方向。","references":[],"evidence":"发展正从大规模增量扩张阶段转向存量提质增效为主的阶段","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6968cae8cf21349b":{"review":{"definition":"原题引文：包括乡村产业、人才、文化、生态、组织振兴五个方面。","explanation":"第34题A项合述了战略的提出和实施的五个方面，因此在选非题中排除A项。十九大报告列出的是产业兴旺、生态宜居、乡风文明、治理有效、生活富裕五项总要求。习近平在2018年3月8日参加十三届全国人大一次会议山东代表团审议时，集中阐述了五个振兴。","references":[{"source":"web-3d08af396229bf84","location":"2018年3月8日山东代表团审议讲话要点条目","quote":"推动乡村产业振兴、人才振兴、文化振兴、生态振兴、组织振兴"}],"evidence":"包括乡村产业、人才、文化、生态、组织振兴五个方面。","disposition":"独立词条","basis":"据原题与所列资料编释。"},"sources":[{"id":"64e0a00ebe161aac","label":"乡村振兴战略","topic":"农业与城乡治理","category":"非时政","text":"1.乡村振兴战略\n党的十九大报告提出实施乡村振兴战略。实施乡村振兴战略，是以习近平同志为核心的\n党中央着眼党和国家事业全局作出的重大决策，是新时代新征程“三农”工作的总抓手。\n实施乡村振兴战略，坚持农业农村优先发展是总方针，产业兴旺、生态宜居、乡风文明、\n治理有效、生活富裕是总要求，建立健全城乡融合发展体制机制和政策体系是制度保障。\n实施乡村振兴战略，要坚持乡村全面振兴，实现乡村产业振兴、人才振兴、文化振兴、\n生态振兴、组织振兴，推动农业全面升级、农村全面进步、农民全面发展。、","source":{"doc":"6cbfb01fe723bba64b75","first":35,"last":35,"page":35,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-97781378434526a5":{"review":{"definition":"习近平在2025年3月28日会见国际工商界代表时指出，中国是全球第二大消费市场，拥有全球最大规模的中等收入群体。","explanation":"讲话以消费市场和中等收入群体的规模说明中国的投资与消费潜力。②沿用了消费市场的排名，却把“中等收入群体”改成“高等收入群体”，因此整项错误。这里的规模表述对应这次讲话的时间和语境。","references":[],"evidence":"中国是全球第二大消费市场，拥有全球最大规模中等收入群体，","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-250dc0a204f29da1":{"review":{"title":"利用外资法规政策体系和工作体系","type":"事实与事件","definition":"2025年3月28日，习近平在会见国际工商界代表时指出，中国已经形成比较健全的利用外资法规政策体系和工作体系。","explanation":"法规政策体系涵盖外商投资立法和相关政策安排，工作体系关系到这些法规政策的组织实施。讲话列举了加强外商投资立法、推动贸易和投资自由化便利化、营造市场化法治化国际化一流营商环境等做法。","basis":"据关联原题及所列出处编释。","references":[{"source":"fp","location":"2025年3月28日会见国际工商界代表时的讲话"}],"related":["k-9a00bd0185c0ac82"],"domain":"经济","examFocus":{"政治理论必刷100题#35":"核对外资投资条件的表述，辨明利用外资的法规政策体系和工作体系处在什么建设阶段。","政治理论必刷100题#90":"对照高水平对外开放论述，辨明利用外资的法规政策与工作体系建设进展，区分制度建设成效和开放的一般作用。"}},"aspects":[{"title":"利用外资体系的建设现状","uses":[{"unit":"Q1","role":"直接考查","use":"本题考查外商来华投资的有利条件。讲话使用“已经形成”，因此③“尚未形成”的判断错误，①④正确，选B。","evidence":"中国已经形成比较健全的利用外资法规政策体系和工作体系。","qids":["政治理论必刷100题#35"]},{"unit":"Q2","role":"直接考查","use":"本题要求选出关于高水平对外开放的错误表述。A项符合2025年3月28日讲话。C项误将多边贸易体制的核心写成联合国经济发展委员会，讲话所指为世界贸易组织，故选C。","evidence":"中国已经形成比较健全的利用外资法规政策体系和工作体系","qids":["政治理论必刷100题#90"]}]}]},"k-8e546bb0b57ff3a5":{"review":{"definition":"“千村示范、万村整治”工程简称“千万工程”，于2003年在浙江启动，以农村环境整治为切入点，逐步推进乡村建设。","explanation":"工程初期着眼于改善农村生产、生活、生态环境，通过示范带动和逐步推广推进美丽乡村建设。第73题第⑤项同时写出了农村环境整治这一切入点和美丽乡村这一建设成效，因此对应正确。","references":[],"evidence":"从农村环境整治入手，造就万千美丽乡村——“千万工程”","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"ae3e8603d2c7cdac","label":"“千万工程”经验","topic":"农业与城乡治理","category":"非时政","text":"2.“千万工程”经验\n2003 年，时任浙江省委书记的习近平同志在广泛深入调查研究基础上，立足浙江省情\n农情和发展阶段特征，准确把握经济社会发展规律和趋势，作出了实施“千村示范、万村整\n治”工程（“千万工程”）的战略决策，在浙江近 4 万个村庄中选择 1 万个左右的行政村进\n行全面整治，把其中 1000 个左右的中心村建设成全面小康示范村，并以此为龙头，深入推\n进社会主义新农村建设。","source":{"doc":"6cbfb01fe723bba64b75","first":33,"last":34,"page":33,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-289b3c85df23fba4":{"review":{"definition":"据习近平2025年4月23日在气候和公正转型领导人视频峰会上的致辞，中国已构建全球最大、发展最快的可再生能源体系，并建成全球最大、最完整的新能源产业链。","explanation":"第77题④同时涉及两个对象。“发展最快”描述可再生能源体系，“最完整”描述新能源产业链，“全球最大”适用于两者。④与该次致辞的表述一致。","references":[],"evidence":"建成了全球最大、最完整的新能源产业链","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-40e7607a47ef3684":{"review":{"definition":"党的十八大将生态文明建设纳入中国特色社会主义事业总体布局，形成经济建设、政治建设、文化建设、社会建设和生态文明建设“五位一体”的总体布局。","explanation":"第79题①把党的十八大提出的“建设美丽中国”与党的十九大部署的社会主义现代化强国建设“两步走”目标混在了一起。十八大在总体布局上的部署，是把生态文明建设纳入“五位一体”。","references":[],"evidence":"将生态文明建设纳入中国特色社会主义事业“五位一体”总体布局。","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"8cff63008c52a13e","label":"“五位一体”总体布局","topic":"党政制度与理论","category":"非时政","text":"2.“五位一体”总体布局\n2012 年 11 月，党的十八大首次提出中国特色社会主义事业总布局是“五位一\n体”，即“经济建设、政治建设、文化建设、社会建设、生态文明建设”五个方面。\n“五位一体”总体布局是一个有机整体，经济建设是根本，政治建设是保障，文化建\n设是灵魂，社会建设是条件，生态文明建设是基础，统一于把我国建成富强民主文明\n和谐美丽的社会主义现代化强国的新目标。","source":{"doc":"41195a191a57c1c36332","first":4,"last":4,"page":4,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-db622407f2126020":{"review":{"definition":"党的十九大对全面建设社会主义现代化国家作出分两个阶段的战略安排。第二阶段到本世纪中叶，把我国建成富强民主文明和谐美丽的社会主义现代化强国。","explanation":"第79题①所说的将“美丽中国”纳入“两步走”目标，具体对应第二阶段强国目标中的“美丽”。这一战略安排由党的十九大提出，因此①所填的党的十八大有误。","references":[],"evidence":"纳入社会主义现代化强国建设“两步走”的目标。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-78a91568d11054f7":{"review":{"definition":"2005年8月15日，时任浙江省委书记习近平在浙江省安吉县余村考察时，首次提出“绿水青山就是金山银山”。","explanation":"第79题③问的是这一论述首次提出的场合。它最早见于浙江安吉余村的考察，③写成全国生态环境保护大会，场合有误。","references":[],"evidence":"在浙江省安吉县余村考察时，","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-58182f0cda54d353":{"review":{"definition":"2013年，党的十八届三中全会首次提出建立国家公园体制，并将其列入全面深化改革的重点任务。","explanation":"第79题④说的是体制建设在中央改革部署中首次提出的时间。2015年起陆续开展的国家公园体制试点属于后续实施，两者对应不同阶段，因此④正确。","references":[],"evidence":"党的十八届三中全会首次提出建立国家公园体制，并将其列入全面","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e694bc3481c4e5b9":{"review":{"definition":"习近平在全国生态环境保护大会上的讲话中指出，新时代生态环境治理从解决突出问题入手，通过点面结合、标本兼治，实现了由重点整治到系统治理的转变。","explanation":"突出生态环境问题是治理的切入点，系统治理是转变的方向。第80题①保留了正确的切入点，却把转变方向写反了。","references":[],"evidence":"实现由重点整治到系统治理的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0091bb208762e6fe":{"review":{"definition":"据习近平2025年3月28日会见国际工商界代表时的讲话，中国商务部每月召开一次外资企业圆桌会议，听取企业诉求并帮助解决困难。","explanation":"③的会议主体和用途与讲话相符，但将每月一次写成了每月两次。题目据这次讲话核对会议频次，因此排除③。","references":[],"evidence":"部每月召开一次外资企业圆桌会议，听取企业诉求，帮助排忧解难","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3296c53b786698c1":{"review":{"definition":"2020年11月16日至17日召开的中央全面依法治国工作会议，将习近平法治思想明确为全面依法治国的指导思想。","explanation":"第96题题干以党的十八大关于依法治国基本方略的表述引入，④涉及的是2020年中央全面依法治国工作会议。④的会议年份、会议名称和所明确的指导思想均与解析一致，应纳入正确组合。","references":[],"evidence":"中央全面依法治国工作会议将习近平法治思想明确为全面依法治国的指导思","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-32ea6dcd334a310e":{"review":{"definition":"“草木植成，国之富也”出自《管子·立政》，意为草木生长繁茂是国家富足的体现。2021年4月30日，习近平在十九届中央政治局第二十九次集体学习时引用这句古语。","explanation":"此次集体学习的主题是新形势下加强我国生态文明建设。习近平借草木繁茂与国家富足的关系阐述人与自然和谐共生，因此A项对应生态文明建设。","references":[],"evidence":"草木植成，国之富也——生态文明建设","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d49bb628e40e2ce0":{"review":{"definition":"这句古语讲的是研读经典以辨明是非、考察史事以明了成败。2022年5月27日，习近平在中央政治局就深化中华文明探源工程进行第三十九次集体学习时引用了这段话。","explanation":"题中用语是对讲话所引古语的简写。习近平在这次学习中借经史之鉴说明中华文明对当代中国文化和文化创新的意义，强调推动中华优秀传统文化创造性转化、创新性发展，因此B项对应文化建设。","references":[],"evidence":"研理于经正是非，征事于史明成败——文化建设","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-806d1654cb064f43":{"review":{"definition":"“新松恨不高千尺，恶竹应须斩万竿”是杜甫诗句。2016年，习近平在十八届中央纪委六次全会上引用这两句诗，强调党风廉政建设和反腐败斗争。","explanation":"这次讲话要求持之以恒纠正“四风”，强调经常抓、深入抓、持久抓，防止反弹回潮。按此次引用的主题，诗句对应党的建设。C项将其配为社会建设，正是本题要求选出的错误项。","references":[],"evidence":"党中央对党风廉政建设和反腐败斗争的高度重视和坚定决心","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f85699c05c6e0fa0":{"review":{"definition":"“强不执弱，富不侮贫”出自《墨子·兼爱》，意为强者不控制弱者，富者不欺侮贫者。2015年11月7日，习近平在新加坡国立大学演讲时援引了这句古语。","explanation":"习近平在演讲中以中国自古倡导的这一准则回应所谓“中国威胁论”，阐明中国坚持走和平发展道路、奉行独立自主的和平外交政策，因此D项的领域对应成立。","references":[],"evidence":"中国自古倡导“强不执弱，富不侮贫”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3039a8202fcf639d":{"review":{"definition":"玉陵湖大桥重建时采用内倾10°的提篮拱桥方案，使桥身呈现优雅灵动的形态，并与周围湖山景色相协调。","explanation":"大桥连接多个旅游景区，设计时反复考虑如何让新桥融入湖光山色。提篮拱突出桥梁的力量美和跨越感，画家将眼前的桥形比作嵌在绿水青山中的彩虹，这对应《巧》的“景观优美”。","references":[],"evidence":"与自然融为一体、相互辉映","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2fbd469d07e465b3":{"review":{"definition":"玉陵湖大桥改建中，旧桥混凝土全部循环再利用，251吨旧桥钢材全部回收。施工污水经集中处理达到排放标准后，用于施工区域洒水。","explanation":"旧桥拆下的混凝土和钢材分别得到再利用和回收，施工中产生的污水经处理后满足现场洒水需求。两项做法共同对应《巧》的“节约资源”。","references":[],"evidence":"旧桥混凝土100%循环再利用，旧桥251吨钢材全部被回收","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-930be7be8e1befce":{"review":{"definition":"窑洞修复完成、文化教育基地开始开展工作后，开窑村部分村民担任义务宣讲员，向游客讲述村里窑洞的历史。","explanation":"修复期间，村民的言行让工匠认识到窑洞文化的历史和修复工作的意义。修复完成后，部分村民又把窑洞的故事讲给游客听。施工中的交流和修复后的讲解体现了题中村民从“参与者”到“传承者”的变化。","references":[],"evidence":"一些村民也成为了义务宣讲员","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6c4b8d153b903d3a":{"review":{"definition":"羲和号是我国首颗太阳探测科学技术试验卫星，于2021年10月14日在太原卫星发射中心发射。","explanation":"二〇二二年新年贺词中的“羲和”逐日指这颗卫星开展太阳探测。B项准确写出了羲和号的任务类别及其在我国同类卫星中的首颗地位，因此为本题正确选项。","references":[],"evidence":"“羲和号”是我国首颗太阳探测科学技术试验卫星","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-51a56984636531ac":{"review":{"definition":"祝融号火星车在火星表面工作所需的电能由太阳能帆板提供。","explanation":"太阳能帆板将太阳光转化为电能。A项把祝融号的供电来源说成核动力电池，与题解给出的装备情况不符。","references":[],"evidence":"并没有配备核电池，在火星上的一切行动依靠太阳能帆板来提供动力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-99be74656b1029c9":{"review":{"definition":"神舟十四号航天员乘组由陈冬、刘洋、蔡旭哲组成。2022年6月5日，三人搭乘神舟十四号前往中国空间站，并在飞船与空间站组合体对接后进入天和核心舱。","explanation":"D项同时涉及飞船编号、航天员名单和目的地。神舟十四号乘组确实进入了天和核心舱，D项的错误在于把该乘组写成聂海胜等三人。","references":[],"evidence":"航天员陈冬、刘洋、蔡旭哲依次进入","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2dd94d0d7c1a40c9":{"review":{"definition":"长征途中，中央红军在四渡赤水、南渡乌江后，由毛泽东指挥北渡金沙江入川。","explanation":"歌词“调虎离山袭金沙”写的是中央红军在滇军调离后北渡金沙江的这段经历。A项所说的毛泽东与题解记载的指挥者相符。","references":[],"evidence":"“调虎离山袭金沙”是由毛泽东指挥的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fae910e359917c6b":{"review":{"definition":"四渡赤水发生在贵州、四川、云南三省交界地区。","explanation":"歌词“横断山，路难行”写的是中央红军长征途中的行军艰难。B项所引李白《蜀道难》描绘的是秦蜀道路的险峻，仅凭两处都写山路难行，不能将它们指认为同一地点。","references":[],"evidence":"四渡赤水的地点在贵州省、四川省、云南省交界地区","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bba484f72c16b736":{"review":{"definition":"《四渡赤水出奇兵》中的军民鱼水情，指长征途中沿途百姓对中央红军的支持和亲近。","explanation":"歌词用“亲人送水来解渴”表现百姓给予部队的帮助。全段叙述的是中央红军长征中的四渡赤水等行动，C项把受支持的部队写成了新四军，认错了歌词中的“我军”。","references":[],"evidence":"亲人送水来解渴，军民鱼水一家人。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ee01611020d9e401":{"review":{"definition":"楚汉战争末期，项羽兵败自刎的乌江，通常指今安徽省和县乌江镇。","explanation":"歌词“乌江天险重飞渡”中的乌江是中央红军长征途中渡过的贵州乌江。D项混淆了贵州这条河流与安徽和县的同名地点。","references":[],"evidence":"而项羽的自刎之地是现在的安\n徽省和县乌江镇。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8014fbb0034e9238":{"review":{"definition":"《七月》是《诗经·豳风》中的一篇，按一年中的时序描写农人的耕种、收获和日常生活，反映劳作的艰辛。","explanation":"讲话用“农夫艰辛劳作”概括《七月》的内容，第一空对应选项D中的《七月》。同句的《采薇》和《关雎》分别对应士兵征战和青年爱情。","references":[],"evidence":"《诗经》中反映农夫艰辛劳作的《七月》","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-12ce7d501f114c66":{"review":{"definition":"《天问》是屈原的作品，以连续发问的形式探问天地起源、日月运行、神话传说和历史往事。","explanation":"对天地起源、日月运行等问题的追问，对应讲话中的“探索宇宙奥秘”，所以第二空填《天问》。四个选项的第二个篇名中，只有D项对应这一表述。","references":[],"evidence":"探索宇宙奥秘的《天问》","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-72ec7a9d0293e4d4":{"review":{"definition":"《敕勒歌》是北朝民歌，描绘敕勒川的草原风光和牛羊放牧景象。","explanation":"“风吹草低见牛羊”写出草原上的放牧景象，对应讲话中的“反映游牧生活”，所以第三空填D项的《敕勒歌》。","references":[],"evidence":"反映游牧生活的《敕勒歌》","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-950c2f128fab2874":{"review":{"definition":"岗上遗址位于山东省滕州市，以大汶口文化中晚期遗存为主，也有部分东周、汉代遗存。该遗址入选2021年度全国十大考古新发现。","explanation":"C项把岗上遗址归入河姆渡文化晚期，与其主要遗存的大汶口文化中晚期归属冲突。题干要求选出错误说法，因此选C。","references":[],"evidence":"遗址时代以大汶口文化中晚期为主","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d717ed1f827f13d4":{"review":{"definition":"皮洛遗址位于四川省甘孜藏族自治州稻城县，地处青藏高原，入选2021年度全国十大考古新发现。","explanation":"“四川稻城”是遗址的行政区划位置，“青藏高原”是其所在的地理区域。A项所说的“位于青藏高原”准确，在本题中应排除。","references":[],"evidence":"皮洛遗址地处青藏高原","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-534e5db90989a5fd":{"review":{"definition":"郑家湖墓地位于湖北省云梦县楚王城城址东南郊，西距睡虎地墓地约3公里，入选2021年度全国十大考古新发现。","explanation":"两处墓地相隔约3公里，支持B项“相距不远”的表述。题干要求选出错误说法，因此排除B。","references":[],"evidence":"西距睡虎地墓地约\n3000米。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-89eb5366b5038460":{"review":{"definition":"明中都遗址是明太祖朱元璋在家乡安徽凤阳营建都城留下的遗址。明中都于洪武二年（1369年）诏建，后停止营建。","explanation":"朱元璋下诏营建明中都，直接支持D项所说的遗址与朱元璋有关。D项说法正确，符合本题选非条件的是C项。","references":[],"evidence":"明中都是明太祖朱元璋在家乡凤阳兴建的都城。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6937c5d60b39fce3":{"review":{"definition":"北京2022年冬奥会期间，赛事交通服务投入使用了氢燃料电池客车，北京市还投运了冬奥会配套的福田加氢站。","explanation":"赛事客车投入运营、福田加氢站提供配套，是判断C项所述冬奥会应用情况的依据。按本题答案，C项“大量使用”的说法成立，错误项为D。","references":[],"evidence":"在这届冬奥会上，投入使用的氢燃料电池客车","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c344fbc87ff0f800":{"review":{"definition":"“性犹湍水也”出自《孟子·告子上》，是告子与孟子辩论人性时所说的话。","explanation":"告子以水随决口向东或向西流为喻，主张人性本无善与不善之分。D项把这段话配给《论语》，出处有误，符合本题选错的要求。","references":[],"evidence":"“性犹湍水也，决诸东方则东流，决诸西方则西流”出自《孟子·告子上》","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bb07a4fa06c1e5b0":{"review":{"definition":"“圣人之心如明镜”见于王阳明《传习录》，以明镜比喻圣人内心清明，能随事物来感而回应。","explanation":"下句“随感而应，无物不照”承接明镜之喻，说明心清明则遇事能够照见并回应。A项所列文句与《传习录》对应正确。","references":[],"evidence":"“圣人之心如明镜，只是一个明，则随感而应，无物不照”出自王阳明的《传习录》","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e74c21b0e344dadf":{"review":{"definition":"“朝菌不知晦朔，蟪蛄不知春秋”出自《庄子·逍遥游》，以短寿生物说明寿命长短会限制其能经历的时间跨度。","explanation":"“晦朔”指月末和月初，“春秋”指春秋两季。朝菌与蟪蛄因生命短暂，无法经历相应的时间变化，呼应篇中的“小年不及大年”。B项把文句配给《庄子》，出处正确。","references":[],"evidence":"“朝菌不知晦朔，蟪蛄不知春秋”出自《庄子·逍遥游》","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1a66cc988667b266":{"review":{"definition":"“五谷者，种之美者也”出自《孟子·告子上》，孟子以五谷成熟比喻仁德修养达到成熟。","explanation":"文中说五谷虽是好种，若未成熟，连荑稗也比不上，再用“夫仁亦在乎熟之而已矣”点明仁德也贵在修养有成。C项把文句配给《孟子》，出处正确。","references":[],"evidence":"“五谷者，种之美者也，苟为不熟，不如荑稗，夫仁亦在乎熟之而已矣”出自《孟子·告子上》","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4b4e78be45ff4fdc":{"review":{"definition":"我国铁矿资源总体上贫矿多、富矿少，即低品位铁矿较多，高品位铁矿较少。","explanation":"储量描述矿产有多少，品位描述矿石的含铁程度。D项把贫矿和富矿的相对多寡说反，因此符合本题选错的要求。","references":[],"evidence":"我国铁矿资源分布具有贫矿多、富矿少的特点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-921f214e8d1ff4a5":{"review":{"definition":"原题引文：我国最大的煤层气田在山西建成投产","explanation":"晋城市政府网站在2022年6月28日发布的报道以“全国最大煤层气田”为标题，正文以项目投产、日产量和年地面抽采能力说明建设规模。国考第17题A项的“最大”可据此理解为当时报道的生产规模。20亿立方米是年抽采能力，题解另列的估算资源量属于另一项指标。按标准答案，A项排除，错误项为D。","references":[{"source":"web-9d332bcec2a6dd5f","location":"标题及正文首段","quote":"国内首个年地面抽采能力超过20亿立方米的煤层气田"},{"source":"web-b9398663fcf3dc90","location":"2022年6月27日第2版，图片新闻正文","quote":"井口日产和日外输商品气量双双突破550万立方米"}],"evidence":"我国最大的煤层气田在山西建成投产","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-8b7109c523ca9f99":{"review":{"definition":"内蒙古包头的白云鄂博矿区和江西赣州所在的赣南地区，都是我国重要的稀土产区。","explanation":"白云鄂博矿区隶属包头市，赣州位于江西南部的赣南地区。B项用包头和赣州指称这两处稀土产区，地理对应正确。","references":[],"evidence":"白云鄂博矿区隶属内蒙古自治区包头市","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f1e5c19b8488509f":{"review":{"definition":"美国地质调查局2022年1月发布的《矿产品概要》估计，中国钨矿储量为190万吨，全球约370万吨，均按所含钨金属量计。报告明确中国钨矿储量居世界首位。","explanation":"国考第17题C项可用考试前已发布的同一份报告、同一储量栏核对。题解所列加拿大49.3万吨、俄罗斯35.5万吨，与美国矿务局1995年版钨章节的储量基础栏数据吻合。储量基础和储量在报告中分列，中国旧制表内A+B+C级储量与美国口径之间也需要另有可比性依据。按统一储量口径，C项成立，选非题应选D。","references":[{"source":"web-76a25a7451e06d52","location":"Tungsten，World Mine Production and Reserves 表及 World Resources 段","quote":"China ranks first in the world in terms of tungsten resources and reserves"},{"source":"web-55b36218962d9e7e","location":"Tungsten，第183页，Canada、Russia 行","quote":"World Mine Production, Reserves, and Reserve Base"}],"evidence":"我国钨矿的储量居世界第一","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-fdce80e5d3cdbcf2":{"review":{"definition":"惊蛰处于早春，华北在此后仍可能降雪。","explanation":"惊蛰前后气温总体回升，但遇到冷空气且水汽条件合适时，华北仍可出现降雪。A项的“可能”只要求这种天气可以发生，“万里雪飘”用于描绘雪景，因此A项不属于本题要选的错误说法。","references":[],"evidence":"惊蛰后华北地区可能会出现“万里雪飘”的现象","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ad812942a5789af8":{"review":{"definition":"原题引文：金黄色的油菜花会开放，所以可以出现诗句中的景象。","explanation":"岑溪市位于北回归线以南附近，金鸡村的实地报道同时记录了菜花和蝴蝶，支持国考第18题B项描述的场景在部分地区可以出现。题解漏列的2月平均气温缺少对应地点和统计时段。广西气候资料中的全区平均只能描述广西全区，无法据此还原题解数值。按标准答案，B项排除，错误项为C。","references":[{"source":"web-4d8bbcc1450143f7","location":"第11版，岑溪市归义镇金鸡村现场报道","quote":"近日，记者走进岑溪市归义镇金鸡村，大片油菜花盛开"},{"source":"web-1b944aa007efaac3","location":"4.1.1.2 梧州市岑溪市区域概况","quote":"北纬22°37′～23°13′之间"},{"source":"web-d8bbab53cb254c37","location":"第一部分，2月份气候概况","quote":"全区平均气温为13.5℃"}],"evidence":"金黄色的油菜花会开放，所以可以出现诗句中的景象。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-3802bbcb31707f29":{"review":{"definition":"谷雨是春季最后一个节气。谷雨前后，江浙部分地方可以出现春雨中插秧的景象。","explanation":"D项的“一把青秧”对应插秧，“轻烟漠漠雨冥冥”对应细雨。谷雨前后的春雨与部分地方的插秧农事可以赶在一起，符合选项的“可能会出现”。具体插秧时间随地点和稻作安排而异。","references":[],"evidence":"谷雨前后江浙地区可能会出现“一把青秧趁手青，轻烟漠漠雨冥冥”的现象","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-90afa57b6c963fe1":{"review":{"definition":"地球外地核呈液态，以铁为主，含镍及少量较轻元素。","explanation":"D项把外地核的主要成分写成熔融的铁和铬，其中“铬”与解析所述的“镍”不符。题干要求选错误项，这一成分错误足以判定D项。","references":[],"evidence":"外地核的物质组成为液态的铁、镍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0a00ac9770278dcf":{"review":{"definition":"截至2021年底，A市所有乡镇均组建了生态强村公司，承担自然资源管理与开发、生态环境保护与修复等工作，并参与公共生态产品的供给和市场交易。","explanation":"云瀑乡的合作企业向当地生态强村公司支付300万元，购买项目所在区域的生态产品。这个例子说明，乡镇识别出有开发价值的生态资源后，可以由生态强村公司承接供给和交易，让公共生态产品形成实际收入。","references":[],"evidence":"成为公共生态产品的供给主体和市场化交易主体","disposition":"题内说明","basis":"据原题和解析编释。","title":"A市生态强村公司","related":[],"examFocus":{"国考 2023 地市级 申论#1":"从材料1的云瀑乡合作案例中，提取参与主体及其在生态产品供给和交易中的分工。","国考 2023 行政执法 申论#1":"结合材料1中A市组建生态强村公司的段落和云瀑乡案例，提取交易主体的组建情况及其参与方式。"}},"readings":[{"origin":"k-0a00ac9770278dcf","title":"A市生态强村公司","qs":["国考 2023 地市级 申论#1"],"definition":"截至2021年底，A市所有乡镇均组建了生态强村公司，承担自然资源管理与开发、生态环境保护与修复等工作，并参与公共生态产品的供给和市场交易。","explanation":"云瀑乡的合作企业向当地生态强村公司支付300万元，购买项目所在区域的生态产品。这个例子说明，乡镇识别出有开发价值的生态资源后，可以由生态强村公司承接供给和交易，让公共生态产品形成实际收入。","evidence":"成为公共生态产品的供给主体和市场化交易主体","doubt":"","references":[]},{"origin":"k-38a569b4cc108361","title":"A市生态强村公司","qs":["国考 2023 行政执法 申论#1"],"definition":"A市在生态产品价值实现试点中由各乡镇组建生态强村公司，负责自然资源管理与开发、生态环境保护与修复，并承担公共生态产品供给和市场化交易职能。","explanation":"截至2021年底，A市所有乡镇均已组建生态强村公司。云瀑乡的合作企业向该乡生态强村公司支付300万元，购买项目所在区域的生态产品。这笔交易说明乡镇安排了具体主体承接生态产品的供给和交易，是本题生态资源开发要点的一部分。","evidence":"成为公共生态产品的供给主体和市场化交易主体","doubt":"","references":[]}]},"k-15eaab5d5d5f8bf4":{"review":{"definition":"“GEP贷”是材料中A市探索的融资产品。2022年3月，芳草镇生态强村公司以调节服务类和文化服务类生态产品的使用经营权作质押担保，获得500万元贷款。","explanation":"芳草镇生态强村公司缺少实体抵押物，按原有条件融资困难。该案例中用于担保的是两类生态产品的使用经营权，所得贷款解决了“溪游记”旅游项目的建设资金需求，对应参考答案中的“催生金融产品”。","references":[],"evidence":"以芳草镇调节服务类和文化服务类两类生态产品的使用经营权作为质押担保","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-da7b6ec6c3500908":{"review":{"definition":"2022年，在L市知识产权信息服务中心引导下，川兴米粉联盟标准和地方标准先后出台，为统一产品质量要求和规范生产提供了依据。","explanation":"案例摘要应同时交代中心引导出台两类标准的做法，以及统一标准促进质量提升、推动标准化和规范化的意义。材料还列出中心指导川兴米粉取得地理标志保护的做法，其成效是带动品牌和行业发展。","references":[],"evidence":"“川兴米粉”联盟标准及地方标准先后出台","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-d46e483cd5c929cb":{"review":{"definition":"L市知识产权信息服务中心协助丰禾庄园分析生产难题，对接L市农业学院科研团队，并协调企业引进高垄草莓种植技术。","explanation":"案例摘要可把两项服务与成效分别对应。中心促成三方签署合作框架协议，由科研团队帮助解决草莓生产中的关键问题。针对传统地栽采摘费力的问题，中心协调企业尝试高垄种植，使采收更省力，较好的采光和透气条件也促进了增产。","references":[],"evidence":"企业尝试引进高垄种植技术","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4859f93707a81f3e":{"review":{"definition":"L市知识产权信息服务中心为“伊山山珍”制定商标注册方案，指导相关企业分批申请，并通过宣讲、培训和指导制定商标标识使用管理办法，推动商标规范使用。","explanation":"由于山珍品类多，中心先检索商品和服务类别，整理申请清单，再指导分批申请。针对冒牌货损害信誉的问题，中心宣讲商标法、培训商标持有人，并指导联合社制定标识使用办法。联合社负责人称，获得授权后，消费者信任度和销量有所提升，这构成摘要中的服务成效。","references":[],"evidence":"现在我们得到商标的授权，消费者对我们的信任度高了","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-58f1053a07e73a56":{"review":{"definition":"L市知识产权信息服务中心联合多个部门推行“企业+地理标志商标+标准化+农户”模式，集中推广“伊山山珍”的主导产业和重点产品。","explanation":"案例摘要应写出多部门协同的做法和产业推广成效。材料用蓝莓、竹荪、两茶一药等拳头产品受到顾客欢迎，说明该模式有助于提升重点产品的市场认可度。商标注册、授权和标识使用管理则对应案例中维护品牌信誉的做法。","references":[],"evidence":"联合多个部门合力推动“企业+地理标志商标+标准化+农户”模式","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-df3c58b3c0f7edca":{"review":{"definition":"“惠农达”和“务工达”是材料中F银行面向村民和外来务工人员提供的两项服务。前者把金融服务设在村内，后者提供工资代发、手机银行和个人快贷等服务。","explanation":"F银行把“惠农达”设在苗种村的小卖部，方便行动不便的老人就近领取养老金、办理社保。“务工达”联接用工相关各方，由银行直接把工资打到务工人员卡上，材料中的老杨因此能准时足额收到工资。短评可据此说明银行如何回应两类群体的具体需求。","references":[],"evidence":"直接由银行把钱打到我们卡上，准时足额","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-d1e64cb58219b228":{"review":{"definition":"“企心助农”是F银行组织小微企业主参与助农公益的平台，通过定向捐助、技术支持和提供工作岗位，帮助农户缓解困难、降低返贫风险。","explanation":"定向捐助回应眼前困难，技术和岗位支持则为农户持续增收提供条件。材料还提到，一些企业主有农村生活经历，对乡亲的处境感受较深。短评可用该平台说明F银行如何把对小微企业的帮扶延伸为带动企业主参与公益、助力共同富裕。","references":[],"evidence":"除了定向捐助，还会提供技术支持和工作岗位","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-420b06729d06d18b":{"review":{"definition":"党的二十大报告指出，新时代十年我国谷物总产量稳居世界首位。","explanation":"报告把谷物总产量的世界位次与十四亿多人的粮食安全保障一并列入新时代十年的成就。A项所说的指标是谷物总产量，位次与报告一致，因此在本题中应排除A项。","references":[],"evidence":"谷物总产量稳居世界首位","disposition":"独立词条","basis":"据原题和解析编释。","title":"新时代十年我国谷物总产量","related":[],"examFocus":{"国考 2023 地市级 行测#3":"对照党的二十大报告，核对新时代十年粮食生产成就所用的产量指标及其世界位次。"}},"readings":[{"origin":"k-420b06729d06d18b","title":"新时代十年我国谷物总产量","qs":["国考 2023 地市级 行测#3"],"definition":"党的二十大报告指出，新时代十年我国谷物总产量稳居世界首位。","explanation":"报告把谷物总产量的世界位次与十四亿多人的粮食安全保障一并列入新时代十年的成就。A项所说的指标是谷物总产量，位次与报告一致，因此在本题中应排除A项。","evidence":"谷物总产量稳居世界首位","doubt":"","references":[]},{"origin":"k-5b2bd2067f38e136","title":"新时代十年我国谷物总产量","qs":["国考 2023 行政执法 行测#4"],"definition":"党的二十大报告在回顾新时代十年成就时指出，我国谷物总产量稳居世界首位。","explanation":"报告给出的世界位次对应谷物总产量。A项沿用这一表述，题目要求选出错误项，因此排除A项。","evidence":"谷物总产量稳居世界首位","doubt":"","references":[]}]},"k-f278385ad21126e8":{"review":{"title":"二十大报告中的全社会研发经费支出","type":"事实与事件","definition":"2022年党的二十大报告在回顾新时代十年成就时指出，全社会研发经费支出从1万亿元增加到2.8万亿元，居世界第二位。","explanation":"报告中的世界第二位对应研发经费支出总额。同段所列的世界首位对应研发人员总量。研发投入强度衡量研发经费支出占国内生产总值的比重。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"过去五年的工作和新时代十年的伟大变革"}],"examFocus":{"国考 2023 地市级 行测#3":"依据党的二十大报告，核对新时代十年的研发经费支出、谷物产量、制造业和外汇储备的世界位次，以及高铁网规模。","江苏 2023 B类 行测#1":"核对新时代十年的成就时，分开辨别研发经费支出、研发投入强度和全球创新指数这三项指标的位次。"}},"aspects":[{"title":"研发经费支出的世界位次","uses":[{"unit":"Q1","role":"直接考查","use":"题目要求选出关于新时代十年成就的错误表述。报告记载全社会研发经费支出居世界第二位，故将其写为跃居世界第一的C项应选。（国考 2023 地市级 行测第3题、国考 2023 行政执法 行测第4题）","evidence":"全社会研发经费支出从一万亿元增加到二万八千亿元，居世界第二位","qids":["国考 2023 地市级 行测#3","国考 2023 行政执法 行测#4"]},{"unit":"Q2","role":"解题依据","use":"③把全社会研发经费、研发投入强度和全球创新指数一并列为世界首位。研发经费支出居世界第二位已足以排除③，正确组合为①②④，答案为B。（江苏 2023 B类 行测第1题）","evidence":"全社会研发经费支出从一万亿元增加到二万八千亿元，居世界第二位","qids":["江苏 2023 B类 行测#1"]}]}]},"k-8999d73c34b13da9":{"review":{"definition":"党的二十大报告将建成世界最大的高速铁路网列为新时代十年我国取得的基础设施建设成就。","explanation":"报告同时列举了高速铁路网和高速公路网，并指出两者都是世界最大的。D项引用了其中关于高速铁路网的成就，表述成立，因此在本题中应排除D项。","references":[],"evidence":"建成世界最大的高速铁路网、高速公路网","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cb2ec5d5c7ad611d":{"review":{"definition":"羲和号是我国首颗太阳探测科学技术试验卫星，于2021年10月14日在太原卫星发射中心发射。","explanation":"二〇二二年新年贺词中的“羲和”逐日对应这项太阳探测任务。B项准确写出了卫星的探测对象、试验性质及其在我国太阳探测中的首创地位。","references":[],"evidence":"“羲和号”是我国首颗太阳探测科学技术试验卫星","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5fd25b8cc8f0973b":{"review":{"definition":"中央红军长征期间，在毛泽东指挥下于四渡赤水、南渡乌江之后北渡金沙江。","explanation":"《四渡赤水出奇兵》中的“调虎离山袭金沙”指这次渡江行动，A项所述指挥者正确。同一段的“军民鱼水”写的是沿途群众对中央红军的支持，C项将部队错置为新四军。","references":[],"evidence":"“调虎离山袭金沙”是由毛泽东指挥的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a989fcfd3b8bd308":{"review":{"definition":"青鱼通常栖息在水体中下层，主要摄食螺蛳、蚌、蚬、蛤等水生动物。","explanation":"D项用青鱼作为例子，声称这类鱼主要在生态塘上层活动。青鱼常在中下层活动，其主要食物也多见于水底，因此D项是本题要求选出的错误说法。","references":[],"evidence":"通常栖息在水的中下层","disposition":"独立词条","basis":"据原题和解析编释。","title":"青鱼的栖息水层","related":[],"examFocus":{"国考 2023 地市级 行测#15":"判断青鱼栖息水层的表述时，关注它通常在哪一层水体活动。"}},"readings":[{"origin":"k-a989fcfd3b8bd308","title":"青鱼的栖息水层","qs":["国考 2023 地市级 行测#15"],"definition":"青鱼通常栖息在水体中下层，主要摄食螺蛳、蚌、蚬、蛤等水生动物。","explanation":"D项用青鱼作为例子，声称这类鱼主要在生态塘上层活动。青鱼常在中下层活动，其主要食物也多见于水底，因此D项是本题要求选出的错误说法。","evidence":"通常栖息在水的中下层","doubt":"","references":[]},{"origin":"k-f02540ec48ab657d","title":"青鱼的栖息水层","qs":["国考 2023 行政执法 行测#15"],"definition":"青鱼通常栖息于水体中下层，主要以螺蛳、蚌等为食。","explanation":"青鱼的典型活动水层在中下层，D项却称“青鱼等肉食性鱼类主要在池塘上层水体活动”。仅以选项点名的青鱼为例，就足以判定D项错误，因此本题选D。","evidence":"通常栖息在水的中下层","doubt":"","references":[]}]},"k-d293d508f53d82b3":{"review":{"definition":"西气东输一线西起新疆塔里木盆地的轮南，东至上海，途经甘肃、安徽等省区。","explanation":"D项说新疆、甘肃、安徽均在西气东输工程沿线。一线本身就连接新疆与上海并途经甘肃、安徽，足以支持D项。","references":[],"evidence":"西气东输工程贯穿了新疆、甘肃、安徽等省区","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-503f5332aa5742af":{"review":{"definition":"2022年，在L市知识产权信息服务中心引导下，川兴米粉的联盟标准和地方标准先后出台，为提升产品质量、推进标准化和规范化提供了统一依据。","explanation":"材料4写到两项服务及其成效。中心指导川兴米粉成为国家地理标志产品，带动品牌和行业发展。随后引导出台联盟标准和地方标准，推动产品提质和生产规范化。案例摘要应将两项做法分别写清，并对应各自的成效。","references":[],"evidence":"“川兴米粉”联盟标准及地方标准先后出台。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-81247a9d1eef6b5e":{"review":{"definition":"L市知识产权信息服务中心协助丰禾庄园研判生产难题，对接L市农业学院科研团队，并协调企业引进草莓高垄种植技术。","explanation":"三方合作涵盖草莓育苗基质配制、有机肥研发利用等需求，科研团队帮助企业解决了生产中的关键问题。传统地栽垄低，工人需要弯腰采摘，高垄种植让采收省力，其采光和透气优势也促进了增产。案例摘要应分别概括科研对接与技术引进的成效。","references":[],"evidence":"企业尝试引进高垄种植技术，不仅让草莓采收轻松省力","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c7b7c1663252e3e1":{"review":{"definition":"L市知识产权信息服务中心为伊山山珍定制品牌商标注册方案，指导企业分批申请，并通过商标法宣讲、培训和指导制定管理办法，帮助规范商标标识使用。","explanation":"品种多，中心便检索相关类别、整理申请清单，指导企业分批申报。以往冒牌货损害了本地山珍的信誉，中心便面向商标持有人开展培训，并指导制定标识使用管理办法。材料中的农村联合社负责人说，取得商标授权后，消费者信任度提高，销量也随之上升。案例摘要可据此把注册指导和授权使用管理写成相互衔接的做法。","references":[],"evidence":"并指导\n我们制定了《“伊山山珍”商标标识使用管理办法》。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1ba04b82345af203":{"review":{"definition":"L市知识产权信息服务中心联合多个部门，采用“企业+地理标志商标+标准化+农户”模式推广当地主导产业。","explanation":"材料4用四个要素概括多部门联合推广的做法，并以蓝莓、竹荪、两茶一药等成为拳头产品、受到市场欢迎来说明成效。案例摘要写完商标注册和使用管理后，可用这一做法及成效交代中心怎样进一步推广地方产业。","references":[],"evidence":"联合多个部门合力推动“企业+地理标志商标+标准化+农户”模式","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4dc56538d3a86707":{"review":{"definition":"党的二十大报告在回顾新时代十年成就时指出，我国制造业规模和外汇储备均稳居世界第一。","explanation":"B项并列的两项指标都符合报告。C项所说的全社会研发经费支出则居世界第二，把它写成跃居世界第一构成了本题的错误表述。","references":[],"evidence":"制造业规模、外汇储备稳居世界第一","disposition":"独立词条","basis":"据原题和解析编释。","title":"新时代十年我国制造业规模和外汇储备","related":[],"examFocus":{"国考 2023 地市级 行测#3":"依据党的二十大报告，逐项核对新时代十年粮食生产、制造业、外汇储备、研发投入和高铁建设的统计口径及规模或位次。"}},"readings":[{"origin":"k-4dc56538d3a86707","title":"新时代十年我国制造业规模和外汇储备","qs":["国考 2023 行政执法 行测#4"],"definition":"党的二十大报告在回顾新时代十年成就时指出，我国制造业规模和外汇储备均稳居世界第一。","explanation":"B项并列的两项指标都符合报告。C项所说的全社会研发经费支出则居世界第二，把它写成跃居世界第一构成了本题的错误表述。","evidence":"制造业规模、外汇储备稳居世界第一","doubt":"","references":[]},{"origin":"k-84cf989831ab111c","title":"新时代十年我国制造业规模和外汇储备","qs":["国考 2023 地市级 行测#3"],"definition":"党的二十大报告指出，新时代十年我国制造业规模和外汇储备均稳居世界第一。","explanation":"B项中的两个指标都对应世界第一。题目要求选出错误表述，真正错配位次的是C项所说的全社会研发经费支出，报告将这项支出列为世界第二。","evidence":"制造业规模、外汇储备稳居世界第一","doubt":"","references":[]}]},"k-9800e1bea42832ba":{"review":{"definition":"党的二十大报告将建成世界最大的高速铁路网列为我国新时代十年的基础设施建设成就。","explanation":"报告同时提到建成世界最大的高速铁路网和高速公路网。D项单独列出高速铁路网的建设成就，符合报告，因此在本题选非时排除。","references":[],"evidence":"建成世界最大的高速铁路网、高速公路网","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-aff19610f24cdc57":{"review":{"definition":"《黄河流域生态保护和高质量发展规划纲要》将河湟-藏羌文化区定位为农耕文化与游牧文化交汇相融的过渡地带。","explanation":"纲要所列范围主要包括上游大通河、湟水河流域，以及甘南、若尔盖、红原、石渠等地区。B项准确复述了这一文化区的过渡地带定位，选非时应排除。","references":[],"evidence":"河湟-藏羌文化区是农耕文化与游牧文化交汇相融的过渡地带","disposition":"独立词条","basis":"据原题和解析编释。","title":"河湟-藏羌文化区","related":[],"examFocus":{"国考 2023 副省级 行测#7":"对照《黄河流域生态保护和高质量发展规划纲要》，辨析河湟—藏羌文化区的地理范围和文化定位。"}},"readings":[{"origin":"k-aff19610f24cdc57","title":"河湟-藏羌文化区","qs":["国考 2023 行政执法 行测#5"],"definition":"《黄河流域生态保护和高质量发展规划纲要》将河湟-藏羌文化区定位为农耕文化与游牧文化交汇相融的过渡地带。","explanation":"纲要所列范围主要包括上游大通河、湟水河流域，以及甘南、若尔盖、红原、石渠等地区。B项准确复述了这一文化区的过渡地带定位，选非时应排除。","evidence":"河湟-藏羌文化区是农耕文化与游牧文化交汇相融的过渡地带","doubt":"","references":[]},{"origin":"k-f7688ed65ce648c1","title":"河湟-藏羌文化区","qs":["国考 2023 副省级 行测#7"],"definition":"《黄河流域生态保护和高质量发展规划纲要》所述的河湟-藏羌文化区，主要包括上游大通河、湟水河流域和甘南、若尔盖、红原、石渠等地区，是农耕文化与游牧文化交汇相融的过渡地带。","explanation":"纲要在黄河文化彰显区的布局中，用两种文化的交汇说明这一文化区的过渡性。B项对文化区性质的表述与纲要一致，本题选错误项，故排除B项。","evidence":"河湟-藏羌文化区是农耕文化与游牧文化交汇相融的过渡地带","doubt":"","references":[]}]},"k-6aa3cd990fce221c":{"review":{"definition":"脱脂棉是用原棉经脱脂等处理制成的棉制品。","explanation":"题干先列成品脱脂棉，再列原料原棉。B项的黑陶和黏土也是成品在前、原料在后。C项的镜头是摄像头的组成部件，对应的是整机与部件。","references":[],"evidence":"原棉是制造脱脂棉的原材料","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b493d6a135565ab5":{"review":{"definition":"黑陶是陶器的一类，制作黑陶使用的原料是黏土。","explanation":"B项的黑陶是制成品，黏土是制作原料，词序与脱脂棉、原棉一致。D项的视力表是测量视力的工具，两个词指向被测对象和测量工具。","references":[],"evidence":"黏土是制造黑陶的原材料","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c653d017b1d92f8b":{"review":{"definition":"刑事警察承担打击犯罪的工作，侦查刑事案件是其中一项具体任务。","explanation":"C 项的“打击犯罪”说明刑事警察做什么，与右侧“外交人员—对外交涉”同为职业与工作内容的对应。B 项的“刑事案件”指侦查的对象。若表述为“侦查刑事案件”，才是在说具体任务。","references":[],"evidence":"刑事警察的工作内容是打击犯罪","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d4e83303eb6ed1d7":{"review":{"definition":"对外交涉是外交人员的工作内容之一，指为处理涉外事务同有关方面沟通、协商。","explanation":"C 项右侧的“外交人员—对外交涉”与左侧的“刑事警察—打击犯罪”同为职业与工作内容的对应。D 项右侧的“外交领事—对外交涉”也可以体现这一关系，但左侧的刑事警察和交通警察是并列的警种，因此 D 项两侧的关系不同。","references":[],"evidence":"外交人员的工作内容是对外交涉","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6d38083ea4b5d1df":{"review":{"definition":"耀然灯饰形成了自己的原创设计思路，并以熟练的制作工艺实现灯饰的艺术造型。","explanation":"方经理把“灯饰”拆成照明与艺术设计两层。获国际大奖的“天鹅灯”以姿态各异的天鹅构成独特外观，人工吹制成形则体现了工人的技艺和匠心。两处信息共同支撑第1题“提升艺术设计能力”这一经验。","references":[],"evidence":"每一盏灯都凝聚着匠人之心。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c75359a4ebc62805":{"review":{"definition":"耀然灯饰针对不同使用场景提供相应的照明功能，并把创意、时尚和现代人文理念融入产品。","explanation":"“玉叶灯”把树叶造型与调光、色温切换功能结合，适应不同场合。“星光灯”允许用户自由组合，并支持语音控光。这些例子说明企业如何在基本照明功能上增加审美价值和个性化体验，对应第1题“赋予产品更多价值”。","references":[],"evidence":"照明只是消费者对灯的基本要求，我们还要赋予它更多的价值。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-390e21071d073ad8":{"review":{"definition":"耀然灯饰聘请照明专家和设计团队担任顾问，与科研机构、高校合作，并将科研成果转化为产品。","explanation":"2019年，耀然灯饰与S大学共建半导体照明技术研究中心，借助高校的人才和科技资源提升产品技术含量。这说明企业怎样把“用照明科技创造美好生活”的品牌主张落实到产品上，对应第1题“科技助力品牌建设”。","references":[],"evidence":"将科研成果转\n化为产品，进一步提升产品的技术含量。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-49b03adf0714c639":{"review":{"definition":"耀然灯饰深耕博物馆、酒店、商业空间和户外照明等细分市场，针对不同空间的专业需求建立多元产品体系。","explanation":"材料用博物馆灯光“讲故事”和商场灯光当“引导员”说明，不同空间对照明的要求会随展陈、导引等用途而变化。按这些专业用途拓展产品，对应第1题“构建多元产品体系”。","references":[],"evidence":"深耕博物馆\n照明、酒店照明、商业空间照明和户外照明等细分市场，建立全面、多元的产品体系。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-08d3619507c20d29":{"review":{"definition":"耀然灯饰主要通过线上直播触达年轻消费者并销售单品，通过线下门店提供服务和产品体验。","explanation":"线上直播扩大触达并促进单品销售，线下全屋光环境体验店让顾客在具体场景中感受照明和服务。方经理还提到，渠道创新带来了业务增量，也传播了品牌价值理念。这些做法和成效对应第1题“创新用户触达渠道”。","references":[],"evidence":"主要负责年轻消费者的触达和单品的销售。线下门店则主要负责\n服务与体验","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-42f5d19b3573fe55":{"review":{"definition":"2017年，河北省承德市塞罕坝机械林场的造林群体获得联合国“地球卫士奖”。几代林场建设者持续造林，把荒原变成林海。","explanation":"C项的奖杯对应塞罕坝造林群体的获奖事实，“荒原变林海”对应当地的造林成就，林场所在地与河北展区相符。其余展品所涉人物或技艺的代表性地点分别是广西百色、天津杨柳青和江苏连云港，与各自选项所列展区不符。","references":[],"evidence":"在河北展区，观众在“地球卫士奖”奖杯前感叹荒原变林海的人间奇迹","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-323857be94c8c198":{"review":{"definition":"西岭金矿位于山东省莱州市三山岛矿区。2023年8月勘探成果发布时，它是国内已发现的资源量规模最大的单体金矿床。","explanation":"2023年8月2日，勘探成果经山东省自然资源厅备案，累计探获金金属量592.186吨。题中“最大”按当时公布的单体金矿床资源量规模理解，所在地为山东莱州，因此选非题中D项所称“在云南省内”错误。","references":[{"source":"web-359b35fd2f5a12bd","location":"正文，2023年8月10日山东黄金集团发布西岭金矿成果段","quote":"国内资源量规模最大的巨型单体金矿床"},{"source":"web-88d890ea7b99304a","location":"黄金矿山情况，资源储量表附注1","quote":"累计探获金金属量 592.186 吨"},{"source":"web-b749c11386dfb2e6","location":"山东西岭金矿段","quote":"山东省莱州市三山岛矿区西岭金矿"},{"source":"web-359b35fd2f5a12bd","location":"正文，2023年8月10日山东黄金集团发布西岭金矿成果段","quote":"在山东莱州探明国内资源量规模最大的巨型单体金矿床"},{"source":"web-f7b768e2169142ae","location":"2025年11月14日发布，正文首段","quote":"新中国成立以来发现的规模最大单体金矿床"},{"source":"web-0392dde2f987c18d","location":"2023年度地质找矿成果，西岭金矿段","quote":"该成果提交备案金金属量592.186吨"}],"evidence":"西岭金矿位于山东省莱州市","disposition":"独立词条","basis":"据原题与所列资料编释。","title":"山东莱州西岭金矿","related":[],"examFocus":{"国考 2024 副省级 行测#15":"核对我国主要矿产的分布与开发情况，留意金矿规模的比较口径及其所在地。"}},"readings":[{"origin":"k-323857be94c8c198","title":"山东莱州西岭金矿","qs":["国考 2024 副省级 行测#15"],"definition":"西岭金矿位于山东省莱州市三山岛矿区。2023年8月勘探成果发布时，它是国内已发现的资源量规模最大的单体金矿床。","explanation":"2023年8月2日，勘探成果经山东省自然资源厅备案，累计探获金金属量592.186吨。题中“最大”按当时公布的单体金矿床资源量规模理解，所在地为山东莱州，因此选非题中D项所称“在云南省内”错误。","evidence":"西岭金矿位于山东省莱州市","doubt":"","references":[{"source":"web-359b35fd2f5a12bd","location":"正文，2023年8月10日山东黄金集团发布西岭金矿成果段","quote":"国内资源量规模最大的巨型单体金矿床"},{"source":"web-88d890ea7b99304a","location":"黄金矿山情况，资源储量表附注1","quote":"累计探获金金属量 592.186 吨"},{"source":"web-b749c11386dfb2e6","location":"山东西岭金矿段","quote":"山东省莱州市三山岛矿区西岭金矿"}]},{"origin":"k-3b8774f9b695e605","title":"山东莱州西岭金矿","qs":["国考 2024 地市级 行测#14"],"definition":"西岭金矿位于山东省莱州市。2023年8月发布勘探成果时，它是国内已发现的资源量规模最大的单体金矿床。","explanation":"2023年8月10日，山东黄金集团公布西岭金矿勘探成果，累计探获金金属量592.186吨。以此时点和单体金矿床资源量口径判断，D项所称“在云南省内”错误。2025年11月14日，自然资源部公布辽宁大东沟金矿共探明金金属量1444.49吨，为新中国成立以来发现的规模最大单体金矿床，当时西岭金矿的排名由此更新。","evidence":"西岭金矿位于山东省莱州市","doubt":"","references":[{"source":"web-359b35fd2f5a12bd","location":"正文，2023年8月10日山东黄金集团发布西岭金矿成果段","quote":"在山东莱州探明国内资源量规模最大的巨型单体金矿床"},{"source":"web-88d890ea7b99304a","location":"黄金矿山情况，资源储量表附注1","quote":"累计探获金金属量 592.186 吨"},{"source":"web-f7b768e2169142ae","location":"2025年11月14日发布，正文首段","quote":"新中国成立以来发现的规模最大单体金矿床"}]},{"origin":"k-dd2375b7bb139737","title":"山东莱州西岭金矿","qs":["国考 2024 行政执法 行测#16"],"definition":"西岭金矿位于山东省莱州市三山岛矿区。2023年8月备案的金金属量为592.186吨，按当时已发现的单体金矿床资源规模计居国内首位。","explanation":"本题将D项“目前最大的金矿”按当时国内已发现单体金矿床的金资源量规模理解。西岭金矿的所在地是山东莱州，因此D项写“云南省内”错误。该排名对应的是当时的矿床资源量口径。","evidence":"我国目前最大的金矿在云南省内","doubt":"","references":[{"source":"web-0392dde2f987c18d","location":"2023年度地质找矿成果，西岭金矿段","quote":"该成果提交备案金金属量592.186吨"}]}]},"k-531a2b182c0c8c6e":{"review":{"definition":"黄山“五绝”指奇松、怪石、云海、温泉、冬雪，“五胜”指历史遗存、书画、文学、传说、名人。","explanation":"“五绝”概括黄山的自然景观，“五胜”概括其人文特色。D项在“五绝”之外列出的五类人文内容与“五胜”逐一对应，因此D项正确。","references":[],"evidence":"历史遗存、书画、文学、传说、名人“五胜”著称于世","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ea2721e80e71bd34":{"review":{"definition":"瓦西里升天大教堂位于俄罗斯莫斯科红场南端，以色彩鲜明的洋葱形穹顶为显著特征。","explanation":"D项将“炫丽色彩”和“洋葱顶”结合起来描写，解析据此指向瓦西里升天大教堂。它所在的国家是俄罗斯，因此与西班牙的对应错误，本题选D。","references":[],"evidence":"位于俄罗斯红场南端的最美教堂——瓦西里升天大教堂","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-91b495cc58f94f05":{"review":{"definition":"比萨斜塔是意大利托斯卡纳比萨城内比萨大教堂的独立钟楼，位于奇迹广场。","explanation":"A项“倾斜却不塌陷，永远是将倒未倒的模样”描写的是塔身倾斜这一外观特征，由此可识别比萨斜塔。它位于意大利，A项的国别对应正确。","references":[],"evidence":"比萨斜塔位于意大利托斯卡纳省比萨城","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d3804a11a74d896b":{"review":{"definition":"格林尼治天文台于1675年创建于英国伦敦格林尼治，是历史上确定本初子午线和建立时间基准的重要地点。","explanation":"B项以“钟表上的指针”和“格林尼治的时间”提示这座天文台与计时基准的关系。天文台位于英国伦敦，因此B项的国别对应正确。","references":[],"evidence":"1675年创建于英国伦敦的皇家格林尼治花园","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9025f59f237f8984":{"review":{"definition":"泰姬陵位于印度阿格拉，是莫卧儿皇帝沙·贾汗为纪念妻子而建的陵墓，其主体以白色大理石建造。","explanation":"C项的“白色大理石”对应陵墓主体的建筑材料，“续写爱情的生命”对应沙·贾汗建陵纪念妻子的背景。这两处线索共同指向泰姬陵，故与印度的对应正确。","references":[],"evidence":"“在一片常绿的簇拥下，白色大理石熠熠闪光，续写爱情的生命”提到的是印度泰姬陵。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-458de7509802a281":{"review":{"definition":"一些蚜虫吸食小麦汁液，七星瓢虫可以捕食蚜虫。","explanation":"第101题中，第一项蚜虫取食第三项小麦，第二项七星瓢虫又取食第一项蚜虫。两段关系的方向都与D项一致。","references":[],"evidence":"蚜虫会吸食小麦的汁液","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bac2fc29ed736280":{"review":{"definition":"老鼠可以取食玉米，黄鼬可以捕食老鼠。","explanation":"第101题D项中，第一项老鼠吃第三项玉米，第二项黄鼬又捕食第一项老鼠。这分别对应题干中蚜虫吸食小麦汁液、七星瓢虫捕食蚜虫的两段关系。","references":[],"evidence":"老鼠吃玉米，二者为捕食者与被捕食对象的对应关系；黄鼬即黄鼠狼，会捕食老鼠","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4d6d86ce59ba886a":{"review":{"title":"吨与千克","type":"事实与事件","definition":"1 吨等于 1 000 千克；公斤是千克的通称。","explanation":"两边同时乘以一万，换算比例不变，1 万吨仍对应 1 000 万千克。","basis":"参照所列资料编释；适用条件和推演见辅助诠释。","references":[{"source":"metre","location":"与国际单位制并用的单位 · tonne"}],"basisGroup":"量纲与单位换算"}},"k-882de4a118a93487":{"review":{"title":"亿吨与万吨","type":"事实与事件","definition":"1 亿吨等于 10 000 万吨。","explanation":"“亿”是 10⁸，“万”是 10⁴，吨这一单位相同。例如 9 000 万吨等于 0.9 亿吨。","basis":"按公式或逻辑关系推导；适用条件见释义与诠释。","references":[],"basisGroup":"量纲与单位换算"}},"k-81fbbd1305e0c3d7":{"review":{"definition":"隆金公司长期专注汽车功能配件，从为国产汽车生产门把手起步，把产品做到行业顶尖，再依托配件业务开拓细分市场。","explanation":"材料说，隆金公司在三十多年里把看似普通的门把手做到行业顶尖，同时挖掘汽车配件的细分需求，向高端、新能源和国际汽车市场拓展。长期积累产品优势和依托本业拓展市场，共同构成本题“始终保持专注”的理由。","references":[],"evidence":"三十多年深耕汽车配件领域，将产品做到行业顶尖","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ebf165412205315f":{"review":{"definition":"隆金公司通过建设数字化车间提升生产效率、降低运营成本，并通过海外研发中心和校企合作引进、培养技术人才。","explanation":"据材料，数字化车间使隆金公司的生产效率提高了28%、运营成本降低了12%。公司还在推进智能工厂建设，通过海外研发中心吸引创新人才，并与高校合作培养技术能手和行业专家。生产环节的降本增效和研发环节的人才积累，共同支撑本题“技术实力雄厚”的归纳。","references":[],"evidence":"布局建立海外研发中心，吸引了200多名创新人才","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4df31a525ea73d9e":{"review":{"definition":"材料中的N市拥有门类齐全的制造业体系，并通过建立企业培育库、出台制造业发展和企业培育政策，支持当地企业成长。","explanation":"汽车及零部件是N市的支柱产业集群之一，为隆金所在行业提供了地方产业基础。市政府建立企业培育库并出台制造业高质量发展和卓越企业培育相关文件，形成政策支持。产业基础和政府培育共同构成本题“产业支撑有力”的外部条件。","references":[],"evidence":"N市建立了企业培育库","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-9cfea3382e902e7f":{"review":{"definition":"2023年7月，习近平在全国生态环境保护大会上概括了我国生态文明建设的四个重大转变，即由重点整治到系统治理、由被动应对到主动作为、由全球环境治理参与者到引领者、由实践探索到科学理论指导。","explanation":"点面结合、标本兼治对应①，转变观念、压实责任对应②，承担大国责任对应③，深化对生态文明建设规律的认识并形成科学理论对应④。⑤所说的压力结构变化未列入大会概括，因此选①②③④。","references":[],"evidence":"实现由重点整治到系统治理的重大转变","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b428603655061451":{"review":{"definition":"锡矿是我国的优势矿产之一。题解以我国锡资源丰富、锡储量和产量长期居世界前列来说明这一点。","explanation":"A项判断的是锡矿是否属于我国优势矿产。题解同时给出广西、云南为我国锡矿储量较多的地区，说明国内资源分布情况。A项成立，在要求选出错误说法的本题中应排除。","references":[],"evidence":"锡矿是我国的优势矿产资源之一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-05d4f2b54f88d694":{"review":{"definition":"2017年，我国在南海北部神狐海域完成首轮天然气水合物试采，实现连续稳定产气60天。","explanation":"B项只判断我国是否已在南海实现天然气水合物试采。试采的地点和连续产气记录直接支持B项，因此在本题选非条件下应排除。","references":[],"evidence":"2017年，我国海域天然气水合物在南海北部神狐海域第一轮试采成功","disposition":"独立词条","basis":"据原题和解析编释。","title":"2017年南海神狐海域天然气水合物试采","related":[],"examFocus":{"国考 2024 地市级 行测#14":"分别核对矿产资源的分布、矿床的规模口径与海上资源的试采进展。"}},"readings":[{"origin":"k-05d4f2b54f88d694","title":"2017年南海神狐海域天然气水合物试采","qs":["国考 2024 地市级 行测#14"],"definition":"2017年，我国在南海北部神狐海域完成首轮天然气水合物试采，实现连续稳定产气60天。","explanation":"B项只判断我国是否已在南海实现天然气水合物试采。试采的地点和连续产气记录直接支持B项，因此在本题选非条件下应排除。","evidence":"2017年，我国海域天然气水合物在南海北部神狐海域第一轮试采成功","doubt":"","references":[]},{"origin":"k-7dab3d4c880dbe6a","title":"2017年南海神狐海域天然气水合物试采","qs":["国考 2024 行政执法 行测#16"],"definition":"2017年，我国在南海北部神狐海域成功完成第一轮海域天然气水合物试采。","explanation":"B项所说的「已在南海实现试采」对应神狐海域的这次试采。年份和地点即可确认B项成立，因此本题选错误说法时应排除B。","evidence":"2017年，我国海域天然气水合物在南海北部神狐海域第一轮试采成功","doubt":"","references":[]}]},"k-a1d4d5a78415eadf":{"review":{"title":"罗布泊钾盐资源","type":"事实与事件","definition":"新疆罗布泊是我国钾盐的主要产地之一，也是我国开发盐湖钾盐资源的地区之一。","explanation":"罗布泊的钾盐资源与现代盐湖有关。青海柴达木的现代盐湖也是我国钾盐的主要产地。","basis":"据关联原题及所列出处编释。","references":[{"source":"salt","location":"罗布泊钾盐"}],"examFocus":{"国考 2024 地市级 行测#14":"分别核对矿产的产地、资源优势和矿床规模，以及海上试采进展。"}},"aspects":[{"title":"钾盐与罗布泊的产地对应","uses":[{"unit":"Q1","role":"直接考查","use":"题目要求选出错误说法。C项把钾盐与新疆罗布泊对应，表述正确。按原题口径，应选D，题中所指的西岭金矿位于山东莱州。","evidence":"新疆罗布泊是我国钾盐的主要产地之一","qids":["国考 2024 地市级 行测#14","国考 2024 行政执法 行测#16"]}]}]},"k-25803b854f9e9e91":{"review":{"definition":"水运仪象台是北宋苏颂、韩公廉等人研制的大型水力天文仪器，兼具天文观测、天文演示和报时功能。","explanation":"B项的复原研究以北宋仪器为对象，其研制时代超出交流会设定的两汉范围，因此最不可能入选。","references":[],"evidence":"水运仪象台是北宋时期苏颂、韩公廉等人发明制造的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1dd9c1597ffc7404":{"review":{"definition":"太初历是西汉汉武帝时期制定的历法，以正月为岁首。","explanation":"A项研究太初历制定中的年干支变化。太初历的制定属于西汉历法发展，因此这项研究符合交流会的两汉科技主题。","references":[],"evidence":"太初历是汉武帝时期制定的一种历法","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cc64df08ed033f7d":{"review":{"definition":"原题引文：《汜胜之书》中的栽培技术及区种法探析","explanation":"中国科学院自然科学史研究所资料采用《氾胜之书》这一通称。本题所给C项写作《汜胜之书》，可从“栽培技术及区种法”辨认其所指。该农书属于两汉科技研究范围，故C项符合交流会主题。本题选B，水运仪象台属于北宋。","references":[{"source":"web-fb19333909ba6e7c","location":"《氾胜之书》小节","quote":"《氾胜之书》的作者氾胜之，是西汉末年人"},{"source":"web-2715c02f9624b866","location":"“星汉灿烂——追溯两汉科技”题C项","quote":"《汜胜之书》中的栽培技术及区种法探析"}],"evidence":"《汜胜之书》中的栽培技术及区种法探析","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-92bfb7e12aafa703":{"review":{"definition":"直辕犁是以直形犁辕连接牵引装置的耕犁，西汉时期已使用。","explanation":"D项讨论直辕犁的推广及其对农业生产的影响。西汉时期已有这种农具，因此相关研究可以纳入两汉农业技术的讨论。","references":[],"evidence":"西汉出现的直辕犁","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5fa16c5b63a4c7c0":{"review":{"definition":"2017年，河北省承德市塞罕坝机械林场建设者获得联合国“地球卫士奖”。几代建设者在当地造林，使荒原变为林海。","explanation":"C项同时给出“地球卫士奖”奖杯和“荒原变林海”两条线索，指向塞罕坝的造林成就。林场位于河北承德，因此该场景与河北展区相符。","references":[],"evidence":"在河北展区，观众在“地球卫士奖”奖杯前感叹荒原变林海的人间奇迹","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-25bbe8375125fcbc":{"review":{"definition":"2018年，黄文秀到广西壮族自治区百色市乐业县新化镇百坭村担任驻村第一书记。","explanation":"A项以黄文秀生前的日记作为展品线索。她的家乡和驻村工作地都在广西百色，按题中的地方展区与代表性事迹配对，应归入广西展区，A项配到天津有误。","references":[],"evidence":"黄文秀出生于广西壮族自治区百色市","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-1335823d6245aaa5":{"review":{"definition":"杨柳青木版年画是天津市的民间传统美术，采用木版刻印与手工绘制相结合的技法。","explanation":"B项展示杨柳青年画代表性传承人现场制作年画。按本题以项目的地域归属匹配地方展区的设定，这一场景对应天津展区，B项配到江苏有误。","references":[],"evidence":"杨柳青木版年画，是天津市民间传统美术","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fa45f0a41880ad8c":{"review":{"definition":"王继才、王仕花夫妇自1986年起驻守开山岛。开山岛位于江苏省连云港市。","explanation":"D项的“今日开山岛”模型和夫妇守岛事迹指向同一地点。按开山岛所在地匹配地方展区，这一场景对应江苏展区，D项配到广西有误。","references":[],"evidence":"开山岛位于江苏省连云港市","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c18c0b596d0c6e87":{"review":{"definition":"公历9月和11月各有30天，10月和12月各有31天。","explanation":"9月和10月各取28天后分别余2天和3天，用活动次数可确定9月29日是周五、9月30日是周六。10月至12月共92天，从9月30日到12月31日相隔13周又1天，所以12月31日是周日，正好是当年最后一次骑行，选A。","references":[],"evidence":"10-12月共31+30+31=92天","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6706a236e08e0456":{"review":{"definition":"七星瓢虫捕食蚜虫，取食小麦的蚜虫会吸食小麦汁液。","explanation":"按题干词序，第二项七星瓢虫捕食第一项蚜虫，第一项蚜虫取食第三项小麦。题目用取食方向归纳两段关系，其中蚜虫吸食植物汁液属于植食。B项的稗草与水稻争夺田间资源，缺少第一项取食第三项的关系。","references":[],"evidence":"蚜虫会吸食小麦的汁液","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3dc1a34009110215":{"review":{"definition":"黄鼬俗称黄鼠狼，可以捕食老鼠，老鼠也可以取食玉米。","explanation":"D项中，第二项黄鼬捕食第一项老鼠，第一项老鼠取食第三项玉米。两段取食的方向和词序都与题干中七星瓢虫捕食蚜虫、蚜虫吸食小麦汁液相同。","references":[],"evidence":"黄鼬即黄鼠狼，会捕食老鼠","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-41a2cb9e3ec0cf7e":{"review":{"definition":"冯教授团队从清池村村民熟悉的生活场景入手，通过一起动手改造来接近和启发村民。","explanation":"起初团队尝试授课，村民响应很少。团队发现村民多从生活中学习，便从村民平时聚坐聊天的地方入手，用本地毛竹和石头建起大椅子。村民看到实际效果后逐渐改观，有人主动邀请团队改造自家院子。老金利用自家老物件办起家庭美术馆，从来访者的欣赏中获得自豪感。这组事例对应参考答案中的“接近、启发村民”。","references":[],"evidence":"尊重村民的学习习惯，和村民一起动手改造","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-049111170e1d80ba":{"review":{"definition":"冯教授团队在清池村重新挖掘传统习俗的文化内涵，并策划重现承载这些内涵的仪式。","explanation":"“烧奔塔”寄托代代繁衍、风调雨顺的愿望，“成人礼”表达青年对成家立业的担当。材料分别写了重新发掘“烧奔塔”的寓意和重现“成人礼”的实践。本题据此归纳团队如何让人们重新认识传统文化及其承载的乡村社会道德秩序。","references":[],"evidence":"清池重新挖掘\n出“烧奔塔”活动的文化内涵，重现“成人礼”仪式","disposition":"题内说明","basis":"据原题和解析编释。","title":"复原传统习俗","related":[],"examFocus":{"国考 2024 地市级 申论#1":"从给定资料1介绍村庄传统习俗的段落中，提取冯教授团队挖掘本土文化的具体做法。","国考 2024 行政执法 申论#1":"从给定材料1关于清池村节俗和仪式的叙述中，提取冯教授团队开展文化活动的具体做法。"}},"readings":[{"origin":"k-049111170e1d80ba","title":"复原传统习俗","qs":["国考 2024 行政执法 申论#1"],"definition":"冯教授团队在清池村重新挖掘传统习俗的文化内涵，并策划重现承载这些内涵的仪式。","explanation":"“烧奔塔”寄托代代繁衍、风调雨顺的愿望，“成人礼”表达青年对成家立业的担当。材料分别写了重新发掘“烧奔塔”的寓意和重现“成人礼”的实践。本题据此归纳团队如何让人们重新认识传统文化及其承载的乡村社会道德秩序。","evidence":"清池重新挖掘\n出“烧奔塔”活动的文化内涵，重现“成人礼”仪式","doubt":"","references":[]},{"origin":"k-a25a4afe63b04416","title":"复原传统习俗","qs":["国考 2024 地市级 申论#1"],"definition":"冯教授团队通过挖掘清池传统习俗的文化内涵、重现其中的仪式，让人们重新认识当地传统文化和乡村社会道德秩序。","explanation":"“烧奔塔”是村里原本保留的中秋习俗，寄托了繁衍不息、风调雨顺的愿望。团队重新挖掘这项活动的内涵，并重现表达青年人担当和成家立业信心的“成人礼”。本题的做法要点涉及两项具体行动，即挖掘既有习俗的内涵和重现其中的仪式。","evidence":"出“烧奔塔”活动的文化内涵，重现“成人礼”仪式","doubt":"","references":[]}]},"k-eaf088118167334c":{"review":{"definition":"隆金公司长期专注于汽车功能配件，从为国产汽车生产门把手起步，并在这一领域拓展高端、新能源和国际汽车市场。","explanation":"材料写明隆金公司从1986年开始生产汽车门把手，经过三十多年做到行业顶尖，并成为国内外知名整车厂的核心供应商。长期专注说明其细分产品优势从何而来，拓展高端、新能源和国际市场说明它如何延伸这一优势，两者共同构成本题“始终保持专注”的作答要点。","references":[],"evidence":"三十多年深耕汽车配件领域，将产品做到行业顶尖","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-cc9c4574c6a62f5d":{"review":{"definition":"隆金公司以数字化车间和智能工厂建设提升生产能力，并通过海外研发中心和校企合作引进、培养技术人才。","explanation":"材料记载，已建成的全自动数字化车间使生产效率提高28%、运营成本降低12%，智能工厂在材料所述时点仍在建设。海外研发中心吸引创新人才，高校合作培养技术能手和行业专家。这些事实从生产效率和研发能力两个方面支撑本题的“技术实力雄厚”。","references":[],"evidence":"建设数字化车间、智能工厂，降本增效","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c41605e5c6f7b9b8":{"review":{"definition":"材料中的N市形成了门类齐全的制造业体系和包括汽车及零部件在内的产业集群，并通过企业培育库及配套政策推动企业成长。","explanation":"制造业体系和汽车及零部件产业集群构成隆金公司所在行业的地方产业基础。企业培育库和制造业企业培育政策体现了政府对企业发展壮大的支持。本题将这些外部条件归纳为“产业支撑有力”。","references":[],"evidence":"N市建立了企业培育库","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-617bc5b51533628c":{"review":{"definition":"材料3中，扎染集团总经理认为非遗法实施增强了企业发展非遗产业的信心，文化传媒公司负责人认为非遗法为企业开展非遗保护、传承和传播指明了方向。","explanation":"扎染集团把传统染、织、绣技艺与研发、时尚设计及数码技术结合，体现产业发展的动力和信心。文化传媒公司开展非遗展览展示、产品开发和品牌打造，体现企业业务方向。两家企业的发言分别支撑情况报告中的两项实施成效。","references":[],"evidence":"非遗法的实施给集团的发展注入了新动力，坚定了非遗产业发展的战略信心。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-663932a5e61c3ed9":{"review":{"definition":"材料3中的艺术研究院研究员指出，随着非遗法的实施，人们逐步认识到一些民间文化的价值。","explanation":"研究员以关公庙会常与弘扬诚信相联系、岳飞庙会与爱国精神相联系为例，说明公众逐步认识到民间活动所承载的文化内涵。报告将这一认识变化列为实施成效。","references":[],"evidence":"随着非遗法的实施，人们逐步认识到一些民间文化的价值。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e6158c82c8dad87b":{"review":{"definition":"材料3中的市非遗保护协会负责人指出，随着保护工作持续深入，专业化和信息化要求提高，现有非遗保护人才队伍尚难适应。","explanation":"发言指出的是现有队伍能力与工作要求之间的差距。报告将其列为实施不足。同一发言中的严把传承人入口关针对传承人遴选，属于另一项工作。","references":[],"evidence":"专业化、信息化要求越来越高，现有从事非遗保护的人才队伍还不","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c2744839d74471e4":{"review":{"definition":"材料3中的大学教授指出，非遗保护理念虽已获得广泛认同，部分地方落实非遗法仍有欠缺，表现为未履行保护传承义务或借活化之名过度开发。","explanation":"前一种表现是应做的保护传承工作没有落实，后一种表现是开发超出了合理活化的范围。报告可将二者归入同一项实施不足，并对应教授提出的由主管部门进一步研究地方落实办法的建议。","references":[],"evidence":"有的不履行非遗保护、传承义务，有的以活化名义进行过度开发。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-b241b57fb62b4fee":{"review":{"definition":"2023年7月全国生态环境保护大会上，习近平将我国生态文明建设的成就概括为四个重大转变：由重点整治到系统治理、由被动应对到主动作为、由全球环境治理参与者到引领者、由实践探索到科学理论指导。","explanation":"第6题①②③④依次对应治理方式、行动主动性、全球环境治理角色和理论指导的转变。⑤谈的是压力结构变化，超出了大会概括的四项，故选A。","references":[],"evidence":"实现由全球环境治理参与者到引领者的重大转变","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-927ab355a83e94ef":{"review":{"definition":"锡矿是我国的优势矿产资源之一，我国锡资源储量和锡产量均居世界前列。","explanation":"解析从探明储量说明锡矿的资源优势，并列举广西、云南为储量较集中的地区。A项关于锡矿资源地位的表述正确，因而在本题问「说法错误」时应排除A。","references":[],"evidence":"锡矿是我国的优势矿产资源之一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c8a03f374554ca90":{"review":{"definition":"2017年，位于河北省承德市的塞罕坝机械林场三代建设者获得联合国「地球卫士奖」。","explanation":"塞罕坝几代建设者在坝上地区造林，把荒原变成林海。C项中的奖杯和「荒原变林海」指向同一事迹，林场所在地又与河北展区对应，因此选C。","references":[],"evidence":"——“地球卫士奖”。塞罕坝机械林场位于河北省承德市","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e93d8ba732284fb7":{"review":{"definition":"蚜虫可吸食小麦的汁液，七星瓢虫可捕食蚜虫。","explanation":"第96题中，第一项蚜虫取食第三项小麦，第二项七星瓢虫捕食第一项蚜虫。蚜虫在两组关系中的角色不同。B项的稗草与水稻是竞争关系，与题干第一项和第三项的取食关系不同。","references":[],"evidence":"蚜虫会吸食小麦的汁液","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b4ef1dc7596c391b":{"review":{"definition":"老鼠可取食玉米，黄鼬又叫黄鼠狼，可捕食老鼠。","explanation":"第96题D项中，第一项老鼠取食第三项玉米，第二项黄鼬捕食第一项老鼠。两个关系的方向分别与题干的蚜虫取食小麦、七星瓢虫捕食蚜虫一致。","references":[],"evidence":"黄鼬即黄鼠狼，会捕食老鼠","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-85b04704b3a94ecf":{"review":{"definition":"据材料，今州粮仓于20世纪50年代在丛江落成，因丛江古称“今州”而得名，曾承担粮食储存任务。20世纪末储粮功能弱化，粮仓后来转作五金、仓储、广告等小业态经营，经营萧条后废弃多年。","explanation":"展板的“前世”可沿储粮、转作经营、废弃的顺序展开。废弃期间完好保留下来的“万担仓”是后续改造的基础，也把粮仓的历史与园区的现状连了起来。","references":[],"evidence":"20世纪末，粮仓的储粮功能逐渐弱化，衰落的步伐不断加速。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c0e606e4cbc51a00":{"review":{"definition":"改造后的今州粮仓通过沉浸式展陈、旧仓再利用和主题活动延续粮食文化，使昔日的储粮空间成为市民和游客的文化活动场所。","explanation":"“云间麦田”用麦穗、草垛和棉花云呈现丰收景象，部分旧仓改成剧场、展馆等空间，承办爱粮节粮主题日等活动。筒仓涂鸦《稻田守望者》展示丛江大米航天育种的主题。这些细节可写入展板的“今生”部分，说明“精神粮仓”让游客体验和了解什么。","references":[],"evidence":"今州粮仓特意打造“云间麦田”展厅，让人们得以通过唯美的场景感悟粮食文化。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6ac8c8091aa99122":{"review":{"title":"2023年中央金融工作会议的货币政策取向","type":"事实与事件","definition":"2023年10月30日至31日召开的中央金融工作会议提出，始终保持货币政策的稳健性，更加注重做好跨周期和逆周期调节，充实货币政策工具箱。","explanation":"跨周期调节着眼于不同经济周期阶段之间的政策衔接，逆周期调节着眼于缓和当前经济波动。会议将这些要求置于营造良好货币金融环境、提高金融服务质量的部署中。","basis":"据关联原题及所列出处编释。","references":[{"source":"finance","location":"2023年中央金融工作会议"}],"related":["k-72228e652f9d5cd4"],"domain":"经济","examFocus":{"国考 2025 副省级 行测#5":"对照中央金融工作会议部署，分别核对货币政策的取向与调节方式、金融资源投向和机构职责。"}},"aspects":[{"title":"稳健取向与跨周期、逆周期调节","uses":[{"unit":"Q1","role":"解题依据","use":"C项关于货币政策的说法符合会议部署。题干要求选出不准确的表述，应选A项。会议列出的金融资源重点投向为科技创新、先进制造、绿色发展和中小微企业，A项将其中两项换成了传统制造和国有企业。","evidence":"始终保持货币政策的稳健性，更加注重做好跨周期和逆周期调节，充实货币政策工具箱","qids":["国考 2025 副省级 行测#5","国考 2025 行政执法 行测#5"]}]}],"sources":[{"id":"977fe73b1089a8fd","label":"货币政策","topic":"经济指标与宏观调控","category":"非时政","text":"7.货币政策\n货币政策是指中央银行通过控制和调节货币供应量以保持社会总供给和社会总需求平\n衡的一种经济政策。","source":{"doc":"6cbfb01fe723bba64b75","first":24,"last":24,"page":24,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-0b5dc68bbfc10583":{"review":{"title":"东北振兴中的战略性新兴产业和未来产业","type":"事实与事件","definition":"2023年9月，新时代推动东北全面振兴座谈会提出，积极培育新能源、新材料、先进制造、电子信息等战略性新兴产业，积极培育未来产业。","explanation":"这项部署服务于以科技创新推动产业创新，目标包括加快形成新质生产力、增强发展新动能。讲话列举的四个领域属于这项部署中的战略性新兴产业培育方向。","basis":"据关联原题及所列出处编释。","references":[{"source":"ne","location":"培育战略性新兴产业、积极培育未来产业"}],"related":["k-07ef47dc10f156ad","k-9b15547988c8ddb9"],"domain":"经济","examFocus":{"国考 2025 副省级 行测#11":"对照东北全面振兴的部署，辨别战略性新兴产业的培育范围及其与科教、成果转化和能源建设举措的关系。"}},"aspects":[{"title":"战略性新兴产业的培育方向","uses":[{"unit":"Q1","role":"直接考查","use":"本题要求统计正确举措。③列出的四个产业方向符合座谈会部署，应计入正确的四项。","evidence":"培育新能源、新材料、先进制造、电子信息等战略性新兴产业","qids":["国考 2025 副省级 行测#11","国考 2025 地市级 行测#11","国考 2025 行政执法 行测#11"]}]}],"sources":[{"id":"f5b282a655709f81","label":"新兴产业和未来产业","topic":"产业、科技与对外开放","category":"非时政","text":"2.新兴产业和未来产业\n新兴产业技术含量高、附加值高、资源集约，成长潜力大，综合效益好，对经济社会全\n局和长远发展具有重大引领带动作用，是当前各地争相布局的领域，如 5G、先进计算、智\n能网联汽车等。\n未来产业代表着科技和产业的发展方向，科技含量高、绿色发展足、产业关联强、市场\n空间大，是抢占未来竞争制高点的关键，如人工智能、人形机器人、元宇宙等领域，但与新\n兴产业不同，未来产业更前沿，发展成熟度相对较低，产业成长的不确定性更大，培育周期\n更长，不能急功近利。","source":{"doc":"6cbfb01fe723bba64b75","first":26,"last":26,"page":26,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-e49c8bd2f1169d98":{"review":{"title":"风光火核储一体化能源基地","type":"事实与事件","definition":"2023年9月，新时代推动东北全面振兴座谈会提出在东北建设风光火核储一体化能源基地。","explanation":"风、光、火、核分别指风电、光电、火电和核电，储指储能。一体化强调多类电源与储能协同布局，储能可用于调节电力供需。","basis":"据关联原题及所列出处编释。","references":[{"source":"ne","location":"风光火核储一体化能源基地"}],"related":["k-5742012cd85fd304"],"examFocus":{"国考 2025 副省级 行测#11":"对照新时代推动东北全面振兴的部署，核对自主创新同科教资源、产业培育、能源基地及央地合作的关系。"}},"aspects":[{"title":"东北能源基地的建设部署","uses":[{"unit":"Q1","role":"直接考查","use":"本题的④对应座谈会提出的能源基地建设举措，应计入正确的四项。","evidence":"建设风光火核储一体化能源基地","qids":["国考 2025 副省级 行测#11","国考 2025 地市级 行测#11"]}]}]},"k-5742012cd85fd304":{"review":{"title":"东北振兴中的央地合作","type":"事实与事件","definition":"2023年9月，新时代推动东北全面振兴座谈会提出创新央地合作模式，促进央地融合发展。","explanation":"这一部署着重改进中央与地方的合作方式，通过融合发展更好带动地方经济发展。","basis":"据关联原题及所列出处编释。","references":[{"source":"ne","location":"央地合作模式"}],"related":["k-e49c8bd2f1169d98"],"examFocus":{"国考 2025 副省级 行测#11":"根据东北全面振兴的部署，辨明地方自主创新与中央、地方协作的关系。"}},"aspects":[{"title":"创新央地合作模式","uses":[{"unit":"Q1","role":"直接考查","use":"本题的⑤提出逐步弱化央地合作，与座谈会促进央地融合发展的部署相悖，因此其余四项计为正确。","evidence":"创新央地合作模式，促进央地融合发展","qids":["国考 2025 副省级 行测#11","国考 2025 地市级 行测#11"]}]}]},"k-103e289498eee6e7":{"review":{"definition":"蚕丛和鱼凫是古蜀传说中的两位国王。题目解析将三星堆出土器物的部分形象与这两位古蜀传说人物联系起来。","explanation":"解析把三星堆纵目面具视为可能与蚕丛有关的象征，并以鸟头勺柄的形象近似鱼鹰，提出它可能与鱼凫传说有关。这些是对器物形象的解释。C项把蚕丛、鱼凫配给二里头遗址，题干要求选出说法不准确的一项，因此选C。","references":[],"evidence":"蚕丛和鱼凫是传说中古蜀国两位国王的名字。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4f43d876564500f7":{"review":{"definition":"1900年，普朗克为解释黑体辐射提出能量量子化假说。在这一模型中，给定频率的振子的能量取值是相应能量基本单位的整数倍。","explanation":"题中A项把能量按离散单位交换的观点归给了麦克斯韦。这个观点在本题对应普朗克的黑体辐射研究，麦克斯韦的代表性贡献则包括预言电磁波。题目要求选出对应错误的一项，因此选A。","references":[],"evidence":"该概念最早是由德国物理学家M·普朗克在1900年提出的。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-938b37c4813e90c7":{"review":{"definition":"武丁是商朝晚期的君主，生活的时代早于秦汉。","explanation":"B项写的是武丁灼烧卜骨、观察裂纹的占卜场景，人物直接指向晚商。其余三项分别指向秦始皇巡游、张骞出使西域和西汉长安的宫殿布局。按本题以场景所属时代判断分集的口径，B项应排除。","references":[],"evidence":"武丁是商朝晚期的君主","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-aa239116dbc79026":{"review":{"definition":"长江流域是世界稻作文明的发源地之一。长江中下游水网密布，水稻种植和淡水渔业发达，典型地区素有“鱼米之乡”之称。","explanation":"解析列举河姆渡遗址、城头山遗址作为长江流域早期稻作的例证。“稻作文明”对应这一历史传统，“鱼米之乡”对应长江中下游的农业和水产特征，两者都能支撑A项的展览题名。","references":[],"evidence":"稻作文明与鱼米之乡形容的是长江流域，尤其是长江中下游地区。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-09867a56795f9ecd":{"review":{"definition":"都江堰是岷江上的古代水利工程，以无坝引水为特征，建成两千多年来持续发挥灌溉、防洪等作用。","explanation":"解析把“千年水道神韵再现”联系到京杭大运河经补水恢复全线水流贯通的事件。都江堰对应的史实是古代水利工程长期运行，所以按本题的命名语境，B项搭配不恰当。","references":[],"evidence":"建堰两千多年来经久不衰","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-226c18326999b005":{"review":{"definition":"牵牛星又称牛郎星、河鼓二，织女星又称织女一。两者都是太阳系外的恒星。","explanation":"“卧看牵牛织女星”中的牵牛星和织女星分别指这两颗恒星，因此 A 项对它们所属范围的判断正确。","references":[],"evidence":"“卧看牵牛织女星”所涉及的天体不属于太阳系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2d207025ffb94071":{"review":{"definition":"北斗七星由大熊座的七颗亮星组成。现今通常所说的北极星是小熊座的勾陈一，在北斗七星之外。","explanation":"B 项的“每依北斗望京华”提到的是北斗七星。北斗七星可用于辨认北极星，两者的指向关系与成员归属是两回事，因此 B 项正确。","references":[],"evidence":"北斗七星不包括北极星","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-36f7f39953f8420d":{"review":{"definition":"启明星是清晨出现在东方天空的金星。金星的公转轨道比地球的更靠近太阳。","explanation":"“启明星在树梢头”中的行星是金星。按距太阳由近及远的行星排序，金星第二，地球第三，因此 C 项把两者的公转轨道大小说反了，应选 C。","references":[],"evidence":"是从太阳向外的第二颗行星，公转轨道半径比地球小","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e2cd3563690186cc":{"review":{"definition":"岁星是木星的古称。木星是从太阳向外数的第五颗行星，属于气态巨行星。","explanation":"“岁星渐高辰星光”同时提到岁星和辰星。D 项只判断岁星的类别，岁星所指的木星确属气态巨行星，因此 D 项正确。","references":[],"evidence":"中国古代称木星为岁星","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bb62ee409c74e538":{"review":{"definition":"1928 年，弗莱明观察到青霉菌能抑制周围的细菌生长，由此发现青霉素。青霉素通常被称为人类发现的第一种抗生素。","explanation":"B 项所说的第一种抗生素指青霉素，产生它的青霉菌是微型真菌。解析提到的葡萄球菌是受到抑制的细菌，因此 B 项关于来源的判断正确。","references":[],"evidence":"从青霉菌中分离出来的青霉素","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9dac219bb8f46479":{"review":{"definition":"原题引文：羊肚菌、松茸等食用真菌味道鲜美，含有丰富的优质蛋白质","explanation":"一项18份羊肚菌种质研究测得鲜样蛋白质为每100克2.96～4.48克，部分种质的氨基酸评分受缬氨酸和赖氨酸限制。日本食品成分数据库列出生松茸每100克可食部含蛋白质2.0克，一项松茸干制研究测得冻干样品每100克约24.8克，并指出含硫氨基酸是该研究样品的第一限制氨基酸。题目将C项视为正确，选A的明确依据是乳酸菌属于细菌，果酒的酒精发酵主要由酵母菌完成。C项的“丰富的优质蛋白质”须结合比较对象、样品和评价标准理解。","references":[{"source":"web-4d67bdd3c93474f5","location":"摘要，营养成分及限制氨基酸","quote":"缬氨酸（Val）和赖氨酸（Lys）分别为第一和第二限制氨基酸"},{"source":"web-aee26d666f90f5e0","location":"食品编号08034，生松茸每100克可食部成分","quote":"きのこ類/まつたけ/生"},{"source":"web-450c33cfc411e4bb","location":"摘要，真空冷冻干燥组的蛋白质含量及限制氨基酸","quote":"分别为247.74 mg/g和207.19 mg/g"}],"evidence":"羊肚菌、松茸等食用真菌味道鲜美，含有丰富的优质蛋白质","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-8e4731a361dc9a81":{"review":{"definition":"据材料记载，宣化葡萄传统种植区限于清远楼以北的城内区域及北门外近城处。当地利用富含碳酸钙的城北土壤和富钾的柳川河水种植葡萄。","explanation":"材料用清远楼南北的种植差异交代选址范围，并指出城北土壤条件有利于葡萄生长，灌溉水源尤为重要。柳川河流经富含钾页岩的北部山脉，河水含钾丰富。这两项条件共同支撑本题的因地制宜选址要点。","references":[],"evidence":"城北的土壤富含碳酸钙利于葡萄的生长","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5d4a4de59e3ac66b":{"review":{"definition":"材料中的宣化果农用马蔺叶绑扎葡萄枝条，用木杆搭建葡萄架，并施用发酵后的农家肥。","explanation":"马蔺叶、木杆和发酵农家肥分别对应绑扎、搭架和施肥，体现本题“绿色环保”要点中的具体做法。材料还记载，2023年呈前村福乐堂葡萄种植专业合作社的葡萄通过国家绿色食品检验并获得证书。","references":[],"evidence":"施用的肥料也是发酵好的农家肥","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-bde662e651e1f3ae":{"review":{"definition":"埠西区政府发布排查公告，虑远科技主动申请参与。区政府经考察，以购买服务的形式委托该企业排查城区32条河道的污染源。","explanation":"政府提出排查需求并考察企业，企业开展实地排查，记录污染源位置、污染类型、排水性质和排水量等，为政府治水决策提供一手资料。这一过程对应本题的政企合作排查要点。","references":[],"evidence":"为政府提供了详实的第一手资料","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-696aaf981b65d96f":{"review":{"definition":"“企业河监”是埠西区政府在万仑河治理中聘请虑远科技承担的协作角色，由企业提供专业力量，协助治河执法监督。","explanation":"区政府借聘任为企业提供参与万仑河治理的渠道。材料中，虑远科技以“企业河监”身份参加治河研讨，也可通过智慧河道云平台接收污染预警。这些工作具体体现了本题所说的专业力量辅助执法监督。","references":[],"evidence":"以专业力量助力执法监督","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1f1005d386e9e76d":{"review":{"definition":"据材料，虑远科技以智慧河道云平台为基础，参与新杭市和埠西区“五水共治”办制定《河长制信息管理系统应用技术规程》，该规程随后在全国团体标准信息平台发布。","explanation":"本题的“合作制定技术规程”发生在云平台试用成功、全市决定推广之后。企业把已有的平台应用经验带入规程制定，市、区治水部门参与制定工作，形成政企合作从技术应用延伸到技术规程制定的具体事例。","references":[],"evidence":"此规程在全国团体标准信息平台发布","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1e815463fcb8cf8c":{"review":{"definition":"蚕丛和鱼凫是古蜀传说中的两位王。三星堆出土的纵目面具和部分鸟首形器物，分别被联系到蚕丛与鱼凫的传说。","explanation":"解析把纵目面具视为蚕丛的象征，并因鸟头勺柄的鸟首形似鱼鹰，提出它可能与鱼凫传说有关。这些联系属于对出土器物的解读。题目要求选出不准确的一项，C项将这组古蜀传说人物与二里头遗址对应，因此入选。","references":[],"evidence":"蚕丛和鱼凫是传说中古蜀国两位国王的名字。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-867a8370eb1e49a0":{"review":{"definition":"良渚遗址出土了大量玉器，代表性器物包括玉琮、玉璧。","explanation":"解析以浙江余杭反山遗址的良渚文化墓葬为例，其中出土的玉器包括完整的玉琮、玉璧。这批出土器物支持A项关于良渚遗址出土大量玉器的说法。","references":[],"evidence":"包括完整的玉琮、玉璧等。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-36f6c25100a535c5":{"review":{"definition":"卜辞是占卜记录，在殷墟出土的甲骨文材料中占多数。","explanation":"殷墟甲骨卜辞记载了祭祀、战争、农业等多类占卜事项。B项说殷墟甲骨中包含大量卜辞，符合这些文字材料的构成。","references":[],"evidence":"殷墟甲骨文中的绝大多数材料是卜辞，即占卜记录","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-393b4174ea13962b":{"review":{"definition":"青铜神树是三星堆遗址出土的代表性青铜器。Ⅰ号大型铜神树由底座、树和龙三部分组成。","explanation":"解析列举Ⅰ号大型铜神树作为出土实例，支持D项将青铜神树列为三星堆文化瑰宝的说法。","references":[],"evidence":"其中最完整的是Ⅰ号大型铜神树，由底座、树和龙三部分组成","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fff7f3fd68d45e66":{"review":{"definition":"武丁是商朝晚期君主。题中以他为主角的卜骨占卜场景属于晚商历史背景。","explanation":"B项直接点出武丁，凭人物即可判断场景的时代。题干要求选出与《秦汉》一集时代背景不符的解说词，因此应选B。","references":[],"evidence":"武丁是商朝晚期的君主","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-39213f4e56d7d142":{"review":{"definition":"原题引文：他登峰山，攀泰山，上琅琊","explanation":"A项的泰山、琅琊与刻石情节指向秦始皇巡游，符合《秦汉》一集的时代范围。本题问哪句解说词不可能出现，B项武丁占卜属于商代，因而当选。A项所写“登峰山”对应的史实地名是峄山，题面异文的来源仍待核对。","references":[{"source":"web-e68217be43cd9978","location":"秦始皇二十八年东巡段","quote":"始皇东行郡县，上邹峄山"}],"evidence":"他登峰山，攀泰山，上琅琊","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-84ac23a3ac8d111e":{"review":{"definition":"西汉汉武帝时期，张骞奉命出使西域。题中描述的是他首次出使途中久经羁留、最终返汉的经历。","explanation":"C项以从长安出发时有百余人、历时十三年仅两人返回为辨认线索，指向张骞首次出使西域，属于西汉史事，因此符合《秦汉》一集的时代范围。","references":[],"evidence":"回程路上，只有两人，一十三年间","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a1b35b5e9fe82f88":{"review":{"definition":"长乐宫与未央宫是西汉长安的主要宫殿。长乐宫由秦离宫兴乐宫改建而成，未央宫是西汉的大朝正宫。","explanation":"D项描写长乐宫和未央宫在龙首原上东西并峙，并以两宫为参照描述北侧宫殿的位置。两座主宫的名称和布局指向西汉长安，因此这段解说词符合《秦汉》一集的时代范围。","references":[],"evidence":"龙首原上，长乐、未央两宫东西并峙","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5c070066cb2636ae":{"review":{"definition":"1900年，普朗克在研究黑体辐射时引入能量元，假设给定频率下的能量可以按能量元的整数倍取值。","explanation":"整数倍取值体现了题中所说的能量量子化。第27题A项把这一观点归给麦克斯韦，因此是应选的错误对应。","references":[],"evidence":"只能取能量基本单位的整数倍","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3b4beb5eb3517450":{"review":{"definition":"渤海湾盆地位于华北地区，是由断层活动造成地块沉降而形成的断陷盆地。","explanation":"渤海湾盆地的分类依据是断层活动和地块沉降。D项将华北渤海湾一带说成多分布岩溶盆地，误用了以溶蚀作用为依据的成因分类，因此是本题要选出的错误项。","references":[],"evidence":"华北渤海湾的盆地属于断陷盆地。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-370f8f3b1a5f6d20":{"review":{"definition":"都江堰是以无坝引水为特征的古代水利工程，建成两千多年后仍在发挥防洪、灌溉等作用。","explanation":"本题解析用都江堰长期发挥水利效益的特点来判断展题是否贴切，并将B项的“千年水道神韵再现”具体联系到京杭大运河恢复全线水流贯通的经历，据此选B。","references":[],"evidence":"以无坝引水为特征的宏大水利工程","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9cd04d0f8130c029":{"review":{"definition":"2022年，京杭大运河通过补水实现百年来首次全线水流贯通。截至2024年，已连续三年实现全线水流贯通。","explanation":"恢复全线水流贯通让这条古运河重新呈现全线有水的景象。本题解析据此把“千年水道神韵再现”与京杭大运河相联系，因此认为把它用作都江堰专题名称不贴切。","references":[],"evidence":"继2022年经补水实现百年来首次全线水流贯通后","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b09696ec35c567c4":{"review":{"definition":"碳纤维具有较高的抗张强度，能承受较大的拉伸应力，同时具有导电性。","explanation":"抗张强度描述纤维抵抗拉伸破坏的能力，导电性描述其传导电流的能力。B项对抗张强度的描述符合碳纤维的特性，但“没有导电性”有误，因此应选B。","references":[],"evidence":"碳纤维抗张强度好且没有导电性","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-68c84a4a242d61cd":{"review":{"definition":"《三国演义》第八回的回目是“王司徒巧使连环计，董太师大闹凤仪亭”，写王允施连环计以及董卓大闹凤仪亭。","explanation":"题中④对应第八回，回次早于官渡之战的第三十回、长江宴饮的第四十八回和刘备托孤的第八十五回，所以④排在首位。","references":[],"evidence":"“王司徒巧使连环计，董太师大闹凤仪亭”出自《三国演义》第8回","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a99120f810cc6f70":{"review":{"definition":"《三国演义》第三十回的回目是“战官渡本初败绩，劫乌巢孟德烧粮”，写袁绍在官渡战败和曹操袭击乌巢烧粮。","explanation":"回目中的“本初”是袁绍，“孟德”是曹操。题中②对应第三十回，在第八回的连环计之后、第四十八回的长江宴饮之前，排在第二位。","references":[],"evidence":"“战官渡本初败绩，劫乌巢孟德烧粮”出自《三国演义》第30回","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b8a689cf7a3cba6f":{"review":{"definition":"《三国演义》第四十八回的回目是“宴长江曹操赋诗，锁战船北军用武”，写赤壁之战前曹操在长江宴饮赋诗和北军用铁锁连接战船。","explanation":"题中①对应第四十八回，回次晚于官渡之战的第三十回，早于刘备托孤的第八十五回，所以①排在第三位。","references":[],"evidence":"“宴长江曹操赋诗，锁战船北军用武”出自《三国演义》第48回","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7e1daa096b6aefd3":{"review":{"definition":"《三国演义》第八十五回的回目是“刘先主遗诏托孤儿，诸葛亮安居平五路”，写刘备在白帝城永安宫托孤和诸葛亮应对五路进兵。","explanation":"题中③对应第八十五回，是所给四个回目中回次最晚的一回。按第八、三十、四十八、八十五回排列，顺序为④②①③，对应D项。","references":[],"evidence":"“刘先主遗诏托孤儿，诸葛亮安居平五路”出自《三国演义》第85回","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-106aaed284890dc1":{"review":{"definition":"A市通过国有投资平台投资战略性新兴产业，建立科技企业贷款服务体系，并由高新区出台基金扶持政策。","explanation":"三项措施共同构成参考答案中的“提供资金支持”。国有平台以投资吸引优质项目落地，政府、银行、担保、征信等多方联动回应科技型企业贷款难题，高新区则以“创九条”“金九条”等政策扶持基金发展。","references":[],"evidence":"国有平台投资新兴产业；构建科技企业贷款服务体系；出台基金扶持政策。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-264a23452b2a95b8":{"review":{"definition":"A市依托国际人才城和名校引才品牌吸引国内外高校毕业生，并成立科技商学院培养复合型科技产业组织人才。","explanation":"国际人才城相关举措对应人才引进，材料以累计引进国内外高校毕业生的人数说明成效。科技商学院对应人才培养，材料明确给出了培养目标。作答时把两项措施归入“吸引培养人才”，并保留各自的实施载体。","references":[],"evidence":"建设国际人才城，引进国内外高校毕业生；成立科技商学院，培养复合型人才。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-938a6a8e25620112":{"review":{"definition":"S市总工会通过“连心桥”小程序开展职工心声大调查，以问卷和互动专区收集职工意见，推动相关单位及时处理反馈的问题。","explanation":"小杨在“吐槽专区”反映公司食堂伙食问题，几天后食堂就有了改善。答题时要写出征集意见和推动整改两个环节，食堂的变化体现了职工反馈怎样转化为服务改进。","references":[],"evidence":"有效助推各单位针对反馈的问题迅速展开行动，增强了与职工之间的沟通互动。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-88e23e229ea5c457":{"review":{"definition":"S市总工会搭建线上培训平台，提供办公软件应用等课程，帮助职工学习工作所需的数字技能。","explanation":"老欧感到跟不上数字时代的步伐，便在平台上选修办公软件应用课程，通过视频讲解和实例分析掌握新技能，并通过在线测试增强了工作信心。这个事例对应答题中的职工成长需求。","references":[],"evidence":"通过视频里的生动讲\n解和实例分析，他很快就掌握了新技能。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-19840e8d34097bd0":{"review":{"definition":"S市总工会在官网开设心理咨询服务专栏，职工可以预约咨询师，通过视频连线获得针对个人情况的指导。","explanation":"小萨因工作和家庭事务感到压力，咨询师先指导她练习情绪管理，几周后再根据她的进展提供更有针对性的建议。答题时，官网预约和视频咨询体现了服务的线上渠道，按进展调整建议体现了服务如何回应个人需求。","references":[],"evidence":"咨询师根据小萨的进展，提供了更有针对性的建议和方法","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3c72972840797e7d":{"review":{"definition":"12351是全国总工会建成运行的职工维权服务热线。材料中，热线听取职工的劳动纠纷诉求，并对接S市总工会的法律服务部门。","explanation":"2024年10月，小白因劳动合同纠纷拨打热线。客服听取问题后迅速联系S市总工会法律服务部门，次日市总工会法律援助中心来电帮助解决纠纷。答题时应交代热线接收诉求、转接和法援跟进的过程，次日跟进是材料记载的个案。","references":[],"evidence":"客服人员耐心听取了我的问题，并迅速帮我联系了S市总工会的法律服务部门。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-95926da67295f9bf":{"review":{"definition":"2024年夏季，S市总工会通过智慧工会平台向环卫工人、快递员、外卖员等户外工作者提供清凉福利，职工可用手机领券并就近使用。","explanation":"环卫工人老辛过去需要提前排队领取清凉福利，现在通过手机领券后即可在附近商店使用。答题时应写明服务对象及领取、使用方式，说明工会怎样便利户外工作者在炎热天气中及时获得福利。","references":[],"evidence":"通过手机就能领取清凉券，不仅省时，还能在附近商店直接用。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f5e417c70fa7003a":{"review":{"definition":"S市总工会结合区域和产业实际，在产业工人、户外职工集聚的地方布设服务站点，并通过星级站点创建推动服务空间专业化、站点运营特色化。","explanation":"选址回应职工就近获得服务的需求，爱心接力站、职工法援点、职工学堂等不同站点覆盖多类需求。首批“五星”站点采用“一站一品”的运营方式，回应户外劳动者和新就业形态劳动者的工作与生活诉求。答题时应同时写出布局和运营两方面。","references":[],"evidence":"通过‘一站一品’式的特色\n化运营，精准回应劳动者特别是户外劳动者和新就业形态劳动者的工作和生活诉求。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4c43924a981c7c8b":{"review":{"definition":"碳纤维具有导电性，同时具有较高的抗张强度。","explanation":"B项把“抗张强度好”和“没有导电性”并列。高抗张强度符合碳纤维的特性，关于导电性的描述有误，所以选非题应选B。","references":[],"evidence":"碳纤维抗张强度好且没有导电性","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0d8314cd58ea5e4d":{"review":{"definition":"白垩纪末大灭绝之后进入新生代，哺乳动物在这一时期显著分化并繁盛。","explanation":"B项的“大灭绝之后”和“哺乳动物继恐龙成为新主”共同指向新生代。选项把这一演化阶段配给古生代的志留纪，因此属于对应不当。","references":[],"evidence":"新生的纪元始于大灭绝之后，哺乳动物继恐龙成为新主","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c318047290f1fe28":{"review":{"definition":"志留纪是古生代的第三个纪，位于奥陶纪与泥盆纪之间。腕足类和珊瑚是当时繁盛的海洋生物。","explanation":"B项把大灭绝后哺乳动物繁盛的景象归入志留纪。志留纪的古生代归属与这一新生代线索冲突，足以判定B项的年代对应有误。","references":[],"evidence":"志留纪是古生代的第三个纪","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d996fa61f9368c9a":{"review":{"definition":"金星是从太阳向外数的第二颗行星，其绕太阳公转的轨道半长轴小于地球的轨道半长轴。","explanation":"题中的“公转轨道半径”用于比较轨道大小。地球是从太阳向外数的第三颗行星，金星轨道在地球轨道内侧，因此C项所说的“较地球更大”有误。","references":[],"evidence":"是从太阳向外的第二颗行星，公转轨道半径比地球小。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a33ba99c7f9d080e":{"review":{"definition":"公历第三季度包括7月、8月和9月，三个月分别有31天、31天和30天，共92个自然日。","explanation":"第128题按自然日计算2022年三季度的日均处理金额，因此用31＋31＋30＝92作为分母。将还原出的季度处理总额约6685.43亿美元除以92，得到约72.67亿美元，符合B项。","references":[],"evidence":"2022年7月有31天，8月有31天，9月有30天","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9200f68847653702":{"review":{"definition":"据材料6，W市总工会整合社区党群服务中心、网格服务站和物业用房等场地，共建快递小哥服务驿站55家。","explanation":"驿站让快递员和网约送餐员能在工作间隙就近喝水、歇脚和充电。宣传单可把这些日常便利和驿站数量写出来，让招新对象了解工会提供的线下服务。","references":[],"evidence":"联建共建快递小哥服务驿站 55 家","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-28ec2c5b68bf922b":{"review":{"definition":"材料6中，W市总工会面向新业态职工，通过线上线下渠道开展政策咨询、技能培训和劳动权益维护等普惠服务。","explanation":"材料指出，W市不少灵活就业人员对工会的职能和意义缺乏了解。宣传单列明咨询、培训和维权服务，可以具体回答网约车司机、快递员、配送员遇到政策疑问、培训需求或劳动权益问题时能获得哪些支持。","references":[],"evidence":"政策咨询、技能培训、劳动权益维护等普惠服务","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1dc4897ac8186bb1":{"review":{"definition":"大山村干部借“六尺巷”典故劝说为土地归属长期争执的倪、莫两户各让一步，引导双方协商利用撂荒地，化解了邻里纠纷。","explanation":"两户都拿不出权属凭证，村干部从邻里情分和改善村庄环境的共同利益入手，提出把地一同用起来。两户和解后，相邻地块的村民也主动让出部分土地，村里建成公共绿地。本题可据此概括借古代礼让智慧化解土地纠纷、改善村庄环境的成效。","references":[],"evidence":"如今两家能否也各让一步，商量将地一同用起来呢？","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-82ef4671e0c228a1":{"review":{"definition":"小雪街道以“和为贵”为理念设立调解室，处理居民因宠物归属、邻里砌墙等引起的纠纷。","explanation":"街道党工委书记介绍，调解室刚成立时每月处理约三四起纠纷，材料记述时已近半年无人前来调解。材料将这一变化视为邻里纠纷减少、民风改善的表现，本题据此归纳以传统尚和理念开展基层调解的成效。","references":[],"evidence":"邻里纠纷的减少反映的是民风的改善","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-b57957a6c002ca88":{"review":{"definition":"Z市延续耕读传统中的重视读书理念，针对城乡群众需求推广全民阅读，通过图书馆驿站、捐赠图书馆等提供阅读服务。","explanation":"百家桥村的24小时“百味书屋”方便村民就近阅读，村党委书记将村民不良习惯的改善与阅读活动联系起来。由市民捐书的益空间·源书房则体现了公众参与。本题可据此概括Z市按需提供阅读服务、培育文明习惯，并以阅读传播思想。","references":[],"evidence":"两年来，通过阅读活动，村民的不良习惯改变了很多。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-fbf84440ce3cee83":{"review":{"definition":"据解析援引的2022年10月党的二十大记者招待会介绍，我国是全球森林资源增长最多、人工造林面积最大的国家。","explanation":"①并列的是森林资源增长量与人工造林面积两项指标。解析所引介绍同时支持两项判断，因此①成立，排除遗漏①的D项。","references":[],"evidence":"成为世界上森林资源增长最多和人工造林面积最大的国家","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-841486135b59aa6b":{"review":{"definition":"截至2022年底，我国水电、风电、太阳能发电和生物质发电的累计装机容量均居世界首位。","explanation":"题中②比较的是四类电源各自的累计装机容量。国家能源局2023年1月16日发布的全国电力工业统计给出了国内装机数据，未列四类电源的国际排名。该局2月发布会明确了年末统计时点，生物质发电装机为0.41亿千瓦。同年6月，国家能源局新能源司副司长在两项2022年行业报告发布时确认四类电源分别连续18年、13年、8年和5年位居全球装机首位，支持选项B所含的②。","references":[{"source":"web-84d2852d99c1eed2","location":"正文第二段","quote":"截至12月底，全国累计发电装机容量约25.6亿千瓦"},{"source":"web-73dea1cc3202db89","location":"王大鹏发布2022年可再生能源发展情况，第一部分","quote":"生物质发电0.41亿千瓦"},{"source":"web-74eb8de19dc37eea","location":"末段，国家能源局新能源司副司长熊敏峰介绍","quote":"分别连续18年、13年、8年和5年稳居全球装机首位"}],"evidence":"水电、风电、太阳能发电、生物质发电装机均居世界第一","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-2f220949069b41ce":{"review":{"definition":"据题解援引的党的二十大报告及2022年研发投入统计口径，我国全社会研发经费总量居世界第二位。党的二十大报告同时指出，我国研发人员总量居世界首位。","explanation":"③将全社会研发经费、研发投入强度和全球创新指数一并说成世界首位。仅研发经费总量居世界第二这一点，就足以否定③并排除A、C、D三项。研发人员总量的首位对应另一项指标。","references":[],"evidence":"居世界第二位，研发人员总量居世界首位","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e1425fd0bbd507a0":{"review":{"definition":"党的二十大报告在总结新时代十年的成就时指出，我国建成了世界上规模最大的教育体系、社会保障体系和医疗卫生体系。","explanation":"④中的“社保体系”是报告所称“社会保障体系”的简称。④对三个体系规模的概括与报告一致，与①②共同构成正确组合B。","references":[],"evidence":"建成世界上规模最大的教育体系、社会保障体系、医疗卫生体系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3e924841778939bd":{"review":{"title":"神舟十五号乘组的舱外安装任务","type":"事实与事件","definition":"2022年11月28日，神舟十五号任务新闻发布会公布了乘组的计划任务，其中包括安装梦天实验舱扩展泵组和载荷暴露平台设备。","explanation":"按发布会公布的任务安排，乘组计划开展3至4次出舱活动，这两项设备安装属于出舱作业。","basis":"据关联原题及所列出处编释。","references":[{"source":"space","location":"2022年11月28日任务发布会"}],"examFocus":{"江苏 2023 A类 行测#3":"以神舟十四号、十五号乘组在轨交接为时间界线，区分不同舱外设备和空间站构型的任务归属。"}},"aspects":[{"title":"梦天实验舱设备安装的任务归属","uses":[{"unit":"Q1","role":"直接考查","use":"题干以神舟十四号与神舟十五号乘组在轨会师为背景，要求辨认神舟十五号乘组接下来要完成的任务。B项所列的两项设备安装属于神舟十五号乘组的任务，D项所列的“T”字基本构型组装属于神舟十四号乘组的任务。","evidence":"安装梦天舱扩展泵组和载荷暴露平台设备","qids":["江苏 2023 A类 行测#3","江苏 2023 B类 行测#4"]}]}]},"k-c3a3038d1c04156a":{"review":{"definition":"1940年，毛泽东在《新民主主义论》中提出，可以建立从全国到乡的各级人民代表大会，并由各级代表大会选举政府。","explanation":"文中具体列出了全国、省、县、区、乡五级人民代表大会，并交代了政府如何产生。这两点直接对应题干所问的制度构想，因此③应入选，与①组成B项。","references":[],"evidence":"并由各级代表大会选举政府","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-159812827e37710b":{"review":{"definition":"1945年，毛泽东在《论联合政府》中提出，新民主主义的政权组织应采取民主集中制，由各级人民代表大会决定大政方针、选举政府。","explanation":"《新民主主义论》已提出设立各级人民代表大会并由其选举政府，《论联合政府》进一步说明了政权组织原则和人民代表大会决定大政方针的职责，因此①和③均应入选。","references":[],"evidence":"由各级人民代表大会决定大政方针，选举政府","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5fd14a172c84147e":{"review":{"definition":"据2022年《求是》刊载的相关论述，中华文明探源工程等重大工程的研究成果实证了我国百万年的人类史、一万年的文化史、五千多年的文明史。","explanation":"题中的①对应百万年人类史，②对应五千多年文明史，③对应一万年文化史。④所说的三千多年城市史未列入题目所据论述的三项实证成果，因此选①②③。","references":[],"evidence":"实证了我国百万年的人类史、一万年的文化史、五千多年的文明史","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-44a23b514e71a63e":{"review":{"definition":"南极洲有企鹅自然分布，北极熊自然分布于北极地区。","explanation":"企鹅和北极熊都是动物，本题用南极洲区分二者的分布。按题干顺序，第二项企鹅在南极洲有分布，第三项北极熊在南极洲无自然分布。B项同样是第二项人物属于首项作品，第三项人物属于另一部作品。","references":[],"evidence":"企鹅生活在南极洲，但北极熊不是生活在南极洲的动物。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9d778ed79f9ff7fd":{"review":{"definition":"李逵是《水浒传》中的人物，沙和尚是《西游记》中的人物。","explanation":"B项后两项都是小说人物，其中第二项李逵属于首项所列的《水浒传》，第三项沙和尚属于另一部小说。这一顺序对应题干中企鹅在南极洲有自然分布、北极熊在南极洲无自然分布的关系。","references":[],"evidence":"李逵是《水浒传》中的人物","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-426948c9e2980177":{"review":{"definition":"在用绳索悬挂座板的秋千中，绳索是秋千的组成部分。","explanation":"本题按绳索式秋千理解C项。“秋千→绳索”与“句子→句号”都是从整体指向组成部分。","references":[],"evidence":"绳索是秋千的组成部分","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f0e9db1b4d73bae3":{"review":{"title":"十三五时期","type":"事实与事件","definition":"“十三五”时期是《中华人民共和国国民经济和社会发展第十三个五年规划纲要》所对应的规划期，从2016年到2020年。","explanation":"按年度统计时，规划期包括首尾两年，共有五个年度。计算规划期内某项指标的年均值，取这五个年度的数据作算术平均。","basis":"据关联原题及所列出处编释。","references":[{"source":"five","location":"规划期"}],"domain":"历史","examFocus":{"江苏 2023 A类 行测#124":"从统计表取2016—2020年综艺益智类广播节目制作时长，以这五年的平均值为基准比较2021年。","江苏 2023 B类 行测#134":"从统计表取2016—2020年综艺益智类广播节目制作时长，以这五年的平均值为基准比较2021年。"}},"aspects":[{"title":"规划期年均值的取数范围","uses":[{"unit":"Q1","role":"解题依据","use":"取统计表中2016—2020年的综艺益智类广播节目制作时长，得到年均205.26万小时。2021年为193.9万小时，比该均值少约5.53%，选A（5.5%）。两卷所附解析均写作5.4%，按所列数据重算均为约5.53%，答案一致。","evidence":"比“十三五”时期年均制作时长少","qids":["江苏 2023 A类 行测#124"]},{"unit":"Q2","role":"解题依据","use":"以解析所列2016—2020年五个年度的综艺益智类广播节目制作时长均值为比较基准，2021年的193.9万小时较该均值少约5.53%，选A（5.5%）。","evidence":"比“十三五”时期年均制作时长少","qids":["江苏 2023 B类 行测#134"]}]}]},"k-ed1c303053ebd139":{"review":{"definition":"D县综合行政执法局主动为符合信用修复条件的企业讲解办理要求和相关法律，并协助企业办理信用修复的服务。","explanation":"材料中的企业因混合收运生活垃圾受罚，后来因不良信息影响未能与合作单位续签。执法人员发现该处罚记录已符合修复条件后主动上门，帮助企业争取缓解经营困难的机会，也让企业在办理过程中了解规则、增强依法经营意识。县综合行政执法局法制科负责人还指出，这项服务改善了政企沟通，降低了执法工作的难度。","references":[],"evidence":"你们公司去年那条行政处罚记录已符合信用修复条件","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-bc38b4c31460f6f6":{"review":{"definition":"2022年党的二十大记者招待会上，生态环境部介绍，我国是世界上森林资源增长最多、人工造林面积最大的国家。","explanation":"①同时涉及两项指标。森林资源看增长量，人工造林看面积，两项均居世界首位，因此①成立。","references":[],"evidence":"成为世界上森林资源增长最多和人工造林面积最大的国家","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9e4584e8c1421308":{"review":{"definition":"截至2022年底，我国水电、风电、太阳能发电和生物质发电的装机容量均居世界首位。","explanation":"②比较的是四类发电设施各自的装机容量，也就是已安装发电设备的额定功率总和。四类都满足世界第一这一条件，因此②正确。","references":[],"evidence":"水电、风电、太阳能发电、生物质发电装机均居世界第一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5661a58834179d34":{"review":{"definition":"党的二十大报告指出，新时代十年，我国建成了世界上规模最大的教育体系、社会保障体系和医疗卫生体系。","explanation":"④中的“全球规模最大”同时适用于三个体系，其中“社保体系”是“社会保障体系”的简称，整项与报告原意相符。","references":[],"evidence":"建成世界上规模最大的教育体系、社会保障体系、医疗卫生体系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a63869d49f78acc8":{"review":{"definition":"2022年，习近平在《求是》发表文章指出，中华文明探源工程等重大工程的研究成果实证了我国百万年的人类史、一万年的文化史和五千多年的文明史。","explanation":"①、②、③分别与文章中的人类史、文明史和文化史年限相符。④所说的“三千多年的城市史”超出文章在本题所引段落列出的三项成果，因此选①②③。","references":[],"evidence":"实证了我国百万年的人类史、一万年的文化史、五千多年的文明史","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3c1ee79f5b7f2e0f":{"review":{"definition":"汉语和藏语是两种不同的语言，二者之间没有种属包含关系。","explanation":"题干的第二项“汉语”与第三项“藏语”在语言类别下并列，对应C项“理学”与“农学”在学科门类下并列。D项中“苗族”属于“民族”，后两项是种属关系。","references":[],"evidence":"后两词是并列关系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-36d1c7ebdebf2ce7":{"review":{"definition":"按本题采用的学科分类，数学归入理学，理学和农学是并列的学科门类。","explanation":"C项“数学—理学”与“吴语—汉语”都是下位类别在前、上位类别在后。“理学—农学”与“汉语—藏语”都是同一层级上的并列关系，两处关系及其位置均与题干一致。","references":[],"evidence":"数学属于理学","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8b654aa0ec297681":{"review":{"definition":"南极洲有企鹅自然分布。北极熊生活在北极地区，在南极洲没有自然分布。","explanation":"企鹅和北极熊都属于动物，第二项和第三项并列，其中只有第二项与首项“南极洲”存在自然分布关系。B项同样是第二项和第三项并列，且只有第二项与首项存在题目所指的归属关系。","references":[],"evidence":"企鹅生活在南极洲，但北极熊不是生活在南极洲的动物","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cee3a70bbc7949a1":{"review":{"definition":"李逵是《水浒传》中的人物，沙和尚是《西游记》中的人物。","explanation":"B项中的李逵和沙和尚同为小说人物，其中只有李逵出自首项《水浒传》。这与题干中企鹅和北极熊同为动物、只有企鹅在南极洲有自然分布的结构一致。","references":[],"evidence":"李逵是《水浒传》中的人物","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2e86b3a02880500a":{"review":{"definition":"麋鹿是草食动物，可摄食野草以获取能量。","explanation":"“野生麋鹿”按是否野生划分，“雄性麋鹿”按性别划分，两类有交集。A项的野草可为两类麋鹿供能，对应题干中汽油的供能作用。D项的雪橇对应的是运动器具。","references":[],"evidence":"野草可以维持麋鹿的行动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-59ba07f04bb96260":{"review":{"definition":"人口普查、经济普查和农业普查是我国三项重大国情国力周期性普查。","explanation":"本题用“国情普查”作为共同上位概念。题干第一项人口普查与第三项经济普查彼此并列，两项分别从属于居中的国情普查。D项的团雾天气和暴雪天气也分别从属于居中的恶劣天气。","references":[],"evidence":"人口普查、经济普查和农业普查是我国的三项重大国情国力周期性普查","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9b0434fcfb446a33":{"review":{"definition":"在本题解析所指的电视剧《西游记》中，汪粤、徐少华和迟重瑞先后扮演唐僧。","explanation":"限定摹状词须凭描述指向唯一对象。D项虽然给出了剧名和角色，但这部剧里的唐僧由多位演员先后饰演，描述本身无法锁定其中一人。题目问哪项不属于限定摹状词，因此选D。","references":[],"evidence":"汪粤、徐少华、迟重瑞等演员先后在《西游记》中扮演过唐僧","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8882da31629371ef":{"review":{"definition":"材料中的龙溪村村务员承担责任区巡查和村内问题处理工作，利用对村情和村民生产生活的了解改善公共服务、调解纠纷。","explanation":"老吴巡查上学路段的交通安全和卫生状况，并提议修建水槽改善校门口排水。老蔡凭种田经验现场查看水深，说服吴大姐恢复向邻田放水，化解了用水纠纷。第1题据此概括村务员及时发现并解决公共服务问题、化解邻里矛盾的作用。","references":[],"evidence":"交通安全、卫生状况是他巡查的重点","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ba2c2dd757187b3a":{"review":{"definition":"T市组建乡村振兴博士“帮帮团”，按各村产业需求选派专业对口的专家结对，推动农业技术落地，并通过跟班实践和专题授课培养本地人才。","explanation":"东林村在专家指导下形成饲料、湖羊、肥料和农田相衔接的绿色循环，体现了技术成果转化。T市安排青年农业委培生跟班学习，并由实践学院组织专题授课。第1题据此概括农业技术推广和本土技术人才培养两方面的变化。","references":[],"evidence":"专家传技术，实践育人才。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-85ae12202aa184bb":{"review":{"definition":"议堂村规划师通过收集村民意见、开展多方协商，将村民的居住需求和当地风俗纳入农房布局设计。","explanation":"部分初稿中后排农房大门朝向前排墙角，村民认为有违当地风俗。协商后，规划师用带状景观划分村庄空间，形成“大分散、小集中”的布局。第1题借此说明规划师如何兼顾村庄景观、使用需求和村民意愿。","references":[],"evidence":"既避免了呆板格局，又满足了村民意愿。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-df2138eab3d5fad2":{"review":{"definition":"W市依托新时代文明实践中心发动基层文艺爱好者组建志愿团队，由村民自编自演，到周边村庄巡演。","explanation":"邻里艺术团用村民熟悉的本地生活素材创作节目，跨村演出丰富了村民的文化生活。小雅村村民接受演艺培训后能独立演出一台晚会，体现了培训对壮大基层文艺队伍的作用。这两项变化均是第1题的概括要点。","references":[],"evidence":"自行编排节目，自行导演剧目，自发到周边村庄巡演","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ceda05910bdf22b8":{"review":{"definition":"紫金图书馆党支部在2023年“品诗词之美 扬文化自信”主题党日的诗词品评环节中，由青年党员代表以演讲、角色表演、PPT展示等方式分享诗词，并联系图书馆工作谈体会。","explanation":"文献部小戴从李白《上李邕》读出不畏困难、勇于进取的精神，进而谈到青年在工作中直面挑战、承担责任。借阅部小吕从苏轼《定风波·莫听穿林打叶声》谈如何面对工作和生活中的挫折。点评可据此写出分享形式多样、诗词感悟与岗位实践相联系两项特色。","references":[],"evidence":"并联系图书馆工作实际，诠释自己对诗词的解读","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-77a3e1808ca5b796":{"review":{"definition":"2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛开幕式上宣布八项行动，包括构建“一带一路”立体互联互通网络、支持建设开放型世界经济、开展务实合作、促进绿色发展、推动科技创新、支持民间交往、建设廉洁之路、完善“一带一路”国际合作机制。","explanation":"题中①、②、③分别对应八项行动中的第二项、第八项和第一项。推动科技创新也是八项行动之一，其中对科技创新行动计划的表述是“继续实施”，因此④中的“启动”有误，正确组合为①②③。","references":[],"evidence":"中国支持高质量共建“一带一路”的八项行动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f65c4b65787428bd":{"review":{"title":"自贸试验区自由贸易账户试点","type":"事实与事件","definition":"率先探索自由贸易账户，是我国自贸试验区在2013—2023年建设首个十年中的金融开放创新成果之一。","explanation":"据题解所引2023年9月27日国新办自贸试验区建设十周年新闻发布会，商务部将率先探索自由贸易账户列入十年建设成果的“五个率先”。","basis":"据关联原题及所列出处编释。","references":[{"source":"ftz","location":"目录（四）及正文第9页起·自由贸易账户"}],"related":["k-9a00bd0185c0ac82","k-0b56b67d9fed06b6"],"examFocus":{"江苏 2024 A类 行测#5":"对照自贸试验区建设十周年总结，核对金融开放中的账户名称和贸易投资措施的表述。"}},"aspects":[{"title":"十周年成果中的账户名称","uses":[{"unit":"Q1","role":"直接考查","use":"题干问哪项不属于十周年总结中的突破性创新成果。发布会列举的金融创新是率先探索自由贸易账户，A项所称“创设境外金融投资账户，加快推进资本市场国际化”与该项成果的表述不符，因此选A。","evidence":"五是率先探索自由贸易账户，金融开放创新稳步推进。","qids":["江苏 2024 A类 行测#5","江苏 2024 B类 行测#5"]}]}]},"k-be200b3bfe4ed7f1":{"review":{"definition":"商代晚期的殷墟甲骨文中已有表示个、十、百、千、万等数级的记载，体现了十进计数观念。","explanation":"十、百、千、万相邻单位按十倍递进，甲骨文中有这些数级的记载即可支持题中①。①判断的是当时是否已有这些数字概念，依据是甲骨文中的数字记载。","references":[],"evidence":"其中有表示个、十、百、千、万等数字概念","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-62b21411f4c2ae7a":{"review":{"definition":"商代晚期的殷历采用阴阳合历，通常一年有十二个月，并通过增设闰月协调历年与回归年的长度。","explanation":"阴历月份按月相周期安排，十二个这样的月份合计短于一个回归年，增设闰月可以减小累计偏差。题中③的“将一年分为12个月”说的是常年安排，与解析所述的置闰做法相容，因此③入选。","references":[],"evidence":"将一年分为12个月，并采取增加闰月的方法","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-47866aec8b539578":{"review":{"definition":"原题引文：商代晚期已能认识人类的10多种疾病","explanation":"本题参考答案把④列为正确项。卜辞确实反映殷人已注意到多种病症，但按患病部位统计的条目与按现代病名统计的疾病种类口径不同。有研究将部分卜辞释为疟疾，这一释读仍需结合具体甲骨核对。台西商代遗址出土物有被解释为砭具和药用种子的实例，相关研究所述砭具出自商代中期墓葬。④所说的商代晚期疗法，需要相应时代的证据。","references":[{"source":"web-b84c32e5f7978e2a","location":"第四节末及第五节结论，第380—381页","quote":"關於患病部位的貞卜記錄"},{"source":"web-b7fc2c1b85e4fa33","location":"摘要","quote":"疫疾、疫蚤、疟疾等传染病名"}],"evidence":"商代晚期已能认识人类的10多种疾病","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-6c37e2f525ed4c24":{"review":{"definition":"《新型电力系统发展蓝皮书》将2045年至2060年划为巩固完善期，并把用户侧与电力系统高度灵活互动列为这一阶段的特征。","explanation":"用户侧的灵活互动体现为用电需求能够响应电力系统的运行需要，例如在一定条件下调整用电时段。D项对应蓝皮书描述的阶段性建设特征，据此判断为正确表述。","references":[],"evidence":"用户侧与电力系统高度灵活互动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4e1b9285b94aa69b":{"review":{"definition":"材料7中，N村通过收储和租赁闲置民房开办民宿，发展乡村旅游并带动村民就业。N村还把印花布、葛粉等特色产品做成伴手礼，增加了收入。","explanation":"闲置民房为民宿提供经营场所，印花布、葛粉则被开发为可销售的特色商品。发言稿据此提出，K村可以从老房子等闲置资源入手发展旅游、带动就业。伴手礼增收是材料记载的N村经营成效，K村的发展思路来自小范的培训体会。","references":[],"evidence":"收储和租赁闲置民房建起了民宿，既发展了乡村旅游，又解决了村民就业","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1d5df4f144112e04":{"review":{"definition":"新时代中国特色社会主义生态文明思想是在不断深化对生态文明建设规律认识的过程中形成的，为新时代生态文明建设提供科学理论指导。","explanation":"2023年7月全国生态环境保护大会讲话将这一思想的形成概括为由实践探索到科学理论指导的重大转变。①对应的是这一已经取得的理论成果，因此入选。","references":[],"evidence":"形成了新时代中国特色社会主义生态文明思想","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"49e1ee3f5a2cb325","label":"生态文明思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.十个坚持\n2022 年 8 月 18 日，习近平生态文明思想研究中心在人民日报刊文，将习近平生态文\n明思想的基本内容概括为“十个坚持”。即：\n（1）坚持党对生态文明建设的全面领导，（2）\n坚持生态兴则文明兴，\n（3）坚持人与自然和谐共生，\n（4）坚持绿水青山就是金山银山，\n（5）\n坚持良好生态环境是最普惠的民生福祉，（6）坚持绿色发展是发展观的深刻革命，（7）坚\n持统筹山水林田湖草沙系统治理，（8）坚持用最严格制度最严密法治保护生态环境，（9）\n坚持把建设美丽中国转化为全体人民自觉行动，\n（10）坚持共谋全球生态文明建设之路。\n（粉\n笔敲黑板：2005 年，时任浙江省委书记习近平同志来到安吉余村考察调研，首次提出“绿\n水青山就是金山银山”科学论断。2025 年是两山理念提出的 20 周年。）\n2.四个重大转变与五个重大关系\n2023 年 7 月 17 日至 18 日，习近平总书记在全国生态环境保护大会上全面总结新时代\n生态文明建设实现“四个重大转变”的历史性成就，深刻阐述新征程上推进生态文明建设需\n要处理好的“五个重大关系”。\n“四个重大转变”即：（1）实现由重点整治到系统治理的重大转变，（2）实现由被动\n应对到主动作为的重大转变，（3）实现由全球环境治理参与者到引领者的重大转变，（4）\n实现由实践探索到科学理论指导的重大转变。\n“五个重大关系”即：（1）高质量发展和高水平保护的关系，（2）重点攻坚和协同治\n理的关系，\n（3）自然恢复和人工修复的关系，\n（4）外部约束和内生动力的关系，\n（5）\n“双碳”\n承诺和自主行动的关系。","source":{"doc":"3ccc56f4000d1642c2d1","first":22,"last":23,"page":22,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-8ce8da4833e746e4":{"review":{"definition":"2023年7月全国生态环境保护大会讲话指出，我国生态环境保护的结构性、根源性、趋势性压力尚未根本缓解。","explanation":"讲话一方面指出我国经济社会发展已进入加快绿色化、低碳化的高质量发展阶段，另一方面指出生态文明建设仍处于压力叠加、负重前行的关键期。③把当时的阶段性判断改成“根本缓解了”，因此排除。","references":[],"evidence":"趋势性压力\n尚未根本缓解","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-489820be3080ddbf":{"review":{"definition":"2023年全国生态环境保护大会讲话将由被动应对到主动作为概括为新时代生态文明建设取得的一项重大转变。","explanation":"讲话把这一转变与转变观念、压实责任联系起来，具体表现为全党全国推进生态文明建设的自觉性和主动性增强。④直接表述了这一变化，因此入选。","references":[],"evidence":"实现由被动应对到主动作为的重大转变","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-210922a2598d0ba7":{"review":{"definition":"2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛开幕式上宣布八项行动，分别是构建“一带一路”立体互联互通网络、支持建设开放型世界经济、开展务实合作、促进绿色发展、推动科技创新、支持民间交往、建设廉洁之路、完善“一带一路”国际合作机制。","explanation":"①支持建设开放型世界经济、②完善国际合作机制、③构建立体互联互通网络均对应八项行动的原有表述。八项行动中的科技领域表述是“推动科技创新”，其下的行动计划是继续实施，故含④“启动”的组合排除。","references":[],"evidence":"立体互联互通网络、支持建设开放型世界经济","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-83fc3e52381c71f6":{"review":{"definition":"2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛上宣布，中方将继续实施“一带一路”科技创新行动计划。","explanation":"这项安排属于“推动科技创新”行动，包含扩大与各方共建的联合实验室、支持各国青年科学家来华短期工作等举措。④使用“启动”，把对既有计划的后续部署表述成了计划开始实施，因此排除。","references":[],"evidence":"中方将继续实施“一带一路”科技创新行动计划","disposition":"独立词条","basis":"据原题和解析编释。","title":"2023年继续实施“一带一路”科技创新行动计划","related":[],"examFocus":{"江苏 2024 A类 行测#2":"核对第三届“一带一路”国际合作高峰论坛公布的支持行动，留意科技创新行动计划所处的实施阶段。"}},"readings":[{"origin":"k-83fc3e52381c71f6","title":"2023年继续实施“一带一路”科技创新行动计划","qs":["江苏 2024 C类 行测#3"],"definition":"2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛上宣布，中方将继续实施“一带一路”科技创新行动计划。","explanation":"这项安排属于“推动科技创新”行动，包含扩大与各方共建的联合实验室、支持各国青年科学家来华短期工作等举措。④使用“启动”，把对既有计划的后续部署表述成了计划开始实施，因此排除。","evidence":"中方将继续实施“一带一路”科技创新行动计划","doubt":"","references":[]},{"origin":"k-c4a22491e478581c","title":"2023年继续实施“一带一路”科技创新行动计划","qs":["江苏 2024 A类 行测#2"],"definition":"2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛开幕式上宣布，中方将继续实施“一带一路”科技创新行动计划。","explanation":"“继续实施”表明论坛宣布的是延续已有计划，题中④以“启动”表述这项安排，因而有误。讲话同时提出举办首届“一带一路”科技交流大会，“首届”修饰交流大会。","evidence":"中方将继续实施“一带一路”科技创新行动计划","doubt":"","references":[]}]},"k-9a1be64e7f074b1c":{"review":{"definition":"2023年10月30日至31日，中央金融工作会议在北京召开，提出着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道，并部署优化融资结构。","explanation":"①推动股票发行注册制走深走实、③更好发挥资本市场枢纽功能、④培育一流投资银行和投资机构，都列在通稿关于优化融资结构的同一句中，②建设种类齐全的金融产品体系未列入这项部署，因此题目选C。通稿在同一句中还部署了发展多元化股权融资和提高上市公司质量，随后谈及债券市场、机构定位、市场规则和法人治理。题干的“三大重点方向”是对入选选项的归纳，通稿没有给①③④设这一合称。","references":[{"source":"web-b307fd9f3de643e2","location":"2023年10月31日通稿，高质量发展段","quote":"优化融资结构，更好发挥资本市场枢纽功能"}],"evidence":"更好发挥资本市场枢纽功能，推动股票发行注册制走深走实","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-7a7cfca01295faa4":{"review":{"definition":"一些白蚁会取食木材等含纤维素的材料。","explanation":"B项把树木填在白蚁前面，树木提供食物，白蚁是取食者。这与后半组中岩羊在前、雪豹在后的排列一致，都是食物在前、取食者在后。前半组具体属于对植物材料的取食，后半组属于动物捕食。","references":[],"evidence":"“白蚁”啃食“树木”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6894c1ad4c6ef7a8":{"review":{"definition":"岩羊是雪豹的猎物之一。","explanation":"B项把雪豹填在岩羊后面，形成猎物在前、捕食者在后的顺序。这与前半组树木在前、白蚁在后的取食方向一致。C项前半组是蚂蚁与白蚁的并列关系，两端关系无法对应。","references":[],"evidence":"“雪豹”捕食“岩羊”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2e7b53738a5af272":{"review":{"definition":"南京江宁织造博物馆的《大梦·红楼》是以《红楼梦》为主题的行进式沉浸体验项目。观众可以沿不同路线近距离观看原著情节并与角色互动。","explanation":"多条观众动线和近距离互动让年轻观众以第一人称进入故事。一些原本对《红楼梦》了解不深的年轻人体验后决定重读原著。第1题可把吸引青年参与、激发重读兴趣概括为南京案例的两项成效。","references":[],"evidence":"一些原本对《红楼梦》了解不深的年轻人体验后也决定回去重读原著","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f8537163f95838cd":{"review":{"definition":"西安大唐不夜城、钟鼓楼广场等地的古装对诗活动，由身着古装的对诗人与游客、路人现场接诗，把诗词融入古都游览。","explanation":"材料中，扮演李白的演员观察到，能接出“兰陵美酒郁金香”下一句的游客越来越多，还有孩子相约再来对诗。第1题可据此概括游客诗词兴趣和储备的增长，并结合肖教授的评价，写出活动丰富了旅游参与体验、增强了情感共鸣。","references":[],"evidence":"游客对诗词的兴趣和储备量在显著增长","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5cf243b09f274fec":{"review":{"definition":"山西省文旅厅依托游戏《黑神话：悟空》中的山西古建场景，推出主题旅游线路和线下集章打卡活动，吸引玩家实地游览。","explanation":"佛光寺、小西天等景区设置线下打卡点，游客可领取通关文牒、集章，延续游戏体验。材料还提到部分活动安排采纳了网友建议。第1题可将这些做法及其成效概括为回应玩家需求、吸引海内外游客、拓展文旅发展新赛道。","references":[],"evidence":"山西省文旅厅在佛光寺、崇福\n寺、小西天、玉皇庙等景区设立了线下存档点（打卡点）","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3bde6e2c223b5398":{"review":{"definition":"自贡以恐龙为核心，借动画《时空龙骑士》融入盐井、彩灯、美食等地域特色，并围绕恐龙形象开发旅游业态和衍生产品。","explanation":"主题餐厅、游乐园等业态与玩具、服装等衍生产品打通了动漫上下游产业链，产生经济效益。动画传播和线下体验也使游客和居民对自贡的地域文化形成更鲜明的认识。第1题应兼顾经济效益和塑造城市特色、增强城市核心竞争力两方面成效。","references":[],"evidence":"让超级IP产生了巨大的经济效益","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-b26307b915e73427":{"review":{"definition":"苏州博物馆以毛绒大闸蟹、吴王夫差剑系列文创等产品吸引游客了解文物和地方文化，并通过VR展览拓展参观体验。","explanation":"模拟买蟹的互动让游客在购物中感受苏州特色，卡通化的吴王夫差剑让文物走近年轻人。门票收入来自苏州博物馆西馆的宇宙探索VR展，产业空间的拓宽则对应材料所述苏州文创与旅游、科技、金融等领域的跨界融合。第1题可据此分别归纳文化传播、门票收入和产业拓展三方面成效。","references":[],"evidence":"让更多的年轻人开始深入了解文物和苏州文化","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2c9e8610df30c021":{"review":{"definition":"2024年5月28日上午，扬州市第三届大运河青年文创产业合作大会在扬州广陵公共文化中心举行。扬州市青商会的青年创客和相关院校、企业、产业基金的嘉宾参会，共谋文创产业发展。","explanation":"江苏2025年A类申论第3题要求写一则大会简讯。开头交代大会全称、时间、地点和参会人员，随后用平台发布、展厅授牌和工作坊启动写出本届大会的三项亮点。","references":[],"evidence":"2024年5月28日上午，扬州市第三届大运河青年文创产业合作大会在扬州广陵公共文化中心举行。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-66c8d4e83c6dd4d4":{"review":{"definition":"扬州市大运河青年文创展厅在第三届大运河青年文创产业合作大会现场举行授牌仪式。材料6将这项活动与推进产学研深度融合、增强扬州经济发展活力联系起来。","explanation":"简讯可把展厅授牌列为一项单独的亮点，接着写材料所述的发展意义。平台发布对应创作者权益保护，展厅授牌在材料中对应产学研融合。","references":[],"evidence":"通过产学研的深度融合，为扬州经济发展注入新的活力。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2fbfba807bb9a3d8":{"review":{"definition":"“行走扬州城：文创产品设计与体验研究生工作坊”在扬州市第三届大运河青年文创产业合作大会上启动，由扬州广陵区与五所高校联合实施。","explanation":"简讯可用跨校联合、跨学科设计实践写清这项亮点。工作坊计划组织不同学科和专业的学生，围绕文旅、交通、健康医疗等具体场景探索用户体验设计方法。","references":[],"evidence":"学生设计实践，聚焦文旅、交通、健康医疗、智慧服务、社区邻里、低碳产业等场景塑造","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ce1e1cc79bdb2c0f":{"review":{"title":"跳出历史周期率的两个答案","type":"事实与事件","definition":"毛泽东在延安时期提出让人民监督政府，这是党探索跳出历史周期率的第一个答案。进入新时代，习近平提出党的自我革命是第二个答案。","explanation":"人民监督强调从外部监督政府权力运行。党的自我革命强调党主动发现和解决自身存在的问题，推进自我净化、自我完善、自我革新、自我提高。","basis":"据关联原题及所列出处编释。","references":[{"source":"cycle","location":"提出“第二个答案”与“让人民来监督政府”的段落"}],"related":["k-1632ca8680fadb9b","k-843675050c632a63"],"examFocus":{"江苏 2025 A类 行测#2":"辨析跳出历史周期率的两个答案各自的提出背景，并核对各项表述是否属于新时代全面从严治党的成就。"}},"readings":[{"origin":"k-ce1e1cc79bdb2c0f","title":"跳出历史周期率的两个答案","qs":["江苏 2025 A类 行测#2","江苏 2025 C类 行测#2"],"definition":"毛泽东在延安时期提出让人民监督政府，这是党探索跳出历史周期率的第一个答案。进入新时代，习近平提出党的自我革命是第二个答案。","explanation":"人民监督强调从外部监督政府权力运行。党的自我革命强调党主动发现和解决自身存在的问题，推进自我净化、自我完善、自我革新、自我提高。","evidence":"","doubt":"","references":[{"source":"cycle","location":"提出“第二个答案”与“让人民来监督政府”的段落"}]},{"origin":"k-7d3ecb3be04078cc","title":"跳出历史周期率的两个答案","qs":["江苏 2025 B类 行测#2"],"definition":"跳出历史周期率的第一个答案是毛泽东在延安提出的让人民监督政府，第二个答案是习近平在新时代提出的党的自我革命。","explanation":"第2题问的是新时代全面从严治党取得的成就。②把提出第一个答案列入新时代成就，错在提出的时段和归属，因此排除。","evidence":"而在新时代，习近\n平总书记给出了第二个答案，这就是自我革命。","doubt":"","references":[]}],"aspects":[{"title":"两个答案的提出背景","uses":[{"unit":"Q1","role":"解题依据","use":"题干要求判断新时代全面从严治党的成就。②所说的第一个答案提出于延安时期，新时代给出的是第二个答案，因此排除②。","evidence":"毛泽东同志在延安的窑洞里给出了跳出历史周期率的第一个答案，即让人民监督政府。","qids":["江苏 2025 A类 行测#2","江苏 2025 C类 行测#2"]}]}]},"k-f1794b73be348a2f":{"review":{"title":"新时代十年反腐败斗争的成效","type":"事实与事件","definition":"2022年党的二十大报告在总结新时代十年的伟大变革时指出，反腐败斗争取得压倒性胜利并全面巩固。","explanation":"2023年1月9日，习近平在二十届中央纪委二次全会上回顾这十年的反腐败工作，将无禁区、全覆盖、零容忍和一体推进不敢腐、不能腐、不想腐列为取得这一成效的做法。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"新时代十年的伟大变革"}],"examFocus":{"江苏 2025 A类 行测#2":"对照新时代全面从严治党的成就表述，核对反腐败斗争的阶段性成效、制度建设和政治建设的定位。"}},"aspects":[{"title":"压倒性胜利并全面巩固","uses":[{"unit":"Q1","role":"直接考查","use":"③用“取得压倒性胜利并全面巩固”概括反腐败斗争成效，与解析所引二十届中央纪委二次全会讲话一致，属于题干所问的新时代全面从严治党成就。","evidence":"开展了史无前例的反腐败斗争，取得压倒性胜利并全面巩固","qids":["江苏 2025 A类 行测#2","江苏 2025 B类 行测#2"]}]}]},"k-3c81c9cf5ea445eb":{"review":{"title":"江苏考察中的公共文化服务部署","type":"事实与事件","definition":"2023年7月，习近平总书记在江苏考察时提出，江苏要繁荣发展文化事业和文化产业，持续推进城乡公共文化服务标准化、均等化。","explanation":"这项部署属于江苏在建设中华民族现代文明上探索新经验的任务，与优秀传统文化的保护传承和创新发展等要求相衔接。标准化着眼于明确服务标准，均等化着眼于促进城乡居民公平获得基本公共文化服务。","basis":"据关联原题及所列出处编释。","references":[{"source":"culture","location":"文化传承与城乡公共文化服务"}],"domain":"文化","examFocus":{"江苏 2025 A类 行测#3":"对照江苏考察中关于中华民族现代文明建设的部署，辨明城乡公共文化服务与文化保护传承、群众素质提升分别着眼于什么。"}},"aspects":[{"title":"城乡公共文化服务标准化、均等化","uses":[{"unit":"Q1","role":"直接考查","use":"本题均将推进城乡公共文化服务标准化、均等化与传统文化保护传承、提升群众科学文化素质等并列在判断③中。③符合江苏建设中华民族现代文明的任务，四项做法均正确，答案为D。","evidence":"繁荣发展文化事业和文化产业，持续推进城乡公共文化服务标准化、均等化","qids":["江苏 2025 A类 行测#3","江苏 2025 C类 行测#3"]}]}]},"k-fdb936b2713f2cd4":{"review":{"definition":"长三角一体化推动了高频政务服务跨省通办、异地就医门诊费用直接结算和轨道交通互联。2024年12月的长三角区域合作新闻发布会披露，长三角高铁营业里程已超过7600公里。","explanation":"政务服务跨省通办和异地就医直接结算体现公共服务共享，高铁营业里程体现基础设施互联与“轨道上的长三角”建设进展，两方面共同支持①。","references":[],"evidence":"长三角高铁营业里程超7600公里","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5a55e792676dd28e":{"review":{"definition":"长三角一体化上升为国家战略后的六年间，区域产业联系趋于紧密、科技协同加快、生态环境持续改善、民生服务持续提升。","explanation":"②概括的是长三角区域在四个方面的整体进展。③的粮食生产“三增”出自江苏省政府工作报告对本省城乡区域协调发展的总结，题目据此区分两项表述的成果归属。","references":[],"evidence":"产业发展日趋密切、科技协同不断加快、生态环境持续改善、民生服务更有温度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fc8e96691efe87fe":{"review":{"definition":"2023年11月，习近平在深入推进长三角一体化发展座谈会上指出，长三角区域整体实力和综合竞争力持续位居全国前列，其作为我国参与国际竞争合作重要平台的作用日益显现。","explanation":"④将讲话总结的两项成效放在一起。整体实力和综合竞争力描述长三角在全国的相对地位，重要平台描述长三角在我国参与国际竞争合作中的作用。","references":[],"evidence":"我国参与国际竞争合作的重要平台的作用日益显现","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-38326e9aa1121683":{"review":{"definition":"据国家统计局2024年发布的新中国75年经济社会发展成就系列报告，2023年中国经济总量超过126万亿元，稳居世界第二位。","explanation":"①所说的世界第二对应报告中的经济总量排名。2023年的数据为题目总结新中国成立75年来的经济发展成就提供了依据。","references":[],"evidence":"稳居世界第二大经济体","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-063d241efdaa2c5f":{"review":{"definition":"国家统计局2024年发布的新中国75年经济社会发展成就系列报告指出，中国制造业增加值连续14年位居世界第一。","explanation":"②所称的“世界第一制造业大国”以制造业增加值排名为依据，“连续十四年”采用该报告总结75年发展成就时的统计口径。","references":[],"evidence":"制造业增加值连续14年位居世界第一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b5af8b71a88c0b0e":{"review":{"definition":"国家统计局2024年发布的新中国75年经济社会发展成就系列报告将谷物列为中国产量居全球首位的农产品。","explanation":"③将谷物产量写为世界第二，与报告所列的全球首位冲突。判断③应直接核对谷物产量的全球位次，报告中粮食总产量的历史增幅用于说明另一项成就。","references":[],"evidence":"谷物、肉类、花生、茶叶、水果等农产品产量居全球首位","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f1a1af0cf7cd9ca6":{"review":{"title":"改革开放以来中国对世界经济增长的贡献","type":"事实与事件","definition":"国家统计局2024年9月发布的新中国成立75年经济社会发展成就系列报告指出，改革开放以来，中国经济持续快速增长，成为世界经济增长的重要引擎和稳定力量。","explanation":"对世界经济增长的贡献率衡量同一时期中国经济增量占世界经济增量的份额。经济总量占比衡量中国经济总量在世界经济总量中的份额。","basis":"据关联原题及所列出处编释。","references":[{"source":"econ","location":"对世界经济增长的贡献"}],"examFocus":{"江苏 2025 A类 行测#11":"区分新中国成立75年来的经济指标全球位次与改革开放后中国对世界经济增长的作用。"}},"aspects":[{"title":"改革开放以来的全球增长作用","uses":[{"unit":"Q1","role":"直接考查","use":"第④项关于改革开放以来中国成为世界经济增长重要引擎的表述正确，应列入答案B所含的①②④。","evidence":"④改革开放以来成为世界经济增长的重要引擎","qids":["江苏 2025 A类 行测#11","江苏 2025 C类 行测#11"]}]}]},"k-6f205dd91f2cf9b4":{"review":{"definition":"1931年11月和1934年1月先后召开的两次中华苏维埃全国代表大会，是中国共产党领导人民实行工农兵代表大会制度的早期实践。这一实践是人民代表大会制度形成和发展的历史起点。","explanation":"第一次大会制定《中华苏维埃共和国宪法大纲》，宣告中华苏维埃共和国临时中央政府成立。这一政权建设实践早于抗日根据地的“三三制”，题中①把历史起点归给“三三制”，因此错误。","references":[],"evidence":"这两次大会是\n工农兵代表大会制度政体的演练","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a82b9b68e6b8ded9":{"review":{"definition":"1949年9月29日，中国人民政治协商会议第一届全体会议通过《中国人民政治协商会议共同纲领》。这份具有临时宪法作用的文件对新中国实行人民代表大会制度作出明确安排。","explanation":"题中②所问的是《共同纲领》是否已经明确安排这一制度，因此②正确。③所指的1954年宪法在这一基础上对人民代表大会制度作出系统规定，对应制度建立的节点。","references":[],"evidence":"《中国人民政治协商会议共同纲领》对新中国实行人民代表大会制度作出了明确安排","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d57761b82caee59e":{"review":{"definition":"1954年，第一届全国人民代表大会第一次会议通过《中华人民共和国宪法》，系统规定了人民代表大会制度，标志着这一制度的建立。","explanation":"题中③对应首届全国人大召开并通过宪法这一制度建立节点，因此正确。题干所说的2024年建立70周年，也对应1954年这一时点。","references":[],"evidence":"一届全国人大一次会议通过《中华人民共和国宪法》，标志着人民代表大会制度的建立","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-03bf9b375ad43c3f":{"review":{"definition":"1979年，第五届全国人民代表大会第二次会议通过修宪决议和地方组织法，规定县级以上地方各级人民代表大会设立常务委员会。","explanation":"县级以上地方人大有了常设机关，可以在本级人民代表大会闭会期间依法履行相应职责。题中④把这一制度完善与五届全国人大二次会议对应起来，设置范围也准确。","references":[],"evidence":"五届全国人大二次会议通过修宪决议和地方组织法，规定县级以上地方各级人大设立常委会","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-66cb1dc04f9c6619":{"review":{"title":"玉米的种子繁殖","type":"事实与事件","definition":"玉米可用含有活胚的成熟籽粒繁殖。籽粒在适宜条件下可以萌发成幼苗。","explanation":"播种所用的玉米籽粒在植物形态上属于颖果，果皮与种皮紧密结合。种质能否采用常规低温种子保存，还取决于籽粒对干燥和低温的耐受性。","basis":"据关联原题及所列出处编释。","references":[{"source":"seed","location":"玉米 · 籽粒的构造"}],"domain":"科技","examFocus":{"江苏 2025 A类 行测#48":"从文中找出保存方式与作物繁殖材料的对应关系，再用文中的例外核对适用条件。","江苏 2025 C类 行测#48":"从文中找出保存方式与作物繁殖材料的对应关系，再用文中的例外核对适用条件。"}},"aspects":[{"title":"由繁殖材料推断种质保存方式","uses":[{"unit":"Q1","role":"解题依据","use":"本题选A。结合玉米可用籽粒繁殖及材料所说的主要保存方式，推断国家作物种质库最可能对玉米采用低温种子保存。","evidence":"玉米作为有种子的作物","qids":["江苏 2025 A类 行测#48"]},{"unit":"Q2","role":"解题依据","use":"本题选A。玉米具有可作种用的籽粒，结合材料对低温种子保存的说明，可推断这是题设中最可能的保存方式。","evidence":"玉米作为有种子的作物","qids":["江苏 2025 C类 行测#48"]}]}]},"k-a73000e7aceaddf1":{"review":{"definition":"题图所示的敦煌汉简残片记载了九九乘法口诀。这类用来记忆个位数相乘结果的口诀，今天仍广泛用于学习乘法和口算。","explanation":"简文按乘数和乘积排列，如“四九卅六”即“四九三十六”。辨认出这种写法，就能判断①所说的“仍在广泛使用”指乘法口诀。②所说的河流水位季节变化和④所说的汉代经丝绸之路西传，都缺少题图材料的支持。","references":[],"evidence":"竹简上记载的是九九乘法口诀","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bcf7a0f57fd095f2":{"review":{"definition":"敦煌出土的汉代九九乘法口诀简以十和一为单位表示乘积，反映了中国至迟在汉代已经使用十进制计数。","explanation":"“四九卅六”的乘积是三十六，“卅”表示三个十，“六”表示六个一。判断③的依据是乘积按十和一组合记数。题图能支持的时间结论是这种计数方式在汉代已经使用。","references":[],"evidence":"竹简上的内容表明我国很早开始使用十进制计数法","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8e0813a8bbe20d9c":{"review":{"definition":"石墨具有耐高温、导电和润滑等性能，广泛用于冶金、机械和电子等行业，常被称为“工业黑金”。","explanation":"石墨的耐高温性适合冶金中的高温工况，导电性使它可用于电极，润滑性使它可用于机械润滑。这些用途支持第15题D项对石墨应用范围和称谓的表述。","references":[],"evidence":"在工业生产中应用广泛，被誉为“工业黑金”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4b067c6b484e946b":{"review":{"definition":"鲜柿子可经晾晒制成柿饼，鲜葡萄也可经晾晒制成葡萄干。","explanation":"四个选项都符合原料与成品的对应关系。按题目采用的常见制法，柿饼和D项的葡萄干都可由鲜果晾晒脱水制成，土豆泥、花生糖和椰子汁的常见制法均无这一共同环节。","references":[],"evidence":"题干“柿子”制成“柿饼”和D项“葡萄”制成“葡萄干”的过程中都需要经过“晾晒”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f4e36106416a38d9":{"review":{"definition":"上海港位于长江与东海交汇处，既是中国沿海的主要枢纽港，也是国际大港。","explanation":"“沿海港口”按地理位置分类，“国际大港”按港口规模和国际往来属性分类。两类有交集，上海港同时落入这两个类别，因此题干的第二项分别与第一项、第三项构成归属关系。","references":[],"evidence":"“上海港”既是“沿海港口”，又是“国际大港”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d11229eca7dfd1fa":{"review":{"definition":"中欧班列是往来于中国与欧洲的铁路货运班列，具有跨境、长途两种属性。","explanation":"“跨境”看线路是否跨越国境，“长途”看运输距离。A项的中欧班列同时属于跨境班列和长途班列，与题干中上海港同时属于沿海港口和国际大港的结构一致。","references":[],"evidence":"“中欧班列”既是“跨境班列”，又是“长途班列”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d08306ba8e76fafd":{"review":{"definition":"材料将兴化大米列为国家地理标志产品和“水韵苏米”建设的重要品牌，戴窑镇是其主产区。","explanation":"兴化地处江淮之间，河湖港汊交错。宣传稿开篇可从这种产地条件写到兴化大米米粒饱满、柔软油润等品质，让读者知道戴窑主产的兴化大米有何地方特色。","references":[],"evidence":"米粒饱满、柔软油润、口感特佳","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6db670ed63b60998":{"review":{"definition":"习近平新时代中国特色社会主义思想继承和发展了马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想和科学发展观，是马克思主义中国化时代化的最新成果。","explanation":"①以对既有理论成果的继承和发展，说明这一思想开辟了马克思主义中国化时代化的新境界。③将确立社会主义市场经济体制改革目标和基本构架等早期改革成果归入这一思想的历史贡献，归属有误。①应选，含③的组合应排除。","references":[],"evidence":"开辟了马克思主义中国化时代化的新境界","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-45dfe5b678d22d1f":{"review":{"definition":"习近平新时代中国特色社会主义思想是全党全国各族人民为实现中华民族伟大复兴而奋斗的行动指南，是新时代党和国家发展事业的根本遵循。","explanation":"④从两个层面说明指导作用。“行动指南”对应全党全国各族人民实现中华民族伟大复兴的奋斗实践，“根本遵循”对应新时代党和国家事业的整体发展。④与①的理论地位、②的文化定位共同构成正确组合B。","references":[],"evidence":"是新时代党和国家发展事业的根本遵循","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6fa2921665cf9427":{"review":{"definition":"原题引文：反腐败斗争取得压倒性胜利并全面巩固","explanation":"讲话将这一成就与坚持无禁区、全覆盖、零容忍以及一体推进不敢腐、不能腐、不想腐相联系，本题③直接对应这一表述。给定组合C还包含④。公开回忆版④写“党的政治各方面”，而讲话原文写“党的各项建设”，③的原文依据只能确认这一分项。","references":[{"source":"web-98350e005102fa64","location":"《求是》全文转载，新时代十年构建全面从严治党体系成果段","quote":"反腐败斗争取得压倒性胜利并全面巩固"},{"source":"web-c724397a3a8ab268","location":"第2题，陈述④及选项C","quote":"把制度建设贯穿党的政治各方面"}],"evidence":"反腐败斗争取得压倒性胜利并全面巩固","disposition":"独立词条","basis":"据原题与所列资料编释。"},"sources":[{"id":"02a36e66317d2ef6","label":"中国特色反腐败之路","topic":"党政制度与理论","category":"非时政","text":"1.中国特色反腐败之路\n《决定》从四个方面对坚定走好中国特色反腐败之路作出部署：一是保持惩治腐败高\n压态势，深化权力集中、资金密集、资源富集领域腐败问题整治，重点查处政治问题和经\n济问题交织、政商勾连、资本向政治领域渗透等问题，深挖细查新型腐败和隐性腐败，常\n态化整治群众身边不正之风和腐败问题；二是加强对权力运行的制约和监督，健全授权用\n权制权相统一、清晰透明可追溯的制度机制，更加科学有效地把权力关进制度笼子；三是\n夯实崇廉拒腐思想根基，加强新时代廉洁文化建设，运用党的创新理论蕴含的理想信念、\n价值理念、道德观念、纪法意识涵养党员、干部清廉操守；四是增强一体推进不敢腐、不\n能腐、不想腐综合效能，抓实以案促改促治，提高反腐败穿透力。","source":{"doc":"41195a191a57c1c36332","first":18,"last":18,"page":18,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-774a03c640316516":{"review":{"definition":"据国家统计局2024年发布的新中国成立75年经济社会发展成就系列报告，2023年中国经济总量居世界第二位。","explanation":"本题①对应的是一国经济总量的全球排名。报告以2023年的数据说明中国稳居世界第二大经济体，因此①正确。","references":[],"evidence":"稳居世界第二大经济体","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f27867b159ee08c9":{"review":{"definition":"国家统计局2024年发布的新中国成立75年经济社会发展成就系列报告指出，中国制造业增加值连续14年位居世界第一。","explanation":"本题②以制造业增加值的世界排名来判断制造业大国地位，报告同时给出了世界第一的位次和连续保持14年的时长。这个年数对应2024年发布的报告口径。","references":[],"evidence":"制造业增加值连续14年位居世界第一","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5951283b185a91f0":{"review":{"definition":"国家统计局2024年发布的新中国成立75年经济社会发展成就系列报告指出，中国谷物产量居全球首位。","explanation":"本题③将谷物产量的世界位次写成第二，和报告给出的全球首位相冲突。同一段中的粮食总产量用于说明国内长期增产，判断③直接依据谷物产量的全球排名。","references":[],"evidence":"谷物、肉类、花生、茶叶、水果等农产品产量居全球首位","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5bf27567017d8bdb":{"review":{"definition":"晾晒是柿饼和葡萄干的传统加工方式，水果在晾晒过程中逐渐失水，形成干制品。","explanation":"四个选项都符合原材料与成品的对应关系。按题目采用的传统制法，柿子制成柿饼与葡萄制成葡萄干都有晾晒失水这一环节，因此D项最接近。土豆泥、花生糖和椰子汁的成品都可在无晾晒环节的情况下制得。","references":[],"evidence":"的过程中都需要经过“晾晒”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d777e5dd64b1818a":{"sources":[{"id":"badca066739db427","label":"中共中央政治局常委会全天会议（1 月 8 日）","topic":"重要会议讲话","category":"时政","text":"考点一 中共中央政治局常委会全天会议（1 月 8 日）\n要坚持好、运用好、发展好党的领导这一最大优势，为中国式现代化建设提供根本保证；树立\n和践行正确政绩观，坚持为人民出政绩、以实干出政绩。","source":{"doc":"4e539a366dce19555ccf","first":1,"last":1,"page":1,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-165ca0f7975abd4e":{"sources":[{"id":"2198cd51fe41f020","label":"二十届中央纪委五次全会（1 月 12 日）","topic":"重要会议讲话","category":"时政","text":"考点二 二十届中央纪委五次全会（1 月 12 日）\n强调，坚持和加强党的全面领导，以更高标准、更实举措推进全面从严治党，提出“三个更\n加”：更加坚决有力地贯彻落实党中央重大决策部署、更加科学有效地把权力关进制度笼子、\n更加清醒坚定地推进反腐败斗争。\n“十五五”时期是基本实现社会主义现代化夯实基础、全面发力的关键时期；党的自我革命重\n在治权；腐败是党和国家事业发展进程中的拦路虎、绊脚石，反腐败是一场输不起也决不能输\n的重大斗争；要保持高压态势不动摇，有腐必反、有贪必肃、除恶务尽，走标本兼治、一体推\n进不敢腐不能腐不想腐的中国特色反腐败之路。","source":{"doc":"4e539a366dce19555ccf","first":1,"last":1,"page":1,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-3910c4012627546e":{"sources":[{"id":"24da87f53b499230","label":"二十届中央纪委五次全会公报（1 月 12 日）","topic":"重要会议讲话","category":"时政","text":"考点三 二十届中央纪委五次全会公报（1 月 12 日）\n公报提出“四个深刻把握”和“六个强化”：强化政治监督，推动全党凝心聚力实现“十五\n五”时期目标任务；强化正风肃纪，巩固拓展深入贯彻中央八项规定精神学习教育成果（以经\n常性学习教育为基础、以压实责任为关键、以风腐同查同治为抓手）；强化标本兼治，以保持\n高压震慑强化不敢腐、以加强监督制约强化不能腐、以深化廉洁教育强化不想腐；强化执纪执\n法为民，深化群众身边不正之风和腐败问题集中整治（县级主战场）；强化政治巡视；强化铁\n军意识，推进纪检监察工作规范化法治化正规化建设。","source":{"doc":"4e539a366dce19555ccf","first":1,"last":1,"page":1,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-af06f55ae2602ed9":{"sources":[{"id":"40076cdaeb35b515","label":"省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班（1 月20 日）","topic":"重要会议讲话","category":"时政","text":"考点四 省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班（1 月\n20 日）\n制定和实施五年规划是我们党治国理政一条重要经验，是中国特色社会主义制度一个重要政治\n优势，有四个“有利于”：有利于实现党的领导、集中力量办大事、前瞻性把握战略问题、保\n持事业连续性。\n创造积累了“五个坚持”经验：坚持党中央集中统一领导、坚持从实际出发、坚持全国一盘\n棋、坚持发扬民主集思广益、坚持规划法定原则。\n领会全会精神要全面、深刻、准确。要坚持智能化、绿色化、融合化方向，保持制造业合理比\n重，大力发展先进制造业；坚持以国内大循环为主体；坚持科学决策、民主决策、依法决策，\n编制好“十五五”规划纲要及专项规划。","source":{"doc":"4e539a366dce19555ccf","first":1,"last":2,"page":1,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-cbcaa67f93c47391":{"sources":[{"id":"7f459cd52c306264","label":"政治局第二十四次集体学习（前瞻布局和发展未来产业）（1 月 30 日）","topic":"重要会议讲话","category":"时政","text":"考点五 政治局第二十四次集体学习（前瞻布局和发展未来产业）（1 月 30 日）\n强调，新一轮科技革命和产业变革加速演进，要站在推进强国建设、民族复兴伟业的战略高\n度，立足客观条件，发挥比较优势，坚持稳中求进、梯度培育。\n未来产业具有前瞻性、战略性、颠覆性等特点；科技突破的程度很大程度上决定未来产业发展\n的速度、广度、深度，坚持“产业出题、科技答题”；要发挥企业主体作用；未来产业培育周\n期长、市场风险大，政策上要支持、政府要做好服务；必须健全治理体系，统筹发展和安全，\n确保既“放得活”又“管得好”。","source":{"doc":"4e539a366dce19555ccf","first":2,"last":2,"page":2,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-4e92d9fdc511916f":{"sources":[{"id":"f2b8deef514ff39c","label":"对国家自然科学基金委员会工作作出重要指示（2 月）","topic":"重要会议讲话","category":"时政","text":"考点六 对国家自然科学基金委员会工作作出重要指示（2 月）\n国家自然科学基金委员会成立 40 年来，在推动基础研究、培养创新人才等方面发挥了积极作\n用，已成为国家资助科研人员开展基础研究的重要渠道。新征程上，要抓住新一轮科技革命和\n产业变革历史机遇，坚持“四个面向”战略导向（面向世界科技前沿、面向经济主战场、面向\n国家重大需求、面向人民生命健康），强化基础研究战略性、前瞻性、体系化布局，深化科学\n基金改革，完善资助体系、提升资助效能，支持科研人员勇攀科学高峰、产出更多原创性成\n果，为推进高水平科技自立自强、建设科技强国作出更大贡献。","source":{"doc":"4e539a366dce19555ccf","first":2,"last":2,"page":2,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-e9de3c83e8740c28":{"sources":[{"id":"c98e0858f8daa9b3","label":"在北京考察并看望慰问基层干部群众（2 月）","topic":"重要会议讲话","category":"时政","text":"考点七 在北京考察并看望慰问基层干部群众（2 月）\n建设社会主义现代化强国，关键在科技自立自强，北京要发挥自身优势作出更大贡献，勉励科\n技工作者厚植报国情怀、发扬奋斗精神。北京要立足城市战略定位和京津冀协同发展，牵住疏\n解北京非首都功能这个推动京津冀协同发展的“牛鼻子”，坚持控增量和疏存量相结合，实现\n疏解和提升有机统一；建设国际一流的和谐宜居之都，必须以首善标准推进城市治理，坚持人\n民城市理念，用好“接诉即办”机制，扎实解决群众急难愁盼问题。","source":{"doc":"4e539a366dce19555ccf","first":2,"last":2,"page":2,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-c38625f3dbdf00f7":{"sources":[{"id":"eaf33db0e980cda9","label":"2026 年政府工作报告（十四届全国人大四次会议）（3 月 5 日）","topic":"重要会议讲话","category":"时政","text":"考点八 2026 年政府工作报告（十四届全国人大四次会议）（3 月 5 日）\n回顾“十四五”：GDP 连续跨越 110 万亿、120 万亿、130 万亿、140 万亿元台阶，年均增长\n5.4%；居民人均可支配收入年均增长 5.4%；研发经费投入强度 2.8%，首超 OECD 平均水平；制\n造业增加值连续 16 年全球第一；人均预期寿命 79.25 岁。\n规律性认识“五个必须”：充分挖掘经济潜能、政策支持和改革创新并举、既“放得活”又\n“管得好”、投资于物和投资于人紧密结合、以苦练内功应对外部挑战。","source":{"doc":"4e539a366dce19555ccf","first":2,"last":2,"page":2,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-d5b896f2987f9ffe":{"sources":[{"id":"ca812adc30f15204","label":"参加江苏代表团审议（3 月 5 日）","topic":"重要会议讲话","category":"时政","text":"考点九 参加江苏代表团审议（3 月 5 日）\n强调完成“十五五”目标任务需应对更复杂环境、解决深层次矛盾，江苏等经济大省要在研究\n新情况、解决新问题上出经验。发展新质生产力对推动高质量发展、增强经济竞争力至关重\n要，要一体推进教育科技人才发展，实现“四新”（原始创新新突破、四链融合新途径、产业\n开创新局面、改革取得新成果）；政绩观总要求为“立党为公、为民造福、科学决策、真抓实\n干”。","source":{"doc":"4e539a366dce19555ccf","first":2,"last":3,"page":2,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-d5a327055a9a96ea":{"sources":[{"id":"8cc2848f6862c74f","label":"看望政协委员参加联组会（健康中国）（3 月 6 日）","topic":"重要会议讲话","category":"时政","text":"考点十 看望政协委员参加联组会（健康中国）（3 月 6 日）\n强调到 2035 年建成健康中国是中共中央作出的战略决策，“十五五”是实现目标的关键时\n期，力求取得决定性进展。要坚持从国情出发，坚定不移走中国特色卫生与健康发展道路，贯\n彻新时代卫生与健康工作方针；健全党委统一领导、党政齐抓共管格局，完善医疗、医保、医\n药协同发展和治理机制。\n新时代卫生与健康工作方针是：以基层为重点，以改革创新为动力，预防为主，中西医并重，\n把健康融入所有政策，人民共建共享。","source":{"doc":"4e539a366dce19555ccf","first":3,"last":3,"page":3,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-23b47310910a98b9":{"sources":[{"id":"0d2814fc25a563e7","label":"出席解放军和武警部队代表团全体会议（3 月 7 日）","topic":"重要会议讲话","category":"时政","text":"考点十一 出席解放军和武警部队代表团全体会议（3 月 7 日）\n强调“十五五”时期如期实现建军一百年奋斗目标、高质量推进国防和军队现代化，必须坚持\n好、运用好、发展好政治建军这个重要法宝，毫不动摇坚持和加强党对军队绝对领导。完成目\n标任务归根到底要靠各级党组织领导和推进；体系推进联合作战指挥、新型作战力量、高层次\n科技创新、高水平战略管理“四类人才”培养。","source":{"doc":"4e539a366dce19555ccf","first":3,"last":3,"page":3,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-3d534270f76b4e6a":{"sources":[{"id":"2b006cb687988fa2","label":"雄安新区考察并主持召开座谈会（3 月 23 日）","topic":"重要会议讲话","category":"时政","text":"考点十二 雄安新区考察并主持召开座谈会（3 月 23 日）\n强调牢牢把握雄安新区作为北京非首都功能疏解集中承载地的首要功能定位，以改革创新为引\n领增强内生发展动力，以要素资源合理集聚为重点激发新区活力，努力建设新时代创新高地和\n推动高质量发展样板。积极稳妥分批推进央企、高校、医院疏解，有序推进金融机构、科研院\n所、事业单位疏解；集中力量推进启动区、起步区建设，努力创造“雄安质量”。","source":{"doc":"4e539a366dce19555ccf","first":3,"last":3,"page":3,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-a7fd487a98b3b6a4":{"sources":[{"id":"87878a8b6f4850e1","label":"参加首都义务植树活动（3 月 30 日）","topic":"重要会议讲话","category":"时政","text":"考点十三 参加首都义务植树活动（3 月 30 日）\n指出我国森林面积和蓄积量持续“双增长”、荒漠化和沙化土地面积持续“双缩减”，是全球\n增绿最多最快的国家；今年为“十五五”开局之年、全民义务植树运动开展 45 周年。新形势\n下要更加注重提质、兴业、利民，实现种与管共抓、生态与产业共促、人与自然共生，以地定\n绿、以水定绿、因地制宜。","source":{"doc":"4e539a366dce19555ccf","first":3,"last":3,"page":3,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-5fa1d95c11d7c10f":{"sources":[{"id":"bf3537bd2802b998","label":"向世界数据组织成立致贺信（3 月 30 日）","topic":"重要会议讲话","category":"时政","text":"考点十四 向世界数据组织成立致贺信（3 月 30 日）\n3 月 30 日世界数据组织成立大会在北京举行，主题为“共建数据合作平台 共享数字发展机\n遇”，这是全球首个旨在推动数据发展与治理实践的专业性国际组织，已汇集 200 余个会员、\n覆盖 40 多个国家。贺信指出，数据的基础资源作用和创新引擎作用日渐显现；该组织以“弥\n合数据鸿沟、释放数据价值、繁荣数字经济”为宗旨。世界数据组织（WDO）为专业性、非政\n府、非营利性国际团体，总部设在北京；中国将秉持共商共建共享理念支持其发挥作用。","source":{"doc":"4e539a366dce19555ccf","first":3,"last":3,"page":3,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-793a000d2d039899":{"sources":[{"id":"42f4b3452eab4809","label":"全国服务业大会（就服务业发展作出重要指示）（4 月 7—8 日）","topic":"重要会议讲话","category":"时政","text":"考点十五 全国服务业大会（就服务业发展作出重要指示）（4 月 7—8 日）\n重要指示指出，党的十八大以来，我国服务业规模稳步扩大、质效持续提升，在支撑产业升\n级、满足民生需要、带动就业扩容等方面发挥重要作用；新征程上要突出需求牵引、改革攻\n坚、科技赋能、开放合作，深入实施服务业扩能提质行动，推进生产性服务业向专业化和价值\n链高端延伸，促进生活性服务业高品质多样化便利化发展，培育更多“中国服务”品牌。2025\n年服务业增加值首破 80 万亿元、占 GDP 比重 57.7%，服务业是国民经济第一大产业。","source":{"doc":"4e539a366dce19555ccf","first":3,"last":4,"page":3,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-92239a56f08a0043":{"sources":[{"id":"ab1f1f1f5f09c4a3","label":"对“义乌发展经验”作出重要指示（4 月 23 日）","topic":"重要会议讲话","category":"时政","text":"考点十六 对“义乌发展经验”作出重要指示（4 月 23 日）\n重要指示指出，义乌小商品闯出大市场、做成大产业，形成“义乌发展经验”，这是因地制宜\n发展县域经济的成功实践；要结合开展树立和践行正确政绩观学习教育，把“义乌发展经验”\n进一步总结好、运用好，引导各地区立足自身资源禀赋，尊重基层和群众首创精神，探索走出\n符合各自实际的高质量发展之路。2006 年 6 月曾以“六大内涵、十二个字、五个结合”加以\n概括，“十二个字”即“莫名其妙、无中生有、点石成金”的发展；改革创新是“义乌发展经\n验”最鲜明的特质。","source":{"doc":"4e539a366dce19555ccf","first":4,"last":4,"page":4,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-711c139879c9d5ca":{"sources":[{"id":"d8a15aa217d9a512","label":"中共中央政治局会议（分析研究当前经济形势和经济工作）（4 月 28日）","topic":"重要会议讲话","category":"时政","text":"考点十七 中共中央政治局会议（分析研究当前经济形势和经济工作）（4 月 28\n日）\n会议指出我国经济起步有力、主要指标好于预期，要坚持稳中求进工作总基调，精准有效实施\n更加积极的财政政策和适度宽松的货币政策，持续扩大内需、优化供给，做优增量、盘活存\n量，着力稳就业、稳企业、稳市场、稳预期（“四稳”，无稳物价），努力实现“十五五”良\n好开局。首次提出加强水网、新型电网、算力网、新一代通信网、城市地下管网、物流网等\n“六网”规划建设；全面实施“人工智能+”行动，发展智能经济新形态；深入整治“内卷\n式”竞争；兜牢基层“三保”底线。","source":{"doc":"4e539a366dce19555ccf","first":4,"last":4,"page":4,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-41b01b79155d86fb":{"sources":[{"id":"146ac361ef11c50b","label":"中共中央政治局第二十五次集体学习（提高防灾减灾救灾能力）（4 月28 日）","topic":"重要会议讲话","category":"时政","text":"考点十八 中共中央政治局第二十五次集体学习（提高防灾减灾救灾能力）（4 月\n28 日）\n强调，要站在统筹高质量发展和高水平安全的战略高度，着力提高防范应对自然灾害能力，切\n实维护人民群众生命财产安全；总结“七个坚持”：坚持党的全面领导，坚持人民至上、生命\n至上，坚持尊重自然规律，坚持预防为主，坚持改革创新，坚持系统观念，坚持社会共治。降\n低灾害风险、减轻灾害损失重在事前预防，要树牢底线思维、极限思维，基层是抵御自然灾害\n的第一线，坚决纠正重发展轻安全、重救灾轻预防等倾向。","source":{"doc":"4e539a366dce19555ccf","first":4,"last":4,"page":4,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-34e1ba9b87210de9":{"sources":[{"id":"c515d1c16c249e6e","label":"在上海出席加强基础研究座谈会（4 月 30 日）","topic":"重要会议讲话","category":"时政","text":"考点十九 在上海出席加强基础研究座谈会（4 月 30 日）\n强调基础研究是整个科学体系的源头，是所有技术问题的总机关，要以更大力度、更实举措加\n强基础研究，提升我国原始创新能力，进一步打牢科技强国建设根基。要坚持“四个面向”战\n略导向（面向世界科技前沿、面向经济主战场、面向国家重大需求、面向人民生命健康），优\n化基础研究系统布局；一体推进教育科技人才发展；逐步提高基础研究经费占比；主动融入全\n球创新网络，积极参与全球科技治理。","source":{"doc":"4e539a366dce19555ccf","first":4,"last":4,"page":4,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-953eb6e0c7852f1e":{"sources":[{"id":"6690d20290ce4eba","label":"同美国总统特朗普会谈（5 月 14 日）","topic":"重要会议讲话","category":"时政","text":"考点二十 同美国总统特朗普会谈（5 月 14 日）\n提出“历史之问、世界之问、人民之问”三问；双方赞同将构建“中美建设性战略稳定关系”\n作为中美关系新定位，内涵为合作为主的积极稳定、竞争有度的良性稳定、分歧可控的常态稳\n定、和平可期的持久稳定，强调“不是一句口号，而应该是相向而行的行动”。中美经贸关系\n本质是互利共赢，平等协商是唯一正确选择；台湾问题是中美关系中最重要的问题，维护台海\n和平稳定是双方最大公约数。","source":{"doc":"4e539a366dce19555ccf","first":5,"last":5,"page":5,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-814d6a5b452d758e":{"sources":[{"id":"217ab3748e9c0812","label":"欢迎特朗普总统宴会讲话（5 月 14 日）","topic":"重要会议讲话","category":"时政","text":"考点二十一 欢迎特朗普总统宴会讲话（5 月 14 日）\n指出 2026 年是中国“十五五”开局之年，也是美国独立 250 周年；55 年前中美开展“乒乓外\n交”，推开了中美冰封 20 多年的大门。强调中美关系是当今世界最重要的双边关系，只能搞\n好不能搞坏；两国合则两利、斗则俱伤，应该成为伙伴而不是对手；能不能做到相互尊重、和\n平共处、合作共赢是双边关系能否稳定发展的关键所在；中美关系承载两国 17 亿多人民福\n祉，关乎世界 80 多亿人民利益。","source":{"doc":"4e539a366dce19555ccf","first":5,"last":5,"page":5,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-889f65e7bdd7c9af":{"sources":[{"id":"c29c3523cc0bccaf","label":"同俄罗斯总统普京会谈（5 月 20 日）","topic":"重要会议讲话","category":"时政","text":"考点二十二 同俄罗斯总统普京会谈（5 月 20 日）\n今年是中俄战略协作伙伴关系建立 30 周年和条约签署 25 周年。以“千磨万击还坚劲”的毅\n力、“更上一层楼”的精神、“乱云飞渡仍从容”的勇气概括中俄关系，强调双方恪守“不结\n盟、不对抗、不针对第三方”原则，发展新时代全面战略协作伙伴关系，成为世界百年变局中\n的关键恒量。","source":{"doc":"4e539a366dce19555ccf","first":5,"last":5,"page":5,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-67f7c4230addfc08":{"sources":[{"id":"4e23485ad3b5a2b7","label":"全国党建工作座谈会（党建思想）（6 月 15 日）","topic":"重要会议讲话","category":"时政","text":"考点二十三 全国党建工作座谈会（党建思想）（6 月 15 日）\n会议认为，党的十八大以来，党中央围绕“建设什么样的长期执政的马克思主义政党、怎样建\n设长期执政的马克思主义政党”重大时代课题，提出一系列新理念新思想新战略，形成党建思\n想。内涵概括为“十四个坚持”（涵盖党的领导、党中央集中统一领导、全面从严治党、初心\n使命、政治建设统领、创新理论凝心铸魂、锤炼坚强党性、组织体系、高素质干部队伍、作风\n建设、严明纪律、一体推进“三不腐”、制度治党依规治党、落实管党治党政治责任）。","source":{"doc":"4e539a366dce19555ccf","first":5,"last":5,"page":5,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-25654b2f8b485b25":{"sources":[{"id":"30aa6e7fa07f6f83","label":"对常态化做好东西部协作工作作出重要指示（6 月）","topic":"重要会议讲话","category":"时政","text":"考点二十四 对常态化做好东西部协作工作作出重要指示（6 月）\n指出，东西部协作开展 30 年来，在助力脱贫攻坚、促进区域协调发展等方面发挥了重要作\n用，彰显了我们党的政治优势和我国社会主义制度的优越性。今年是“十五五”开局之年，也\n是开展常态化帮扶第一年。要总结运用闽宁协作等有益经验，进一步完善协作机制，优化协作\n方式，拓展协作领域，推动东西部产业互补、人员互动、技术互学、观念互通、作风互鉴，实\n现互利共赢、共同发展。","source":{"doc":"4e539a366dce19555ccf","first":5,"last":5,"page":5,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-9ac8f92c1c425920":{"sources":[{"id":"4de823901aceb5b3","label":"在山东德州考察（6 月 24 日）","topic":"重要会议讲话","category":"时政","text":"考点二十五 在山东德州考察（6 月 24 日）\n强调，农业农村现代化关系中国式现代化全局和成色，要以扎实举措做好各项工作，着力提升\n农业综合生产能力和质量效益，确保粮食等重要农产品稳定供给，因地制宜推进宜居宜业和美\n乡村建设。他强调保障粮食等重要农产品稳定供给是农业生产的重中之重，要落实粮食生产支\n持政策，稳步提高单产和效益，力争全年粮食丰收。他了解片区化推进乡村振兴做法，希望村\n党组织进一步发挥党建引领作用，并指出树立和践行正确政绩观，最终要落到为民造福上。","source":{"doc":"4e539a366dce19555ccf","first":5,"last":6,"page":5,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-580b8200386ad0f2":{"sources":[{"id":"fa6ef46684599940","label":"中共中央政治局会议（研究部署防汛抗旱工作）（6 月 30 日）","topic":"重要会议讲话","category":"时政","text":"考点二十六 中共中央政治局会议（研究部署防汛抗旱工作）（6 月 30 日）\n会议指出，今年主汛期我国极端天气气候事件仍将偏多、旱涝并重，各地区各有关部门要树牢\n底线思维、极限思维，立足防大汛、抗大旱、防强台风，采取有力措施做好防汛抗旱、抢险救\n灾各项工作。要始终把人民生命安全放在首位，提高监测预报精准度，及时果断组织人员转移\n避险，严防出现群死群伤；确保大江大河大湖防洪安全，全面加强河湖行洪空间管控；高度重\n视旱涝急转风险，坚持防汛抗旱两手抓，加强水源统一管理和调度；保障重大基础设施和在建\n工程度汛安全，加强北方地区水利等基础设施规划建设。","source":{"doc":"4e539a366dce19555ccf","first":6,"last":6,"page":6,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-040e391b5fa8645c":{"sources":[{"id":"36ab9880bf019a62","label":"庆祝中国共产党成立 105 周年大会（7 月 1 日）","topic":"重要会议讲话","category":"时政","text":"考点二十七 庆祝中国共产党成立 105 周年大会（7 月 1 日）\n讲话回顾四个伟大成就（新民主主义革命、社会主义革命和建设、改革开放和社会主义现代化\n建设、新时代中国特色社会主义），提出五大历史贡献（从根本上改变中国人民前途命运、开\n辟民族复兴正确道路、展示马克思主义强大生命力、深刻影响世界历史进程、锻造强大的中国\n共产党），指出党已成为具有重大全球影响力的世界第一大执政党。\n提出党“六个始终”优秀特质（矢志追求真理、深深植根人民、勇担历史使命、顺应发展潮\n流、敢于善于斗争、注重强健自身，是“中国共产党为什么能”的关键密码）和“五个必须”\n（坚持基本理论基本路线基本方略、紧紧依靠人民、积极应对风险挑战、持续推动构建人类命\n运共同体、持之以恒推进全面从严治党）。","source":{"doc":"4e539a366dce19555ccf","first":6,"last":6,"page":6,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-cdd2fe1abf4227f3":{"sources":[{"id":"97b1a3978bcadfa6","label":"国家科学技术奖励大会、两院院士大会、中国科协第十一次全国代表","topic":"重要会议讲话","category":"时政","text":"考点二十八 国家科学技术奖励大会、两院院士大会、中国科协第十一次全国代表\n大会（7 月 8 日）\n向 2025 年度国家最高科学技术奖获得者陈立泉院士、贲德院士颁奖。讲话指出我国正从全球\n科技参与者、贡献者向开拓者、引领者加速转变，成为创新力上升最快的国家之一（综合创新\n能力位居世界第九）；“十五五”时期是科技强国建设的关键攻坚期，要 2035 年建成科技强\n国。\n人工智能以数据、算力、算法为关键要素，以神经科学、认知科学、计算科学、数学等理论突\n破和学科交叉为基础，以智能前沿技术群体性突破和广泛渗透赋能为标志。\n部署六方面工作：增强科技创新体系化攻关能力；推动科技创新和产业创新深度融合（科技创\n新突出应用导向，产业创新提出科学问题）；优化科教协同育人机制培养青年科技人才；提高\n科技创新投入效能；深化科技评价改革（强化创新能力、质量、实效、贡献导向）；加强科技\n伦理和安全治理。","source":{"doc":"4e539a366dce19555ccf","first":6,"last":6,"page":6,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-455fce7c1a980818":{"sources":[{"id":"18db6de02974c373","label":"在上海考察（人民城市）（7 月 15 日）","topic":"重要会议讲话","category":"时政","text":"考点二十九 在上海考察（人民城市）（7 月 15 日）\n强调，高质量推进城市更新是城市现代化建设的重要抓手，要全面践行人民城市理念，坚持问\n需于民、问计于民、问效于民，增强居民群众获得感、幸福感、安全感。党中央提出建设创\n新、宜居、美丽、韧性、文明、智慧的现代化人民城市，改造城市老旧小区是重要一环；要以\n“绣花功夫”提升小区物业管理和便民服务水平。强调社区是城市治理体系的基本单元，要提\n高社区治理水平，推动资源、服务、管理下沉基层一线，加强党建引领，探索社区党组织领导\n下的居委会、业委会、物业服务企业协调运行新模式，建设完整社区和便民生活圈。","source":{"doc":"4e539a366dce19555ccf","first":6,"last":7,"page":6,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-59e2dee75413cecc":{"sources":[{"id":"27be298a0cd273f1","label":"2026 世界人工智能大会主旨讲话《携手构建公正合理的全球人工智能治理体系》（7 月 17 日）","topic":"重要会议讲话","category":"时政","text":"考点三十 2026 世界人工智能大会主旨讲话《携手构建公正合理的全球人工智能治\n理体系》（7 月 17 日）\n发表题为《携手构建公正合理的全球人工智能治理体系》的主旨讲话，大会主题为“智能伙伴\n共创未来”。讲话提出“四个时代之问”：当机器开始思考，人类如何与之相处？当算法参与\n决策，安全如何保障？当技术挑战伦理，治理如何跟上？当鸿沟不断拉大，普惠如何实现？\n中方主张各国秉持以人为本、向上向善理念，让人工智能成为促进共同繁荣、维护共同安全的\n重要动力源，并提出四点意见：\n第一，坚持开放共赢，驱动创新发展，鼓励开源开放、合作共享，推进传统产业改造升级、新\n兴产业培育壮大、未来产业前瞻布局；\n第二，强化风险意识，确保安全可控，确保人工智能始终处于人类控制之下，共同反对泛化国\n家安全概念、把本国安全凌驾于他国安全之上；\n第三，鼓励包容并蓄，促进文明互鉴；\n第四，倡导和衷共济，完善全球治理，发挥联合国重要作用，帮助全球南方国家弥合数智鸿\n沟。\n宣布中国智能经济核心产业规模已超万亿元人民币。\n世界人工智能合作组织（政府间国际组织，7 月 16 日成立，总部上海，29 个成员国）在上海\n应运而生；未来 5 年中国将向发展中国家提供 5000 个人工智能专题研修培训名额，建设国际\n人工智能应用合作中心，推动气象智能预警方案“妈祖”在 30 个国家落地。\n会议发表主席声明，提出“同球共济”精神，强调创新是核心驱动力，倡导培育以企业为主\n体、以市场为牵引、以应用为导向、以科研为基础、以人才为根本的创新生态，开源开放是普\n惠发展的重要路径。","source":{"doc":"4e539a366dce19555ccf","first":7,"last":7,"page":7,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-260f7988a0f059cc":{"sources":[{"id":"e045025444cd31f3","label":"对基础教育工作作出重要指示（7 月）","topic":"重要会议讲话","category":"时政","text":"考点三十一 对基础教育工作作出重要指示（7 月）\n指出，党中央把基础教育作为基础性、先导性工作来抓，基础教育长足发展为建设教育强国提\n供有力支撑。\n新征程上要落实立德树人根本任务，用党的创新理论铸魂育人，培养德智体美劳全面发展的社\n会主义建设者和接班人；遵循教育规律，落实健康第一教育理念，促进广大学生身心健康；推\n进基础教育扩优提质，牢牢守住教育公平底线；弘扬教育家精神，加强师德师风建设；推动学\n校（主阵地）、家庭（第一课堂）、社会（大课堂）同向发力。\n我国基础教育整体已达世界高收入国家平均水平，建成世界上规模最大且有质量的基础教育体\n系，多项关键指标处于全球领先位置。","source":{"doc":"4e539a366dce19555ccf","first":7,"last":8,"page":7,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-5245742ceb6c4b94":{"sources":[{"id":"fb1d85e1a50ca32f","label":"中共中央政治局会议（分析研究当前经济形势和经济工作）（7 月 30日）","topic":"重要会议讲话","category":"时政","text":"考点三十二 中共中央政治局会议（分析研究当前经济形势和经济工作）（7 月 30\n日）\n上半年我国 GDP 同比增长 4.7%（一季度增长 5%，二季度增长 4.3%），经济呈现动能向新、结\n构向优的发展态势。下半年部署：实施更加积极的财政政策和适度宽松的货币政策，加大逆周\n期调节力度，加力扩大内需、优化供给；扎实推进“六张网”（水网、电网、算力网、新型通\n信网、城市地下管网、物流网）规划建设；深入实施“人工智能+”行动，发展智能经济新形\n态；制定实施全国统一大市场建设条例，综合整治“内卷式”竞争；毫不放松做好“三农”工\n作；统筹化解房地产、地方债务、中小金融机构等风险，推动经济持续向新向优向好发展，努\n力实现“十五五”良好开局。","source":{"doc":"4e539a366dce19555ccf","first":8,"last":8,"page":8,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-4fbe8027cdfbecca":{"sources":[{"id":"6e0eaa3c954781a4","label":"中共中央政治局第二十七次集体学习（高质量推进国防和军队现代化）（7 月 30 日）","topic":"重要会议讲话","category":"时政","text":"考点三十三 中共中央政治局第二十七次集体学习（高质量推进国防和军队现代\n化）（7 月 30 日）\n强调，“十五五”时期要强化政治引领、深化创新发展，高质量推进国防和军队现代化，如期\n实现建军一百年奋斗目标，推动基本实现国防和军队现代化取得决定性进展，为强国建设、民\n族复兴伟业提供坚强战略支撑。讲话明确：高质量推进国防和军队现代化是推进中国式现代化\n的应有之义；政治建军是人民军队立军之本，关乎建设方向和底色，确保枪杆子永远听党指\n挥；根本指向和检验标准始终是战斗力，要加强无人智能技术军事应用，逐步构建智能化军事\n体系；巩固提高一体化国家战略体系和能力是必由之路，要形成各司其职、紧密协作、规范有\n序的跨军地工作格局。","source":{"doc":"4e539a366dce19555ccf","first":8,"last":8,"page":8,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-18d40e6f06c9c438":{"sources":[{"id":"623b933d46b6f961","label":"对巩固拓展树立和践行正确政绩观学习教育成果作出指示（8 月）","topic":"重要会议讲话","category":"时政","text":"考点三十四 对巩固拓展树立和践行正确政绩观学习教育成果作出指示（8 月）\n强调，树立和践行正确政绩观是一项长期任务，必须久久为功，不断巩固拓展学习教育成果，\n持续推动各级党组织和广大党员、干部立党为公、为民造福、科学决策、真抓实干（总要求十\n六字），努力创造经得起实践、人民、历史检验的实绩。指示提出四点要求：经常性开展政绩\n观教育，重点抓好地方党政正职、新提拔干部、年轻干部、关键岗位干部教育培训；坚持常态\n化查改问题，深化“新官不理旧账”整改整治；用好考核指挥棒，完善差异化考核评价体系；\n加强政绩观行为管理监督，严格执行民主集中制。","source":{"doc":"4e539a366dce19555ccf","first":8,"last":8,"page":8,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-7d9d5ef378ba3495":{"sources":[{"id":"35c115750f22db74","label":"出席上海合作组织成员国元首理事会第二十六次会议（9 月 1 日）","topic":"重要会议讲话","category":"时政","text":"考点三十五 出席上海合作组织成员国元首理事会第二十六次会议（9 月 1 日）\n今年是上海合作组织成立 25 周年。25 年来，最重大的发展成就是一步步成为世界上幅员最\n广、人口最多、发展潜力巨大的新型区域合作组织；最宝贵的精神财富是“上海精神”；最重\n要的合作经验是找到不结盟、不对抗、不针对第三方的正确共处之道。提出 4 点主张：坚持发\n展优先，开创共同繁荣的前景；坚持安全为要，营造普遍安全的环境；坚持以人为本，厚植世\n代友好的根基；坚持对话协商，完善公平有序的治理。","source":{"doc":"4e539a366dce19555ccf","first":8,"last":8,"page":8,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-7dc0e10ea5dcac2d":{"sources":[{"id":"ced24caa01ecf71a","label":"出席“上海合作组织+”会议并发表重要讲话（9 月 1 日）","topic":"重要会议讲话","category":"时政","text":"考点三十六 出席“上海合作组织+”会议并发表重要讲话（9 月 1 日）\n平等有序的世界多极化，主权平等、相互尊重是根本原则，均衡有序、遵守法治是必然要求，\n多边主义、对话协商是关键路径，互利共赢、普惠包容是发展方向。","source":{"doc":"4e539a366dce19555ccf","first":9,"last":9,"page":9,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-37c6b8d4a7c8f5c0":{"sources":[{"id":"b4eef14896f64636","label":"出席金砖国家领导人第十八次会晤第一阶段会议（9 月 12 日）","topic":"重要会议讲话","category":"时政","text":"考点三十七 出席金砖国家领导人第十八次会晤第一阶段会议（9 月 12 日）\n今年是金砖国家合作 20 周年。金砖国家作为全球南方的第一方阵，实现历史性扩员，迈入\n“大金砖合作”高质量发展新阶段。金砖国家要做四个“先锋”：促进创新发展的先锋、维护\n和平稳定的先锋、推动文明互鉴的先锋、改革完善全球治理的先锋。","source":{"doc":"4e539a366dce19555ccf","first":9,"last":9,"page":9,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-23d98e2b63125144":{"sources":[{"id":"e5bd3b4de9fc5c90","label":"就发展先进制造业作出重要指示（9 月）","topic":"重要会议讲话","category":"时政","text":"考点三十八 就发展先进制造业作出重要指示（9 月）\n就发展先进制造业作出重要指示。全国先进制造业大会 9 月 16 日至 17 日在京召开，我国制造\n业增加值连续 16 年位居世界第一、占全球比重约 30%。强调，以新一代智能制造为主攻方\n向，坚持智能化、绿色化、融合化方向，纵深开展“人工智能+制造”行动，加快构建以先进\n制造业为骨干的现代化产业体系。","source":{"doc":"4e539a366dce19555ccf","first":9,"last":9,"page":9,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-94d23eaddeba3fe0":{"sources":[{"id":"cebce59b61e713d0","label":"庆祝中华人民共和国成立 77 周年招待会（9 月 30 日）","topic":"重要会议讲话","category":"时政","text":"考点三十九 庆祝中华人民共和国成立 77 周年招待会（9 月 30 日）\n讲话指出，77 年来，我们党团结带领人民不懈奋斗，创造了经济快速发展和社会长期稳定两\n大奇迹，实现了全面建成小康社会的第一个百年奋斗目标，正朝着全面建成社会主义现代化强\n国的第二个百年奋斗目标奋勇前进。面对错综复杂的国际国内形势，要坚持稳中求进工作总基\n调，完整准确全面贯彻新发展理念，加快构建新发展格局，进一步深化改革开放，更好统筹发\n展和安全，推动经济持续向新向优向好发展，切实保障和改善民生，努力完成全年目标任务，\n实现“十五五”良好开局。","source":{"doc":"4e539a366dce19555ccf","first":9,"last":9,"page":9,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-ef5dd52a8b2095c8":{"sources":[{"id":"628277e2a7bd9720","label":"全国卫生与健康大会（10 月 12—13 日）","topic":"重要会议讲话","category":"时政","text":"考点四十 全国卫生与健康大会（10 月 12—13 日）\n10 月 12 日至 13 日，全国卫生与健康大会在北京召开，讲话强调，“十五五”时期是实现到\n2035 年建成健康中国目标的关键时期，要坚定不移走中国特色卫生与健康发展道路，贯彻新\n时代卫生与健康工作方针，扬优势、固基础、补短板、强弱项，推动卫生与健康事业高质量发\n展，确保健康中国建设取得决定性进展。\n讲话指出，我们要建成的健康中国，是均衡普惠、优质高效的健康中国，应当具有强大的健康\n管理能力、疾病防控能力、医疗服务能力、医保支撑能力、医药创新能力、人才培养能力。必\n须坚定实施健康优先发展战略；预防是最经济最有效的健康策略；全面提高医疗服务水平是建\n成健康中国的重点任务；坚持把推进医疗、医保、医药协同发展和治理作为医药卫生体制改革\n的主攻方向；保障人民健康需要建强卫生与健康系统干部人才队伍；积极推动构建人类卫生健\n康共同体。","source":{"doc":"4e539a366dce19555ccf","first":9,"last":9,"page":9,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-84d852b8ca224a43":{"sources":[{"id":"4c218ddcb1b3b919","label":"在内蒙古乌兰察布考察（10 月 16 日）","topic":"重要会议讲话","category":"时政","text":"考点四十一 在内蒙古乌兰察布考察（10 月 16 日）\n10 月 16 日，来到内蒙古乌兰察布察哈尔高新技术开发区考察，了解“东数西算”工程枢纽节\n点建设和绿色算力产业发展等情况。对构建全国一体化算力网提出明确要求：加强科学规划、\n要素支撑、安全保障，确保已建成项目高效运行并如期完成后续项目建设；积极延伸产业链，\n推动数字经济与实体经济深度融合，不断把算力优势转化为发展优势。强调要注重“算电协\n同”“算水协同”，落实高效、绿色、安全的要求，积极推动绿色算力产业发展，为推进数字\n中国建设、促进新质生产力发展多作贡献。","source":{"doc":"4e539a366dce19555ccf","first":9,"last":10,"page":9,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-51fd3be46fe3b710":{"sources":[{"id":"4d987c83191ff402","label":"纪念中国工农红军长征胜利 90 周年大会（10 月）","topic":"重要会议讲话","category":"时政","text":"考点四十二 纪念中国工农红军长征胜利 90 周年大会（10 月）\n纪念中国工农红军长征胜利 90 周年大会隆重举行。从 1934 年 10 月至 1936 年 10 月，我们党\n领导红军第一、第二、第四方面军和第二十五军，进行了震撼世界、彪炳史册的伟大长征。红\n军长征纵横十余省，长驱二万五千里，跨越近百条江河，翻越皑皑雪山，穿过茫茫草地，进行\n600 余次战役战斗，粉碎上百万敌军围追堵截，胜利实现北上抗日的战略转移，成功开创了中\n国革命新局面。\n讲话深刻阐述了红军长征的制胜之道：一是依靠党的正确领导，1935 年 1 月遵义会议事实上\n确立了毛泽东同志在党中央和红军的领导地位，在最危急关头挽救了党、挽救了红军、挽救了\n中国革命；二是依靠坚定的革命意志；三是依靠独立自主、实事求是；四是依靠广大人民群众\n支持，长征一路宣传了党的主张，播撒下革命火种。\n伟大长征精神，就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信\n念，坚信正义事业必然胜利的精神；就是为了救国救民，不怕任何艰难险阻，不惜付出一切牺\n牲的精神；就是坚持独立自主、实事求是，一切从实际出发的精神；就是顾全大局、严守纪\n律、紧密团结的精神；就是紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的\n精神。伟大长征精神作为中国共产党人精神谱系的重要组成部分，跨越时空、历久弥新。新征\n程是党和人民的新长征，要大力弘扬伟大长征精神，同心协力走好新的长征路。","source":{"doc":"4e539a366dce19555ccf","first":10,"last":10,"page":10,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-f83367f5baff3488":{"sources":[{"id":"1eac60c08cf0b9f6","label":"中共中央政治局会议（10 月 23 日）","topic":"重要会议讲话","category":"时政","text":"考点四十三 中共中央政治局会议（10 月 23 日）\n10 月 23 日召开会议，审议《关于二十届中央第七轮巡视情况的综合报告》。会议指出，要压\n实整改责任、加强整改监督，切实抓好巡视反馈问题整改，动真碰硬、真改实改。中央和国家\n机关是践行“两个维护”的第一方阵，要不断提高政治判断力、政治领悟力、政治执行力，强\n化履职尽责的政治担当，坚决贯彻落实党中央重大决策部署。严格落实管党治党政治责任，以\n更高标准、更实举措抓好全面从严治党各项工作，保持惩治腐败高压态势，把严的基调一贯到\n底，建设风清气正的政治机关。","source":{"doc":"4e539a366dce19555ccf","first":10,"last":10,"page":10,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-1766c2f7cfaf5f07":{"sources":[{"id":"fcf7e8e678576d45","label":"二十届五中全会（10 月 26 日至 29 日）","topic":"重要会议讲话","category":"时政","text":"考点四十三 二十届五中全会（10 月 26 日至 29 日）\n全会指出，持之以恒推进全面从严治党，必须坚持马克思列宁主义、毛泽东思想、邓小平理\n论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思想，深\n入学习贯彻习近平党建思想，围绕实现党的使命任务，落实新时代党的建设总要求，以党章为\n根本，坚持党的先锋队性质，坚持党的全面领导和党中央集中统一领导，着眼于提高党的长期\n执政能力、保持党的先进性和纯洁性、保持党同人民群众的血肉联系，坚持严的基调不动摇，\n健全全面从严治党体系，以党的政治建设为统领，全面推进党的各方面建设，充分激发全党积\n极性主动性创造性，不断实现党的自我净化、自我完善、自我革新、自我提高，持续增强党的\n政治领导力、思想引领力、群众组织力、社会号召力，确保党始终成为走在时代前列、人民衷\n心拥护、经得起各种风浪考验、朝气蓬勃的马克思主义执政党，始终成为中国特色社会主义事\n业的坚强领导核心。\n全会强调，持之以恒推进全面从严治党遵循的原则是：坚持服务使命任务，坚持以党的政治建\n设为统领，坚持全面从严，坚持问题导向，坚持守正创新，坚持以上率下，坚持依规治党。\n全会提出，增强党性是全面从严治党的根本性任务。必须推动全体党员、干部坚持党的性质和\n宗旨，增强党的意识、党员意识、先锋队意识，把加强党性修养作为终身课题，在坚定理想信\n念、铸牢对党忠诚、厚植为民情怀、坚持实事求是、纯正道德品质、保持清正廉洁等方面下功\n夫，做到忠诚干净担当，始终保持共产党人政治本色。要强化对党忠诚教育，坚持用党的创新\n理论凝心铸魂，用党的优良传统和中华优秀传统文化涵养党性，在实践中锤炼党性，加强党性\n鉴别。\n全会提出，民主集中制是党的根本组织原则和领导制度，贯彻执行民主集中制是全面从严治党\n的内在要求。必须完善和落实民主集中制各项制度，充分发扬党内民主，有效实行正确的集\n中，更好发挥民主集中制的政治优势、组织优势、制度优势、工作优势。要坚持和加强党中央\n集中统一领导，提高党内民主质量，严格执行领导班子决策议事规则，规范“一把手”履职用\n权。\n全会提出，全面从严治党关键在从严治吏。必须贯彻新时代党的组织路线，严格干部教育培\n养、选拔任用、管理监督，建设一支政治过硬、本领高强、作风优良、纪律严明的高素质干部\n队伍。要坚持正确用人导向，精准科学选人用人，推动干部树立和践行正确政绩观，增强干部\n干事创业本领，提高培养选拔优秀年轻干部质量，加强干部管理监督，全方位培养、引进、用\n好人才。\n全会提出，党的各级组织是全面从严治党的主体。必须体系化推进各层级各领域党组织建设，\n强化党组织政治功能和组织功能，确保贯彻落实党的路线方针政策和党中央决策部署上下协\n同、精准高效。要发挥中央和国家机关党组织表率作用，强化地方党委功能，统筹推进各领域\n基层党组织建设，突出抓好新兴领域党的建设，加强党员队伍建设，完善党的各级组织贯通机\n制。\n全会提出，正风肃纪是全面从严治党的有力举措。必须坚持党性党风党纪一起抓、正风肃纪反\n腐相贯通，深化运用从抓作风入手推进全面从严治党经验，不断改进作风，用严明的纪律管党\n治党，以良好形象凝心聚力。要走好新时代党的群众路线，锲而不舍落实中央八项规定精神，\n推进作风建设常态化长效化，强化从严执纪，综合发挥纪律教育约束、保障激励作用。\n全会提出，一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本方\n针。必须牢记党除了工人阶级和最广大人民群众的利益没有自己特殊的利益、党同腐败水火不\n容，坚定走好中国特色反腐败之路，加强党中央对反腐败工作的集中统一领导，更加注重标本\n兼治、系统施治，坚持从严惩、精准治、有效防、一体抓，将反腐败斗争进行到底。要保持惩\n治腐败高压态势，加强对权力运行的制约和监督，夯实崇廉拒腐思想根基，增强一体推进不敢\n腐不能腐不想腐综合效能。\n全会提出，加强党内法规制度建设是全面从严治党的长远之策、根本之策。必须坚持把党章作\n为全党的根本行为规范，深化党的建设制度改革，推动依法治国和依规治党有机统一，为持之\n以恒推进全面从严治党提供有力制度保障。要完善党内法规制度体系，增强制度执行力，大力\n破除潜规则。\n全会提出，持之以恒推进全面从严治党，必须进一步完善党和国家监督体系。要做实党委（党\n组）全面监督，完善纪检监察工作双重领导体制，推动党内监督同各方面监督深度融合、高效\n联动，发挥巡视综合监督利剑作用。\n全会强调，持之以恒推进全面从严治党是全党的共同政治责任。必须扭住管党治党责任制“牛\n鼻子”，健全各负其责、统一协调的责任体系，优化责任落实考评机制，对管党治党不力、出\n现严重问题的严肃追责问责。","source":{"doc":"4e539a366dce19555ccf","first":10,"last":12,"page":10,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-3feaca28aa7cc75f":{"sources":[{"id":"749420890a1aeef5","label":"《现代化首都都市圈空间协同规划（2023—2035 年）》获批（2 月 2 日）","topic":"重要文件","category":"时政","text":"考点一 《现代化首都都市圈空间协同规划（2023—2035 年）》获批（2 月 2 日）\n这是全国首个由中共中央、国务院批复的都市圈规划。规划以有序疏解北京非首都功能、解决\n北京“大城市病”为基本出发点，锚定优化提升和服务保障首都功能的重要地区、世界一流城\n市群建设主引擎、中华文明传承发展重要地区、区域协同治理引领区、美丽中国建设先行区的\n战略定位。发展目标：到 2030 年取得积极进展、到 2035 年构架基本形成、展望 2050 年全面\n建成；构建“一核两翼、双城多点、双廊多圈”空间格局（一核即北京，两翼为雄安新区和北\n京城市副中心，双城为北京、天津，双廊为京津、京雄走廊）。","source":{"doc":"4e539a366dce19555ccf","first":12,"last":12,"page":12,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-6d901e37c8f7cef6":{"sources":[{"id":"37b0808d33b7ca12","label":"2026 年中央一号文件《关于锚定农业农村现代化扎实推进乡村全面振兴的意见》（2 月 3 日）","topic":"重要文件","category":"时政","text":"考点二 2026 年中央一号文件《关于锚定农业农村现代化扎实推进乡村全面振兴的\n意见》（2 月 3 日）\n是“十五五”首个中央一号文件，也是党的十八大以来第 14 个指导“三农”工作的中央一号\n文件。文件坚持以推进乡村全面振兴为总抓手，以学习运用“千万工程”经验为引领，以改革\n创新为根本动力，守牢国家粮食安全底线。部署四项重点任务：提升农业综合生产能力和质量\n效益（粮食产量稳定在 1.4 万亿斤左右、加力实施新一轮千亿斤粮食产能提升行动、因地制宜\n发展农业新质生产力）、实施常态化精准帮扶（首次提出）、积极促进农民稳定增收、因地制\n宜推进宜居宜业和美乡村建设，并强化体制机制创新、加强党对“三农”工作的全面领导（五\n级书记抓乡村振兴）。","source":{"doc":"4e539a366dce19555ccf","first":12,"last":12,"page":12,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-a97117194afed951":{"sources":[{"id":"dfe7c893e40c2101","label":"中办印发《关于在全党开展树立和践行正确政绩观学习教育的通知》（2月 23 日）","topic":"重要文件","category":"时政","text":"考点三 中办印发《关于在全党开展树立和践行正确政绩观学习教育的通知》（2\n月 23 日）\n学习教育以县处级以上领导班子和领导干部特别是“一把手”为重点，于 2026 年春节假期后\n启动、7 月底基本结束。以立党为公、为民造福、科学决策、真抓实干为总要求，以一体推进\n学查改为抓手，坚持聚焦主题、简约务实，不分批次、不划阶段，落实学习研讨、查摆问题、\n整改整治、建章立制、开门教育等工作安排，坚持开门教育、民生为大。开展此次学习教育是\n贯彻落实党的二十届四中全会战略部署、践行党的根本宗旨、巩固拓展党内集中学习教育成果\n的重要举措，对推进党和国家事业、推进全面从严治党意义重大。","source":{"doc":"4e539a366dce19555ccf","first":12,"last":13,"page":12,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-72da897ece6c77f8":{"sources":[{"id":"4df9a8fa3af7a522","label":"“十五五”规划纲要（3 月 5 日）","topic":"重要文件","category":"时政","text":"考点四 “十五五”规划纲要（3 月 5 日）\n纲要提出 20 项主要目标指标，其中民生福祉指标最多（7 项）；明确到 2035 年人均国内生产\n总值比 2020 年翻一番、达到中等发达国家水平。全社会研发经费投入年均增长 7%以上；单位\nGDP 二氧化碳排放累计降低 17%。重大战略任务四个方面：突出推动高质量发展、做强国内大\n循环、推进全体人民共同富裕、统筹发展和安全。关键数字：数字经济核心产业增加值占 GDP\n比重达 12.5%，劳动年龄人口平均受教育年限提高到 11.7 年，人均预期寿命提高到 80 岁，粮\n食综合生产能力 1.45 万亿斤左右，能源综合生产能力 58 亿吨标准煤。","source":{"doc":"4e539a366dce19555ccf","first":13,"last":13,"page":13,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-38432423575893fe":{"sources":[{"id":"e7f7bcf826593945","label":"2026 年经济社会发展预期目标与政策取向（3 月 5 日）","topic":"重要文件","category":"时政","text":"考点五 2026 年经济社会发展预期目标与政策取向（3 月 5 日）\n政府工作报告确定 2026 年预期目标：经济增长 4.5%—5%，城镇调查失业率 5.5%左右，城镇新\n增就业 1200 万人以上，CPI 涨幅 2%左右，粮食产量 1.4 万亿斤左右，单位 GDP 二氧化碳排放\n降低 3.8%左右。政策取向坚持稳中求进、提质增效：继续实施更加积极的财政政策，赤字率\n拟按 4%左右安排、赤字规模 5.89 万亿元，发行超长期特别国债 1.3 万亿元、特别国债 3000\n亿元，地方专项债 4.4 万亿元；继续实施适度宽松的货币政策，把促进经济稳定增长、物价合\n理回升作为重要考量。十大任务居首为着力建设强大国内市场，首次提出打造智能经济新形\n态。","source":{"doc":"4e539a366dce19555ccf","first":13,"last":13,"page":13,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-d628f77d481c1a3e":{"sources":[{"id":"b4202040d54a7ef2","label":"《关于做好第二轮土地承包到期后再延长 30 年试点工作的意见》（3 月18 日）","topic":"重要文件","category":"时政","text":"考点六 《关于做好第二轮土地承包到期后再延长 30 年试点工作的意见》（3 月\n18 日）\n明确保持土地承包关系稳定并长久不变，第二轮土地承包到期后再延长 30 年是党中央重大决\n策部署（第二轮 2027 年到期）。牢牢把住处理好农民和土地关系这条主线，把依法维护农民\n权益作为出发点和落脚点，不断完善农村承包地所有权、承包权、经营权分置政策体系。第二\n轮承包合同到期的原则上在期满后 1 年内完成延包；“四个坚持”：坚持集体所有制不动摇、\n坚持农户家庭承包经营、坚持农民主体地位、坚持维护农村社会稳定。","source":{"doc":"4e539a366dce19555ccf","first":13,"last":13,"page":13,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-4016a0125cd032ba":{"sources":[{"id":"04a9e8455b9860f8","label":"《关于加快建立长期护理保险制度的意见》（3 月 25 日）","topic":"重要文件","category":"时政","text":"考点七 《关于加快建立长期护理保险制度的意见》（3 月 25 日）\n长期护理保险制度是为失能人员的基本生活照料和与之密切相关的医疗护理提供服务或资金保\n障的社会保险制度，是实施积极应对人口老龄化国家战略的重要内容（“五险”变“六\n险”）。主要目标是用 3 年左右时间基本建立适应我国基本国情的长期护理保险制度；坚持覆\n盖全民、统筹城乡、公平统一、安全规范、可持续，坚持以收定支、收支平衡，实现基金稳定\n筹集、独立运行、精算平衡，按属地管理原则参保。","source":{"doc":"4e539a366dce19555ccf","first":13,"last":13,"page":13,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-35c9ac339e801eb8":{"sources":[{"id":"df56ff50011cbf35","label":"《关于加快建设分级诊疗体系的若干措施》（4 月 9 日）","topic":"重要文件","category":"时政","text":"考点八 《关于加快建设分级诊疗体系的若干措施》（4 月 9 日）\n提出 4 个方面举措：以紧密型医联体为抓手完善分级诊疗协同机制；以常见病、慢性病为重点\n引导群众基层首诊；以提升就医连续性为导向加强转诊服务管理；完善分级诊疗多元保障措\n施，以省为单位规范基层病种范围，实行统筹区内不同等级医疗卫生机构基层病种“同病同\n付”。目标是做到基层首诊、双向转诊、急慢分治、上下联动，实现大病不出省、一般病在市\n县解决、日常疾病在基层解决。","source":{"doc":"4e539a366dce19555ccf","first":14,"last":14,"page":14,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-71ba838d33c12afb":{"sources":[{"id":"93b7853bd8cbbb64","label":"《碳达峰碳中和综合评价考核办法》（4 月 12 日）","topic":"重要文件","category":"时政","text":"考点九 《碳达峰碳中和综合评价考核办法》（4 月 12 日）\n办法旨在发挥碳达峰碳中和的战略牵引作用，加快构建碳排放总量和强度双控制度体系；评价\n考核实行党政同责、一岗双责。“十五五”时期将制定碳达峰行动方案，确保 2030 年碳排放\n强度比 2005 年降低 65%以上、2030 年非化石能源消费占比达 25%等目标，实现煤炭消费总量\n和石油消费总量达峰，力争年度新增清洁能源电量逐步覆盖全社会新增用电量。","source":{"doc":"4e539a366dce19555ccf","first":14,"last":14,"page":14,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-d5bd54c4f161edf0":{"sources":[{"id":"2f801db2701866c5","label":"国务院《关于推进服务业扩能提质的意见》（4 月）","topic":"重要文件","category":"时政","text":"考点十 国务院《关于推进服务业扩能提质的意见》（4 月）\n《意见》提出，到 2030 年，服务业高质量发展取得明显进展，服务业总规模迈上 100 万亿元\n台阶，质量更高、结构更优、品质更佳、活力更足的发展格局基本形成，培育更多“中国服\n务”品牌，服务业全球竞争力、影响力明显增强，人民群众获得感持续提升。2026 年是“十\n五五”开局之年，2030 年是“十五五”收官之年，凸显扩能提质服务业的决心。","source":{"doc":"4e539a366dce19555ccf","first":14,"last":14,"page":14,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-8a2881218d1551e8":{"sources":[{"id":"223697f0b6279109","label":"新修订《中国共产党发展党员工作细则》（5 月 18 日）","topic":"重要文件","category":"时政","text":"考点十一 新修订《中国共产党发展党员工作细则》（5 月 18 日）\n明确发展党员工作是党的建设一项重要的基础性工程，按照“控制总量、优化结构、提高质\n量、发挥作用”总要求，坚持党章规定的党员标准，始终把政治标准放在首位；坚持入党自愿\n原则和个别吸收原则，成熟一个、发展一个；禁止突击发展，反对“关门主义”。《细则》坚\n持问题导向，明确由中央组织部统一制定入党积极分子培养考察登记表、预备党员教育考察登\n记表式样，对入党志愿书式样作修订，规范存档材料，鼓励有条件的地方和单位实行党员档案\n电子化管理。","source":{"doc":"4e539a366dce19555ccf","first":14,"last":14,"page":14,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-89b4dc89398ac031":{"sources":[{"id":"8f65da4c26e86ec6","label":"《关于推行常住地提供基本公共服务的实施意见》（5 月 22 日）","topic":"重要文件","category":"时政","text":"考点十二 《关于推行常住地提供基本公共服务的实施意见》（5 月 22 日）\n由常住地提供基本公共服务，逐步消除基本公共服务与户籍挂钩因素，促进未落户常住人口与\n户籍人口同等享有基本公共服务，促进基本公共服务均等化水平明显提升，有力支撑深入实施\n以人为本的新型城镇化战略。部署六大公共服务：加强随迁子女教育保障、扩大公租房保障范\n围、健全就业地参加职工社会保险制度（全面取消就业地参保户籍限制）、加强常住地基本医\n疗保障、强化就业基本公共服务、完善兜底性基本公共服务；并提出优化设施布局、梯度供\n给、财政转移支付、用地配置、共建共享、协同经办（省内通办、跨省通办）、常住人口登记\n统计等支持保障措施。","source":{"doc":"4e539a366dce19555ccf","first":14,"last":14,"page":14,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-aa89d7cbe7587c24":{"sources":[{"id":"d49d978dc4a40f98","label":"国务院《城市更新“十五五”规划》（5 月 28 日）","topic":"重要文件","category":"时政","text":"考点十三 国务院《城市更新“十五五”规划》（5 月 28 日）\n这是城市更新领域第一部国家级专项规划，也是“十五五”规划纲要公布后第一个分领域专项\n规划。坚持稳中求进、以人民为中心、系统观念、规划引领、统筹发展和安全、保护第一应保\n尽保以用促保。到 2030 年城市更新行动取得重要进展、开发建设方式转型初见成效；到 2035\n年创新、宜居、美丽、韧性、文明、智慧的现代化人民城市基本建成。部署培育城市发展新动\n能等 6 方面重点任务、7 方面政策举措和“好房子”建设改造等 14 项重大工程，构建中央统\n筹、省负总责、城市抓落实的工作格局。","source":{"doc":"4e539a366dce19555ccf","first":14,"last":15,"page":14,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-83af5109eddff9fb":{"sources":[{"id":"60fb17ebb1dc967a","label":"《实施就业优先战略“十五五”规划》（6 月 5 日）","topic":"重要文件","category":"时政","text":"考点十四 《实施就业优先战略“十五五”规划》（6 月 5 日）\n规划明确，就业是最基本的民生，事关人民群众切身利益、经济社会健康发展、国家长治久\n安。全面贯彻劳动者自主就业、市场调节就业、政府促进就业和鼓励创业的方针，聚焦促进高\n质量充分就业目标，围绕就业领域人力资源供需不匹配的主要矛盾，坚持投资于物和投资于人\n紧密结合，以推动高质量发展为基础，以实施就业优先战略为引领，以强化就业优先政策为抓\n手，以破解结构性就业矛盾为着力点，以深化就业体制机制改革为动力，以不发生规模性失业\n风险为底线，构建就业友好型发展方式，持续促进就业质的有效提升和量的合理增长。","source":{"doc":"4e539a366dce19555ccf","first":15,"last":15,"page":15,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-62f85243294247ab":{"sources":[{"id":"336a6f0485ec8ebd","label":"国务院《加快农业农村现代化“十五五”规划》（6 月）","topic":"重要文件","category":"时政","text":"考点十五 国务院《加快农业农村现代化“十五五”规划》（6 月）\n规划强调以加快农业农村现代化更好推进中国式现代化建设，将因地制宜发展农业新质生产力\n摆在更加突出的战略位置，并首次提出培育壮大农业领域新兴产业和未来产业。明确“十五\n五”时期是基本实现农业农村现代化的关键时期，坚持农业农村优先发展、城乡融合发展，锚\n定建设农业强国目标，以推进乡村全面振兴为总抓手，以学习运用“千万工程”经验为引领，\n统筹发展科技农业、绿色农业、质量农业、品牌农业。到 2030 年，农业科技进步贡献率达到\n67%；到 2035 年，乡村全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生\n活条件，农业强国建设取得显著成效。","source":{"doc":"4e539a366dce19555ccf","first":15,"last":15,"page":15,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-3d4202fbfb0efd8b":{"sources":[{"id":"af0df0c8252e375f","label":"国务院《教育发展“十五五”规划》（6 月）","topic":"重要文件","category":"时政","text":"考点十六 国务院《教育发展“十五五”规划》（6 月）\n规划坚持党对教育事业的全面领导，坚持教育优先发展，牢牢把握教育的政治属性、人民属\n性、战略属性，聚焦高质量教育体系建设，一体推进教育科技人才发展，培养德智体美劳全面\n发展的社会主义建设者和接班人，推动教育强国建设迈上新台阶。目标到 2030 年，教育强国\n建设取得显著成效，高质量教育体系基本建成。具体举措包括：大力推进健康学校建设，坚持\n健康第一的教育理念，落实中小学生每天综合体育活动时间不低于 2 小时，推行“课间 15 分\n钟”，广泛开展“三大球”比赛，使每个学生至少掌握 1 项体育技能；大力发展公办幼儿园、\n提高公办幼儿园学位占比；稳步扩大免费教育范围，探索延长义务教育年限。","source":{"doc":"4e539a366dce19555ccf","first":15,"last":15,"page":15,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-d2f34cba9acb152d":{"sources":[{"id":"68e5edca241b1d88","label":"白皮书《构建更加公正合理的全球治理体系：中国的理念、倡议与行动》（6 月 17 日）","topic":"重要文件","category":"时政","text":"考点十七 白皮书《构建更加公正合理的全球治理体系：中国的理念、倡议与行\n动》（6 月 17 日）\n白皮书指出，新时代以来，历史性提出构建人类命运共同体重大理念，倡导共商共建共享的全\n球治理观，2025 年郑重提出全球治理倡议，为解答“构建什么样的全球治理体系、如何改革\n完善全球治理”的时代命题提供了中国方案。落实全球治理倡议，最根本的是坚定维护联合国\n的权威和地位，最关键的是大国展现责任担当，最需要的是各国团结合作，最紧迫的是弥补和\n平与发展赤字。倡议提出奉行主权平等、遵守国际法治、践行多边主义、倡导以人为本、注重\n行动导向五大核心理念；主权平等是联合国宪章开宗明义提出的基本原则，是规范国与国关系\n最重要的准则。","source":{"doc":"4e539a366dce19555ccf","first":15,"last":16,"page":15,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-0fa5d71387d477ef":{"sources":[{"id":"dff610fcdc1c7cef","label":"《党建文选》第一卷、第二卷出版发行（6 月 23 日）","topic":"重要文件","category":"时政","text":"考点十八 《党建文选》第一卷、第二卷出版发行（6 月 23 日）\n选中的重要论断包括：坚定理想信念是共产党人安身立命的根本，政治纪律是最重要、最根\n本、最关键的纪律，党要管党首先是管好干部、从严治党关键是从严治吏，全面从严治党核心\n是加强党的领导、基础在全面、关键在严、要害在治，一体推进不敢腐不能腐不想腐是反腐败\n斗争的基本方针，自我革命是党跳出历史周期率的第二个答案，全面建设社会主义现代化国\n家、全面推进中华民族伟大复兴关键在党。","source":{"doc":"4e539a366dce19555ccf","first":16,"last":16,"page":16,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-a65699576a82e6f0":{"sources":[{"id":"47ee3e64439de8e6","label":"《美丽中国建设“十五五”规划》（7 月）","topic":"重要文件","category":"时政","text":"考点十九 《美丽中国建设“十五五”规划》（7 月）\n规划指出“十五五”时期是美丽中国建设承前启后、扩面提质，实现生态环境根本好转的关键\n阶段。践行绿水青山就是金山银山理念，以碳达峰碳中和为牵引，以健全生态文明制度体系为\n保障，统筹产业结构调整、污染治理、生态保护、应对气候变化，协同推进降碳、减污、扩\n绿、增长，加快经济社会发展全面绿色转型，筑牢中华民族伟大复兴的生态根基。主要目标：\n到 2030 年，生态环境质量全面改善，美丽中国建设取得新的重大进展，碳达峰目标如期实\n现；到 2035 年，生态环境根本好转，美丽中国目标基本实现，全国 PM2.5 浓度下降到 25 微克\n/立方米以下，全经济范围温室气体净排放量比峰值下降 7%—10%，生态环境治理体系和治理\n能力现代化基本实现。","source":{"doc":"4e539a366dce19555ccf","first":16,"last":16,"page":16,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-b39cc1dc83e8f90b":{"sources":[{"id":"03c81608a13fe0a4","label":"《中华人民共和国生态环境法典》正式施行（8 月 15 日）","topic":"重要文件","category":"时政","text":"考点二十 《中华人民共和国生态环境法典》正式施行（8 月 15 日）\n2026 年 8 月 15 日第四个全国生态日，《中华人民共和国生态环境法典》正式施行，标志着中\n国生态环境保护开启“法典化”时代。\n该法典于 2026 年 3 月 12 日由十四届全国人大四次会议表决通过，是继民法典后中国第二部以\n“法典”命名的法律，也是世界上第一部以“生态环境”命名的法典，共 5 编、1242 条，是\n30 多部生态环境法律、100 余件行政法规、1000 多件地方性法规的“集大成者”。\n法典将“绿色低碳发展”独立成编，为世界范围内首次，标志着我国生态环境法治从“末端治\n污”转向“源头防控”；以“适度法典化”编纂模式形成法典统领、单行法配套衔接的分层立\n法格局。\n污染防治坚持精准治污、科学治污、依法治污方针；国家实行水资源刚性约束制度，坚持以水\n定城、以水定地、以水定人、以水定产。","source":{"doc":"4e539a366dce19555ccf","first":16,"last":16,"page":16,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-2d501a2f4acad338":{"sources":[{"id":"92816857cf32a6ff","label":"《国务院关于修改〈住房公积金管理条例〉的决定》（8 月）","topic":"重要文件","category":"时政","text":"考点二十一 《国务院关于修改〈住房公积金管理条例〉的决定》（8 月）\n主要内容包括四个方面：一是拓宽提取和使用范围，提取公积金支付房租不再设置门槛限制，\n新增装修自住住房、支付自住住房物业费等提取情形，适当拓宽投资运用渠道；二是提升管理\n服务效能，实现住房公积金缴存记录全国范围内互信互认，推动转移接续、异地贷款便捷办\n理；三是强化风险防控，建立全面完整准确的信用记录并纳入全国信用信息共享平台；四是扩\n大制度覆盖面，明确个体工商户、非全日制从业人员及其他灵活就业人员可以自愿缴存。","source":{"doc":"4e539a366dce19555ccf","first":16,"last":17,"page":16,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-e5c938da3194d1bc":{"sources":[{"id":"021c379f2547f377","label":"《中共中央 国务院关于发展新质生产力的意见》（10 月 9 日）","topic":"重要文件","category":"时政","text":"考点二十二 《中共中央 国务院关于发展新质生产力的意见》（10 月 9 日）\n10 月 9 日，中共中央、国务院印发《关于发展新质生产力的意见》。发展新质生产力是推动\n高质量发展的内在要求和重要着力点。坚持“创新主导、改革为要、因地制宜、先立后破”4\n条原则，坚持高技术、高效能、高质量，统筹处理好政府和市场、质态和业态、改革和发展、\n自主和开放的关系，统筹发展和安全。围绕大力推进科技创新、推动科技创新和产业创新深度\n融合、着力推进发展方式创新、扎实推进体制机制创新、深化人才工作机制创新 5 个方面部署\n19 项重点举措。强调坚持先立后破、稳中求进，不能脱实向虚、贪大求全、搞泡沫化，不能\n出现产业空心化或产业断层现象，不能盲目求新、顾此失彼。","source":{"doc":"4e539a366dce19555ccf","first":17,"last":17,"page":17,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-6b014861b5a96394":{"sources":[{"id":"8ed0e8365cf860b0","label":"《关于推动科技创新和产业创新深度融合的意见》（10 月 21 日）","topic":"重要文件","category":"时政","text":"考点二十三 《关于推动科技创新和产业创新深度融合的意见》（10 月 21 日）\n2026 年 10 月 21 日，中共中央办公厅、国务院办公厅《关于推动科技创新和产业创新深度融\n合的意见》对外发布。以发展新质生产力、建设现代化产业体系为目标，以构建企业主导、各\n主体协同的产学研融通创新体系为重点，推动全链条贯通、全领域覆盖、全要素融通、全方位\n保障，形成科技创新和产业创新互融共促新格局，打通从科技强到产业强、经济强、国家强的\n通道。工作中要坚持准确把握科技革命和产业变革新趋势新特点，加强系统谋划和一体推进；\n坚持统筹科技供给和需求牵引，围绕产业链部署创新链，围绕创新链布局产业链；坚持强化企\n业创新主体地位，完善激励创新的市场机制，推动创新资源向企业集聚；坚持以改革激发创新\n活力，坚决破除阻碍科技创新和产业创新深度融合发展的思想观念和制度障碍。","source":{"doc":"4e539a366dce19555ccf","first":17,"last":17,"page":17,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-cb043cba1c272c72":{"sources":[{"id":"814609a54146325c","label":"《求是》第 1 期《学习好贯彻好党的二十届四中全会精神》（1 月 1 日）","topic":"重要文章","category":"时政","text":"考点一 《求是》第 1 期《学习好贯彻好党的二十届四中全会精神》（1 月 1 日）\n文章提出“五个深刻领会”：深刻领会“十五五”时期经济社会发展的重大意义（实现社会主\n义现代化是阶梯式递进、不断发展进步的历史过程，“十五五”时期具有承前启后的重要地\n位）；深刻领会党中央关于国内外形势的基本判断（战略机遇和风险挑战并存、不确定难预料\n因素增多）；深刻领会指导思想和重大原则（“六个坚持”）；深刻领会重大战略任务；深刻\n领会根本保证（坚持好、运用好、发展好党的领导这一最大优势）。落实中要坚定不移推动高\n质量发展，把发展经济的着力点放在实体经济上，构建以先进制造业为骨干的现代化产业体\n系；加快构建新发展格局；推动全体人民共同富裕迈出坚实步伐；更好统筹发展和安全（把捍\n卫政治安全摆在首位）；统筹推进各领域工作。","source":{"doc":"4e539a366dce19555ccf","first":17,"last":17,"page":17,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-48c8b453a3a58a84":{"sources":[{"id":"7a50287aebfdad11","label":"《求是》第 2 期《在中央城市工作会议上的讲话》（1 月 16 日）","topic":"重要文章","category":"时政","text":"考点二 《求是》第 2 期《在中央城市工作会议上的讲话》（1 月 16 日）\n我国城镇化正从快速增长期转向稳定发展期，城市发展正从大规模增量扩张阶段转向存量提质\n增效为主的阶段。总体要求：以建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市\n为目标，以推动城市高质量发展为主题，以坚持城市内涵式发展为主线，以推进城市更新为重\n要抓手，走出一条中国特色城市现代化新路子。把握五个转变：转变城市发展理念更注重以人\n为本、转变城市发展方式更注重集约高效、转变城市发展动力更注重特色发展、转变城市工作\n重心更注重治理投入、转变城市工作方法更注重统筹协调；部署优化城市体系、创新城市、宜\n居城市、美丽城市、韧性城市、文明城市、智慧城市 7 个方面重点任务。","source":{"doc":"4e539a366dce19555ccf","first":17,"last":18,"page":17,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-431f561447dd5b09":{"sources":[{"id":"549e3ed7940da1b4","label":"《求是》第 3 期《走好中国特色金融发展之路，建设金融强国》（2 月）","topic":"重要文章","category":"时政","text":"考点三 《求是》第 3 期《走好中国特色金融发展之路，建设金融强国》（2 月）\n文章概括中国特色金融发展之路“八个坚持”：坚持党中央对金融工作的集中统一领导、以人\n民为中心的价值取向、把金融服务实体经济作为根本宗旨（实体经济是金融的根基，金融是实\n体经济的血脉）、把防控风险作为金融工作的永恒主题、在市场化法治化轨道上推进金融创新\n发展、深化金融供给侧结构性改革、统筹金融开放和安全、稳中求进工作总基调。明确金融强\n国六大关键核心金融要素：强大的货币、中央银行、金融机构、国际金融中心、金融监管、金\n融人才队伍。指出我国已是金融大国但大而不强；培育中国特色金融文化，做到诚实守信、以\n义取利、稳健审慎、守正创新、依法合规。","source":{"doc":"4e539a366dce19555ccf","first":18,"last":18,"page":18,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-4155899aa6e188ee":{"sources":[{"id":"668be6a620f408e6","label":"《求是》第 4 期《当前经济工作的重点任务》（2 月）","topic":"重要文章","category":"时政","text":"考点四 《求是》第 4 期《当前经济工作的重点任务》（2 月）\n系统阐述 2026 年经济工作八个重点任务：坚持内需主导，建设强大国内市场（深入实施提振\n消费专项行动、制定城乡居民增收计划、推动投资止跌回稳）；坚持创新驱动，加紧培育壮大\n新动能（建设北京/京津冀、上海/长三角、粤港澳大湾区国际科技创新中心，打造世界级科技\n创新策源地，深化拓展“人工智能+”）；坚持改革攻坚，增强高质量发展动力活力（制定全\n国统一大市场建设条例、整治“内卷式”竞争、推进中小金融机构减量提质）；坚持对外开\n放，推动多领域合作共赢（稳步推进制度型开放、促进外资境内再投资）；坚持协调发展，促\n进城乡融合和区域联动（以县城为重要载体推进城镇化）；坚持“双碳”引领，推动全面绿色\n转型；坚持民生为大，努力为人民群众多办实事；坚持守牢底线，积极稳妥化解房地产、地方\n政府债务等重点领域风险。","source":{"doc":"4e539a366dce19555ccf","first":18,"last":18,"page":18,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-4e1dc2bc02507863":{"sources":[{"id":"d28211d48deda036","label":"《求是》第 5 期《让愿担当、敢担当、善担当蔚然成风》（3 月 1 日）","topic":"重要文章","category":"时政","text":"考点五 《求是》第 5 期《让愿担当、敢担当、善担当蔚然成风》（3 月 1 日）\n指出干部敢于担当作为，这既是政治品格，也是从政本分；有多大担当才能干多大事业。党的\n纪律和干事创业是内在统一的，要正确处理干净和担当的关系，把干净和担当、勤政和廉政统\n一起来；全面从严治党和鼓励担当作为是内在统一的，不是彼此对立的。落实“三个区分开\n来”，把敢不敢扛事、愿不愿做事、能不能干事作为识别干部、评判优劣、奖惩升降的重要标\n准。","source":{"doc":"4e539a366dce19555ccf","first":18,"last":18,"page":18,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-7395ece3c108ff6e":{"sources":[{"id":"5527aa7c1dce00e1","label":"《求是》第 6 期《推动海洋经济高质量发展》（3 月 16 日）","topic":"重要文章","category":"时政","text":"考点六 《求是》第 6 期《推动海洋经济高质量发展》（3 月 16 日）\n指出推进中国式现代化，必须高效开发利用海洋，推动海洋经济高质量发展，走出中国特色向\n海图强之路。我国已攻克造船工业皇冠上“三大明珠”（航空母舰、大型邮轮、大型 LNG 运输\n船），建成“蛟龙”号、“梦想”号、“深海一号”等国之重器。提出五个“更加注重”：创\n新驱动、高效协同（陆海统筹、山海联动）、产业更新、人海和谐、合作共赢。","source":{"doc":"4e539a366dce19555ccf","first":18,"last":19,"page":18,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-d6903b35b79411ec":{"sources":[{"id":"13223713fc43bdd0","label":"《求是》第 7 期《树立和践行正确政绩观》（4 月 1 日）","topic":"重要文章","category":"时政","text":"考点七 《求是》第 7 期《树立和践行正确政绩观》（4 月 1 日）\n文章指出，政绩观问题是一个根本性问题，关乎立党为公、执政为民；树立和践行正确政绩\n观，起决定性作用的是党性，衡量党性强弱的根本尺子是公、私二字；共产党人必须牢记为民\n造福是最大政绩，衡量干部业绩好不好关键看老百姓口碑；高质量发展是全面建设社会主义现\n代化国家的首要任务，要坚持高质量发展成为领导干部政绩观的重要内容；要处理好稳和进、\n立和破、虚和实、标和本、近和远的关系，完善差异化考核评价体系，防止“数字出官、官出\n数字”。","source":{"doc":"4e539a366dce19555ccf","first":19,"last":19,"page":19,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-a835c54fe19c888b":{"sources":[{"id":"23045fba0650308c","label":"《求是》第 8 期《推动全民阅读，建设书香社会》（4 月 16 日）","topic":"重要文章","category":"时政","text":"考点八 《求是》第 8 期《推动全民阅读，建设书香社会》（4 月 16 日）\n文章指出，阅读是人类获取知识、启智增慧、培养道德的重要途径；学习理论最有效的办法是\n读原著、学原文、悟原理，共产党人要把读马克思主义经典、悟马克思主义原理当作生活习惯\n和精神追求；要发扬“挤”和“钻”的精神，建设全民终身学习的学习型社会、学习型大国，\n促进人人皆学、处处能学、时时可学；数字阅读要和传统阅读结合起来。文中引述王国维治学\n三境界勉励领导干部理论学习。","source":{"doc":"4e539a366dce19555ccf","first":19,"last":19,"page":19,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-4fdadd51b021ab59":{"sources":[{"id":"e09e9a278367a8af","label":"《求是》第 9 期《在省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班上的讲话》（5 月 1 日）","topic":"重要文章","category":"时政","text":"考点九 《求是》第 9 期《在省部级主要领导干部学习贯彻党的二十届四中全会精\n神专题研讨班上的讲话》（5 月 1 日）\n指出制定和实施五年规划是我们党治国理政一条重要经验、中国特色社会主义制度一个重要政\n治优势，体现四个“有利于”（实现党的领导、集中力量办大事、前瞻性把握战略问题、保持\n事业连续性），积累五个坚持经验（党中央集中统一领导、从实际出发、全国一盘棋、发扬民\n主集思广益、规划法定原则）。部署建设现代化产业体系：坚持智能化、绿色化、融合化方\n向，骨干是先进制造业，现代化基础设施是有机组成部分，发展新质生产力是必然要求；要加\n快构建新发展格局，以国内大循环为主体，让内需成为经济发展主动力。","source":{"doc":"4e539a366dce19555ccf","first":19,"last":19,"page":19,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-7208cc93f1335234":{"sources":[{"id":"cdc6f2f93572d09d","label":"《求是》第 10 期《做强做优做大实体经济》（5 月 16 日）","topic":"重要文章","category":"时政","text":"考点十 《求是》第 10 期《做强做优做大实体经济》（5 月 16 日）\n指出实体经济是一国经济的立身之本、财富创造的根本源泉、国家强盛的重要支柱，是我国经\n济发展和在国际经济竞争中赢得主动的根基；我国经济靠实体经济起家，也要靠实体经济走向\n未来，坚持把发展经济的着力点放在实体经济上，推动资源要素向实体经济集聚、政策措施向\n实体经济倾斜、工作力量向实体经济加强。\n强调制造业是实体经济的基础，要坚定不移建设制造强国；坚持把金融服务实体经济作为根本\n宗旨，实体经济是金融的根基，金融是实体经济的血脉，服务实体经济是金融的天职，决不能\n脱实向虚。","source":{"doc":"4e539a366dce19555ccf","first":19,"last":19,"page":19,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-05cf86f817b0ce2e":{"sources":[{"id":"d7f2fdafc35c3ca1","label":"求是第 11 期《前瞻布局和发展未来产业》（6 月）","topic":"重要文章","category":"时政","text":"考点十一 求是第 11 期《前瞻布局和发展未来产业》（6 月）\n文章指出，培育发展未来产业，对于抢占科技和产业制高点、牢牢把握发展主动权，对于发展\n新质生产力、建设现代化产业体系，对于提高人民生活品质、促进人的全面发展和社会全面进\n步，都具有重要意义。要站在推进强国建设、民族复兴伟业的战略高度，立足客观条件，发挥\n比较优势，坚持稳中求进、梯度培育。未来产业具有前瞻性、战略性、颠覆性等特点，要在量\n子科技、生物制造、氢能和核聚变能、脑机接口、具身智能、第六代移动通信等领域聚焦发\n力，因地制宜、错位发展；坚持“产业出题、科技答题”，发挥企业主体作用，完善政策支\n持，健全治理体系，确保既“放得活”又“管得好”。","source":{"doc":"4e539a366dce19555ccf","first":19,"last":20,"page":19,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-d7b8c47ba0633777":{"sources":[{"id":"6f9fcdbda842023b","label":"求是第 12 期《一体推进教育科技人才发展》（6 月）","topic":"重要文章","category":"时政","text":"考点十二 求是第 12 期《一体推进教育科技人才发展》（6 月）\n文章指出，教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑，建设教\n育强国、科技强国、人才强国具有内在一致性和相互支撑性。要坚持教育优先发展、科技自立\n自强、人才引领驱动，统筹推进教育科技人才体制机制一体改革，实现科教兴国战略、人才强\n国战略、创新驱动发展战略有效联动，形成推动高质量发展的倍增效应。要强化教育对科技和\n人才的支撑作用，高水平研究型大学发挥国家基础研究主力军和重大科技突破策源地作用；科\n学技术是第一生产力、第一竞争力；人才是第一资源，综合国力竞争归根到底是人才竞争，人\n才是创新活动中最为活跃、最为积极的因素。","source":{"doc":"4e539a366dce19555ccf","first":20,"last":20,"page":20,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-7b1c1e07f7afc7f5":{"sources":[{"id":"ec5f791a9c2ffb4c","label":"《求是》第 13 期重新发表《做焦裕禄式的县委书记》（7 月 1 日）","topic":"重要文章","category":"时政","text":"考点十三 《求是》第 13 期重新发表《做焦裕禄式的县委书记》（7 月 1 日）\n文章指出县一级处在承上启下的关键环节，是发展经济、保障民生、维护稳定、促进国家长治\n久安的重要基础；县委是党执政兴国的“一线指挥部”，县委书记是“一线总指挥”。提出当\n好县委书记必须做到“四有”：心中有党（对党忠诚是县委书记的重要标准，把学习掌握马克\n思主义理论作为看家本领）、心中有民（心系群众、为民造福，树立正确政绩观）、心中有责\n（为官一任、造福一方）、心中有戒（依法用权、秉公用权、廉洁用权）。我国县的建制始于\n春秋时期，因秦代推进郡县制而巩固发展，2000 多年来县一直是国家结构的基本单元。","source":{"doc":"4e539a366dce19555ccf","first":20,"last":20,"page":20,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-ae4f23adb3cd8bfb":{"sources":[{"id":"58e13597d6f91ece","label":"《求是》第 15 期《加快建设健康中国》（8 月 1 日）","topic":"重要文章","category":"时政","text":"考点十四 《求是》第 15 期《加快建设健康中国》（8 月 1 日）\n文章指出，到 2035 年建成健康中国是中央作出的战略决策，“十五五”（2026—2030 年）是\n实现这一目标的关键时期，必须统筹谋划、加紧推进，力求取得决定性进展。要坚持从国情出\n发，坚持党对卫生与健康工作的领导，坚持人民至上、生命至上，坚持健康优先发展战略，坚\n持基本医疗卫生事业的公益性，走中国特色卫生与健康发展道路。2016 年提出的新时代卫生\n与健康工作方针为：以基层为重点，以改革创新为动力，预防为主，中西医并重，把健康融入\n所有政策，人民共建共享。分级诊疗内涵为基层首诊、双向转诊、急慢分治、上下联动，做到\n大病不出省、一般病在市县解决、日常疾病在基层解决。","source":{"doc":"4e539a366dce19555ccf","first":20,"last":20,"page":20,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-9f190695ba3ee4b3":{"sources":[{"id":"053709a382c7926f","label":"《求是》第 16 期《提高防灾减灾救灾能力》（8 月 16 日）","topic":"重要文章","category":"时政","text":"考点十五 《求是》第 16 期《提高防灾减灾救灾能力》（8 月 16 日）\n文章总结防灾减灾救灾宝贵经验“七个坚持”：坚持党的全面领导，坚持人民至上、生命至\n上，坚持尊重自然规律，坚持预防为主，坚持改革创新，坚持系统观念，坚持社会共治。\n提出“三个转变”：从注重灾后救助向注重灾前预防转变，从应对单一灾种向综合减灾转变，\n从减少灾害损失向减轻灾害风险转变。\n部署五方面举措：推动灾害治理向事前预防转型（加紧补齐北方地区防洪排涝抗灾基础设施短\n板）；提升大灾巨灾应对处置能力（树牢底线思维、极限思维，提高预警的及时性、精准性、\n通达性）；强化科技支撑和法治保障；夯实基层基础；抓好责任落实（应急管理部为牵头部\n门），坚决纠正重发展轻安全、重救灾轻预防等倾向。","source":{"doc":"4e539a366dce19555ccf","first":20,"last":21,"page":20,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-baa26b7e60cf8605":{"sources":[{"id":"35a6c4c25dc789ff","label":"《坚持落实管党治党政治责任》（《求是》第 17 期）（9 月 1 日）","topic":"重要文章","category":"时政","text":"考点十六 《坚持落实管党治党政治责任》（《求是》第 17 期）（9 月 1 日）\n全面从严治党，核心是加强党的领导，基础在全面，关键在严，要害在治。要健全主体明确、\n要求清晰的责任体系，明确党委（党组）全面从严治党主体责任、各级纪委的监督责任、党委\n（党组）书记第一责任人责任、领导班子其他成员“一岗双责”的管党治党责任、党员、干部\n的具体责任。","source":{"doc":"4e539a366dce19555ccf","first":21,"last":21,"page":21,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-b4ecf41ae189782a":{"sources":[{"id":"9fc7ca8e36b61996","label":"《在加强基础研究座谈会上的讲话》（《求是》第 18 期）（9 月 16日）","topic":"重要文章","category":"时政","text":"考点十七 《在加强基础研究座谈会上的讲话》（《求是》第 18 期）（9 月 16\n日）\n基础研究是整个科学体系的源头，是所有技术问题的总机关。举措包括：优化基础研究系统布\n局、壮大基础研究人才队伍、加强对基础研究的支持保障、拓展基础研究国际合作。","source":{"doc":"4e539a366dce19555ccf","first":21,"last":21,"page":21,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-44ae4ad041651a58":{"sources":[{"id":"08c69bfb119c5942","label":"《求是》第 19 期《加强普惠性、基础性、兜底性民生建设》（10 月 1日）","topic":"重要文章","category":"时政","text":"考点十八 《求是》第 19 期《加强普惠性、基础性、兜底性民生建设》（10 月 1\n日）\n文章强调，中国式现代化，民生为大；人民对美好生活的向往，就是我们的奋斗目标。要坚持\n以人民为中心，加强普惠性、基础性、兜底性民生建设，坚守底线、突出重点、完善制度、引\n导预期，统筹做好教育、收入分配、就业、社会保障、医疗卫生、住房等方面的工作，不断推\n动幼有所育、学有所教、劳有所得、病有所医、老有所养、住有所居、弱有所扶取得新进展。\n发展经济的根本目的是更好保障和改善民生，抓民生也是抓发展；要把发展经济和改善民生有\n机统一起来，使民生改善和经济发展有效对接、相得益彰。","source":{"doc":"4e539a366dce19555ccf","first":21,"last":21,"page":21,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-36748c6d8c84f34b":{"sources":[{"id":"9d18151be1895236","label":"《求是》第 20 期《以更高标准、更实举措推进全面从严治党》（10 月16 日）","topic":"重要文章","category":"时政","text":"考点十九 《求是》第 20 期《以更高标准、更实举措推进全面从严治党》（10 月\n16 日）\n文章强调，“十五五”时期是基本实现社会主义现代化夯实基础、全面发力的关键时期，要把\n党的二十届四中全会擘画的蓝图变为现实，必须坚持和加强党的全面领导，持之以恒推进全面\n从严治党。文章提出“三个更加”：更加坚决有力地贯彻落实党中央重大决策部署、更加科学\n有效地把权力关进制度笼子、更加清醒坚定地推进反腐败斗争；并强调防止“牛栏关猫”，确\n保制度规定真正成为带电的高压线。","source":{"doc":"4e539a366dce19555ccf","first":21,"last":21,"page":21,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-fd7e12e09dcf4054":{"sources":[{"id":"a37d5bd5c46f501e","label":"《中华人民共和国民族团结进步促进法》（3 月 12 日）","topic":"重要法律","category":"时政","text":"考点一 《中华人民共和国民族团结进步促进法》（3 月 12 日）\n3 月 12 日十四届全国人大四次会议通过，自 2026 年 7 月 1 日起施行。这是我国现行有效法律\n中除宪法外第四部设置“序言”的法律，是新时代实施宪法有关规定、处理民族事务和开展民\n族工作的基本法律。明确把铸牢中华民族共同体意识作为党的民族工作主线、民族地区各项工\n作的主线；强调民族团结是我国各族人民的生命线，各族人民凝聚成血脉相融、信念相同、文\n化相通、经济相依、情感相亲的命运共同体。","source":{"doc":"4e539a366dce19555ccf","first":21,"last":22,"page":21,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-8217cd81ae4088d8":{"sources":[{"id":"40d72d9e6e6705a2","label":"《中华人民共和国国家发展规划法》（3 月 12 日）","topic":"重要法律","category":"时政","text":"考点二 《中华人民共和国国家发展规划法》（3 月 12 日）\n3 月 12 日十四届全国人大四次会议表决通过，自公布之日起施行。这是中国首次以法律形式\n规范国家发展规划，是“十五五”开局之年的标志性法律之一。明确国家发展规划是规划期内\n经济社会发展的蓝图和行动纲领，是政府履行经济调节、市场监管、社会管理、公共服务、生\n态环境保护等职能的重要依据，是其他各级各类规划的总遵循。国家建立健全以国家发展规划\n为统领、以国土空间规划为基础、以专项规划、区域规划为支撑的国家规划体系。","source":{"doc":"4e539a366dce19555ccf","first":22,"last":22,"page":22,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-8ead579aa09c4f13":{"sources":[{"id":"932020682664602f","label":"《中华人民共和国社会救助法》（4 月 30 日）","topic":"重要法律","category":"时政","text":"考点三 《中华人民共和国社会救助法》（4 月 30 日）\n社会救助领域第一部专门法律，取代《社会救助暂行办法》。2026 年 4 月 30 日由十四届全国\n人大常委会第二十二次会议表决通过，自 2026 年 7 月 1 日起施行。根本方针为保基本、兜底\n线、救急难、可持续；构建基本生活救助（最低生活保障、特困人员供养）、专项救助（医\n疗、教育、住房、就业、受灾人员救助）、急难救助（临时救助、疾病应急救助、生活无着流\n散人员救助）三层次救助体系；新增最低生活保障边缘家庭、刚性支出困难家庭两类对象；建\n立“一门受理、协同办理”机制；实行救助渐退机制，避免“断崖式”退出。","source":{"doc":"4e539a366dce19555ccf","first":22,"last":22,"page":22,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-9ce2e002de038208":{"sources":[{"id":"2c5f1086437306a2","label":"《中华人民共和国监狱法》（4 月 30 日）","topic":"重要法律","category":"时政","text":"考点五 《中华人民共和国监狱法》（4 月 30 日）\n2026 年 4 月 30 日由十四届全国人大常委会第二十二次会议表决通过，自 2026 年 11 月 1 日起\n施行，系 1994 年颁布以来首次全面修订。监狱提出减刑假释建议应经减刑假释评审委员会评\n审，同意提请的在监狱内公示；暂予监外执行建议应经省级监狱管理机关评审委员会审核；人\n民检察院对监狱刑罚执行、管理活动实行监督；增加警务督察制度，推行狱务公开；保障罪犯\n人格尊严、生命健康、人身安全及申诉、控告、检举、辩护权等权利；增加爱国主义、集体主\n义、中华优秀传统文化、法治观念、道德规范等教育内容；对未成年犯实行教育、感化、挽救\n方针。","source":{"doc":"4e539a366dce19555ccf","first":22,"last":22,"page":22,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-7fdf07b45367cf56":{"sources":[{"id":"002f800bb511882e","label":"《中华人民共和国国防动员法》（8 月 28 日）","topic":"重要法律","category":"时政","text":"考点六 《中华人民共和国国防动员法》（8 月 28 日）\n2026 年 8 月 28 日由十四届全国人大常委会第二十四次会议表决通过，自 2026 年 10 月 1 日起\n施行，系该法首次全面修订。坚持党的领导，贯彻强军思想，坚持总体国家安全观；将“预备\n役人员储备与征召制度”调整为“后备兵员储备与征召制度”；构建政府主导、社会共建、多\n元互补的战略物资储备体系；实施国防动员后可依法征收、征用，造成直接经济损失的给予公\n平、合理补偿；开展军品产业链、供应链安全评估，推动军品通用化、系列化、组合化。","source":{"doc":"4e539a366dce19555ccf","first":22,"last":22,"page":22,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-8a563c93c8085c3e":{"sources":[{"id":"f054c80c9945ecc7","label":"《中华人民共和国律师法》（8 月 28 日）","topic":"重要法律","category":"时政","text":"考点七 《中华人民共和国律师法》（8 月 28 日）\n2026 年 8 月 28 日由十四届全国人大常委会第二十四次会议表决通过，自 2026 年 9 月 1 日起\n施行，以“小切口”方式修正。律师工作坚持中国共产党的领导；律师事务所按党章设立党组\n织；执业条件为拥护宪法、党的领导、社会主义法治，通过国家统一法律职业资格考试，实习\n满一年，品行良好；“国家推进刑事案件律师辩护全覆盖”写入法律；港澳法律执业者通过粤\n港澳大湾区律师执业考试取得资质后，可在广州、深圳、珠海、佛山、惠州、东莞、中山、江\n门、肇庆九市执业。","source":{"doc":"4e539a366dce19555ccf","first":22,"last":23,"page":22,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-0d26ab22b6fb990e":{"sources":[{"id":"0e77f0cfe607bc8e","label":"《中华人民共和国仲裁法》（新修订）","topic":"重要法律","category":"时政","text":"考点八 《中华人民共和国仲裁法》（新修订）\n2026 年全面修订，自 2026 年 3 月 1 日起施行。民商事纠纷当事人自愿达成仲裁协议，提交仲\n裁委员会裁决并受其约束的制度。可仲裁范围：平等主体的自然人、法人、非法人组织之间的\n合同纠纷和其他财产权益纠纷；不可仲裁：婚姻、收养、监护、扶养、继承等身份纠纷及依法\n应由行政机关处理的行政争议。\n仲裁机构不按行政区划层层设立，不实行级别管辖和地域管辖，由当事人协议选定；实行或裁\n或审原则、一裁终局；裁决按多数仲裁员意见作出，不能形成多数时按首席仲裁员意见作出；\n支持在线仲裁。","source":{"doc":"4e539a366dce19555ccf","first":23,"last":23,"page":23,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-1478a1ab4917755e":{"sources":[{"id":"684c0afed1b51195","label":"《中华人民共和国行政复议法实施条例》（新修订）","topic":"重要法律","category":"时政","text":"考点九 《中华人民共和国行政复议法实施条例》（新修订）\n配套 2023 年《行政复议法》修订，自 2026 年 7 月 1 日起施行。国务院行政复议机构统一平\n台，在线进行与线下同等法律效力；新增农村集体经济组织、村民委员会、村民小组、业主委\n员会可以自己名义申请复议；申请期限 60 日；复议前置情形包括当场处罚、侵犯自然资源权\n属、不履行法定职责、政府信息公开不予公开等 5 种；列入严重失信主体名单、开除学籍申诉\n处理、学位撤销等可复议；简易程序可由 1 名复议人员审理。","source":{"doc":"4e539a366dce19555ccf","first":23,"last":23,"page":23,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-8c22ed74e0ab827f":{"sources":[{"id":"bfb994650a64e1a9","label":"数字人民币正式迈入 2.0 时代（1 月 1 日）","topic":"重要事件","category":"时政","text":"考点一 数字人民币正式迈入 2.0 时代（1 月 1 日）\n2026 年 1 月 1 日，数字人民币正式迈入 2.0 时代，核心是从“数字现金”升级为“数字存款\n货币”。按《行动方案》，银行机构为客户实名数字人民币钱包余额计付利息，标志着其进入\n以账户为基础、具备生息能力且生态更加完善的新阶段，货币层次由流通中现金拓展到存款。\n数字人民币是国家信用、法定货币，支持实时结算、离线支付、不收费，可追溯资金流，有助\n于防范电信诈骗和腐败洗钱风险。","source":{"doc":"4e539a366dce19555ccf","first":23,"last":23,"page":23,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-1a55ffd46460137f":{"sources":[{"id":"53589f89cd77b536","label":"中国迈入全球制造强国行列，实现“第一步走”战略目标（1 月）","topic":"重要事件","category":"时政","text":"考点二 中国迈入全球制造强国行列，实现“第一步走”战略目标（1 月）\n《2025 中国制造强国发展指数报告》显示，2024 年我国制造业顶压前行、向新向优，制造强\n国发展指数与德国、日本处于同一区间，进入全球制造强国第二阵列，成功实现制造强国建设\n“第一步走”战略目标，成为继美国、德国、日本后第四个迈入全球制造强国行列的国家。未\n来十年是“第二步走”关键时期，要牢牢确立实体经济在国民经济中的重要地位，保持制造业\n合理比重，坚持以创新为根本动力，加快人工智能赋能新型工业化，到 2035 年基本实现新型\n工业化，迈入世界制造强国前列。","source":{"doc":"4e539a366dce19555ccf","first":23,"last":24,"page":23,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-8752f9fc38ef1922":{"sources":[{"id":"e2787eb4a5c44cac","label":"中国连续 17 年成为全球第二大进口市场（2 月 5 日）","topic":"重要事件","category":"时政","text":"考点三 中国连续 17 年成为全球第二大进口市场（2 月 5 日）\n2 月 5 日获悉，2025 年中国进口规模达 18.5 万亿元，连续 17 年成为全球第二大进口市场（出\n口规模居全球第一）。中国自 130 多个国家和地区的进口实现增长，成为近 80 个国家的主要\n出口目的地，充分彰显我国超大规模市场的吸引力，为世界经济发展提供了稳定的需求支撑，\n是拉动世界经济增长的重要引擎。","source":{"doc":"4e539a366dce19555ccf","first":24,"last":24,"page":24,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-4fc01c89e40a0023":{"sources":[{"id":"3249ed40d6b7e89d","label":"《2025 年国民经济和社会发展统计公报》发布（2 月 28 日）","topic":"重要事件","category":"时政","text":"考点四 《2025 年国民经济和社会发展统计公报》发布（2 月 28 日）\n2 月 28 日，国家统计局发布《2025 年国民经济和社会发展统计公报》。2025 年我国 GDP 比上\n年增长 5.0%，经济总量首次突破 140 万亿元大关，圆满完成预期目标任务；人均 GDP 达 99665\n元，比上年增长 5.1%。我国对世界经济增长贡献率预计保持在 30%左右，持续成为世界经济增\n长的最大贡献者和最强稳定锚，稳居世界第二大经济体，经济总量占全球六分之一左右。全社\n会研究与试验发展（R&D）经费投入比上年增长 8.1%，与 GDP 之比达 2.80%，首次超过 OECD 国\n家平均水平，其中基础研究经费占比达 7.08%。","source":{"doc":"4e539a366dce19555ccf","first":24,"last":24,"page":24,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-8f1b680c1da908f6":{"sources":[{"id":"7a5ca499d0af7df7","label":"中国发展高层论坛 2026 年年会（3 月 22 日）","topic":"重要事件","category":"时政","text":"考点五 中国发展高层论坛 2026 年年会（3 月 22 日）\n3 月 22 日中国发展高层论坛 2026 年年会在北京开幕，主题为“'十五五'的中国：高质量发展\n与共创新机遇”。年会上国家数据局从官方角度给出 Token 的中文翻译“词元”：到今年 3\n月，我国日均词元（Token）调用量已超过 140 万亿。Token 是 AI 模型处理信息的最小计量单\n位，Token 调用量是衡量 AI 模型活跃度和产业价值的关键指标。","source":{"doc":"4e539a366dce19555ccf","first":24,"last":24,"page":24,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-e176563877e8671f":{"sources":[{"id":"3ff64afe1eadf333","label":"我国新增两处世界地质公园（4 月 15 日）","topic":"重要事件","category":"时政","text":"考点六 我国新增两处世界地质公园（4 月 15 日）\n北京时间 4 月 15 日，在法国巴黎召开的联合国教科文组织执行局第 224 届会议上，我国浙江\n常山和四川四姑娘山顺利通过审议，正式成为世界地质公园。至此，我国世界地质公园增至\n51 处，分布在全国 24 个省（自治区、直辖市）及香港特别行政区。","source":{"doc":"4e539a366dce19555ccf","first":24,"last":24,"page":24,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-496f895b5c7a63b6":{"sources":[{"id":"b4e5f226268cd094","label":"2025 年度全国十大考古新发现揭晓（4 月 29 日）","topic":"重要事件","category":"时政","text":"考点七 2025 年度全国十大考古新发现揭晓（4 月 29 日）\n4 月 29 日，2025 年度全国十大考古新发现 4 月 29 日在北京揭晓：\n吉林东部长白山旧石器时代遗址群：构建距今 22 万年至 1.3 万年连续完整的古人类活动序\n列，填补东北亚史前文化交流研究空白 。\n河南新郑裴李岗遗址：发现北方最早红曲霉酿酒技术与早期纺织染色工艺，深化中原农业起源\n研究 。\n河北宣化郑家沟遗址：首次在红山文化核心区之外发现高等级积石冢，拓展红山文化分布范\n围 。\n甘肃庆阳南佐遗址：揭示 5000 年前黄土高原都邑中轴线格局，实证区域王权出现 。\n山西昔阳钟村遗址：发现夏代晚期高等级贵族墓葬，揭示跨区域资源贸易网络 。\n河南郑州商城遗址：新发现早商大型仓储基址群与城市水网，完善早商都城制度体系 。\n陕西富平长春遗址：填补关中东部西周采邑考古空白，还原西周基层治理秩序 。\n山东青岛琅琊台遗址：实证秦汉国家级海洋祭祀礼制，展现海疆治理体系 。\n浙江绍兴越国都城和汉六朝会稽郡遗址：揭示越国都城完整格局，出土汉六朝官方简牍 。\n宁夏贺兰苏峪口瓷窑址：复原国内保存最完整的古代制瓷产业链，填补西夏官作制度空白 。","source":{"doc":"4e539a366dce19555ccf","first":24,"last":25,"page":24,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-8f08df4e1f6fc2fb":{"sources":[{"id":"a96eed071e124dbe","label":"中国矿产资源最新“家底”公布：31 项世界第一（4 月 29 日）","topic":"重要事件","category":"时政","text":"考点八 中国矿产资源最新“家底”公布：31 项世界第一（4 月 29 日）\n4 月 29 日，自然资源部公布，截至“十四五”末，中国稀土、钨、锡、钼、锑、镓、锗、\n铟、萤石、石墨等 14 种矿产储量居世界第一位；2025 年煤炭、钒、钛、锌、稀土、钨、锡、\n钼、锑、镓、铟、金、碲、磷、萤石、石墨等 17 种矿产产量居世界第一，其中稀土、钨、\n锑、镓、铟、碲等 11 种矿产产量占全球 50%以上。我国是全世界唯一能够提供全部 17 种稀土\n金属的国家；内蒙古白云鄂博矿是世界最大稀土矿，“中国稀土之父”是徐光宪。","source":{"doc":"4e539a366dce19555ccf","first":25,"last":25,"page":25,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-8130c59e8ea60187":{"sources":[{"id":"8aead7cdbe0cd0cf","label":"国家发改委部署“六张网”建设（5 月 23 日）","topic":"重要事件","category":"时政","text":"考点九 国家发改委部署“六张网”建设（5 月 23 日）\n国家发展改革委表示，我国将抓紧出台水网、新型电网、算力网、新一代通信网、城市地下管\n网、物流网“六张网”相关规划和实施方案，统筹建设内容、明确各领域投资重点、将目标任\n务分解到年度。推进“六张网”建设投资规模超过 7 万亿元，这些重大基础设施网络既是深入\n挖掘内需潜力的有力抓手，还能更好支撑产业发展、服务百姓生活、强化安全保障。","source":{"doc":"4e539a366dce19555ccf","first":25,"last":25,"page":25,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-a1e35e7b28cb2dac":{"sources":[{"id":"53df5c430dfe1914","label":"“七一勋章”颁授（7 月 1 日）","topic":"重要事件","category":"时政","text":"考点十 “七一勋章”颁授（7 月 1 日）\n2026 年 7 月 1 日，中共中央发布关于授予“七一勋章”的决定，授予马善祥、王於昌、李连\n成、吾哈斯·苏来曼、吴亚琴、陈俊武、赵亚夫、钟掘 8 名同志“七一勋章”，他们是各条战\n线党员的杰出代表。“七一勋章”是党内最高荣誉（我国表彰体系为“五章一簿”）。\n马善祥为坚守服务群众化解矛盾第一线的金牌调解员（“老马工作室”）；\n王於昌为深藏功名的英雄老兵（曾两次击落 U-2 高空侦察机）；\n李连成为村党支部书记优秀典范（开创“户户有股、人人劳动、家家分红”集体经济模式）；\n吾哈斯·苏来曼为守护边疆人民的白衣卫士；\n吴亚琴为社区工作者杰出代表（践行新时代“枫桥经验”）；\n陈俊武为中国催化裂化工程技术奠基人；\n赵亚夫为脱贫攻坚惠农兴农楷模（“党支部+合作社+农户”戴庄经验）；\n钟掘为机械工程领域著名专家（攻克多项“卡脖子”难题）。","source":{"doc":"4e539a366dce19555ccf","first":25,"last":25,"page":25,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-324d966951519522":{"sources":[{"id":"0ea40fb26c4bb824","label":"国务院批复设立上海辰山国家植物园（7 月 2 日）","topic":"重要事件","category":"时政","text":"考点十一 国务院批复设立上海辰山国家植物园（7 月 2 日）\n2026 年 7 月 2 日，国务院印发国函〔2026〕58 号批复，正式同意设立上海辰山国家植物园。\n至此，我国形成北京、华南（广州）、上海辰山三大国家植物园的分布格局。","source":{"doc":"4e539a366dce19555ccf","first":25,"last":26,"page":25,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-fb59666b9d7d6c04":{"sources":[{"id":"428edd374cbdf82f","label":"2025 年度国家最高科学技术奖揭晓（7 月 8 日）","topic":"重要事件","category":"时政","text":"考点十二 2025 年度国家最高科学技术奖揭晓（7 月 8 日）\n2026 年 7 月 8 日，2025 年度国家最高科学技术奖揭晓，陈立泉院士、贲德院士获奖。\n陈立泉（1940 年生，中国科学院物理研究所研究员，中国工程院院士）是我国锂电池领域的\n奠基人、开拓者和引领者；\n贲德（1938 年生，中国电子科技集团第十四研究所研究员，中国工程院院士）是我国机载脉\n冲多普勒雷达技术的奠基者、相控阵雷达技术的主要开创者、天基监视雷达技术的先行者。","source":{"doc":"4e539a366dce19555ccf","first":26,"last":26,"page":26,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-42ce6833786efc26":{"sources":[{"id":"a1d0d5d175af503f","label":"中国籍数学家首次斩获菲尔兹奖（7 月 23 日）","topic":"重要事件","category":"时政","text":"考点十三 中国籍数学家首次斩获菲尔兹奖（7 月 23 日）\n2026 年 7 月 23 日，北大 2007 级本科校友王虹、邓煜斩获数学界最高荣誉菲尔兹奖。这是中\n国籍数学家首次斩获菲尔兹奖，更是菲尔兹奖 90 年历史上首次由中国籍数学家同届摘得两枚\n奖章，创下历史性纪录。\n王虹（1991 年生，现为纽约大学柯朗数学科学研究所教授）证明困扰国际数学界逾百年的三\n维挂谷猜想，成为菲尔兹奖历史上第三位女性得主；邓煜（1989 年生，芝加哥大学数学系教\n授）在著名的希尔伯特第六问题上取得里程碑式重大突破。","source":{"doc":"4e539a366dce19555ccf","first":26,"last":26,"page":26,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-9410efcb3b355d87":{"sources":[{"id":"d8a10c16eab04e32","label":"“景德镇手工瓷业遗存”列入《世界遗产名录》（7 月 25 日）","topic":"重要事件","category":"时政","text":"考点十五 “景德镇手工瓷业遗存”列入《世界遗产名录》（7 月 25 日）\n2026 年 7 月 25 日，在韩国釜山召开的联合国教科文组织第 48 届世界遗产大会上，中国提交\n的“景德镇手工瓷业遗存”项目通过审议，成功列入《世界遗产名录》，至此中国世界遗产总\n数达 61 项。该遗存完整保存了 10 至 19 世纪手工制瓷技术体系和产业组织形态，包含原料开\n采、燃料供应、生产加工、水运物流等全产业链设施，体现了世界对中国瓷器的认可。\n此次申遗成功，填补了《世界遗产名录》中“瓷”主题遗产的空白，标志着中国古代丝绸、\n茶、瓷三大文化载体在世界遗产领域实现了完整呈现。","source":{"doc":"4e539a366dce19555ccf","first":26,"last":26,"page":26,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-aeb68691aabad109":{"sources":[{"id":"756eab4f5d79c7c8","label":"上半年“新新三样”出口成中国出口新名片（7 月）","topic":"重要事件","category":"时政","text":"考点十六 上半年“新新三样”出口成中国出口新名片（7 月）\n2026 年上半年，机器人、人工智能、创新药等代表未来产业方向的“新新三样”出口增速明\n显，正在成为中国出口的新名片。我国出口产品序列不断迭代：“老三样”为服装、家具、家\n电，“新三样”为新能源车、锂电池、光伏，“新新三样”为机器人、人工智能、创新药，标\n志着我国科技创新能力和出口结构持续升级。","source":{"doc":"4e539a366dce19555ccf","first":26,"last":26,"page":26,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-78d3968e3d854b88":{"sources":[{"id":"624e7a05f92b8211","label":"北京获 2029 年“世界建筑之都”称号（8 月 5 日）","topic":"重要事件","category":"时政","text":"考点十七 北京获 2029 年“世界建筑之都”称号（8 月 5 日）\n2026 年 8 月 5 日，联合国教科文组织正式授予北京 2029 年“世界建筑之都”称号，北京成为\n全球第四座获此殊荣的城市。“世界建筑之都”是联合国教科文组织与国际建筑师协会联合设\n立的全球性荣誉机制，每三年指定世界建筑师大会主办城市为该称号获得城市。北京成为继里\n约热内卢（2020）、哥本哈根（2023）、巴塞罗那（2026）后第四个获此称号的城市；随着\n2026 年 7 月第 29 届世界建筑师大会在巴塞罗那闭幕并完成会旗交接，2029 年第 30 届世界建\n筑师大会进入“北京时间”，这是北京继 1999 年后再次承办全球建筑界最高级别盛会。","source":{"doc":"4e539a366dce19555ccf","first":26,"last":27,"page":26,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-7c8baf0d583eff5f":{"sources":[{"id":"e324fab220a2d776","label":"2026 世界机器人大会开幕（8 月 19 日）","topic":"重要事件","category":"时政","text":"考点十八 2026 世界机器人大会开幕（8 月 19 日）\n2026 年 8 月 19 日，主题为“人机共生产需共融”的 2026 世界机器人大会在北京开幕，由中\n国电子学会、世界机器人合作组织共同主办。\n拓展知识点：“人工智能”于 1956 年在美国达特茅斯学院的一次暑期研讨会上被首次正式提\n出（2026 年为概念提出 70 周年）；“人工智能+”于 2024 年首次写入中国政府工作报告；\n“智能经济新形态”是 2026 年《政府工作报告》首次提出的全新概念；人工智能是世界经济\n增长的新引擎和新旧动能转换的加速器，正从“数字世界”走向“物理世界”。","source":{"doc":"4e539a366dce19555ccf","first":27,"last":27,"page":27,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-156dae68f1dfb926":{"sources":[{"id":"a07fa318700778db","label":"我国光伏发电装机历史性超过煤电（9 月 1 日）","topic":"重要事件","category":"时政","text":"考点十九 我国光伏发电装机历史性超过煤电（9 月 1 日）\n9 月 1 日，国家能源局宣布，我国光伏发电装机历史性超过煤电，成为装机规模最大的电源品\n类。这是我国能源绿色低碳转型进程中具有里程碑意义的标志性事件。","source":{"doc":"4e539a366dce19555ccf","first":27,"last":27,"page":27,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-78e12cc17044e339":{"sources":[{"id":"fb042347cfc41dd2","label":"国家数据集团有限公司成立（10 月 20 日）","topic":"重要事件","category":"时政","text":"考点二十 国家数据集团有限公司成立（10 月 20 日）\n10 月 20 日，国家数据集团有限公司成立大会在河北雄安新区举行。组建国家数据集团有限公\n司，对于充分把握人工智能发展先机、加快建设数字中国、构筑国家竞争新优势具有重要意\n义。","source":{"doc":"4e539a366dce19555ccf","first":27,"last":27,"page":27,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-1ee58878c5dd6b58":{"sources":[{"id":"e7d78b441121cfb5","label":"第 140 届中国进出口商品交易会（10 月 14 日）","topic":"重要事件","category":"时政","text":"考点二十一 第 140 届中国进出口商品交易会（10 月 14 日）\n10 月 14 日，向第 140 届中国进出口商品交易会（广交会）致贺信。讲话指出，广交会创办 70\n年来，在促进中外贸易往来方面发挥了重要作用，已成为中国扩大高水平对外开放、推动建设\n开放型世界经济的有效平台。新形势下，中国愿同世界各国携起手来，共同维护多边贸易体\n制，保障全球产业链供应链稳定畅通，拓展国际经贸互利合作空间，推进普惠包容的经济全球\n化，为世界发展繁荣持续注入新动力。","source":{"doc":"4e539a366dce19555ccf","first":27,"last":27,"page":27,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-b37cbd8996144cc8":{"sources":[{"id":"2fe1c3c308f302a6","label":"2026 全球治理论坛（雄安）（10 月 23 日）","topic":"重要事件","category":"时政","text":"考点二十二 2026 全球治理论坛（雄安）（10 月 23 日）\n2026 全球治理论坛（雄安）当日在河北雄安新区开幕，主题为“重建信心与合作：百年变局\n与改革完善全球治理”。10 月 23 日，向 2026 全球治理论坛（雄安）致信。讲话指出，当\n前，世界百年变局加速演进，和平赤字、发展赤字、安全赤字、治理赤字有增无减。提出全球\n治理倡议，旨在推动构建更加公正合理的全球治理体系，建设一个更加美好的世界。中国愿同\n各方一道，践行共商共建共享的全球治理观，以信心汇聚力量，以合作破解难题，推动落实全\n球治理倡议，为变乱交织的世界注入更多确定性和正能量，携手迈向人类命运共同体。","source":{"doc":"4e539a366dce19555ccf","first":27,"last":27,"page":27,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-13df6daaa5788daf":{"sources":[{"id":"7e1496dee6b49f4c","label":"2026 年（第十三批）世界灌溉工程遗产名录公布（10 月 14 日）","topic":"重要事件","category":"时政","text":"考点二十三 2026 年（第十三批）世界灌溉工程遗产名录公布（10 月 14 日）\n2026 年 10 月 14 日晚，在法国马赛召开的国际灌排委员会第 77 届国际执行理事会会议上，公\n布 2026 年（第十三批）世界灌溉工程遗产名录，我国申报的河南沁河广利渠（五龙口）、甘\n肃讨赖河绿洲灌溉系统、江西上饶市广信黄沙渠、福建长泰龙津古陂灌溉工程全部成功入选。\n至此，中国的世界灌溉工程遗产总数已达 46 项。","source":{"doc":"4e539a366dce19555ccf","first":27,"last":28,"page":27,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-1af3f5dd8a49aa8f":{"sources":[{"id":"8c29055c47067561","label":"国家航天局盘点 2025 年航天成就（1 月 4 日）","topic":"重要科技成就","category":"时政","text":"考点一 国家航天局盘点 2025 年航天成就（1 月 4 日）\n2025 年我国在载人航天、深空探测、商业航天等领域完成多项突破、实现多个首次：全年航\n天发射 92 次，创历史新高；神舟二十号乘组在轨执行任务 204 天，创中国载人航天史上最长\n在轨时长纪录；神舟二十一号创造 3.5 小时快速交会对接纪录；针对神舟二十号载人飞船突发\n情况，首次成功实施“16 天应急发射”，展现应急响应能力；天问二号启程执行我国首次小\n行星探测与采样返回任务，我国成为全球第一航空人口大国。","source":{"doc":"4e539a366dce19555ccf","first":28,"last":28,"page":28,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-c04e66dfd2264cc2":{"sources":[{"id":"77a6ff503e9db3fb","label":"我国机器人产业实现跨越式发展（1 月）","topic":"重要科技成就","category":"时政","text":"考点二 我国机器人产业实现跨越式发展（1 月）\n“十四五”时期，我国机器人产业锚定科技自立自强，在核心部件攻关、产业链构建、场景应\n用拓展等方面实现跨越式发展，成为全球机器人技术创新策源地、高端制造集聚地和集成应用\n新高地，我国成为全球第一大机器人生产国。机器人被誉为“制造业皇冠顶端的明珠”，“十\n五五”规划建议将具身智能列为前瞻布局的未来产业之一。","source":{"doc":"4e539a366dce19555ccf","first":28,"last":28,"page":28,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-90c3eb91d54cb691":{"sources":[{"id":"e25df9d131582703","label":"中国建成全球最完整的深潜装备矩阵（1 月）","topic":"重要科技成就","category":"时政","text":"考点三 中国建成全球最完整的深潜装备矩阵（1 月）\n目前，中国已建成全球最完整的深潜装备矩阵。载人深潜器形成“蛟龙”“深海勇士”“奋斗\n者”三剑客；无人深潜器包括“海斗”“潜龙”系列；配套科考船有“探索一号”“探索二\n号”“探索三号”和“深海一号”等，形成海上移动基地。\n其中“奋斗者”号为万米载人潜水器，“海斗”号为万米级作业型无人潜水器，填补了我国万\n米级作业型无人潜水器空白，标志我国深海探测装备体系化、谱系化发展水平居世界前列。","source":{"doc":"4e539a366dce19555ccf","first":28,"last":28,"page":28,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-59b5e19916b1371f":{"sources":[{"id":"f668087f6070b78b","label":"2025 年度“中国科学十大进展”发布（3 月）","topic":"重要科技成就","category":"时政","text":"考点四 2025 年度“中国科学十大进展”发布（3 月）\n国家自然科学基金委员会在 2026 中关村论坛年会开幕式上发布 2025 年度“中国科学十大进\n展”。入选进展包括：嫦娥六号样品首次揭示月背演化历史和巨型撞击效应（月球背面南极艾\n特肯盆地采样返回）、创新方法实现规模化制备柔性超平金刚石薄膜、可控核聚变大科学装置\n实现“亿度”运行、发现神经酰胺受体和菌源调控物及其在心血管与代谢性疾病中的作用、基\n因编辑猪肝植入人体突破跨物种器官移植壁垒、炎性衰老机制解析与多维靶向干预、深渊海沟\n最深处发现繁盛的化能合成生物群落、全功能二维半导体/硅基混合架构异质集成闪存芯片、\n实现基于熔盐堆的钍铀核燃料转换、界面调控新方法创制面向空天应用的高性能柔性叠层太阳\n能电池。","source":{"doc":"4e539a366dce19555ccf","first":28,"last":28,"page":28,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-a186a7cbdaec3fc6":{"sources":[{"id":"73cd2f67279c1fee","label":"月球陨石新矿物“铈镁嫦娥石”（4 月）","topic":"重要科技成就","category":"时政","text":"考点五 月球陨石新矿物“铈镁嫦娥石”（4 月）\n2026 年 4 月，我国本土发现的首块月球陨石揭示了月球两次关键地质事件，并发现一种月球\n新矿物——铈镁嫦娥石。这是人类发现的第十一种月球新矿物，也是继美国和德国科研团队之\n后，在月球陨石中发现的第三种月球新矿物。“铈、镁”分别代表矿物富含稀土元素铈和镁元\n素，“嫦娥石”则体现了中国探月工程的文化传承。","source":{"doc":"4e539a366dce19555ccf","first":28,"last":29,"page":28,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-cf346c53f51a6619":{"sources":[{"id":"7e08d48104c1f6ea","label":"天舟十号货运飞船发射成功（5 月 11 日）","topic":"重要科技成就","category":"时政","text":"考点六 天舟十号货运飞船发射成功（5 月 11 日）\n5 月 11 日 8 时 14 分，长征七号运载火箭托举天舟十号货运飞船在文昌航天发射场成功发射，\n随后成功对接于空间站天和核心舱后向端口。天舟十号是世界现役货物运输能力最大、在轨支\n持能力最全面的货运飞船，计划在轨停靠时间长达 12 个月，将创造该系列飞船在轨驻留时间\n新纪录；首次携带“人工胚胎”进入太空，开展空间环境下人类“人工胚胎”的构建与发育研\n究。","source":{"doc":"4e539a366dce19555ccf","first":29,"last":29,"page":29,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-803380c5a10ffd2f":{"sources":[{"id":"62276a0f5cb36d4c","label":"神舟二十三号载人飞船发射（5 月 24 日）","topic":"重要科技成就","category":"时政","text":"考点七 神舟二十三号载人飞船发射（5 月 24 日）\n5 月 24 日 23 时 08 分，神舟二十三号载人飞船在酒泉发射，是空间站应用与发展阶段第 7 次\n载人飞行任务、载人航天工程第 40 次飞行任务。乘组由朱杨柱（指令长，飞行工程师）、张\n志远（航天驾驶员）、黎家盈（载荷专家）组成，涵盖我国现役 3 种航天员类型；黎家盈是首\n位来自中国香港特别行政区的航天员，入选前在香港特区政府警务处工作。5 月 25 日与神舟\n二十一号乘组完成中国航天史上第 8 次“太空会师”，“天宫”首次有香港航天员进驻。任务\n计划安排 1 名航天员执行 1 年期在轨驻留试验，将实施我国首个太空人体研究计划。","source":{"doc":"4e539a366dce19555ccf","first":29,"last":29,"page":29,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-47bdde1e2a61faad":{"sources":[{"id":"44eeb0150d7f9d8c","label":"长征十号乙运载火箭全球首次网系回收成功（7 月 10 日）","topic":"重要科技成就","category":"时政","text":"考点八 长征十号乙运载火箭全球首次网系回收成功（7 月 10 日）\n2026 年 7 月 10 日 12 时 15 分，长征十号乙运载火箭在海南商业航天发射场发射升空，将卫星\n顺利送入预定轨道；火箭一二级分离约 6 分钟后，一子级垂直返回，在海上“领航者号”回收\n船上通过网系捕获方式成功回收。此次任务是我国首次成功实施运载火箭一子级可控回收，同\n时也是全球首次运载火箭网系回收，标志着我国在重复使用火箭技术领域取得历史性突破。任\n务成功突破复杂力热环境适应性、高精度导航控制、海上平台网系捕获回收等关键核心技术，\n长征十号乙运载火箭成为我国首型成功实施回收的重复使用运载火箭，将为加快提升我国进出\n空间能力奠定坚实基础。","source":{"doc":"4e539a366dce19555ccf","first":29,"last":29,"page":29,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-deb80f088a3b0901":{"sources":[{"id":"a2efc3ca50247ad5","label":"平陆运河正式通航（9 月 16 日）","topic":"重要科技成就","category":"时政","text":"考点九 平陆运河正式通航（9 月 16 日）\n考点：9 月 16 日，新中国成立以来第一条国家层面统筹建设的通江达海运河工程——平陆运\n河正式通航。平陆运河是广西境内沟通珠江流域西江与北部湾的运河，全长 134.2 公里，按内\n河Ⅰ级航道建设，可通航 5000 吨级船舶。平陆运河有四项“世界之最”：世界同类运河通航\n能力最强、世界同类船闸通航速度最快、世界省水船闸落差最高、世界内河省水船闸规模最\n大。","source":{"doc":"4e539a366dce19555ccf","first":29,"last":29,"page":29,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-de3d67299864cf01":{"sources":[{"id":"1460c4653eca4036","label":"“星算”计划 02 组算力卫星发射成功（10 月 14 日）","topic":"重要科技成就","category":"时政","text":"考点十 “星算”计划 02 组算力卫星发射成功（10 月 14 日）\n10 月 14 日，国星宇航“星算”计划 02 组星座的 8 颗卫星由朱雀二号改进型火箭成功发射并\n完成首次组网。这是由我国商业航天公司联合国内 100 余所高校、科研院所等共同建设的全球\n首个太空计算星座；随着 8 颗卫星入轨，整个“星算”星座在轨总算力达到 50P，标志着我国\n太空算力基础设施从“单点验证”迈入“规模化部署”新阶段。","source":{"doc":"4e539a366dce19555ccf","first":29,"last":30,"page":29,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-7c5a5dbe7667dd2a":{"sources":[{"id":"b41c0d05250aa0ec","label":"我国“人造太阳”EAST 装置迎来建成运行 20 周年（9 月 28 日）","topic":"重要科技成就","category":"时政","text":"考点十一 我国“人造太阳”EAST 装置迎来建成运行 20 周年（9 月 28 日）\n2026 年 9 月 28 日，我国“人造太阳”EAST 装置迎来建成运行 20 周年。EAST 是我国自主设\n计、研制的世界首个全超导非圆截面托卡马克核聚变实验装置。2006 年 9 月 28 日，“人造太\n阳”EAST 首次成功放电，获得电流 200 千安、持续时间接近 3 秒的高温等离子体。","source":{"doc":"4e539a366dce19555ccf","first":30,"last":30,"page":30,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-a74be79a48188b75":{"sources":[{"id":"01fc438f2792500c","label":"建党 105 周年","topic":"重要周年","category":"时政","text":"考点一 建党 105 周年\n2026 年是中国共产党成立 105 周年。1921 年中共一大召开，中国共产党应运而生。2026 年同\n时是“十五五”开局之年，中央纪委五次全会公报、政治局常委会会议均强调做好建党 105 周\n年各项工作。党的二十届四中全会部署的“十五五”规划目标任务，是党领导人民接续奋斗、\n以中国式现代化全面推进强国建设民族复兴伟业的接续篇章。\n时间   1921 年 7 月 23 日至 31 日\n地点   上海，大会最后一天转移到浙江嘉兴南湖\n13 名代表+2 名共产国际代表，陈独秀和李大钊因事务繁忙未出席会议\n13 名代表：李达、李汉俊（上海）；张国焘、刘仁静（北京）；毛泽东、何叔衡（长\n参会\n沙）；董必武、陈潭秋（武汉）；王尽美、邓恩铭（济南）；陈公博（广州）；周佛海\n人物\n（旅日）。包惠僧（广州）受陈独秀派遣，出席了会议。\n2 名共产国际代表：马林、尼克尔斯基。\n党的名称为“中国共产党”（最早由蔡和森提出）\n党的性质是无产阶级政党\n确定\n主要            党的奋斗目标是社会主义和共产主义\n内容            党在当前的任务是组织工人阶级，开展工人运动\n选举       陈独秀为书记，张国焘为组织主任，李达为宣传主任\n通过       党的第一个纲领和党的工作决议\n历史\n党的一大的召开标志着中国共产党的成立\n意义","source":{"doc":"4e539a366dce19555ccf","first":30,"last":30,"page":30,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-b8af4010ed07dd07":{"sources":[{"id":"23256f8f5ea85206","label":"中国航天创建 70 周年","topic":"重要周年","category":"时政","text":"考点二 中国航天创建 70 周年\n1956 年中国航天事业创建（国防部第五研究院成立，钱学森任院长），2026 年恰逢 70 周年。\n70 年来，中国航天从无到有、从小到大，在载人航天、深空探测、卫星导航等领域取得举世\n瞩目的成就，2025 年全年航天发射 92 次创历史新高，天问二号执行首次小行星探测采样返回\n任务，中国正由航天大国向航天强国迈进。","source":{"doc":"4e539a366dce19555ccf","first":31,"last":31,"page":31,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-d5063bbaa3885bf1":{"sources":[{"id":"6c75816c52084720","label":"红军长征胜利 90 周年","topic":"重要周年","category":"时政","text":"考点三 红军长征胜利 90 周年\n1936 年 10 月，红军三大主力在甘肃会宁胜利会师，长征胜利结束。2026 年是红军长征胜利\n90 周年。长征是一次理想信念的伟大远征，铸就了伟大长征精神。纪念长征胜利 90 周年，对\n于传承红色基因、赓续红色血脉，弘扬伟大长征精神，走好新时代长征路具有重大意义。\n路线：江西瑞金——渡过于都河——挺进湘西——冲破四道封锁线——改向贵州——渡过乌\n江——夺取遵义——四渡赤水——巧渡金沙江——强渡大渡河、飞夺泸定桥——翻雪山——过\n草地——翻越六盘山——到达陕北吴起镇——甘肃会宁——将台堡会师","source":{"doc":"4e539a366dce19555ccf","first":31,"last":31,"page":31,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-f56f624c235c40f4":{"sources":[{"id":"529aeaf3e0f44e25","label":"美国独立 250 周年","topic":"重要周年","category":"时政","text":"考点四 美国独立 250 周年\n1776 年 7 月 4 日《独立宣言》发表，标志美利坚合众国诞生，2026 年是美国独立 250 周年。","source":{"doc":"4e539a366dce19555ccf","first":31,"last":31,"page":31,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-266405f85825eda0":{"sources":[{"id":"220f311b9b119b74","label":"长江经济带发展战略实施十周年","topic":"重要周年","category":"时政","text":"考点五 长江经济带发展战略实施十周年\n2026 年是长江经济带发展战略实施十周年。长江经济带覆盖上海、江苏、浙江、安徽、江\n西、湖北、湖南、重庆、四川、云南、贵州 11 个省市，发展战略核心要求为“共抓大保护，\n不搞大开发”，坚持生态优先、绿色发展，是推动区域协调发展的重要国家战略。","source":{"doc":"4e539a366dce19555ccf","first":31,"last":31,"page":31,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-ef9c43bd7005fd84":{"sources":[{"id":"586513138ed673ef","label":"中美“乒乓外交”55 周年","topic":"重要周年","category":"时政","text":"考点六 中美“乒乓外交”55 周年\n55 年前，中美老一辈领导人以卓越的政治智慧和战略远见，重新开启两国人民友好往来的大\n门，成就了“小球转动大球”的历史佳话。“乒乓外交”指 1971 年中美两国乒乓球队互访的\n一系列事件；1972 年 2 月 28 日中美签署《上海公报》，1979 年 1 月 1 日《中美建交公报》生\n效、中美正式建交。一个中国原则是中美关系的政治基础。","source":{"doc":"4e539a366dce19555ccf","first":31,"last":31,"page":31,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-97adc493336088fb":{"sources":[{"id":"240b7ce9b8ce5d5c","label":"第 18 个全国防灾减灾日","topic":"重要周年","category":"时政","text":"考点七 第 18 个全国防灾减灾日\n2026 年 5 月 12 日是第 18 个全国防灾减灾日，主题是“人人讲安全、个个会应急——提高防\n灾减灾救灾能力”，全国防灾减灾日暨防灾减灾宣传周主场活动在江西省南昌市举行。强调公\n共安全坚持安全第一、预防为主，事前预防是完善公共安全治理体制的首要环节。","source":{"doc":"4e539a366dce19555ccf","first":31,"last":31,"page":31,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-6742eb7a853b707f":{"sources":[{"id":"61ef15ecd8867982","label":"东西部协作开展 30 周年","topic":"重要周年","category":"时政","text":"考点八 东西部协作开展 30 周年\n2026 年是东西部协作开展 30 周年。30 年来，东西部协作在助力脱贫攻坚、促进区域协调发展\n等方面发挥了重要作用，彰显了我们党的政治优势和我国社会主义制度的优越性。当前协作转\n入常态化帮扶新阶段，2026 年是开展常态化帮扶第一年。","source":{"doc":"4e539a366dce19555ccf","first":31,"last":31,"page":31,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-fe365d2c1219ed48":{"sources":[{"id":"49fef520449c8e64","label":"辛亥革命 115 周年、孙中山先生诞辰 160 周年","topic":"重要周年","category":"时政","text":"考点十 辛亥革命 115 周年、孙中山先生诞辰 160 周年\n2026 年是辛亥革命 115 周年、孙中山先生诞辰 160 周年。","source":{"doc":"4e539a366dce19555ccf","first":32,"last":32,"page":32,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-ef6d010fb34efc58":{"sources":[{"id":"4cff6b03289e95d8","label":"辛亥革命的历史影响","topic":"历史常识","category":"非时政","text":"1911 年辛亥革命爆发，推翻了清王\n朝统治，结束了在中国延续两千多年的君主专制制度，是中华民族伟大复兴征程上的一座里程\n碑。","source":{"doc":"4e539a366dce19555ccf","first":32,"last":32,"page":32,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编中的史实"}]},"k-f785705d8f4454b3":{"sources":[{"id":"75dfa27b32266bff","label":"台湾光复 81 周年（10 月 25 日）","topic":"重要周年","category":"时政","text":"考点十一 台湾光复 81 周年（10 月 25 日）\n2026 年 10 月 25 日是台湾光复 81 周年，也是国家设立台湾光复纪念日一周年。","source":{"doc":"4e539a366dce19555ccf","first":32,"last":32,"page":32,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"k-73b07c7587f51cd1":{"sources":[{"id":"56eb3c6aec7cfe6b","label":"台湾光复与台北受降典礼","topic":"历史常识","category":"非时政","text":"1945 年 10 月\n25 日，中国战区台湾省受降典礼在台北举行，台湾及澎湖列岛正式重归中国主权管辖之下，\n结束了台湾被日本殖民统治 50 年的历史。","source":{"doc":"4e539a366dce19555ccf","first":32,"last":32,"page":32,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编中的史实"}]},"k-5b29da432731d85c":{"sources":[{"id":"763ab0bec449c368","label":"社会主义的产生和发展 · 科学社会主义的创立","topic":"科学社会主义","category":"非时政","text":"二、科学社会主义的创立\n马克思和恩格斯在新的历史条件下创立了唯物史观和剩余价值学说，揭示了人类历史发\n展的奥秘和资本主义剥削的秘密，论证了无产阶级的历史使命，把争取无产阶级和全人类解\n放的斗争建立在社会发展客观规律的基础上，从而超越了空想社会主义，创立了科学社会主\n义。\n1848 年 2 月，《共产党宣言》的发表标志着科学社会主义的产生。","source":{"doc":"3ccc56f4000d1642c2d1","first":11,"last":11,"page":11,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-2a0c6aa1ae74cc31":{"sources":[{"id":"96042e2e2eb458e7","label":"地位、形成与发展","topic":"新时代中国特色社会主义思想","category":"非时政","text":"习近平新时代中国特色社会主义思想是当代中国马克思主义、二十一世纪马克思主义，\n是中华文化和中国精神的时代精华，实现了马克思主义中国化新的飞跃。习近平同志是习近\n平新时代中国特色社会主义思想的主要创立者。\n党的十九大把习近平新时代中国特色社会主义思想确立为我们党必须长期坚持的指导\n思想，并在党章中把习近平新时代中国特色社会主义思想确立为党的行动指南，将这一思想\n的核心内容概括为“八个明确”“十四个坚持”。\n党的十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》，\n用“十个明确”对习近平新时代中国特色社会主义思想的核心内容作了进一步概括，并从十\n三个方面分领域总结成就、概括原创性理念和思想，提出“两个确立”重要论断：确立习近\n平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地\n位。\n党的十九大、十九届六中全会提出的“十个明确”、“十四个坚持”、\n“十三个方面成就”\n概括了习近平新时代中国特色社会主义思想的主要内容。\n党的二十大提出“六个必须坚持”\n，概括阐述了习近平新时代中国特色社会主义思想的\n世界观、方法论和贯穿其中的立场观点方法。","source":{"doc":"3ccc56f4000d1642c2d1","first":14,"last":14,"page":14,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-2b3ccd01344a6ba7":{"sources":[{"id":"6fea1f813857cf3a","label":"年度政府工作","topic":"年度政府工作","category":"时政","text":"2026 政府工作报告\n2026 年 3 月 5 日上午 9 时，十四届全国人大四次会议在人民大会堂开幕，国务院总理\n李强作政府工作报告。政府工作报告摘登如下：","source":{"doc":"6cbfb01fe723bba64b75","first":2,"last":2,"page":2,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-7b04cef3fd55b9f0":{"sources":[{"id":"06937d4c1a3da02c","label":"纪念中国人民抗日战争暨世界反法西斯战争胜利 80 周年大会","topic":"年度政府工作","category":"时政","text":"1.纪念中国人民抗日战争暨世界反法西斯战争胜利 80 周年大会\n2025 年 9 月 3 日，纪念中国人民抗日战争暨世界反法西斯战争胜利 80 周年大会在京隆\n重举行，天安门广场举行盛大阅兵仪式，习近平发表重要讲话并检阅受阅部队。习近平强调，\n隆重纪念中国人民抗日战争暨世界反法西斯战争胜利 80 周年，目的是铭记历史、缅怀先烈、\n珍爱和平、开创未来。中华民族是不畏强暴、自立自强的伟大民族。中国人民解放军始终是\n党和人民完全可以信赖的英雄部队。要坚定不移走中国特色社会主义道路，传承和弘扬伟大\n抗战精神，踔厉奋发、勇毅前行。中华民族伟大复兴势不可挡！人类和平与发展的崇高事业\n必将胜利！\n——新华社","source":{"doc":"6cbfb01fe723bba64b75","first":2,"last":2,"page":2,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-6e45edac07f2aa25":{"sources":[{"id":"e7aa7e5cadd713b7","label":"台湾光复纪念日","topic":"年度政府工作","category":"时政","text":"2.台湾光复纪念日\n2025 年 10 月 24 日，十四届全国人大常委会第十八次会议经表决，通过了关于设立台\n湾光复纪念日的决定，以法律形式将 10 月 25 日设立为台湾光复纪念日，并规定国家通过多\n种形式举行纪念活动。\n——新华社","source":{"doc":"6cbfb01fe723bba64b75","first":2,"last":2,"page":2,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-4b3c135664acff90":{"sources":[{"id":"673b944789a70a1d","label":"学前一年免费教育政策","topic":"年度政府工作","category":"时政","text":"3.学前一年免费教育政策\n从 2025 年秋季学期起，免除公办幼儿园学前一年在园儿童保育教育费。对在教育部门\n批准设立的民办幼儿园就读的适龄儿童，参照当地同类型公办幼儿园免除水平，相应减免保\n育教育费。财政部、教育部将统筹考虑学龄人口变化、财力状况等因素，研究适时完善免费\n学前教育政策。西藏，四川、云南、甘肃、青海四省涉藏州县，新疆喀什、和田、阿克苏、\n克孜勒苏柯尔克孜四地州等地区在园儿童继续执行现行政策。\n——《国务院办公厅关于逐步推行免费学前教育的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":3,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a47a55eaf2f233b8":{"sources":[{"id":"f598e0ba75191fb2","label":"天问二号","topic":"年度政府工作","category":"时政","text":"1.天问二号\n2025 年 5 月 29 日 1 时 31 分，天问二号探测器由长征三号乙运载火箭在中国西昌卫星\n发射中心发射，发射任务取得圆满成功。我国首次小行星探测与采样返回之旅正式开启。\n天问二号主要任务目标是对小行星 2016HO3 进行探测、取样并返回地球，预计于 2027 年底\n着陆地球并完成回收。此后再对主带彗星 311P 开展科学探测。\n——央视网","source":{"doc":"6cbfb01fe723bba64b75","first":4,"last":4,"page":4,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-7f06b39a6043667a":{"sources":[{"id":"b5c199f54f8c4d89","label":"雅下水电工程","topic":"年度政府工作","category":"时政","text":"2.雅下水电工程\n2025 年 7 月 19 日上午，雅鲁藏布江下游水电工程开工仪式在西藏自治区林芝市举行。\n中共中央政治局常委、国务院总理李强出席开工仪式，并宣布工程正式开工。\n雅鲁藏布江下游水电工程位于西藏自治区林芝市。工程主要采取截弯取直、隧洞引水\n的开发方式，建设 5 座梯级电站，总投资约 1.2 万亿元。工程电力以外送消纳为主，兼顾西\n藏本地自用需求。\n——新华社","source":{"doc":"6cbfb01fe723bba64b75","first":4,"last":4,"page":4,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-fba8928332a85276":{"sources":[{"id":"33e1922b729069ea","label":"福建舰","topic":"年度政府工作","category":"时政","text":"3.福建舰\n2025 年 11 月 5 日，我国第一艘电磁弹射型航空母舰福建舰入列授旗仪式在海南三亚某\n军港举行。中共中央总书记、国家主席、中央军委主席习近平出席入列授旗仪式并登舰视察。\n福建舰是我国第一艘电磁弹射型航空母舰，也是我国第三艘航空母舰，舷号为“18”，\n2022 年 6 月下水命名。福建舰由我国完全自主设计建造，其电磁弹射技术处于世界先进水\n平。\n——新华社","source":{"doc":"6cbfb01fe723bba64b75","first":4,"last":4,"page":4,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-73b65dde591877d1":{"sources":[{"id":"afa2441ef44cd933","label":"国产大模型引领全球开源生态","topic":"年度政府工作","category":"时政","text":"4.国产大模型引领全球开源生态\n工业和信息化部信息显示，“十四五”期间，中国人工智能企业数量和产业规模持续增\n长，创新成果不断涌现。DeepSeek、通义千问等国产大模型引领全球开源创新生态，AI 手\n机、AI 眼镜等终端产品加速普及，行业专用大模型落地应用取得初步成效。\n——人民网","source":{"doc":"6cbfb01fe723bba64b75","first":4,"last":4,"page":4,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-5d3eada523d78394":{"sources":[{"id":"5086a85ea8f2d943","label":"工作成就","topic":"年度政府工作","category":"时政","text":"过去一年取得的成绩来之不易。我们面对的是多年少有的外部冲击挑战和国内两难多难\n问题交织叠加的复杂严峻形势。国际经贸环境急剧变化，单边主义、保护主义陡然升级，市\n场预期受到频繁扰动，对外贸易明显承压。国内经济深刻转型，深层次结构性矛盾问题持\n续显现，消费、投资增长动力不足。以习近平同志为核心的党中央带领我们沉着应对、勇\n毅前行，对外有理有力有效开展经贸斗争，坚定维护我国利益，中美 5 轮经贸磋商取得积极\n成果，两国元首釜山会晤达成重要共识，为经贸合作注入更多稳定性；对内打好政策“组合\n拳”，加强宏观政策逆周期调节①，着力稳就业、稳企业、稳市场、稳预期，集中力量办好\n自己的事。我们从最坏处打算，向最好处努力，不仅稳住了宏观经济大盘，推动高质量发展\n取得新成效，而且极大提振了全社会的士气和信心。在这个过程中，我们进一步认识到，做\n好新形势下经济工作必须充分挖掘经济潜能、必须坚持政策支持和改革创新并举、必须做\n到既“放得活”又“管得好”②、必须坚持投资于物和投资于人紧密结合③、必须以苦练内\n功来应对外部挑战。实践再次证明，坚持党中央集中统一领导是应对一切困难、做好各项工\n作的根本保证，中国人民有信心有智慧有力量战胜一切艰难险阻！","source":{"doc":"6cbfb01fe723bba64b75","first":4,"last":5,"page":4,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"dfb757aaca693d35","label":"工作成就","topic":"年度政府工作","category":"时政","text":"一年来，我国经济顶压前行、展现强大韧性。经济运行总体平稳、稳中有进，国内生产\n总值①增长 5%，总量达到 140.19 万亿元。就业总体稳定，城镇新增就业 1267 万人，城镇调\n查失业率②平均为 5.2%。对外贸易较快增长，出口多元化成效明显，国际收支基本平衡。民\n生保障更加有力，居民收入增长和经济增长同步，脱贫攻坚成果巩固拓展，实施学前一年\n免费教育政策③、惠及 1400 万儿童，全面实施育儿补贴制度④、惠及 3000 多万婴幼儿。粮食\n产量达到 1.43 万亿斤。重点领域风险化解取得积极进展，社会大局保持稳定。","source":{"doc":"6cbfb01fe723bba64b75","first":2,"last":3,"page":2,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"10b3ba48665a42f2","label":"工作成就","topic":"年度政府工作","category":"时政","text":"一年来，我国发展向新向优、彰显蓬勃活力。新质生产力稳步发展，科技创新成果丰硕，\n人工智能、生物医药、机器人、量子科技等研发应用走在世界前列，芯片自主研发有了新突\n破，天问二号①开启“追星”之旅，北斗规模应用全面拓展，雅下水电工程②开工建设，首艘\n国产电磁弹射型航母福建舰③正式入列，国产大模型④引领全球开源生态。产业结构持续优化，\n高技术制造业、装备制造业增加值分别增长 9.4%、9.2%，工业机器人、集成电路产量分别\n增长 28%、10.9%，新能源汽车年产量超过 1600 万辆，电动汽车充电设施突破 2000 万个。\n单位国内生产总值能耗降低 5.1%，生态环境质量持续改善。","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":4,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"5fae0af5c3d9fb8d","label":"工作成就","topic":"年度政府工作","category":"时政","text":"（一）工作成就\n2025 年是很不平凡的一年。党的二十届四中全会胜利召开，擘画了未来五年我国发展\n的宏伟蓝图。我们隆重纪念中国人民抗日战争暨世界反法西斯战争胜利 80 周年①，设立台\n湾光复纪念日②，极大振奋民族精神、激发爱国热情、凝聚奋斗力量。面对国内外形势深刻\n复杂的变化，以习近平同志为核心的党中央团结带领全国各族人民迎难而上、奋力拼搏，坚\n定不移贯彻新发展理念、推动高质量发展，统筹国内国际两个大局，全年经济社会发展主要\n目标任务顺利完成，“十四五”圆满收官，中国式现代化迈出新的坚实步伐。","source":{"doc":"6cbfb01fe723bba64b75","first":2,"last":2,"page":2,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-24f809924fbb1604":{"sources":[{"id":"e5316b59c18f28c9","label":"“人工智能+”行动","topic":"年度政府工作","category":"时政","text":"“人工智能+”行动\n2025 年 8 月 26 日，《关于深入实施“人工智能+”行动的意见》（以下简称《意见》）\n正式对外发布，这也是我国首部 AI 领域的纲领性文件，首次提出了“人工智能+”6 大行动。\n“人工智能+”6 大行动包括+科学技术、+产业发展、+消费提质、+民生福祉、+治理能\n力、+全球合作，这 6 大重点领域面向科学家、工程师、企业员工、消费者、政府部门、全\n球伙伴等各类主体，涵盖各行各业。\n《意见》指出，到 2027 年，率先实现人工智能与 6 大重点领域广泛深度融合，新一代\n智能终端、智能体等应用普及率超 70%，智能经济核心产业规模快速增长，人工智能在公共\n治理中的作用明显增强，人工智能开放合作体系不断完善。到 2030 年，我国人工智能全面\n赋能高质量发展，新一代智能终端、智能体等应用普及率超 90%，智能经济成为我国经济发\n展的重要增长极，推动技术普惠和成果共享。到 2035 年，我国全面步入智能经济和智能社\n会发展新阶段，为基本实现社会主义现代化提供有力支撑。\n——《国务院关于深入实施“人工智能+”行动的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":7,"last":7,"page":7,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-2dd879cdcaced5ff":{"sources":[{"id":"a89c1e9df6ffda2f","label":"海南自由贸易港启动全岛封关运作","topic":"年度政府工作","category":"时政","text":"5.海南自由贸易港启动全岛封关运作\n全岛封关运作是海南自贸港建设的标志性工程，是进一步扩大开放的重要举措。封关是\n指将海南岛全岛建成一个海关监管特殊区域，实施以“‘一线’放开、‘二线’管住、岛\n内自由”为基本特征的自由化便利化政策制度。\n“‘一线’放开”，是将海南自贸港与我国关境外其他国家和地区之间作为“一线”，\n实施一系列自由便利进出举措；“‘二线’管住”，是将海南自贸港与内地之间作为“二线”，\n针对“一线”放开的内容实施精准管理；“岛内自由”，是在海南自贸港内，各类要素可以\n相对自由流通。\n——中国政府网","source":{"doc":"6cbfb01fe723bba64b75","first":8,"last":9,"page":8,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-ee609bfb489f4069":{"sources":[{"id":"24f01d3f17f9f72f","label":"巩固拓展脱贫攻坚成果同乡村振兴有效衔接","topic":"农业与城乡治理","category":"非时政","text":"2.巩固拓展脱贫攻坚成果同乡村振兴有效衔接\n巩固拓展脱贫攻坚成果同全面推进乡村振兴有效衔接，是激发脱贫地区内生发展动力\n的根本途径与持久之策。巩固拓展脱贫攻坚成果，其工作重心之一就是从过去的“输血”为\n主，转向更加注重培育“造血”功能。通过发展壮大特色优势产业、加强职业技能培训、提\n升人力资本、完善基层治理体系等方式，全面提升脱贫地区和脱贫群众的自我发展能力，引\n导他们用自己的辛勤劳动创造美好生活，从而实现从“要我脱贫”到“我要振兴”的深刻转\n变，为乡村振兴注入最深厚、最持久的力量。\n——中国共产党新闻网","source":{"doc":"6cbfb01fe723bba64b75","first":9,"last":10,"page":9,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-acb7ce8d9f5ee80b":{"sources":[{"id":"f7180001d080372c","label":"第九届亚洲冬季运动会","topic":"年度政府工作","category":"时政","text":"4.第九届亚洲冬季运动会\n2025 年 2 月 7 日晚，第九届亚洲冬季运动会在黑龙江省哈尔滨市隆重开幕。习近平等\n党和国家领导人出席开幕式。\n本届亚冬会是继北京冬奥会后我国举办的又一重大综合性国际冰雪运动盛会，也是继\n1996 年哈尔滨亚冬会和 2007 年长春亚冬会后我国第三次举办亚冬会。\n——央视网","source":{"doc":"6cbfb01fe723bba64b75","first":11,"last":11,"page":11,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-3a7e94131d347c7f":{"sources":[{"id":"685874e2d67578d5","label":"第十五届全国运动会","topic":"年度政府工作","category":"时政","text":"5.第十五届全国运动会\n2025 年 11 月 9 日晚，中华人民共和国第十五届运动会在广东省广州市隆重开幕。中共\n中央总书记、国家主席、中央军委主席习近平出席开幕式并宣布运动会开幕。这是首次由粤\n港澳三地联合举办的全国运动会。\n十五运会主题口号为“激情全运会，活力大湾区”，残特奥会主题口号为“追梦大湾\n区，出彩人生路”。\n十五运会和残特奥会吉祥物以国家一级保护野生动物、“海上国宝”中华白海豚为原型，\n分别取名“喜洋洋”和“乐融融”，寓意喜气洋洋、其乐融融、团圆和美。\n——新华社","source":{"doc":"6cbfb01fe723bba64b75","first":11,"last":12,"page":11,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-37efce8112b63bb4":{"sources":[{"id":"b8e11131c5836c17","label":"工作举措","topic":"年度政府工作","category":"时政","text":"一年来，加快美丽中国建设，推动绿色低碳发展。\n扎实开展大气污染防治提质增效行动，地级及以上城市细颗粒物（PM2.5）平均浓度下\n降 4.4%。持续加强大江大河和重要湖库保护，地表水水质优良断面比例提高到 91.4%。启动\n实施美丽中国先行区建设。加快重点行业绿色低碳转型。第一批“沙戈荒”新能源基地项目\n基本建成投产，新型储能装机规模超过 1.3 亿千瓦，非化石能源消费占比达到 21.7%。宣布\n应对气候变化 2035 年国家自主贡献目标，充分展现负责任大国担当。","source":{"doc":"6cbfb01fe723bba64b75","first":12,"last":12,"page":12,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"97c13a7510bc24ef","label":"工作举措","topic":"年度政府工作","category":"时政","text":"一年来，持续加强政府建设，创新和完善社会治理。\n贯彻落实党中央全面从严治党战略部署，扎实开展深入贯彻中央八项规定精神学习教育，\n加强党风廉政建设和反腐败斗争，大力整治形式主义为基层减负。深入推进法治政府建设，\n提请全国人大常委会审议法律议案 13 件，制定修订行政法规 30 部。自觉依法接受监督。认\n真办理人大代表议案、建议和政协委员提案。开展规范涉企行政执法专项行动。健全“高效\n办成一件事”重点事项常态化推进机制。开展推动高质量发展综合督查。加强城乡基层治理。\n做好新就业群体服务管理。提升信访工作法治化水平。持续推进安全生产治本攻坚三年行动，\n生产安全事故总起数下降 8.7%。有效应对部分地区洪涝、干旱、台风、地震等自然灾害。\n全力维护国家安全和社会稳定，积极预防、依法打击各类违法犯罪活动，平安中国建设取得\n新进展。","source":{"doc":"6cbfb01fe723bba64b75","first":12,"last":12,"page":12,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"eefe8cc300b9a4a1","label":"工作举措","topic":"年度政府工作","category":"时政","text":"一年来，进一步深化改革开放，畅通国民经济循环。\n扎实落实党的二十届三中全会改革部署。实施全国统一大市场建设①指引，出台新版市\n场准入负面清单②，系统整治招标投标、招商引资领域突出问题，推进重点行业产能治理，\n综合整治“内卷式”竞争③成效显现。开展要素市场化配置综合改革试点。国有企业改革深\n化提升行动取得积极成效，出台进一步促进民间投资发展的措施。加快加力清理拖欠企业账\n款。有序推进自主开放、单边开放，稳步扩大单方面免签或全面互免签证。加大稳外贸力度，\n进出口量稳质升，出口增长 6.1%。出台稳外资行动方案，新设外资企业数量增长 19.1%。实\n施自由贸易试验区提升战略④，海南自由贸易港启动全岛封关运作⑤。扎实推进高质量共建\n“一带一路”，各领域务实合作水平不断提升。","source":{"doc":"6cbfb01fe723bba64b75","first":7,"last":7,"page":7,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"e8380e5bee03d914","label":"工作举措","topic":"年度政府工作","category":"时政","text":"一年来，统筹推进新型城镇化和乡村全面振兴，促进城乡区域协调发展。\n贯彻中央城市工作会议部署，培育发展现代化都市圈①，加强城市规划建设治理，持续\n实施城市更新，落实好农业转移人口市民化政策，开展新型城镇化试点，常住人口城镇化率\n达到 67.9%。着力稳面积、提单产、抗灾害，再夺粮食丰收。扎实做好巩固拓展脱贫攻坚成\n果同乡村振兴有效衔接，脱贫人口务工就业规模稳定在 3000 万人以上。加大区域战略实施\n力度，区域联动发展水平不断提升。","source":{"doc":"6cbfb01fe723bba64b75","first":9,"last":9,"page":9,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"cefe4ea61e4e601e","label":"工作举措","topic":"年度政府工作","category":"时政","text":"（二）工作举措\n一年来，实施更加积极有为的宏观政策，着力稳定经济运行。\n年初我们就做好了应对复杂多变局面的充分准备，一季度经济起势有力、开局良好。二\n季度以后，针对经济运行中的新情况特别是美国加征关税冲击，充分发挥存量政策作用，加\n力推出稳就业稳经济等一系列新举措，有力对冲了经济下行压力，保障了全年主要目标实现。\n实施更加积极的财政政策和适度宽松的货币政策，扩大财政支出规模，加强重点领域财力\n保障，下调政策利率和存款准备金率①，持续降低社会综合融资成本。加力扩围实施消费品\n以旧换新②，带动商品销售额超过 2.6 万亿元，文旅体等服务消费潜力加快释放，社会消费\n品零售总额突破 50 万亿元。围绕扩大有效投资，加强“两重”项目③建设，加快设备更新资\n金拨付使用，设备购置投资增长 11.8%，设立新型政策性金融工具补充重点项目资本金。持\n续用力稳楼市，合理控制新增房地产用地供应，因城施策调减限制性措施，下调个人住房公\n积金贷款利率，“保交房”任务全面完成。综合施策稳股市，资本市场回稳回暖、交易活跃。\n深入实施一揽子化债方案，有序置换地方政府存量隐性债务，持续压减融资平台数量，地方\n债务结构不断优化。一体推进地方中小金融机构风险处置和转型发展，高风险机构数量大幅\n下降，风险化解成效明显。","source":{"doc":"6cbfb01fe723bba64b75","first":5,"last":6,"page":5,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"b0b546aadbae426a","label":"工作举措","topic":"年度政府工作","category":"时政","text":"一年来，切实抓好民生保障，积极发展社会事业。\n出台稳就业支持政策，开展大规模职业技能提升培训行动，重点群体就业保持稳定。推\n进教育强国建设三年行动计划，推动高校学科专业调整，加强县域普通高中建设。实施医疗\n卫生强基工程①。完善儿科和精神卫生服务体系，全国二三级公立综合医院儿科服务实现全\n覆盖。有效防控基孔肯雅热等传染病疫情。健全基本医保参保长效机制，优化医药集采措施，\n推出商业健康保险创新药目录，长期护理保险制度覆盖 3 亿人。渐进式延迟法定退休年龄②\n改革稳妥实施。城乡居民基础养老金月最低标准提高 20 元，在全国实施个人养老金制度③，\n开展养老服务消费补贴试点。持续推进社会救助扩围增效，加强重度残疾人托养照护，完善\n困境儿童福利保障措施。提高优抚标准。发展文化事业和文化产业，旅游业活力显现，国内\n出游人次增长 16.2%，入境旅游人次增长 17.1%。成功举办第九届亚洲冬季运动会④、第十五\n届全国运动会⑤，群众体育赛事和全民健身活动蓬勃开展。","source":{"doc":"6cbfb01fe723bba64b75","first":10,"last":10,"page":10,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"b6280c2fa76b39a8","label":"工作举措","topic":"年度政府工作","category":"时政","text":"一年来，坚持创新驱动发展，建设现代化产业体系。\n全面推进科技强国建设战略部署，强化国家战略科技力量建设，完善区域科技创新体系，\n加强基础前沿领域体系化布局和关键核心技术攻关。全社会研发经费投入强度达到 2.8%，\n技术合同成交额增长 10.8%。科技创新和产业创新融合加快，传统产业转型升级不断深入，\n新兴产业、未来产业蓬勃发展，现代服务业保持快速发展势头。聚焦重点领域制定修订 583\n项国家标准。持续推进制造业数字化转型和“人工智能+”行动，行业应用加快落地，新型\n智能终端不断涌现。数据要素潜力加快释放，数字经济核心产业增加值占国内生产总值的比\n重提高到 10.5%以上。","source":{"doc":"6cbfb01fe723bba64b75","first":6,"last":7,"page":6,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"177eab7d2aa587b9","label":"工作举措","topic":"年度政府工作","category":"时政","text":"过去一年，中国特色大国外交取得新成效。\n习近平主席等党和国家领导人出访多国，出席中国－中亚峰会、亚太经合组织领导人非\n正式会议、金砖国家领导人线上峰会、二十国集团领导人峰会等重大多双边活动。成功举办\n上海合作组织天津峰会、全球妇女峰会、中拉论坛第四届部长级会议等重大主场外交活动。\n坚决反对保护主义和单边霸凌行径，坚定维护多边主义和开放合作，坚定捍卫二战胜利成果，\n提出全球治理倡议，推动构建人类命运共同体，在应对全球性挑战和解决国际地区热点问题\n中发挥积极建设性作用。中国为促进世界和平与发展作出了重要贡献。","source":{"doc":"6cbfb01fe723bba64b75","first":13,"last":13,"page":13,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-093f295fb9a01792":{"sources":[{"id":"9435ea99da8190a1","label":"“十四五”时期经济社会发展成就","topic":"年度政府工作","category":"时政","text":"二、“十四五”时期经济社会发展成就\n2025 年是“十四五”收官之年。过去 5 年，以习近平同志为核心的党中央团结带领全\n国各族人民，有效应对世纪疫情等超乎寻常的冲击挑战，推动党和国家事业取得新的重大成\n就，第二个百年奋斗目标新征程实现良好开局。\n经济总量实现新跃升，国内生产总值连续跨越 110 万亿元、120 万亿元、130 万亿元、\n140 万亿元台阶，年均增长 5.4%、明显高于全球平均增速。科技和产业创新取得新突破，全\n社会研发经费投入年均增长 10%，每万人口高价值发明专利拥有量达到 16 件，攻克一批重\n大关键核心技术，制造业增加值规模连续 16 年保持全球第一，产业链供应链韧性和安全水\n平稳步提升。改革开放迈出新步伐，重点领域改革扎实推进，全国统一大市场加快构建，高\n水平对外开放不断扩大，制造业领域外资准入限制措施全部取消，货物贸易第一大国地位更\n加巩固，高质量共建“一带一路”走深走实。民生福祉达到新水平，居民人均可支配收入年\n均增长 5.4%，城镇新增就业累计超过 6000 万人，巩固拓展脱贫攻坚成果同乡村振兴有效衔\n接 5 年过渡期任务圆满完成，脱贫地区农村居民收入增速持续高于全国农村平均水平，基本\n养老保险全国统筹稳步实施，劳动年龄人口平均受教育年限增加到 11.3 年，人均预期寿命\n提高到 79.25 岁，人民群众文化生活更加丰富多彩。生态文明建设取得新进步，地级及以上\n城市空气质量优良天数比例提高到 89.3%，森林覆盖率提高到 25%以上，成为全球森林资源\n增长最快最多的国家，构建起全球最大、发展最快的可再生能源体系。安全保障能力实现\n新提升，粮食、能源资源、金融、网络等重点领域安全能力建设明显加强，社会大局保持稳\n定，牢牢守住了不发生系统性风险底线。经过艰苦奋斗、不懈努力，“十四五”规划《纲要》\n确定的 20 项主要指标、17 方面重大战略任务、102 项重大工程项目胜利完成。\n这些重大成就的取得，根本在于以习近平同志为核心的党中央领航掌舵，在于习近平新\n时代中国特色社会主义思想科学指引，是全党全军全国各族人民团结奋斗的结果。\n在肯定成绩的同时，我们也清醒看到面临的困难和挑战。外部环境变化影响加深，地缘\n政治风险持续上升，世界经济动能疲弱，多边主义、自由贸易受到严重冲击。国内经济发展\n和转型中面临的老问题、新挑战仍然不少。困难不容忽视，信心必须坚定。我国经济长期向\n好的支撑条件和基本趋势没有改变，制度优势和大国优势不断彰显。经历了风雨洗礼，我\n们的意志更加坚强、步伐更加坚定，只要用足用好优势、妥善应对挑战，我国的发展前景一\n定更加可期！","source":{"doc":"6cbfb01fe723bba64b75","first":14,"last":14,"page":14,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-f38beac81da3b4df":{"sources":[{"id":"0033129db5806c2b","label":"“十五五”时期主要目标和重大任务","topic":"年度政府工作","category":"时政","text":"三、“十五五”时期主要目标和重大任务\n根据《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》①，国务院编\n制了《中华人民共和国国民经济和社会发展第十五个五年规划纲要（草案）》，提交大会审\n查。这里就主要目标指标、重大战略任务、重大工程项目作简要报告。","source":{"doc":"6cbfb01fe723bba64b75","first":14,"last":14,"page":14,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-82c3c9b511d97127":{"sources":[{"id":"5d14fac1ca2aecb9","label":"《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》","topic":"年度政府工作","category":"时政","text":"1.《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》\n五年规划，全称为中华人民共和国国民经济和社会发展五年规划纲要，是中国国民经济\n计划的重要部分。主要是对国家重大建设项目、生产力分布和国民经济重要比例关系等作出\n规划，为国民经济发展远景规定目标和方向。\n“十五五”规划，从 2026—2030 年，围绕以中国式现代化全面推进强国建设、民族复\n兴伟业。","source":{"doc":"6cbfb01fe723bba64b75","first":15,"last":15,"page":15,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-887d09ee4855eb15":{"sources":[{"id":"1f607c14071800c9","label":"主要目标指标","topic":"年度政府工作","category":"时政","text":"（一）主要目标指标\n贯彻落实党中央《建议》明确的主要目标，《纲要（草案）》细化提出 20 项主要指标。\n经济发展方面，围绕增长、结构、效率提出 3 项指标。其中，综合考虑国内外形势和各方面\n因素，兼顾需要与可能，提出国内生产总值增长保持在合理区间、各年度视情提出，为到\n2035 年人均国内生产总值比 2020 年翻一番、达到中等发达国家水平打好基础。创新驱动方\n面，围绕创新投入及其成效提出 3 项指标。其中，充分考虑研发投入增长趋势和企业投入能\n力，提出全社会研发经费投入①年均增长 7%以上，与“十四五”规划目标保持一致，确保研\n发投入力度不减。民生福祉方面，为更好解决人民群众急难愁盼问题，针对性提出就业、收\n入、教育、医疗、健康、“一老一小”等 7 项指标。绿色低碳方面，围绕降碳减污、生态环\n保等提出 5 项指标。其中，根据国家自主贡献目标②，提出单位国内生产总值二氧化碳排放\n累计降低 17%，继续推动重点领域绿色低碳转型。安全保障方面，围绕粮食、能源生产能力\n提出 2 项指标，着力夯实国家安全重要基础保障。","source":{"doc":"6cbfb01fe723bba64b75","first":15,"last":15,"page":15,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-654e33ef6636a8a6":{"sources":[{"id":"db5cf4ee399bbb83","label":"国家自主贡献目标","topic":"生态环境与能源","category":"非时政","text":"2.国家自主贡献目标\n2025 年 9 月 24 日，中国新一轮国家自主贡献目标发布。我国新一轮国家自主贡献目标\n是，到 2035 年，中国全经济范围温室气体净排放量比峰值下降 7%—10%，力争做得更好。\n非化石能源消费占能源消费总量的比重达到 30%以上，风电和太阳能发电总装机容量达到\n2020 年的 6 倍以上，力争达到 36 亿千瓦，森林蓄积量达到 240 亿立方米以上，新能源汽车\n成为新销售车辆的主流，全国碳排放权交易市场覆盖主要高排放行业，气候适应型社会基本\n建成。","source":{"doc":"6cbfb01fe723bba64b75","first":15,"last":15,"page":15,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-58343549d170437b":{"sources":[{"id":"1143bb02e8e25bae","label":"碳达峰目标","topic":"生态环境与能源","category":"非时政","text":"6.碳达峰目标\n2020 年，我国向世界作出承诺：二氧化碳排放力争于 2030 年前达到峰值，努力争取 2060\n年前实现碳中和。","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":17,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-06be6ba4390f814c":{"sources":[{"id":"12e90c0b38637c9e","label":"重大战略任务","topic":"年度政府工作","category":"时政","text":"二是突出做强国内大循环①。在外部环境复杂严峻的情况下，必须坚持扩大内需这个战\n略基点②。《纲要（草案）》着眼增强国内大循环内生动力和可靠性，坚持惠民生和促消费、\n投资于物和投资于人紧密结合，大力提振消费，促进居民消费率明显提高，扩大有效投资。\n着眼充分释放我国超大规模市场红利，纵深推进全国统一大市场建设，破除地方保护和市\n场分割。着眼增强高质量发展动力，充分激发各类经营主体活力，加快完善要素市场化配置\n体制机制。着眼畅通国内国际双循环，统筹用好全球要素和市场资源。","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":17,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"f5190da3839df905","label":"重大战略任务","topic":"年度政府工作","category":"时政","text":"三是突出推进全体人民共同富裕①。中国式现代化是全体人民共同富裕的现代化②。《纲\n要（草案）》着眼建设生育友好型社会，健全人口服务体系；办好人民满意的教育，劳动\n年龄人口平均受教育年限提高到 11.7 年；加快建设健康中国和体育强国，人均预期寿命提\n高到 80 岁；积极应对人口老龄化，养老机构护理型床位占比提高到 73%；促进高质量充分\n就业，完善收入分配制度③，健全社会保障体系④。着眼缩小区域差距和城乡差别，加快农\n业农村现代化，持续巩固拓展脱贫攻坚成果，优化重大生产力布局，深入推进以人为本的新\n型城镇化。着眼促进人民精神生活共同富裕，弘扬和践行社会主义核心价值观⑤，大力繁荣\n文化事业，加快发展文化产业，提升中华文明传播力影响力。","source":{"doc":"6cbfb01fe723bba64b75","first":18,"last":18,"page":18,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"7beaf32bdc2cab80","label":"重大战略任务","topic":"年度政府工作","category":"时政","text":"四是突出统筹发展和安全。安全是发展的前提，发展是安全的保障。《纲要（草案）》\n贯彻总体国家安全观①，着眼推进国家安全体系和能力现代化提出多项任务举措。增强粮食、\n能源资源等供给保障能力，粮食综合生产能力②达到 1.45 万亿斤左右，能源综合生产能力③\n达到 58 亿吨标准煤。统筹推进房地产、地方政府债务、地方中小金融机构等风险有序化解。\n提高公共安全治理水平，有效维护社会安全稳定。","source":{"doc":"6cbfb01fe723bba64b75","first":19,"last":19,"page":19,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"b2f01ec486c36c42","label":"重大战略任务","topic":"年度政府工作","category":"时政","text":"（二）重大战略任务\n《纲要（草案）》分领域阐述了“十五五”发展的重大战略任务，突出体现四个方面。\n一是突出推动高质量发展。发展新质生产力①是高质量发展的内在要求。《纲要（草案）》\n强调科技创新的引领作用，着眼巩固壮大实体经济②根基，构建以先进制造业为骨干的现代\n化产业体系③。着眼高水平科技自立自强④，加强原始创新和关键核心技术攻关，深入推进\n数字中国建设⑤，数字经济核心产业增加值占国内生产总值比重达到 12.5%。着眼建设美丽\n中国，持续深入推进污染防治攻坚和生态系统优化，加快形成绿色生产生活方式，确保碳\n达峰目标⑥如期实现。","source":{"doc":"6cbfb01fe723bba64b75","first":16,"last":16,"page":16,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-04042cf9b8329482":{"sources":[{"id":"0accb4e58892471a","label":"扩大内需这个战略基点 · 年度进展或目标","topic":"年度政府工作","category":"时政","text":"2025 年人均国内生产总值约 1.4 万美元，是全球第二大消费市场、第一大网络零售市场，\n拥有全球规模最大的中等收入群体且规模在持续扩大，处于消费持续升级阶段，具有全梯度、\n多元化的需求结构。国内超大规模市场潜能若得到有效激发，不但能成为全球优质商品、服\n务、技术的“引力场”，而且能以国内需求为导向，推动我国产业链供应链从“世界工厂”\n向“世界市场+创新高地”升级，在全球分工中掌握主动权，塑造长期国际竞争力。","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":18,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-b7753c6601e5bab7":{"sources":[{"id":"0ec4b35ee5891b6c","label":"重大工程项目","topic":"年度政府工作","category":"时政","text":"（三）重大工程项目\n围绕推动“十五五”目标任务落实落地，统筹考虑战略性、牵引性和连续性，《纲要（草\n案）》提出 6 方面 109 项重大工程。引领新质生产力发展方面，围绕产业基础能力和竞争力\n提升、新产业新赛道①培育发展、前沿科技攻关、创新基础能力提升提出 28 项工程。构建现\n代化基础设施体系方面，围绕国家综合立体交通网、新型能源体系②、新型基础设施③、对\n外开放平台等提出 23 项工程。促进城乡融合发展方面，围绕新型城镇化建设、农业农村现\n代化建设提出 9 项工程。保障和改善民生方面，围绕社会主义文化繁荣发展、高质量教育体\n系建设、健康中国建设、优化“一老一小”服务、社会关爱服务提出 25 项工程。推动绿色\n低碳转型方面，围绕碳达峰碳中和、环境质量提升、生态保护修复提出 18 项工程。重点领\n域安全保障方面，围绕粮食、能源安全等提出 6 项工程。这些重大工程兼顾当前和长远，既\n涉及“硬投资”④也包含“软建设”⑤。我们将注重以政府投资带动社会力量参与，更好发挥\n重大工程项目强基础、补短板、增后劲等重要作用。\n展望未来，我们充满信心。在以习近平同志为核心的党中央坚强领导下，全国上下团结\n奋斗，一定能够把“十五五”宏伟蓝图变成美好现实。","source":{"doc":"6cbfb01fe723bba64b75","first":20,"last":20,"page":20,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-635a61276555a56b":{"sources":[{"id":"a2ac53289746886e","label":"2026 年经济社会发展总体要求和政策取向","topic":"年度政府工作","category":"时政","text":"四、2026 年经济社会发展总体要求和政策取向\n今年是“十五五”开局之年。做好政府工作，要在以习近平同志为核心的党中央坚强领\n导下，以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全\n会精神，认真落实党的二十届四中全会和中央经济工作会议部署，完整准确全面贯彻新发展\n理念①，加快构建新发展格局，着力推动高质量发展，坚持稳中求进工作总基调，统筹国内\n国际两个大局，更好统筹发展和安全，实施更加积极有为的宏观政策，增强政策前瞻性针\n对性协同性，持续扩大内需、优化供给，做优增量、盘活存量，因地制宜发展新质生产力，\n纵深推进全国统一大市场建设，持续防范化解重点领域风险，着力稳就业、稳企业、稳市\n场、稳预期，推动经济实现质的有效提升和量的合理增长，保持社会和谐稳定，实现“十\n五五”良好开局。","source":{"doc":"6cbfb01fe723bba64b75","first":21,"last":21,"page":21,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-8b937d0610a6cb2f":{"sources":[{"id":"79f1d712beb5a242","label":"预期目标","topic":"年度政府工作","category":"时政","text":"（一）预期目标\n今年发展主要预期目标是：经济增长 4.5%－5%①，在实际工作中努力争取更好结果；城\n镇调查失业率 5.5%左右，城镇新增就业 1200 万人以上；居民消费价格涨幅 2%左右；居民\n收入增长和经济增长同步；国际收支基本平衡；粮食产量 1.4 万亿斤左右；单位国内生产\n总值二氧化碳排放降低 3.8%左右。\n提出这些预期目标，主要考虑是开局之年为调结构、防风险、促改革留出空间，为后期\n更好发展打牢基础。经济增长目标同 2035 年远景目标总体衔接，与我国经济长期增长潜力\n基本吻合，实现这个目标具备有利条件，各地区要结合实际，通过扎实工作争取好的结果。\n城镇调查失业率 5.5%左右，体现了在就业总量和结构性压力较大的情况下，坚持就业优先\n政策导向和加大稳就业力度的要求。居民消费价格涨幅 2%左右，考虑了预期引导和现实可\n能，我们将通过改善总供求关系，推动价格总水平由负转正、消费价格合理温和回升，促进\n经济良性循环。单位国内生产总值二氧化碳排放降低 3.8%左右②，综合考虑了经济社会发展、\n绿色低碳转型和国家能源安全等多种需要，有利于有序实现 2030 年前碳达峰目标。","source":{"doc":"6cbfb01fe723bba64b75","first":21,"last":22,"page":21,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-d924519807fd012a":{"sources":[{"id":"fa16e6adf85d1b87","label":"经济增长 4.5%－5%","topic":"年度政府工作","category":"时政","text":"1.经济增长 4.5%－5%\n2016 年，我国将经济增速目标设定为 6.5%—7%，2019 年，则是 6%—6.5%，两年实际分\n别增长 6.8%和 6.1%。今年，预期目标再次以区间形式提出，可谓统筹考虑了国际国内形势，\n兼顾了发展的需要和可能，体现了实事求是、因势利导的思路。","source":{"doc":"6cbfb01fe723bba64b75","first":22,"last":22,"page":22,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-328057d54791293e":{"sources":[{"id":"11edea88f659f2b4","label":"单位国内生产总值二氧化碳排放降低 3.8%左右","topic":"年度政府工作","category":"时政","text":"2.单位国内生产总值二氧化碳排放降低 3.8%左右\n2026 年是“十五五”开局之年，也是我国从能耗双控全面转向碳排放双控的第一年。\n今年的政府工作报告提出，“单位国内生产总值二氧化碳排放降低 3.8%左右”，这一指标\n综合考虑了经济社会发展、绿色低碳转型和国家能源安全等多种需要，有利于有序实现 2030\n年前碳达峰目标。","source":{"doc":"6cbfb01fe723bba64b75","first":22,"last":22,"page":22,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a4829692a35f3760":{"sources":[{"id":"60ba137d1c26f2ea","label":"政策取向","topic":"年度政府工作","category":"时政","text":"（二）政策取向\n我们将坚持稳中求进、提质增效，发挥存量政策和增量政策集成效应，加大逆周期和\n跨周期调节力度，切实提升宏观经济治理效能。\n继续实施更加积极的财政政策①。今年赤字率②拟按 4%左右安排，赤字规模 5.89 万亿元、\n比上年增加 2300 亿元。一般公共预算支出③规模将首次达到 30 万亿元、比上年增加约 1.27\n万亿元。拟发行超长期特别国债④1.3 万亿元，持续支持“两重”建设、“两新”⑤工作等。\n拟发行特别国债 3000 亿元，支持国有大型商业银行补充资本。拟安排地方政府专项债券 4.4\n万亿元，完善专项债券项目负面清单管理和自审自发试点，重点支持建设重大项目、置换隐\n性债务、消化政府拖欠账款等。今年财政支出继续保持相当规模，要持续用力优化支出结构，\n更加注重支持提振消费、投资于人、保障民生等方面，提高财政资金使用效益。中央财政增\n加对地方财力性转移支付规模，开展整合统筹使用转移支付资金试点，增强地方自主财力和\n统筹能力。压实分级保障主体责任，兜牢基层“三保”⑥底线。各级政府要更好“当家理财”，\n建立健全增收节支机制，积极盘活利用存量资源资产，严肃财经纪律，强化预算约束，严控\n一般性支出，坚决落实过紧日子的要求，务必把省下来的每一分钱都用到发展的关键点、群\n众的急需处。\n继续实施适度宽松的货币政策⑦。把促进经济稳定增长、物价合理回升作为货币政策的\n重要考量，灵活高效运用降准降息等多种政策工具，保持流动性充裕，使社会融资规模、\n货币供应量增长同经济增长、价格总水平预期目标相匹配。优化创新结构性货币政策工具⑧，\n适当增加规模，完善实施方式。畅通货币政策传导机制，充分发挥数据要素、知识产权等无\n形资产作用，强化考核评估、融资担保、风险补偿等支持措施，引导金融机构加力支持扩大\n内需、科技创新、中小微企业等重点领域。规范信贷市场经营行为，降低融资中间费用，促\n进社会综合融资成本低位运行。保持人民币汇率在合理均衡水平上的基本稳定。\n强化改革举措与宏观政策协同。推动高质量发展，既要政策给力，也要改革发力。要\n用改革的办法打通经济循环的卡点堵点，将政策效果转化为经济内生增长动能。增强宏观政\n策取向一致性和有效性，将各类经济政策和非经济政策、存量政策和增量政策纳入宏观政策\n取向一致性评估，使各类政策措施同向发力、形成合力。加强财政、金融、就业、产业等\n政策协同，深入挖掘政策结合点，创新实施工具，持续放大“组合拳”效应。健全预期管理\n机制，提振社会信心。","source":{"doc":"6cbfb01fe723bba64b75","first":22,"last":23,"page":22,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-6f56499ef0661e64":{"sources":[{"id":"e4f3cd1bc70e9deb","label":"着力建设强大国内市场","topic":"年度政府工作","category":"时政","text":"（一）着力建设强大国内市场。坚持内需主导，统筹促消费和扩投资，拓展内需增长\n新空间，更好发挥我国超大规模市场优势。\n深入实施提振消费专项行动。激发居民消费内生动力和促消费政策并举，推动消费持\n续增长。制定实施城乡居民增收计划，在促进低收入群体增收、增加居民财产性收入、完善\n薪酬和社保制度等方面推出一批务实举措。促进商品消费扩容升级，安排超长期特别国债\n2500 亿元支持消费品以旧换新，优化政策实施机制。设立 1000 亿元财政金融协同促内需专\n项资金，组合运用贷款贴息、融资担保、风险补偿等方式，支持扩大内需。扩大个人消费贷\n款和服务业经营主体贷款贴息政策支持领域，提高贴息上限，延长实施期限。实施好一次性\n信用修复政策。实施服务消费提质惠民行动，打造一批带动面广、显示度高的消费新场景，\n加快培育消费新增长点。活跃线下消费，激发下沉市场消费活力。清理消费领域不合理限制\n措施，释放文旅、赛事、康养等领域消费潜力。支持有条件的地方推广中小学春秋假，落实\n职工带薪错峰休假制度。加强消费者权益保护。优化入境消费环境，打造“购在中国”品牌。\n充分挖掘释放有效投资潜力。聚焦新质生产力、新型城镇化、人的全面发展等重点领\n域，增强市场主导的有效投资增长动力，提高民生类政府投资比重。今年拟安排中央预算\n内投资 7550 亿元，安排 8000 亿元超长期特别国债资金用于“两重”建设，分类提高中央投\n资补助标准。单列并提高用于项目建设的地方政府专项债券额度，继续向投资项目准备充分、\n资金用得好的地方倾斜。发行新型政策性金融工具 8000 亿元，带动更多社会资本参与投资。\n统筹用好各类政府投资资金，支持工作基础较好的地方探索编制全口径政府投资计划，加强\n项目资金监管，坚决防止低效无效投资。落实促进民间投资的政策措施，完善民营企业参与\n重大项目建设长效机制，引导民间投资向高技术、现代服务业等新赛道拓展，有效激发民间\n投资活力。","source":{"doc":"6cbfb01fe723bba64b75","first":24,"last":25,"page":24,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-61cf9b0cc6cc75cd":{"sources":[{"id":"63c9502fca3ed409","label":"加紧培育壮大新动能","topic":"年度政府工作","category":"时政","text":"（二）加紧培育壮大新动能。坚持把发展经济的着力点放在实体经济上，因地制宜发\n展新质生产力，建设现代化产业体系。\n优化提升传统产业①。持续推进重点产业提质升级，新部署一批重大技术改造升级项目，\n安排 2000 亿元超长期特别国债资金支持大规模设备更新。实施新一轮制造业重点产业链高\n质量发展行动，强化产业基础再造和重大技术装备攻关，打造一批国家先进制造业集群。推\n行普惠性“上云用数赋智”服务，持续加大对中小企业数智化转型的支持。拓展智能制造，\n新建设一批智能工厂和智慧供应链。发展智能建造，培育现代化建筑产业链。加快推进标准\n升级，强化质量监督和品牌建设，支持企业提供更加优质、更具特色的产品。\n培育壮大新兴产业和未来产业②。实施产业创新工程，鼓励央企国企带头开放应用场景，\n打造集成电路、航空航天、生物医药、低空经济等新兴支柱产业。建立未来产业投入增长和\n风险分担机制，培育发展未来能源、量子科技、具身智能、脑机接口、6G 等未来产业。构\n建促进专精特新中小企业发展壮大机制，培育独角兽企业。高效用好国家创业投资引导基金，\n大力发展创业投资、天使投资，政府投资基金要带头做耐心资本，推动更多初创企业加快成\n长为科技领军企业。\n扩能提质服务业③。深化先进制造业和现代服务业融合发展试点。壮大科技服务市场，\n促进软件服务价值提升。发展金融、现代物流、知识产权、检验检测等生产性服务业。促进\n生活性服务业高品质、多样化、便利化发展。有序放宽服务业准入限制，扩大重点领域服务\n业投资。健全服务业国家标准，培育“中国服务”品牌。\n打造智能经济新形态④。深化拓展“人工智能+”，促进新一代智能终端和智能体加快推\n广，推动重点行业领域人工智能商业化规模化应用，培育智能原生新业态新模式。支持人工\n智能开源社区建设，促进开源生态繁荣。实施超大规模智算集群、算电协同等新基建工程，\n加强全国一体化算力监测调度，支持公共云发展。加快发展卫星互联网。打造“5G+工业互\n联网”升级版。深化数据资源开发利用，健全数据要素基础制度，建设高质量数据集。完善\n人工智能治理。","source":{"doc":"6cbfb01fe723bba64b75","first":25,"last":25,"page":25,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-ff2d3ed676546887":{"sources":[{"id":"d98c241fc257c148","label":"打造智能经济新形态","topic":"年度政府工作","category":"时政","text":"4.打造智能经济新形态\n“打造智能经济新形态”是政府工作报告中首次出现这一提法。“打造智能经济新形态”\n其实就是要抓住人工智能发展的机遇，拓展人工智能赋能千行百业的广度和深度，尽快打开\n经济增长的新空间，培育新模式、壮大新动能。","source":{"doc":"6cbfb01fe723bba64b75","first":26,"last":26,"page":26,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-00edc606be0cf511":{"sources":[{"id":"631a95845c110053","label":"新一轮“双一流”","topic":"年度政府工作","category":"时政","text":"1.新一轮“双一流”\n“新一轮双一流”指的是中国高等教育领域“世界一流大学和一流学科建设”战略的\n第三轮建设周期（（2026-2030 年）），于 2026 年正式启动，其核心目标是引导高校分类\n发展、特色突围，并深度融入国家现代化发展大局，以更好地服务高质量发展需求。","source":{"doc":"6cbfb01fe723bba64b75","first":27,"last":28,"page":27,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-ad19d603dcec7278":{"sources":[{"id":"0e5498750afcb675","label":"推进全国统一大市场建设 · 年度进展或目标","topic":"年度政府工作","category":"时政","text":"2025 年 7 月 1 日，习近平总书记主持召开中央财经委员会第六次会议时强调：纵深推\n进全国统一大市场建设，基本要求是“五统一、一开放”。","source":{"doc":"6cbfb01fe723bba64b75","first":28,"last":28,"page":28,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-b54d6423dea9ed3f":{"sources":[{"id":"f2253c827a3214c4","label":"“内卷式”竞争 · 年度进展或目标","topic":"年度政府工作","category":"时政","text":"2025 年 3 月 5 日，中共中央总书记、国家主席、中央军委主席习近平强调，要深化要素市\n场化配置改革，主动破除地方保护、市场分割和“内卷式”竞争。","source":{"doc":"6cbfb01fe723bba64b75","first":28,"last":28,"page":28,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-39dd0a8ce74c7700":{"sources":[{"id":"b9701ba6ba0ed64a","label":"持续深化重点领域改革","topic":"年度政府工作","category":"时政","text":"充分激发各类经营主体活力。坚持和落实“两个毫不动摇”①。制定和实施进一步深化\n国资国企改革方案，推进国有经济布局优化和结构调整。完善民营经济②促进法配套法规政\n策，从法律和制度上保障平等使用生产要素、公平参与市场竞争、有效保护合法权益。完\n善中国特色现代企业制度③。大力弘扬企业家精神④，促进年轻一代企业家健康成长。推动\n平台企业和平台内经营者、劳动者共赢发展。分型分类精准帮扶个体工商户发展。下更大力\n气解决拖欠企业账款问题。持续打造一流营商环境，更好支持企业安心经营、高质量发展。","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":29,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"90a77577d89da6a9","label":"持续深化重点领域改革","topic":"年度政府工作","category":"时政","text":"（四）持续深化重点领域改革。围绕构建高水平社会主义市场经济体制①，强化改革攻\n坚，深入破除体制机制障碍，增强高质量发展动力活力。\n纵深推进全国统一大市场建设②。制定全国统一大市场建设条例。完善统计、财税、考\n核等制度，规范地方政府经济促进行为，出台地方政府招商引资鼓励和禁止事项清单，规范\n税收优惠、财政补贴政策。深化招标投标体制机制改革。加强反垄断、反不正当竞争，强化\n公平竞争审查刚性约束，综合运用产能调控、标准引领、价格执法、质量监管等手段，深入\n整治“内卷式”竞争③，营造良好市场生态。深化要素市场化配置综合改革试点，将更多符\n合条件的地区纳入试点范围。稳步推进公用事业和公共服务价格改革。","source":{"doc":"6cbfb01fe723bba64b75","first":28,"last":28,"page":28,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"caf62967f18664d2","label":"持续深化重点领域改革","topic":"年度政府工作","category":"时政","text":"推进财税金融体制改革。加大财政资源和预算统筹力度，提高国有资本①收益收取比例。\n加强财政科学管理，深化零基预算②改革，进一步扩大中央部门试点范围。健全地方税体系，\n拓展地方税源。调整优化消费税征税范围、税率，并推进部分品目征收环节后移。规范金融\n机构竞争秩序，深入推进地方中小金融机构减量提质。持续深化资本市场投融资综合改革，\n进一步健全中长期资金入市机制，完善投资者保护制度，拓展私募股权和创投基金退出渠道，\n提高直接融资、股权融资比重。","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":29,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-36811b35d8283113":{"sources":[{"id":"06aed25bc42bd572","label":"进一步扩大高水平对外开放","topic":"年度政府工作","category":"时政","text":"（五）进一步扩大高水平对外开放。坚持合作共赢，稳步扩大制度型开放①，拓展国际\n循环，以开放促改革促发展。\n积极扩大自主开放。以服务业为重点扩大市场准入和开放领域，进一步扩大增值电信、\n生物技术、外商独资医院等领域开放试点，有序扩大数字领域开放，压减跨境服务贸易负面\n清单。建好国家服务业扩大开放综合示范区②。推动商签更多区域和双边贸易投资协定，积\n极推动加入《数字经济伙伴关系协定》③和《全面与进步跨太平洋伙伴关系协定》④进程。\n全面深入参与世贸组织改革，维护和发展开放型世界经济。优化自由贸易试验区布局范围、\n提升创新引领发展能级，扎实推进海南自由贸易港建设。","source":{"doc":"6cbfb01fe723bba64b75","first":30,"last":30,"page":30,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"4b893777b13e9171","label":"进一步扩大高水平对外开放","topic":"年度政府工作","category":"时政","text":"推动外贸稳规模优结构。加大信贷、信保支持，扩大人民币跨境使用。引导企业优化全\n球市场布局，推进贸易投资一体化、内外贸一体化发展。培育壮大贸易发展新动能，推动\n跨境电商加海外仓模式扩容升级、规范有序发展，加强国际寄递物流体系建设，拓展中间品\n贸易，发展数字贸易①、绿色贸易②，提升边境贸易。鼓励支持服务出口。积极扩大进口，推\n进贸易平衡发展。提高跨境贸易便利化水平。","source":{"doc":"6cbfb01fe723bba64b75","first":31,"last":31,"page":31,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"dc13420c0f2035be","label":"进一步扩大高水平对外开放","topic":"年度政府工作","category":"时政","text":"扩大双向投资合作。深化外商投资促进体制机制改革，保障外资企业国民待遇，实施新\n版鼓励外商投资产业目录，促进外资境内再投资、扩大本地化生产。加强对外资企业的服务\n保障，擦亮“投资中国”名片。规范提升各类开发区、园区。引导产业链供应链合理有序跨\n境布局，完善海外综合服务体系，加强对外投资风险防控和海外利益保护。\n高质量共建“一带一路”①。加强与共建国家战略对接，做实做细“硬联通”、“软联\n通”、“心联通”②。统筹推进重大标志性工程和“小而美”民生项目③建设。提升中欧中\n亚班列发展水平，加快西部陆海新通道④建设。深入推进“智慧海关”合作伙伴计划⑤。拓\n展新兴领域务实合作，让合作成果更多惠及各国人民。","source":{"doc":"6cbfb01fe723bba64b75","first":32,"last":32,"page":32,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-d240277350dbcd44":{"sources":[{"id":"722c90cc9025a0d8","label":"“智慧海关”合作伙伴计划","topic":"年度政府工作","category":"时政","text":"5.“智慧海关”合作伙伴计划\n智慧海关合作伙伴计划是中国海关推动的国际合作计划，于 2023 年 8 月由习近平主席\n在“金砖”领导人对话会上宣布实施。其核心内容是推动“智慧海关（旨在通过数字化手段\n提升海关国际合作效率）、智能边境、智享联通”（三智）合作。","source":{"doc":"6cbfb01fe723bba64b75","first":33,"last":33,"page":33,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-27c282c2d8eb38ad":{"sources":[{"id":"bf7a6fc1b16026c6","label":"种业振兴行动","topic":"年度政府工作","category":"时政","text":"6.种业振兴行动\n农业种质资源是国家战略性资源，事关种业振兴全局。习近平总书记曾生动指出种地选\n好种的重要性，强调“农业现代化，种子是基础，必须把民族种业搞上去，把种源安全提升\n到关系国家安全的战略高度”。\n2021 年 7 月 9 日，中央全面深化改革委员会第二十次会议审议通过《种业振兴行动方\n案》，强调要把种源安全提升到关系国家安全的战略高度，集中力量破难题、补短板、强优\n势、控风险，实现种业科技自立自强、种源自主可控。","source":{"doc":"6cbfb01fe723bba64b75","first":34,"last":34,"page":34,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-0565b75e74d2a2a9":{"sources":[{"id":"b380da2bf8353e74","label":"扎实推进乡村全面振兴","topic":"年度政府工作","category":"时政","text":"持续推进农村改革发展。全面开展第二轮土地承包到期后再延长 30 年整省试点①，发\n展农业适度规模经营，健全现代农业经营体系和社会化服务体系②。支持发展新型农村集体\n经济③。深化集体产权、集体林权、农垦、供销社等改革。开展第四次全国农业普查④。推动\n城乡要素双向流动，深化农文旅等融合发展，培育壮大乡村特色产业，提高农产品精深加工\n水平，发展林下经济，完善联农带农机制，促进农民稳定增收。发展壮大乡村人才队伍。深\n化农村移风易俗，提升乡村治理和文明乡风建设水平。持续整治提升农村人居环境，以钉\n钉子精神⑤解决好农村改厕、垃圾围村等问题。扎实推进全域土地综合整治。完善乡村建设\n实施机制，加快补齐农村现代生活条件短板，推进宜居宜业和美乡村建设。","source":{"doc":"6cbfb01fe723bba64b75","first":35,"last":35,"page":35,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"e1c73e651b4ca724","label":"扎实推进乡村全面振兴","topic":"年度政府工作","category":"时政","text":"（六）扎实推进乡村全面振兴。坚持把“三农”①工作作为重中之重，深入学习运用“千\n万工程”②经验，提高强农惠农富农政策效能，进一步夯实农业农村基础、提升发展质效。\n毫不放松抓好粮食生产。坚持产量产能、生产生态、增产增收一起抓，加力实施新一\n轮千亿斤粮食产能提升行动。稳定粮油生产，促进良田良种良机良法集成增效，推动大面积\n单产提高、品种培优、品质提升。巩固提升大豆油料产能，推动棉糖胶等稳产提质。坚持农\n林牧渔并举，增加多元食物供给③。严守耕地红线④，严格占补平衡管理，高质量推进高标\n准农田⑤建设，加强黑土地保护和盐碱地综合利用。制定促进农业保险发展的措施。提高农\n业综合防灾减灾能力。深入实施种业振兴⑥行动，加快选育推广突破性品种，推进先进适用\n农机装备研发应用，打通农业科技推广“最后一公里”。统筹生产、收储等政策，促进粮食\n等重要农产品价格保持在合理水平，实施粮食产销区省际横向利益补偿，调动主产区和农民\n种粮积极性。各地区都要扛稳责任，共同端牢中国人的饭碗。","source":{"doc":"6cbfb01fe723bba64b75","first":33,"last":33,"page":33,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"c982988738a573a2","label":"扎实推进乡村全面振兴","topic":"年度政府工作","category":"时政","text":"实施常态化精准帮扶。持续巩固拓展脱贫攻坚成果，把常态化帮扶纳入乡村振兴战略①\n统筹实施，守牢不发生规模性返贫致贫底线。保持帮扶政策总体稳定。合理确定防止返贫\n致贫对象认定标准，做好监测识别，确保早发现、早干预、早帮扶。提高产业、就业等开发\n式帮扶②实效，发挥社会救助③兜底保障作用。继续做好易地搬迁后续扶持。完善东西部协作、\n定点帮扶、驻村帮扶和消费帮扶等。分层分类帮扶欠发达地区，支持乡村振兴重点帮扶县加\n快发展，增强内生动力。","source":{"doc":"6cbfb01fe723bba64b75","first":34,"last":35,"page":34,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-ace2b8a5bbfb6df8":{"sources":[{"id":"621b170b3396922e","label":"健全现代农业经营体系和社会化服务体系 · 年度进展或目标","topic":"年度政府工作","category":"时政","text":"2025 年 1 月，中共中央、国务院印发的《乡村全面振兴规划（2024——2027 年）》进一步\n提出，“建立健全以农户家庭经营为基础、合作与联合为纽带、社会化服务为支撑的立体\n式复合型现代农业经营体系”。2025 年 4 月，中共中央、国务院印发的《加快建设农业强\n国规划（2024——2035 年）》指出，“全环节完善现代农业经营体系，促进小农户和现代\n农业发展有机衔接”。经营体系强是农业强国的重要标志，是发展现代农业的重要支撑。新\n时代发展农业社会化服务、健全现代农业经营体系是解决“谁来种地、如何种好地”的关键。","source":{"doc":"6cbfb01fe723bba64b75","first":36,"last":36,"page":36,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-f97866c86d170578":{"sources":[{"id":"0d69b0759e55e811","label":"第四次全国农业普查","topic":"年度政府工作","category":"时政","text":"4.第四次全国农业普查\n全国农业普查每 10 年进行一次。\n第四次全国农业普查的对象是在中华人民共和国境内的下列个人和单位：农村住户，包\n括农村农业生产经营户和其他住户；城镇农业生产经营户；农业生产经营单位；村民委员会；\n乡镇人民政府。\n普查的行业范围包括：农作物种植业、林业、畜牧业、渔业和农林牧渔服务业。\n普查的主要内容包括：农业生产条件、粮食和大食物生产情况、农业新质生产力情况、\n乡村发展基本情况、农村居民生活情况等。\n普查的标准时点为 2026 年 12 月 31 日 24 时，时期资料为 2026 年年度资料。","source":{"doc":"6cbfb01fe723bba64b75","first":36,"last":36,"page":36,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-0853e26868da0146":{"sources":[{"id":"a6a30ccd9a48a5fd","label":"推动新型城镇化和区域协调发展","topic":"年度政府工作","category":"时政","text":"不断增强区域发展协调性。优化主体功能区划，引导各地区围绕主体功能定位，更好发\n挥比较优势。扎实推动西部大开发形成新格局、东北全面振兴取得新突破、中部地区加快\n崛起、东部地区加快推进现代化。加强改革攻坚、政策赋能和要素保障，支持经济大省挑大\n梁。支持京津冀、长三角、粤港澳大湾区打造世界级城市群。高标准高质量推进雄安新区\n建设。持续推进长江经济带发展、黄河流域生态保护和高质量发展。提升成渝地区双城经\n济圈发展能级。推动长江中游城市群等加快发展。加强重点城市群协调联动，健全规划统筹、\n产业协作、利益共享等机制，实施国家产业转移发展提升工程，深化跨行政区合作。加大差\n异化政策支持力度，深入推进兴边富民行动，促进革命老区、民族地区、边疆地区、资源\n枯竭城市等振兴发展。加强主要海湾整体规划，做强做优做大海洋产业。","source":{"doc":"6cbfb01fe723bba64b75","first":39,"last":39,"page":39,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"454b69a203423969","label":"推动新型城镇化和区域协调发展","topic":"年度政府工作","category":"时政","text":"（七）推动新型城镇化和区域协调发展。深入实施区域协调发展战略、区域重大战略、\n主体功能区战略和新型城镇化战略①，构建优势互补、高质量发展的区域经济布局和国土空\n间体系。\n深入推进以人为本的新型城镇化。科学有序推进农业转移人口市民化，因地制宜放宽\n在流入地参加中考报名条件，进一步完善“人地钱”挂钩政策②。优化县域基础设施布局和\n公共资源配置，发展县域特色产业，推动县域经济高质量发展。坚持城市内涵式发展③，优\n化现代化城市体系。高质量推进城市更新，稳步实施城镇老旧小区、城中村等改造。盘活利\n用存量土地和闲置房屋设施。加强城市基础设施生命线安全工程建设，提升高层建筑火灾防\n范和救援能力。建设创新型产业社区、商务社区，推动城市治理智慧化精细化④，建设现代\n化人民城市。","source":{"doc":"6cbfb01fe723bba64b75","first":37,"last":37,"page":37,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-23052e028a84b1b3":{"sources":[{"id":"d629cf0f04bc9385","label":"健康优先发展战略 · 年度进展或目标","topic":"年度政府工作","category":"时政","text":"到 2035 年建成健康中国是中共中央作出的一项战略决策，“十五五”是实现这一目标\n的关键时期，必须统筹谋划、加紧推进，力求取得决定性进展。\n——《习近平总书记在看望参加全国政协十四届四次会议的农工党、九三学社、医药卫\n生界、社会福利和社会保障界委员，并参加联组会听取意见和建议时的讲话》","source":{"doc":"6cbfb01fe723bba64b75","first":42,"last":42,"page":42,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-7f49c83d1046a4fa":{"sources":[{"id":"9e5b7459627ab289","label":"居民医保人均财政补助标准提高 24 元","topic":"年度政府工作","category":"时政","text":"3.居民医保人均财政补助标准提高 24 元\n城乡居民基本医疗保险人均财政补助标准再提高 24 元，达到每人每年 724 元。","source":{"doc":"6cbfb01fe723bba64b75","first":42,"last":42,"page":42,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-d8134e255c103c8a":{"sources":[{"id":"dc8df8f946d86e5d","label":"城乡居民基础养老金月最低标准再提高 20 元","topic":"年度政府工作","category":"时政","text":"1.城乡居民基础养老金月最低标准再提高 20 元\n城乡居民基础养老金全国最低标准再提高 20 元，由每月 143 元提高至 163 元。","source":{"doc":"6cbfb01fe723bba64b75","first":43,"last":43,"page":43,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-52ce365008e73bc8":{"sources":[{"id":"87c9e6cc976223bc","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"更好满足人民群众精神文化需求。以社会主义核心价值观①引领文化建设。发展哲学社\n会科学事业，推动新闻出版、广播影视、文学艺术等领域精品创作。加强网络内容建设和管\n理，深化网络综合治理，推进未成年人网络保护。实施公共文化服务提质增效行动，做好公\n共图书馆、博物馆、文化馆等惠民开放，完善全民阅读推广服务体系②，广泛开展群众性文\n化活动，繁荣互联网条件下新大众文艺。发展档案事业。深入实施中华优秀传统文化传承\n发展工程③，完成第四次全国文物普查④，加强文化遗产系统性保护、监管和合理利用。高质\n量发展文化旅游业，丰富文旅体商等融合业态。鼓励更多文化企业和优秀文化产品走向世界，\n增强主流媒体国际传播能力。做好 2026 年亚运会⑤备战参赛工作。加快重塑足球青训体系。\n积极发展赛事经济、冰雪经济、户外运动，建好用好群众身边的运动场地设施，培育更多特\n色群众体育赛事活动。","source":{"doc":"6cbfb01fe723bba64b75","first":43,"last":43,"page":43,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"7ba474934bd98273","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"加强社会保障和服务。城乡居民基础养老金月最低标准再提高 20 元①。完善并落实基\n本养老保险全国统筹制度，扩大失业、工伤保险覆盖面，稳妥有序推进职业伤害保障试点扩\n围，健全社保关系转移接续政策。深入实施积极应对人口老龄化国家战略②，扩大普惠养老\n服务供给，积极发展农村养老服务，实施中度以上失能老年人养老服务消费补贴项目。积极\n开发老年人力资源，制定推进银发经济③高质量发展的措施，完善老年用品产品、养老金融、\n旅居养老等支持政策。实施康复护理扩容提升工程。推行长期护理保险制度。做好独居老人、\n失能失智等困难群体的关爱帮扶。倡导积极婚育观。加强初婚初育家庭住房保障，支持多\n子女家庭改善性住房需求。完善生育保险制度和生育休假制度。深入开展托育服务补助示范\n试点，发展普惠托育和托幼一体化服务。加强残疾预防、康复和托养照护服务，推进养老助\n残资源统筹利用。做好困境儿童关爱服务，保障妇女儿童合法权益。加强军人军属、退役军\n人和其他优抚对象服务保障。建立健全基本殡葬服务制度。分层分类做好社会救助工作，兜\n住兜牢民生底线。","source":{"doc":"6cbfb01fe723bba64b75","first":42,"last":43,"page":42,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"d6508f6770645279","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"强化基本医疗卫生服务。实施健康优先发展战略①，健全健康促进政策制度体系，提升\n爱国卫生运动②成效，强化公共卫生能力。健全医疗、医保、医药协同发展和治理机制，深\n化以公益性为导向的公立医院改革，加强县区、基层医疗机构运行保障。强化薄弱专科建设，\n全方位提升急诊急救、血液保障和应急能力。优化医疗机构功能定位和布局，加强基层用药\n衔接，做实家庭医生签约服务，促进分级诊疗。推进中医药传承创新，促进中西医结合。居\n民医保人均财政补助标准提高 24 元③。健全多层次医疗保障体系，稳步推动基本医疗保险\n省级统筹，优化医药集中采购和价格治理，深化医保支付方式改革，完善结余资金使用政策。\n坚决打击欺诈骗保。加快发展商业健康保险，推动创新药和医疗器械高质量发展，更好满足\n人民群众多元化就医用药需求。","source":{"doc":"6cbfb01fe723bba64b75","first":42,"last":42,"page":42,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"51149344a9fef782","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"推动教育公平与质量提升。实施新时代立德树人工程①，促进思政课堂和社会课堂有效\n融合。适应学龄人口结构变化，推进教育资源布局结构调整。推动基础教育扩优提质，统筹\n义务教育优质均衡发展、学前教育优质普惠发展，完善免费学前教育政策，增加普通高中\n学位供给。持续扩大优质本科教育招生规模。提升职业学校办学能力，建设特色鲜明高职院\n校。办好特殊教育、专门教育，提升终身学习公共服务水平，引导规范民办教育发展。建设\n高素质专业化教师队伍②，加强师德师风建设，强化教师待遇保障。加强体育、美育、劳动\n教育和心理健康教育③，健全学校家庭社会协同育人机制，促进学生身心健康、全面发展。","source":{"doc":"6cbfb01fe723bba64b75","first":41,"last":41,"page":41,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"883805ea74f5491f","label":"更大力度保障和改善民生","topic":"年度政府工作","category":"时政","text":"（八）更大力度保障和改善民生。坚持民生为大，加强普惠性、基础性、兜底性民生\n建设①，努力为人民群众多办实事。\n促进高质量充分就业②。加大各类政策对就业的支持力度，构建就业友好型发展方式③。\n延续实施稳岗返还、社保补贴、专项贷款等阶段性措施，进一步增加以工代赈投资规模。实\n施稳岗扩容提质行动，支持劳动密集型行业企业④稳定岗位，围绕发展新兴产业、未来产业\n培育新职业新岗位，增强服务业带动就业能力。制定高校毕业生等青年就业支持政策，强化\n农民工稳岗帮扶，做好退役军人安置和就业服务，加强困难人员就业援助，出台支持灵活就\n业人员、新就业形态人员参加职工保险的政策。发挥创业担保贷款贴息等政策作用，加强创\n业支持引导。完善适应人工智能技术发展促进就业创业的措施。全面落实农民工工资支付\n保障制度，加强就业歧视治理⑤，坚决维护劳动者合法权益。持续开展大规模职业技能提升\n培训，让更多劳动者拥有一技之长，更好就业增收。","source":{"doc":"6cbfb01fe723bba64b75","first":39,"last":39,"page":39,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-41f4992a40d3796b":{"sources":[{"id":"09d4e80ae5059289","label":"第四次全国文物普查","topic":"年度政府工作","category":"时政","text":"4.第四次全国文物普查\n第四次全国文物普查是国务院于 2023 年 11 月启动的重大国情国力调查，旨在系统掌握\n全国不可移动文物资源现状，建立国家文物总目录。此次普查计划用 3 到 4 年时间逐步推进\n（2023 年 11 月-2026 年 6 月），分三阶段实施，覆盖全国地上、地下、水下不可移动文物，\n重点开展既有文物复查和新发现登记工作。","source":{"doc":"6cbfb01fe723bba64b75","first":45,"last":45,"page":45,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-73b440ee601b5fa6":{"sources":[{"id":"b391318ed9d2dfee","label":"2026 年亚运会","topic":"年度政府工作","category":"时政","text":"5.2026 年亚运会\n2026 年爱知·名古屋亚运会，即第二十届亚洲运动会，将于 2026 年 9 月 19 日至 10 月\n4 日在日本爱知县名古屋市举行，名古屋是继东京、广岛后第三个取得亚运会主办权的日本\n城市。第五届亚洲残疾人运动会将于 2026 年 10 月 18 日至 24 日在该地举行。","source":{"doc":"6cbfb01fe723bba64b75","first":45,"last":45,"page":45,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-2c0ba297ccc21e63":{"sources":[{"id":"b8427c514a3ee369","label":"加快推动全面绿色转型①","topic":"年度政府工作","category":"时政","text":"（九）加快推动全面绿色转型①。以碳达峰碳中和②为牵引，协同推进降碳、减污、扩\n绿、增长，增强绿色发展动能。\n加强生态环境综合治理。深入打好蓝天、碧水、净土保卫战③，制定实施空气质量持续\n改善行动计划，推进县城和农村黑臭水体治理，加强重点行业污染地块风险管控。强化新污\n染物治理，实施固体废物综合治理行动。完善多元化生态补偿机制，拓展生态产品价值实现\n渠道。加强生物多样性保护，实施好长江十年禁渔④。坚持山水林田湖草沙一体化保护和系\n统治理，实施自然保护地整合优化，推进国家公园建设，扎实推进“三北”工程攻坚战⑤，\n让人民群众身边的山更绿、水更清。\n大力发展绿色低碳经济。完善促进绿色低碳发展政策，实施重点行业提质降本降碳行动，\n深入推进零碳园区和工厂建设⑥。设立国家低碳转型基金，培育氢能、绿色燃料等新增长点。\n有力有效管控高耗能高排放项目，加快淘汰落后产能，支持绿色低碳技术装备创新应用。完\n善资源总量管理和全面节约制度，强化再生资源循环利用。\n积极稳妥推进碳达峰碳中和。实施碳排放总量和强度双控制度⑦，完善碳排放统计核算、\n碳足迹管理体系，进一步扩大碳排放权交易市场覆盖范围。制定能源强国建设规划纲要。着\n力构建新型电力系统，加快智能电网建设，发展新型储能，扩大绿电应用。加强化石能源清\n洁高效利用。","source":{"doc":"6cbfb01fe723bba64b75","first":45,"last":45,"page":45,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-21ff91e80c3c1bf2":{"sources":[{"id":"0319ce3f7d6b2cf3","label":"长江十年禁渔","topic":"年度政府工作","category":"时政","text":"4.长江十年禁渔\n长江十年禁渔计划是中国自 2021 年 1 月 1 日起实施的重要生态保护政策，旨在保护长\n江水生生物资源、修复水域生态环境。该计划依据 2019 年 12 月农业农村部发布的《关于长\n江流域重点水域禁捕范围和时间的通告》启动，覆盖长江流域 332 个保护区及干流、支流等\n重点水域，全面禁止生产性捕捞至 2030 年。","source":{"doc":"6cbfb01fe723bba64b75","first":46,"last":46,"page":46,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-e2c5925504cbae0f":{"sources":[{"id":"a2985415f3934ea2","label":"“三北”工程攻坚战","topic":"年度政府工作","category":"时政","text":"5.“三北”工程攻坚战\n（1）“三北”工程：\n三北防护林工程，是我国在三北地区（西北、华北、东北）建设的大型人工林业生态工\n程。“三北”工程规划从 1978 年开始到 2050 年结束，历时 73 年，分三个阶段、八期工程\n进行建设。\n（2）“三北”工程攻坚战\n2021－2030 年是“三北”工程六期工程建设期，是巩固拓展防沙治沙成果的关键期，\n是推动“三北”工程高质量发展的攻坚期。要完整、准确、全面贯彻新发展理念，坚持山水\n林田湖草沙一体化保护和系统治理，以防沙治沙为主攻方向，以筑牢北方生态安全屏障为根\n本目标，因地制宜、因害设防、分类施策，加强统筹协调，突出重点治理，调动各方面积极\n性，力争用 10 年左右时间，打一场“三北”工程攻坚战，把“三北”工程建设成为功能完\n备、牢不可破的北疆绿色长城、生态安全屏障。\n要突出治理重点，全力打好三大标志性战役：要全力打好黄河“几字弯”攻坚战。要全\n力打好科尔沁、浑善达克两大沙地歼灭战。要全力打好河西走廊－塔克拉玛干沙漠边缘阻击\n战。\n——习近平在加强荒漠化综合防治和推进“三北”等重点生态工程建设座谈会上的讲话","source":{"doc":"6cbfb01fe723bba64b75","first":46,"last":47,"page":46,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-f6d54a7da76261c3":{"sources":[{"id":"fd834d0f3b0b3f1e","label":"安全生产治本攻坚三年行动","topic":"年度政府工作","category":"时政","text":"2.安全生产治本攻坚三年行动\n通过三年治本攻坚，地方党委和政府、部门和生产经营单位统筹发展和安全的理念进一\n步强化，坚守安全红线的意识更加强烈，消减重大安全风险、消除重大事故隐患的积极性主\n动性显著增强；重点行业领域建立健全“一件事”由牵头部门组织推动、各相关部门齐抓共\n管，全链条排查整治重大事故隐患的责任体系，安全监管能力显著提升；2024 年底前基本\n消除 2023 年及以前排查发现的重大事故隐患存量，2025 年底前有效遏制重大事故隐患增量，\n2026 年底前形成重大事故隐患动态清零的常态化机制；针对重大安全风险的一批“人防、\n技防、工程防、管理防”措施落地见效，本质安全水平大幅提升；全国安全生产形势持续稳\n定向好，重特大生产安全事故多发势头得到有效遏制。\n——《安全生产治本攻坚三年行动方案 2024-2026 年》","source":{"doc":"6cbfb01fe723bba64b75","first":50,"last":50,"page":50,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-069b062c908f8ae9":{"sources":[{"id":"a5cdcb95febb1cc2","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"新的形势和任务，对政府工作提出了更高要求。\n各级政府及其工作人员要深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚\n定“四个自信”、做到“两个维护”①，自觉在思想上政治上行动上同以习近平同志为核心\n的党中央保持高度一致。坚决扛起全面从严治党政治责任，巩固拓展深入贯彻中央八项规定\n精神学习教育②成果，加强对权力配置、运行的规范和监督，纵深推进政府党风廉政建设和\n反腐败斗争，深化整治群众身边不正之风和腐败问题。牢固树立和践行正确政绩观③，坚持\n为人民出政绩、以实干出政绩，自觉按规律办事。","source":{"doc":"6cbfb01fe723bba64b75","first":50,"last":50,"page":50,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"feea5fd5926b1697","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"李强强调，蓝图已经绘就，奋进正当其时。我们要更加紧密地团结在以习近平同志为核\n心的党中央周围，高举中国特色社会主义伟大旗帜，以习近平新时代中国特色社会主义思\n想为指导，万众一心、砥砺前行，奋力实现全年经济社会发展目标任务，确保“十五五”良\n好开局，为以中国式现代化全面推进强国建设、民族复兴伟业不懈奋斗！","source":{"doc":"6cbfb01fe723bba64b75","first":56,"last":56,"page":56,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"a7c6dbe87574bda8","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"我们要坚定不移贯彻“一国两制”、“港人治港”、“澳人治澳”、高度自治方针，\n落实“爱国者治港”、“爱国者治澳”原则①，提升港澳依法治理效能，促进港澳经济社会\n发展。支持港澳更好融入和服务国家发展大局，发挥港澳背靠祖国、联通世界独特优势和重\n要作用，促进香港、澳门长期繁荣稳定。\n我们要深入贯彻新时代党解决台湾问题的总体方略②，坚持一个中国原则和“九二共识”，\n坚决打击“台独”分裂势力，反对外部势力干涉，推动两岸关系和平发展、推进祖国统一大\n业。深化两岸交流合作和融合发展，共同传承弘扬中华文化，落实台湾同胞享受同等待遇政\n策，增进两岸同胞福祉，共同开创民族复兴伟业。","source":{"doc":"6cbfb01fe723bba64b75","first":54,"last":55,"page":54,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"bf7189eda8acd937","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"我们要以铸牢中华民族共同体意识为主线①，积极促进各民族广泛交往交流交融，加快\n民族地区现代化建设步伐，推进中华民族共同体建设。坚持党的宗教工作基本方针，坚持我\n国宗教中国化②方向，加强宗教事务治理法治化。全面贯彻党的侨务政策，维护海外侨胞和\n归侨侨眷合法权益，更好凝聚侨心侨力。","source":{"doc":"6cbfb01fe723bba64b75","first":52,"last":52,"page":52,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"17f556fab3c26093","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"过去一年，国防和军队现代化建设取得新的成就。新的一年，我们要深入贯彻习近平强\n军思想①，贯彻新时代军事战略方针，坚持党对人民军队的绝对领导②，全面深入贯彻军委\n主席负责制，以政治建军为引领，持续深化政治整训，接续打好实现建军一百年奋斗目标③\n攻坚战。扎实推进练兵备战，加快先进战斗力建设，提高捍卫国家主权、安全、发展利益的\n战略能力。抓好军队建设“十五五”规划编制，实施国防发展重大工程，实施军事理论现代\n化推进工程。协力推进跨军地改革，优化国防科技工业体系和布局，巩固提高一体化国家战\n略体系和能力。加快国防动员能力建设，深化全民国防教育。各级政府要大力支持国防和军\n队建设，深入开展“双拥”工作，巩固军政军民团结。","source":{"doc":"6cbfb01fe723bba64b75","first":53,"last":54,"page":53,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"47d68837fae0378c","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"我们要强化法治政府建设①，深入推进依法行政，严格依照宪法法律履职尽责。\n自觉接受同级人大及其常委会的监督，自觉接受人民政协的民主监督，自觉接受社会\n和舆论监督。提高审计监督质效②。坚持科学、民主、依法决策。扎实做好政务公开工作，\n加强政策宣传解读。支持工会、共青团、妇联等群团组织更好发挥作用。深化事业单位改革。\n健全规范涉企行政执法长效机制。以“高效办成一件事”为牵引，持续优化政务服务，加快\n数字政府建设。着力提升行政效能，沉下心来抓落实，认认真真解决问题，提高对党中央决\n策部署一贯到底的执行力穿透力。各级政府要树牢大局观，准确把握在全国发展大局中的定\n位，善于把国家战略、市场需求和地区优势结合起来，因地制宜探索高质量发展新模式。完\n善差异化考核评价体系，持续深化整治形式主义为基层减负③，让广大干部心无旁骛抓落实、\n办实事。营造良好政治环境、人才环境、营商环境、舆论环境，在全社会凝聚推动高质量\n发展的强大合力。","source":{"doc":"6cbfb01fe723bba64b75","first":51,"last":51,"page":51,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"1c5a2f939216b230","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"我们要坚持独立自主的和平外交政策①，坚持走和平发展道路，拓展全球伙伴关系网络，\n坚决反对霸权主义和强权政治，维护国际公平正义。中国愿同国际社会一道，倡导平等有序\n的世界多极化、普惠包容的经济全球化，推动落实全球发展倡议、全球安全倡议、全球文\n明倡议、全球治理倡议②，积极参与全球治理体系改革和建设，推动国际秩序朝着更加公正\n合理的方向发展，携手构建人类命运共同体，共创世界和平发展美好未来。","source":{"doc":"6cbfb01fe723bba64b75","first":55,"last":56,"page":55,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"d81d4ef637c273d2","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"维护国家安全和社会稳定。全面贯彻总体国家安全观①，健全国家安全体系，加强重点\n领域国家安全能力建设。强化公共安全治理，提升重要基础设施本质安全水平，持续夯实安\n全生产、防灾减灾基层基础，全面完成安全生产治本攻坚三年行动②。加强气象、水文、\n地质灾害、森林草原火灾、地震监测预报预警。加快补齐北方地区防洪排涝抗灾基础设施、\n应急处置等短板。加快建设现代化水网。健全巨灾保险保障体系。严格食品、药品、重点工\n业产品、特种设备等安全监管。完善社会治理体系，引导支持社会组织、人道救助、志愿服\n务、公益慈善等健康发展，推动行业协会商会改革发展。坚持和发展新时代“枫桥经验”③，\n推进综治中心规范化建设，完善社区治理，推进矛盾纠纷预防和多元化解。加强社会心理疏\n导。深入推进信访工作法治化，集中化解信访问题。深化社会治安整体防控体系和能力建设，\n健全扫黑除恶常态化机制，加大预防和打击电信网络诈骗、毒品犯罪等力度，建设更高水\n平的平安中国。","source":{"doc":"6cbfb01fe723bba64b75","first":49,"last":49,"page":49,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"3197796e3b42dba0","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"（十）加强重点领域风险防范化解和安全能力建设。统筹防风险和促发展，进一步增\n强发展韧性，坚决守牢安全底线，促进社会和谐稳定。\n着力稳定房地产市场①。因城施策控增量、去库存、优供给，探索多渠道盘活存量商品\n房，鼓励收购存量商品房重点用于保障性住房等。深化住房公积金制度改革。优化保障性住\n房供给，加快危旧房改造。有序推动安全舒适绿色智慧的“好房子”建设，实施房屋品质\n提升工程和物业服务质量提升行动。进一步发挥“保交房”的白名单制度作用，防范债务违\n约风险。深入推进房地产发展新模式的基础制度和配套政策建设。\n积极有序化解地方政府债务风险②。支持各地用足用好政策，加快化解隐性债务风险，\n严防虚假化债，坚决把遏制违规新增隐性债务作为铁的纪律。加大金融、财政支持力度，优\n化债务重组和置换办法，多措并举化解地方政府融资平台经营性债务风险，分类有序推动改\n革转型。优化债务监测考核指标，构建统一的政府债务管理长效机制。\n积极稳妥化解金融领域风险③。充实地方中小金融机构风险处置资源和手段。坚持市场\n化法治化原则，有序推进高风险机构处置。多渠道加大资本补充力度，稳妥处置金融机构不\n良资产。加强金融监管协同，防范打击非法金融活动。强化金融风险监测预警和早期纠正，\n提高风险源头防控能力。","source":{"doc":"6cbfb01fe723bba64b75","first":48,"last":48,"page":48,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"k-0672e13b123466d9":{"sources":[{"id":"c6c50fa6203838d2","label":"中央八项规定精神学习教育","topic":"年度政府工作","category":"时政","text":"2.中央八项规定精神学习教育\n深入贯彻中央八项规定精神学习教育，是中共中央于 2025 年全国两会后启动、2025 年\n7 月底前基本结束，在全党开展的贯彻中央八项规定精神的学习教育。坚持聚焦主题、简约\n务实，不分批次、不划阶段，一体推进学查改，融入日常、抓在经常。\n——共产党员网","source":{"doc":"6cbfb01fe723bba64b75","first":51,"last":51,"page":51,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"},{"id":"7f367a44396a1a5d","label":"中央八项规定精神学习教育","topic":"年度政府工作","category":"时政","text":"中央八项规定精神学习教育\n学习教育于 2025 年全国两会后启动、7 月底前基本结束。要坚持坚持聚焦主题、简约\n务实，不分批次、不划阶段，一体推进学查改，融入日常、抓在经常。学习研讨要组织学习\n习近平总书记关于加强党的作风建设的重要论述和中央八项规定及其实施细则精神，总结学\n习深入贯彻中央八项规定精神的成效和经验，提高认识、增强信心，坚定不移抓好落实。查\n摆问题要通过对标对表查摆，充分运用纪检监察、巡视巡察、审计监督、财会监督、督促检\n查、调查研究、信访反映等途径，全面深入查找落实中央八项规定及其实施细则精神方面存\n在的问题。集中整治要坚持有什么问题就解决什么问题，什么问题突出就重点整治什么问题，\n立查立改、即知即改。开门教育要注重群众参与，接受群众监督，各级领导干部要带头走\n好新时代党的群众路线，组织党员、干部立足岗位，在推动高质量发展、加强基层治理、完\n成急难险重任务中担当作为、服务群众，让群众可感可及。\n——《关于在全党开展深入贯彻中央八项规定精神学习教育的通知》","source":{"doc":"6cbfb01fe723bba64b75","first":13,"last":13,"page":13,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-bdd4ecfd3776998b":{"sources":[{"id":"fc7f6a21efeac773","label":"实现建军一百年奋斗目标","topic":"年度政府工作","category":"时政","text":"3.实现建军一百年奋斗目标\n国防和军队现代化新“三步走”战略\n第一步：到 2027 年实现建军一百年奋斗目标。\n第二步：到 2035 年基本实现国防和军队现代化。\n第三步：到本世纪中叶把人民军队全面建成世界一流军队。","source":{"doc":"6cbfb01fe723bba64b75","first":54,"last":54,"page":54,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-1bf0a2e0bb57237f":{"sources":[{"id":"db9f406d98b5fe18","label":"二十届五中全会","topic":"二十届五中全会","category":"时政","text":"《中国共产党第二十届中央委员会第五次全体会议公报》解读\n（2026 年 10 月 29 日中国共产党第二十届中央委员会第五次全体会议通过）\n中国共产党第二十届中央委员会第五次全体会议①，于 2026 年 10 月 26 日至 29 日在\n北京举行。全会听取和讨论了习近平受中央政治局委托所作的工作报告，审议通过了《中\n共中央关于持之以恒推进全面从严治党②若干重大问题的决定》。","source":{"doc":"41195a191a57c1c36332","first":2,"last":2,"page":2,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-0dfedc65c5bc75ea":{"sources":[{"id":"8d7cb7cfd62ef202","label":"二十届历次全会研究了哪些内容？","topic":"二十届五中全会","category":"时政","text":"（2）二十届历次全会研究了哪些内容？\n①二十届一中全会\n时间：2022 年 10 月 23 日\n内容：全会选举了中央政治局委员、中央政治局常务委员会委员、中央委员会总\n书记。\n②二十届二中全会\n时间：2023 年 2 月 26 日\n内容：审议通过了《党和国家机构改革方案》。\n③二十届三中全会\n时间：2024 年 7 月 15 日\n内容：审议通过了《中共中央关于进一步全面深化改革、推进中国式现代化的决\n定》。\n④二十届四中全会\n时间：2025 年 10 月 20 日\n内容：审议通过了《中共中央关于制定国民经济和社会发展第十五个五年规划的\n建议》。","source":{"doc":"41195a191a57c1c36332","first":2,"last":2,"page":2,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-4668e5de9e2f9c13":{"sources":[{"id":"a9be58b365382644","label":"全面从严治党 · 年度进展或目标","topic":"二十届五中全会","category":"时政","text":"2026 年 6 月 15 日，全国党建工作座谈会对学习贯彻习近平党建思想作出工作部\n署。习近平党建思想“十四个坚持”的内涵要义，其中之一正是“坚持全面从严治\n党”。","source":{"doc":"41195a191a57c1c36332","first":3,"last":3,"page":3,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-4218ca73d33244f2":{"sources":[{"id":"c0ddd9dc60a68f54","label":"“十五五”","topic":"二十届五中全会","category":"时政","text":"6.“十五五”\n2026 年是“十五五”规划开局之年。“十五五”规划，从 2026—2030 年，围绕以\n中国式现代化全面推进强国建设、民族复兴伟业，“十五五”时期是基本实现社会主\n义现代化夯实基础、全面发力的关键时期。\n——《人民网》","source":{"doc":"41195a191a57c1c36332","first":4,"last":5,"page":4,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-2637656b83b34378":{"sources":[{"id":"b74b1cfd8b4131c8","label":"树立和践行正确政绩观学习教育","topic":"二十届五中全会","category":"时政","text":"7.树立和践行正确政绩观学习教育\n2026 年 2 月，中办印发《关于在全党开展树立和践行正确政绩观学习教育的通知》，\n明确：“以立党为公、为民造福、科学决策、真抓实干为总要求，以一体推进学查改为\n抓手，教育引导各级党组织和党员、干部坚持实事求是、求真务实，为人民出政绩、以\n实干出政绩”。\n政绩观问题是一个根本性问题，关乎立党为公、执政为民。\n正确政绩观要求我们坚持从实际出发、按规律办事，通过科学决策和实干苦干，创\n造经得起实践和历史检验、真正造福人民、得到群众公认的业绩。\n错误政绩观则是从个人或小团体利益出发，心浮气躁、急功近利、弄虚作假、盲\n目蛮干，搞‘形象工程’、‘政绩工程’，留下包袱和隐患，引起人民群众强烈不\n满。","source":{"doc":"41195a191a57c1c36332","first":5,"last":5,"page":5,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-94187d1283fc8d88":{"sources":[{"id":"d421d38d3ac1f43b","label":"庆祝中国共产党成立 105 周年","topic":"二十届五中全会","category":"时政","text":"8.庆祝中国共产党成立 105 周年\n2026 年是中国共产党成立 105 周年，习近平在庆祝中国共产党成立 105 周年大会\n上发表重要讲话，重点内容包括：\n（1）105 年不懈奋斗的五个方面成就：①105 年不懈奋斗，从根本上改变了中国\n人民的前途命运；②105 年不懈奋斗，开辟了实现中华民族伟大复兴的正确道路；③\n105 年不懈奋斗，展示了马克思主义的强大生命力；④105 年不懈奋斗，深刻影响了世\n界历史进程；⑤105 年不懈奋斗，锻造了强大的中国共产党。\n（2）优秀特质“六个始终”：中国共产党之所以能够在 105 年奋斗中不断铸就辉\n煌，历史和人民之所以选择中国共产党，根本在于我们党具有其他政党和政治力量无\n可比拟的优秀特质。①矢志追求真理，始终把准前进方向；②深深植根人民，始终拥\n有坚实根基；③勇担历史使命，始终掌握战略主动；④顺应发展潮流，始终走在时代\n前列；⑤敢于善于斗争，始终保持必胜信心；⑥注重强健自身，始终充满生机活力。\n（3）五个必须：实现新时代新征程党的使命任务，要求全体中国共产党人坚定信\n心、接续奋斗，不断创造无愧于时代和人民的新业绩。①坚定信心、接续奋斗，必须\n坚持党的基本理论、基本路线、基本方略；②坚定信心、接续奋斗，必须紧紧依靠人\n民创造历史伟业；③坚定信心、接续奋斗，必须积极应对前进道路上的风险挑战；④\n坚定信心、接续奋斗，必须持续推动构建人类命运共同体；⑤坚定信心、接续奋斗，\n必须持之以恒推进全面从严治党。\n——《中国政府网》","source":{"doc":"41195a191a57c1c36332","first":5,"last":6,"page":5,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-29e2ab3a476bb649":{"sources":[{"id":"a1b63355863aa1ad","label":"回顾成就","topic":"二十届五中全会","category":"时政","text":"全会高度评价新时代全面从严治党取得的伟大成就。一致认为，以习近平同志为核心\n的党中央以巨大的政治勇气和强烈的责任担当，直面一度出现党的领导弱化虚化淡化、管\n党治党不严不实不力、党内一些问题触目惊心的严峻现实，坚定不移全面从严治党，刀刃\n向内、重典治乱，持续解决突出问题，从根本上扭转了管党治党宽松软状况，刹住了一些\n长期没有刹住的歪风，纠治了一些多年未除的顽瘴痼疾，消除了党、国家、军队内部存在\n的严重隐患，党在革命性锻造中更加坚强有力。新时代全面从严治党开辟了百年大党自我\n革命新境界，推动党和国家事业取得历史性成就、发生历史性变革，党和人民赢得强党强\n国的历史主动。\n全会指出，在新时代管党治党、兴党强党伟大实践中，以习近平同志为核心的党中央\n围绕建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党的重\n大时代课题，提出一系列新理念新思想新战略，形成习近平党建思想①。这一思想丰富和\n发展了马克思主义建党学说，是坚持把马克思主义基本原理同中国具体实际相结合、同中\n华优秀传统文化相结合推进党的理论创新的重大成果，是党和人民实践经验和集体智慧的\n结晶，是习近平新时代中国特色社会主义思想的重要组成部分，为深入推进新时代党的建\n设新的伟大工程提供了根本遵循和行动指南。","source":{"doc":"41195a191a57c1c36332","first":7,"last":7,"page":7,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"},{"id":"291933e712394d83","label":"回顾成就","topic":"二十届五中全会","category":"时政","text":"全会回顾党 100 多年来的奋斗历程，指出中国共产党能够从胜利走向胜利，就在于胸\n怀共产主义远大理想，立志于中华民族千秋伟业，坚持为中国人民谋幸福、为中华民族谋\n复兴①，在各个历史时期都高度重视管党治党，勇于坚持真理、修正错误，在依靠自身力量\n和人民支持解决自身问题中不断强大，成为党和人民事业的坚强领导核心。在革命、建\n设、改革中先后把党的建设②作为伟大工程、新的伟大工程，党的十八大以来深入推进新\n时代党的建设新的伟大工程，找到“让人民来监督政府”和“自我革命”③两个跳出治乱\n兴衰历史周期率的答案，这是中国共产党的独特创造，永载马克思主义政党建设史册。","source":{"doc":"41195a191a57c1c36332","first":6,"last":6,"page":6,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"},{"id":"afab433c71329e45","label":"回顾成就","topic":"二十届五中全会","category":"时政","text":"一、回顾成就\n全会充分肯定党的二十届四中全会以来中央政治局的工作。一致认为，中央政治局认\n真落实党的二十大和二十届历次全会精神，坚持稳中求进工作总基调，完整准确全面贯彻\n新发展理念①，统筹推进“五位一体”总体布局②，协调推进“四个全面”战略布局③，统\n筹国内国际两个大局④，统筹发展和安全，扎实推动经济高质量发展，推进社会主义民主法\n治建设，做好宣传思想文化工作，抓好民生保障和生态文明建设，维护国家安全和社会稳\n定，纵深推进全面从严治党，加强国防和军队现代化建设⑤，做好港澳工作和对台工作，推\n进中国特色大国外交，“十四五”圆满收官，“十五五”⑥开局良好，党和国家事业取得新\n进展新成效。开展树立和践行正确政绩观学习教育⑦，隆重庆祝中国共产党成立 105 周年\n⑧，进一步凝聚起全党全国各族人民团结奋进的强大力量。","source":{"doc":"41195a191a57c1c36332","first":3,"last":3,"page":3,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-60e2ec1fe07704d6":{"sources":[{"id":"ff13708461214eb0","label":"面临问题","topic":"二十届五中全会","category":"时政","text":"二、面临问题\n全会强调，全面从严治党具备许多有利条件，同时面临许多新情况新问题。随着世情国\n情党情发生深刻变化，党团结带领人民维护国家主权、安全、发展利益任务更加艰巨，党团\n结带领人民推动改革发展、维护社会和谐稳定任务更加艰巨，党保持先进性和纯洁性任务更\n加艰巨。这些对党在新形势下的执政能力、领导水平、队伍素质、拒腐防变带来重大挑战，\n党面临的“四大考验”①和“四种危险”②是长期的、复杂的、严峻的。全党必须从巩固党的\n长期执政地位、实现中华民族伟大复兴的战略高度，深刻认识持之以恒推进全面从严治党的\n重大意义，坚定信心，保持定力，以更高标准、更实举措把新时代全面从严治党宝贵经验③\n坚持好、运用好，把党的建设面临的突出问题④整治好、解决好，把管党治党形成的良好政\n治局面巩固好、发展好。","source":{"doc":"41195a191a57c1c36332","first":8,"last":9,"page":8,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-9c44a126f0b73503":{"sources":[{"id":"7a3d4d37e3aac5f1","label":"党的建设面临的突出问题","topic":"党政制度与理论","category":"非时政","text":"5.党的建设面临的突出问题\n在十八届中央政治局常委同中外记者见面时，习近平总书记斩钉截铁地指出“坚持\n党要管党、从严治党，切实解决自身存在的突出问题”，彰显了大党大国领袖深邃的历\n史洞察和鲜明的问题导向。从当时党内实际状况来看，一些长期存在的深层次问题尚未\n根本解决，一些新问题又日益凸显。\n有的地方和部门对坚持党的领导认识模糊、行动乏力，落实党的领导弱化虚化淡\n化、党的建设缺失；\n一些基层党组织软弱涣散，一些党员、干部党性意识不强，政治信仰发生动摇，形\n式主义、官僚主义、享乐主义和奢靡之风盛行，特权思想和特权现象较为严重；\n选人用人风气不正，任人唯亲、跑官要官、买官卖官、拉票贿选现象屡禁不止；\n一些党员、干部法治意识、纪律观念淡薄，自我约束松懈，纪律执行失之于宽、失\n之于松、失之于软；\n贪污受贿、腐化堕落等现象滋生蔓延，一些领导干部特别是高级干部贪腐程度相当\n严重甚至触目惊心；等等。\n这些问题具有极强的危险性和破坏性，严重损害党的形象和威信、侵蚀党的执政根\n基，令党和人民忧心忡忡。\n——共产党员网","source":{"doc":"41195a191a57c1c36332","first":9,"last":10,"page":9,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-0d2aff4682680104":{"sources":[{"id":"8df8d4353be4feb1","label":"全社会研发经费投入","topic":"经济指标与宏观调控","category":"非时政","text":"1.全社会研发经费投入\n全社会研发经费投入，不仅是一个国家和地区科技投入的重要构成，也是衡量其对创新\n重视程度的关键指标，更能从侧面反映整体科技发展水平和创新竞争力。2025 年，我国全\n社会研究与试验发展经费投入达 39262 亿元，研发经费投入强度达 2.8%，比上年提高 0.11\n个百分点。“十四五”时期，我国全社会研发经费投入年均增长 10%，研发经费投入强度提\n高 0.44 个百分点。","source":{"doc":"6cbfb01fe723bba64b75","first":15,"last":15,"page":15,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]}}};
